/**
 * Bank Accounts Management
 * Sage equivalent: Banking > Bank Accounts
 * View and manage bank accounts linked to GL
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Landmark, Loader2, AlertCircle, Plus, ArrowUpRight, ArrowDownRight, X, Pencil } from 'lucide-react';
import { notify } from '@/utils/toast';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

/** Mask account number for display: show last 4 digits only */
function maskAccountNumber(num: string): string {
  if (num.length <= 4) return num;
  return '****' + num.slice(-4);
}

interface BankAccount {
  id: string;
  accountCode: string;
  accountName: string;
  description?: string;
  bankAccountNumber?: string | null;
  isActive: boolean;
  txnCount: number;
  totalDebits: number;
  totalCredits: number;
  balance: number;
  firstDate?: string;
  lastDate?: string;
}

interface EditForm {
  accountName: string;
  description: string;
  bankAccountNumber: string;
}

export default function BankAccountsPage() {
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ accountCode: '', accountName: '', description: '', bankAccountNumber: '' });

  const [editingAccount, setEditingAccount] = useState<BankAccount | null>(null);
  const [editForm, setEditForm] = useState<EditForm>({ accountName: '', description: '', bankAccountNumber: '' });

  const loadAccounts = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/bank-accounts');
      const json = await res.json();
      const data = json.data || json;
      setAccounts(Array.isArray(data) ? data : []);
    } catch {
      setError('Failed to load bank accounts');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadAccounts(); }, [loadAccounts]);

  const handleAdd = async () => {
    if (!form.accountCode || !form.accountName) {
      notify.error('Account code and name are required');
      return;
    }
    setSaving(true);
    try {
      const res = await apiFetch('/api/accounting/chart-of-accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          accountCode: form.accountCode,
          accountName: form.accountName,
          accountType: 'asset',
          accountSubtype: 'bank',
          parentAccountId: 'bf801b3b-de70-4c10-8d8f-689de8b8a9ad',
          description: form.description || form.accountName,
          normalBalance: 'debit',
        }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json?.error?.message || 'Failed to create account');
        return;
      }
      // If bank account number provided, save it separately
      if (form.bankAccountNumber.trim()) {
        const created = json.data || json;
        await apiFetch('/api/accounting/bank-accounts', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ id: created.id, bankAccountNumber: form.bankAccountNumber.trim() }),
        });
      }
      notify.success('Bank account created');
      setShowAddModal(false);
      setForm({ accountCode: '', accountName: '', description: '', bankAccountNumber: '' });
      loadAccounts();
    } catch {
      notify.error('Failed to create bank account');
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (acct: BankAccount) => {
    setEditingAccount(acct);
    setEditForm({
      accountName: acct.accountName,
      description: acct.description || '',
      bankAccountNumber: acct.bankAccountNumber || '',
    });
  };

  const handleSaveEdit = async () => {
    if (!editingAccount) return;
    if (!editForm.accountName.trim()) {
      notify.error('Account name is required');
      return;
    }
    setSaving(true);
    try {
      // Update name & description via chart-of-accounts
      const coaRes = await apiFetch('/api/accounting/chart-of-accounts', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          id: editingAccount.id,
          accountName: editForm.accountName.trim(),
          description: editForm.description.trim() || null,
        }),
      });
      if (!coaRes.ok) {
        const json = await coaRes.json();
        notify.error(json.message || 'Failed to update account');
        return;
      }
      // Update bank account number
      await apiFetch('/api/accounting/bank-accounts', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          id: editingAccount.id,
          bankAccountNumber: editForm.bankAccountNumber.trim() || null,
        }),
      });
      notify.success('Bank account updated');
      setEditingAccount(null);
      loadAccounts();
    } catch {
      notify.error('Failed to update bank account');
