const buf = readFileSync('/home/hein/Workspace/IsaFlow/test-docs/bank-statements/vf_sbsa_1.pdf');
(async () => {
  const { PDFParse } = await import('pdf-parse');
  const { text } = await new PDFParse({ data: buf }).getText();
  const lines = text.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean);

  // Row pattern: "<page> <desc> <fee> <debit> <credit> <yyyymmdd> <balance>"
  // Numbers may be 0.00 or -262.83 or 1,300,000.00
  const num = `(-?\\d{1,3}(?:,\\d{3})*\\.\\d{2})`;
  const rowPat = new RegExp(`^(\\d+)\\s+(.+?)\\s+${num}\\s+${num}\\s+${num}\\s+(\\d{8})\\s+${num}\\s*$`);

  const parseNum = (s: string) => parseFloat(s.replace(/,/g, ''));
  const parseDate = (yyyymmdd: string) => `${yyyymmdd.slice(0,4)}-${yyyymmdd.slice(4,6)}-${yyyymmdd.slice(6,8)}`;

  const txs: any[] = [];
  let last: any = null;
  for (const line of lines) {
    const m = line.match(rowPat);
    if (!m) {
      // continuation description
      if (last && !/^(page|date|details|service|statement|balance|\*\*|--|--\s*\d)/i.test(line)) {
        last.description += ' ' + line;
      }
      continue;
    }
    const [, , desc, fee, debit, credit, date, balance] = m;
    const debitN = parseNum(debit!);
    const creditN = parseNum(credit!);
    const amount = creditN !== 0 ? creditN : debitN;  // use whichever is non-zero
    last = {
      transactionDate: parseDate(date!),
      description: desc!.replace(/\s*##$/,'').trim(),
      amount,
      balance: parseNum(balance!),
    };
    txs.push(last);
  }
  console.log('Parsed:', txs.length);
  txs.forEach(t => console.log(t));
})();
