    const description = rawDesc.replace(/\s+Settlement\s+\d[\d\s,]*\.\d{2}\s+[TA]$/i, '')
      .replace(/\s+Settlement$/i, '')
      .trim();

    result.transactions.push({
      transactionDate,
      amount: signedAmount,
      description,
      balance,
    });

    prevBalance = balance;
  }

  return result;
}

