// continuation stitching, stop stitching for the current transaction
// until the next dated row appears. This prevents the last transaction
// on each page from greedily absorbing the page footer + next-page
// header text (column legend, legal boilerplate, customer address).
const isPageBoundary = (line: string): boolean => {
  if (/^-{2,}\s*\d+\s+of\s+\d+\s*-{2,}$/i.test(line)) return true;  // "-- 3 of 6 --"
  if (/^Page\s+\d+\s+of\s+\d+/i.test(line)) return true;
  if (/^Tax Invoice/i.test(line)) return true;
  if (/^Your transactions( \(continued\))?$/i.test(line)) return true;
  if (/^Date\s+Transaction\s+Description/i.test(line)) return true;  // column header row
  if (/^Authorised Financial Services Provider/i.test(line)) return true;
  if (/^Registration Number\s+\d{4}/i.test(line)) return true;
  if (/^CSP\d+|^BFIBRE\s+\d+/i.test(line)) return true;              // document-code footer
  if (/^Cheque Account Number:?$/i.test(line)) return true;
  if (/^YOUR PRICING PLAN/i.test(line)) return true;
  if (/^CREDIT INTEREST RATE/i.test(line)) return true;
  if (/^ABSA:/i.test(line)) return true;                             // marketing banner block
  if (/^\d{2}-\d{4}-\d{4}\s*$/.test(line)) return true;              // "41-0242-6629" bare ref
  return false;
};

