async function phaseExports(cookie: string) {
  console.log('\n═══ Phase 5: Export barrage (PDFs / CSVs / XLS) ═══');

  const cosDb = await sql`SELECT id FROM companies WHERE is_active = true LIMIT 5` as any[];
  const jobs: Promise<HitResult>[] = [];

  for (const c of cosDb as any[]) {
    const cid = c.id as string;
    const qp = `?companyId=${cid}`;
    jobs.push(hit(cookie, `tb-export ${cid.slice(0,8)}`,   `/api/accounting/trial-balance-export${qp}&format=csv`));
    jobs.push(hit(cookie, `bs-export ${cid.slice(0,8)}`,   `/api/accounting/balance-sheet-export${qp}&format=pdf`));
    jobs.push(hit(cookie, `bt-export ${cid.slice(0,8)}`,   `/api/accounting/bank-transactions-export${qp}&format=csv`));
    jobs.push(hit(cookie, `cf-export ${cid.slice(0,8)}`,   `/api/accounting/cash-flow-export${qp}&format=pdf`));
    jobs.push(hit(cookie, `ar-export ${cid.slice(0,8)}`,   `/api/accounting/ar-aging-export${qp}`));
    jobs.push(hit(cookie, `ap-export ${cid.slice(0,8)}`,   `/api/accounting/ap-aging-export${qp}`));
