async function phaseHTTPLoad(cookie: string) {
  console.log('\n═══ Phase 2: Concurrent HTTP load ═══');

  // Get real company IDs from DB
  const cosDb = await sql`SELECT id FROM companies WHERE is_active = true LIMIT 10` as any[];
  const coIds = cosDb.map((c: any) => c.id as string);

  const allHits: Promise<HitResult>[] = [];

  // For each company: blast all report endpoints concurrently
  for (const cid of coIds) {
    const qp = `?companyId=${cid}`;
    // Reports
    allHits.push(hit(cookie, `trial-balance ${cid.slice(0,8)}`, `/api/accounting/trial-balance${qp}`));
    allHits.push(hit(cookie, `pl-report ${cid.slice(0,8)}`, `/api/accounting/pl-report${qp}`));
    allHits.push(hit(cookie, `balance-sheet ${cid.slice(0,8)}`, `/api/accounting/balance-sheet${qp}`));
    allHits.push(hit(cookie, `cash-flow ${cid.slice(0,8)}`, `/api/accounting/cash-flow${qp}`));
    allHits.push(hit(cookie, `ar-aging ${cid.slice(0,8)}`, `/api/accounting/ar-aging${qp}`));
    allHits.push(hit(cookie, `ap-aging ${cid.slice(0,8)}`, `/api/accounting/ap-aging${qp}`));
    // Listings
    allHits.push(hit(cookie, `bank-txns ${cid.slice(0,8)}`, `/api/accounting/bank-transactions${qp}&limit=100`));
    allHits.push(hit(cookie, `bank-rules ${cid.slice(0,8)}`, `/api/accounting/bank-rules${qp}`));
    allHits.push(hit(cookie, `gl-accounts ${cid.slice(0,8)}`, `/api/accounting/gl-accounts${qp}`));
    allHits.push(hit(cookie, `customers ${cid.slice(0,8)}`, `/api/accounting/customers${qp}`));
    allHits.push(hit(cookie, `suppliers ${cid.slice(0,8)}`, `/api/accounting/suppliers${qp}`));
    allHits.push(hit(cookie, `bank-recons ${cid.slice(0,8)}`, `/api/accounting/bank-reconciliations${qp}`));
    allHits.push(hit(cookie, `assets ${cid.slice(0,8)}`, `/api/accounting/assets${qp}`));
    allHits.push(hit(cookie, `budgets ${cid.slice(0,8)}`, `/api/accounting/budgets${qp}`));
    allHits.push(hit(cookie, `audit-log ${cid.slice(0,8)}`, `/api/accounting/audit-log${qp}&limit=50`));
  }

  console.log(`  Firing ${allHits.length} concurrent requests across ${coIds.length} companies...`);
  const t0 = Date.now();
  const results = await Promise.all(allHits);
  const elapsed = Date.now() - t0;

  let passed = 0, failed = 0, totalMs = 0;
  const slow: HitResult[] = [];
  const errors: HitResult[] = [];

  for (const r of results) {
    totalMs += r.ms;
    if (r.ok) {
      passed++;
      if (r.ms > 3000) slow.push(r);
    } else {
      failed++;
      errors.push(r);
    }
  }

  console.log(`  Elapsed: ${fmt(elapsed)} | Pass: ${passed} | Fail: ${failed} | Avg: ${fmt(Math.round(totalMs / results.length))}`);
  if (slow.length > 0) {
    console.log(`  SLOW (>3s):`);
    for (const s of slow.sort((a, b) => b.ms - a.ms).slice(0, 5))
      console.log(`    ${s.label}: ${fmt(s.ms)}`);
  }
  if (errors.length > 0) {
    console.log(`  ERRORS:`);
    for (const e of errors.slice(0, 10))
      console.log(`    ${e.status} ${e.label}`);
  }

  return { passed, failed, elapsed, slow, errors };
}

