async function phaseSeed() {
  console.log('\n═══ Phase 1: Seeding stress companies ═══');
  const TX_PER_CO = 800;
  const JE_PER_CO = 100;

  for (const co of STRESS_COMPANIES) {
    const t0 = Date.now();
    process.stdout.write(`  ${co.name} ... `);

    // Create company
    await sql`
      INSERT INTO companies (id, name, is_active, registration_number, vat_number, financial_year_start_month)
      VALUES (${co.id}::uuid, ${co.name}, true, ${`2025/${co.id.slice(0,8).toUpperCase()}`}, ${`4${co.id.slice(0,8)}`}, 3)
