// ── Clean ─────────────────────────────────────────────────────────────────────
async function cleanStressCompanies() {
  console.log('\n[CLEAN] Removing stress-test companies...');
  for (const c of STRESS_COMPANIES) {
    await sql`DELETE FROM bank_transactions WHERE company_id = ${c.id}::uuid`;
