            (SELECT COUNT(*)::int FROM bank_rules WHERE company_id = ${co.id}::UUID) AS bank_rules
        `) as Array<{
          posted_jes: number;
          je_lines: number;
          bank_txns: number;
          bank_rules: number;
        }>;

        if (stats) {
          indent(
            `${co.name.padEnd(30)}  JEs=${String(stats.posted_jes).padStart(6)}  ` +
            `lines=${String(stats.je_lines).padStart(7)}  ` +
            `bank_txns=${String(stats.bank_txns).padStart(6)}  ` +
            `bank_rules=${String(stats.bank_rules).padStart(4)}`
          );
        }
      }
    }

    // Check 9 is informational — always counts as passed
    passed++;
    total++;
  }

  // -------------------------------------------------------------------------
  // Summary
  // -------------------------------------------------------------------------
  console.log('');
  console.log(`=== SUMMARY: ${passed}/${total} checks passed ===`);

  if (passed < total) {
    process.exit(1);
  }
}

main().catch((err: unknown) => {
  console.error('FATAL:', err instanceof Error ? err.message : String(err));
  process.exit(1);
});

