    await cleanLargeCompanies();
  }

  // Process companies sequentially to avoid overwhelming Neon serverless
  for (let i = 0; i < LARGE_COMPANIES.length; i++) {
    await seedCompany(LARGE_COMPANIES[i]!, i);
