    console.log(`Total JEs        : ${t.total_jes.toLocaleString()}`);
    console.log(`Total rules      : ${t.total_rules.toLocaleString()}`);
  }
  console.log(`Total elapsed    : ${fmt(Date.now() - totalStart)}`);
  console.log('\nDone.');
}

main().catch(err => {
