// ── Bank transaction templates ────────────────────────────────────────────────
const TX_TEMPLATES = [
  { desc: 'FROGFOOT NETWORKS PMT',  amount: () => randInt(50000, 250000),  type: 'credit' },
  { desc: 'METROFIBRE NETWORX INV', amount: () => randInt(80000, 400000),  type: 'credit' },
