// ── 15 original + 5 additional categorisation rule templates ─────────────────
const RULE_TEMPLATES = [
  { pattern: 'FROGFOOT',     code: '4100' },
  { pattern: 'METROFIBRE',   code: '4100' },
  { pattern: 'VUMATEL',      code: '4100' },
