    error: { code: 'ACCOUNT_INACTIVE', message: 'Account is disabled' },
  });
}

// Check account lockout
if (user.locked_until) {
  const lockedUntil = user.locked_until instanceof Date ? user.locked_until : new Date(user.locked_until as string);
  if (lockedUntil > new Date()) {
    const minutesRemaining = Math.ceil((lockedUntil.getTime() - Date.now()) / 60000);
    return res.status(403).json({
      success: false,
      error: {
        code: 'ACCOUNT_LOCKED',
        message: `Account locked due to too many failed attempts. Try again in ${minutesRemaining} minute(s).`,
      },
    });
  }
}

// Verify password
const passwordValid = await verifyPassword(password, user.password_hash as string);
if (!passwordValid) {
  // Increment failed attempts; lock after 10 failures
  const attempts = ((user.failed_login_attempts as number) ?? 0) + 1;
  if (attempts >= 10) {
    await sql`
      UPDATE users
      SET failed_login_attempts = ${attempts},
          locked_until = NOW() + INTERVAL '30 minutes'
      WHERE id = ${user.id as string}
    `;
    log.warn('Account locked after failed attempts', { userId: user.id, attempts }, 'auth/login');
  } else {
    await sql`
      UPDATE users SET failed_login_attempts = ${attempts} WHERE id = ${user.id as string}
    `;
  }

/**
 * AP Aging Report API
 * GET /api/accounting/ap-aging - AP aging buckets by supplier
 * GET /api/accounting/ap-aging?supplier_id=123 - Aging detail for one supplier
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAPAging, getAPAgingDetail } from '@/modules/accounting/services/apAgingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { supplier_id, as_at_date } = req.query;
    const asAtDate = as_at_date as string | undefined;

    if (supplier_id) {
      const detail = await getAPAgingDetail(companyId, supplier_id as string, asAtDate);
      return apiResponse.success(res, detail);
    }

    const aging = await getAPAging(companyId, asAtDate);
    return apiResponse.success(res, aging);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to get AP aging';
    log.error('Failed to get AP aging', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * WS-5.1: Cache Stats API
 * GET  /api/accounting/cache-stats  — Returns cache hit/miss statistics (admin only)
 * POST /api/accounting/cache-stats  — Clears all cache entries (admin only)
 *                                     Body: { action: "clear" }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { cache } from '@/lib/cache';

const ADMIN_ROLES = ['owner', 'admin', 'super_admin'];

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId, companyRole } = req as CompanyApiRequest;

  if (!ADMIN_ROLES.includes(companyRole)) {
    return apiResponse.forbidden(res, 'Only admins can view or manage cache statistics.');
  }

  if (req.method === 'GET') {
    const stats = cache.stats();
    log.info('Cache stats requested', { companyId, stats }, 'cache');
    return apiResponse.success(res, stats);
  }

  if (req.method === 'POST') {
    const { action } = req.body as { action?: string };
    if (action !== 'clear') {
      return apiResponse.badRequest(res, 'Invalid action. Supported: "clear"');
    }
    cache.clear();
    log.info('Cache cleared via API', { companyId }, 'cache');
    return apiResponse.success(res, { cleared: true });
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

