  // createSupplierInvoice). Use testuser2 who has a proper UUID.
  // admin@isaflow.co.za is still used first to show the issue, then
  // we fall back to testuser2 for write operations.
  const start = Date.now();
  const res = await fetch(`${BASE_URL}/api/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'admin@isaflow.co.za', password: 'admin123' }),
  });
  const ms = Date.now() - start;

  if (!res.ok) {
    fail('Login', await res.json());
    return false;
  }

  const cookieHeader = res.headers.get('set-cookie') ?? '';
  const match = cookieHeader.match(/ff_auth_token=([^;]+)/);
  if (!match) {
    fail('Login — no ff_auth_token cookie in response', cookieHeader);
    return false;
  }
  authCookie = `ff_auth_token=${match[1]}`;
  pass(`Login as admin@isaflow.co.za (${ms}ms)`, `cookie extracted`);
  console.log('  ℹ  NOTE: admin@isaflow.co.za has non-UUID id="admin-001" — write APIs that do');
  console.log('          ${userId}::UUID will fail (customer-payments, supplier-invoices).');
  console.log('          This is a known bug. Re-logging as testuser2@isaflow.co.za for write ops.');

  // Re-login as testuser2 (proper UUID id) so write operations succeed
  const res2 = await fetch(`${BASE_URL}/api/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'testuser2@isaflow.co.za', password: 'admin123' }),
  });
  if (res2.ok) {
    const cookie2 = res2.headers.get('set-cookie') ?? '';
    const match2 = cookie2.match(/ff_auth_token=([^;]+)/);
    if (match2) {
      authCookie = `ff_auth_token=${match2[1]}`;
      pass('Re-login as testuser2@isaflow.co.za', 'UUID-id user — write ops will succeed');
    }
  } else {
    console.log('  ⚠ testuser2 login failed — sticking with admin (write ops may fail with UUID error)');
  }

  return true;
}

