-- 293: Fix admin user ID to be a valid UUID
-- The admin user was seeded with id='admin-001' (non-UUID varchar).
-- Tables like customer_payments.created_by are UUID typed and reject 'admin-001'.
-- This migration promotes admin to a proper UUID.

DO $$
DECLARE
  v_old_id    VARCHAR := 'admin-001';
  v_new_id    VARCHAR := '00000000-0000-0000-0000-000000000099';
  v_old_email VARCHAR;
  v_exists    BOOLEAN;

  -- Helper: safely UPDATE a table if it exists
  PROCEDURE safe_update(t TEXT, col TEXT) AS $$
  BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = t AND table_schema = 'public') THEN
      EXECUTE format('UPDATE %I SET %I = %L WHERE %I = %L', t, col, v_new_id, col, v_old_id);
    END IF;
  END;
  $$;
BEGIN
  -- Check if old user still exists
  SELECT EXISTS(SELECT 1 FROM users WHERE id = v_old_id) INTO v_exists;
  IF NOT v_exists THEN
    RAISE NOTICE 'Admin user admin-001 not found — migration already applied or not needed.';
    RETURN;
  END IF;

  -- Check new UUID is not already taken
  IF EXISTS(SELECT 1 FROM users WHERE id = v_new_id) THEN
    RAISE NOTICE 'Target UUID % already exists — skipping.', v_new_id;
    RETURN;
  END IF;

  -- Capture old email
  SELECT email INTO v_old_email FROM users WHERE id = v_old_id;

  -- Step 1: Insert new user row with UUID and temp email (to avoid unique constraint)
  INSERT INTO users (id, email, password_hash, first_name, last_name, role,
                     permissions, is_active, created_at, updated_at)
  SELECT v_new_id,
         email || '__migrating',
         password_hash, first_name, last_name, role,
         permissions, is_active, created_at, updated_at
  FROM users WHERE id = v_old_id;

  -- Step 2: Update all FK references (only tables that actually exist)
  CALL safe_update('user_sessions',           'user_id');
  CALL safe_update('company_users',           'user_id');
  CALL safe_update('user_preferences',        'user_id');
  CALL safe_update('company_invitations',     'invited_by');
  CALL safe_update('audit_log',               'user_id');
  CALL safe_update('user_2fa',                'user_id');
  CALL safe_update('user_trusted_devices',    'user_id');
  CALL safe_update('user_granular_permissions', 'user_id');
  CALL safe_update('custom_reports',          'created_by');
  CALL safe_update('disclosure_notes',        'created_by');
  CALL safe_update('archive_runs',            'run_by');
  CALL safe_update('page_visits',             'user_id');
  CALL safe_update('recurring_templates',     'created_by');
  CALL safe_update('user_permissions',        'user_id');
  CALL safe_update('user_roles',              'user_id');

  -- Step 3: Delete old user (all FK refs already updated; no cascade fires)
  DELETE FROM users WHERE id = v_old_id;

  -- Step 4: Restore the real email on the new row
  UPDATE users SET email = v_old_email WHERE id = v_new_id;

  RAISE NOTICE 'Admin user migrated from % to % (email: %)', v_old_id, v_new_id, v_old_email;
END;
$$;

