    await sql`DELETE FROM bank_reconciliations WHERE company_id = ${c.id}::uuid`;
    await sql`DELETE FROM gl_journal_lines WHERE journal_entry_id IN (
      SELECT id FROM gl_journal_entries WHERE company_id = ${c.id}::uuid
