/**
 * Supplier Batch Payments API
 * GET  — list batches
 * POST — create batch
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBatches, getBatchById, createBatch } from '@/modules/accounting/services/batchPaymentService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { id, status, limit, offset } = req.query;

    // Single batch by ID
    if (id) {
      const batch = await getBatchById(companyId, id as string);
      if (!batch) return apiResponse.notFound(res, 'Batch', id as string);
      return apiResponse.success(res, batch);
    }

    const result = await getBatches(companyId, {
      status: status as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = req.user.id;  // User identity from JWT only
    try {
      const item = await createBatch(companyId, req.body, userId);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('Batch payment create failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Batch Payment Actions API
 * POST — approve, process, cancel
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  approveBatch,
  processBatch,
  cancelBatch,
} from '@/modules/accounting/services/batchPaymentService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { action, id } = req.body;
    const userId = req.user.id;
    if (!action || !id) return apiResponse.badRequest(res, 'action and id are required');

    switch (action) {
      case 'approve': {
        await approveBatch(companyId, id, userId);
        return apiResponse.success(res, { status: 'approved' });
      }
      case 'process': {
        await processBatch(companyId, id, userId);
        return apiResponse.success(res, { status: 'processed' });
      }
      case 'cancel':
        await cancelBatch(companyId, id);
        return apiResponse.success(res, { status: 'cancelled' });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Action failed';
    log.error('Batch payment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, msg);
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Recurring Invoices API
 * GET  — list recurring invoices
 * POST — create recurring invoice
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  getRecurringInvoices,
  createRecurringInvoice,
} from '@/modules/accounting/services/recurringInvoiceService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { status, clientId, limit, offset } = req.query;
    const result = await getRecurringInvoices(companyId, {
      status: status as string,
      clientId: clientId as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = req.user.id;
    try {
      const item = await createRecurringInvoice(companyId, req.body, userId);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('Recurring invoice create failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  if (req.method === 'PUT') {
    const { id, templateName, frequency, nextRunDate, description, lineItems } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      let subtotal = 0;
      if (lineItems) {
        for (const l of lineItems) subtotal += (l.quantity || 1) * (l.unitPrice || 0);
      }
      const taxRate = req.body.taxRate ?? 15;
      const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
      await sql`
        UPDATE recurring_invoices SET
          template_name = COALESCE(${templateName || null}, template_name),
          frequency = COALESCE(${frequency || null}, frequency),
          next_run_date = COALESCE(${nextRunDate || null}, next_run_date),
          description = COALESCE(${description || null}, description),
          line_items = COALESCE(${lineItems ? JSON.stringify(lineItems) : null}::JSONB, line_items),
          subtotal = CASE WHEN ${lineItems ? 'true' : 'false'} = 'true' THEN ${subtotal} ELSE subtotal END,
          tax_amount = CASE WHEN ${lineItems ? 'true' : 'false'} = 'true' THEN ${taxAmount} ELSE tax_amount END,
          total_amount = CASE WHEN ${lineItems ? 'true' : 'false'} = 'true' THEN ${subtotal + taxAmount} ELSE total_amount END,
          updated_at = NOW()
        WHERE id = ${id}::UUID AND company_id = ${companyId} AND status IN ('active', 'paused')
      `;
      log.info('Recurring invoice updated', { id });
      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Recurring invoice update failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Update failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
