/**
 * Journal Entry Service — Facade
 * Re-exports from journalEntryCrudService and journalEntryPostingService
 * for backward compatibility.
 */

export type { JournalEntryFilters } from './journalEntryCrudService';
export {
  getJournalEntries,
  getJournalEntryById,
  createJournalEntry,
  getTrialBalance,
  mapEntryRow,
  mapLineRow,
  resolveUserUuid,
} from './journalEntryCrudService';

export {
  postJournalEntry,
  reverseJournalEntry,
} from './journalEntryPostingService';

/**
 * Journal Entry Posting Service
 * Post and reverse journal entries with fiscal period and balance validation.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateJournalEntry } from '../utils/doubleEntry';
import type { JournalEntry, JournalLineInput } from '../types/gl.types';
import {
  getJournalEntryById,
  createJournalEntry,
  resolveUserUuid,
  mapEntryRow,
} from './journalEntryCrudService';

type Row = Record<string, unknown>;

export async function postJournalEntry(companyId: string, id: string, userId: string): Promise<JournalEntry> {
  try {
    const entry = await getJournalEntryById(companyId, id);
    if (!entry) throw new Error(`Journal entry ${id} not found`);
    if (entry.status !== 'draft') throw new Error(`Cannot post entry with status: ${entry.status}`);

    if (entry.fiscalPeriodId) {
      const period = (await sql`
        SELECT status FROM fiscal_periods WHERE id = ${entry.fiscalPeriodId}
      `) as Row[];
      if (period.length > 0 && String(period[0]!.status) !== 'open') {
        throw new Error(`Cannot post to ${String(period[0]!.status)} fiscal period`);
      }
    }

    if (entry.lines) {
      const validation = validateJournalEntry(entry.lines.map(l => ({
        glAccountId: l.glAccountId,
        debit: l.debit,
        credit: l.credit,
      })));
      if (!validation.valid) throw new Error(`Entry not balanced: ${validation.errors.join('; ')}`);
    }

    const safePostUserId = await resolveUserUuid(userId);
    const rows = (await sql`
      UPDATE gl_journal_entries
      SET status = 'posted', posted_by = ${safePostUserId}::UUID, posted_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];

    log.info('Posted journal entry', { id, entryNumber: String(rows[0]!.entry_number) }, 'accounting');
    return mapEntryRow(rows[0]!);
  } catch (err) {
    log.error('Failed to post journal entry', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reverseJournalEntry(companyId: string, id: string, userId: string): Promise<JournalEntry> {
  try {
    const entry = await getJournalEntryById(companyId, id);
    if (!entry) throw new Error(`Journal entry ${id} not found`);
    if (entry.status !== 'posted') throw new Error('Can only reverse posted entries');
    if (!entry.lines || entry.lines.length === 0) throw new Error('Entry has no lines');

    const reversalLines: JournalLineInput[] = entry.lines.map(l => ({
      glAccountId: l.glAccountId,
      debit: l.credit,
      credit: l.debit,
      description: `Reversal: ${l.description || ''}`,
      projectId: l.projectId,
      costCenterId: l.costCenterId,
    }));

    const reversalEntry = await createJournalEntry(companyId, {
      entryDate: new Date().toISOString().split('T')[0]!,
      description: `Reversal of ${entry.entryNumber}`,
      source: entry.source,
      fiscalPeriodId: entry.fiscalPeriodId,
      lines: reversalLines,
    }, userId);

    await postJournalEntry(companyId, reversalEntry.id, userId);

    await sql`
      UPDATE gl_journal_entries
      SET status = 'reversed', reversed_by = ${userId}::UUID, reversed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
    `;

    await sql`
      UPDATE gl_journal_entries
      SET reversal_of_id = ${id}::UUID
      WHERE id = ${reversalEntry.id} AND company_id = ${companyId}
    `;

    log.info('Reversed journal entry', { originalId: id, reversalId: reversalEntry.id }, 'accounting');
    return reversalEntry;
  } catch (err) {
    log.error('Failed to reverse journal entry', { id, error: err }, 'accounting');
    throw err;
  }
}

/**
 * Journal Entry CRUD Service
 * Create, read, and trial balance operations for GL journal entries.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateJournalEntry } from '../utils/doubleEntry';
import type { JournalEntry, JournalLine, JournalEntryCreateInput, GLEntryStatus, GLEntrySource, TrialBalanceRow, VatType } from '../types/gl.types';

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export async function resolveUserUuid(userId: string): Promise<string> {
  if (UUID_PATTERN.test(userId)) return userId;
  const rows = (await sql`SELECT id FROM users WHERE id::TEXT ~ '^[0-9a-f]{8}-' LIMIT 1`) as { id: string }[];
  return rows.length > 0 ? String(rows[0]!.id) : '00000000-0000-0000-0000-000000000000';
}

type Row = Record<string, unknown>;

export interface JournalEntryFilters {
  status?: GLEntryStatus;
  source?: GLEntrySource;
  fiscalPeriodId?: string;
  limit?: number;
  offset?: number;
}

export function mapEntryRow(row: Row): JournalEntry {
  return {
    id: String(row.id),
    entryNumber: row.entry_number ? String(row.entry_number) : '',
    entryDate: String(row.entry_date),
    fiscalPeriodId: row.fiscal_period_id ? String(row.fiscal_period_id) : undefined,
    description: row.description ? String(row.description) : undefined,
    source: String(row.source) as GLEntrySource,
    sourceDocumentId: row.source_document_id ? String(row.source_document_id) : undefined,
    status: String(row.status) as GLEntryStatus,
    postedBy: row.posted_by ? String(row.posted_by) : undefined,
    postedAt: row.posted_at ? String(row.posted_at) : undefined,
    reversedBy: row.reversed_by ? String(row.reversed_by) : undefined,
    reversedAt: row.reversed_at ? String(row.reversed_at) : undefined,
    reversalOfId: row.reversal_of_id ? String(row.reversal_of_id) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

export function mapLineRow(row: Row): JournalLine {
  return {
    id: String(row.id),
    journalEntryId: String(row.journal_entry_id),
    glAccountId: String(row.gl_account_id),
    debit: Number(row.debit),
    credit: Number(row.credit),
    description: row.description ? String(row.description) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    costCenterId: row.cost_center_id ? String(row.cost_center_id) : undefined,
    vatType: row.vat_type ? String(row.vat_type) as VatType : undefined,
    createdAt: String(row.created_at),
    accountCode: row.account_code ? String(row.account_code) : undefined,
    accountName: row.account_name ? String(row.account_name) : undefined,
  };
}

export async function getJournalEntries(companyId: string, filters?: JournalEntryFilters): Promise<{
  entries: JournalEntry[];
  total: number;
}> {
  try {
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;

    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.fiscalPeriodId) {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.status = ${filters.status}
          AND je.fiscal_period_id = ${filters.fiscalPeriodId}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries
        WHERE company_id = ${companyId} AND status = ${filters.status} AND fiscal_period_id = ${filters.fiscalPeriodId}
          AND source NOT LIKE 'auto_%'
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.status = ${filters.status}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries
        WHERE company_id = ${companyId} AND status = ${filters.status} AND source NOT LIKE 'auto_%'
      `) as Row[];
    } else if (filters?.fiscalPeriodId) {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.fiscal_period_id = ${filters.fiscalPeriodId}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries
        WHERE company_id = ${companyId} AND fiscal_period_id = ${filters.fiscalPeriodId} AND source NOT LIKE 'auto_%'
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries WHERE company_id = ${companyId} AND source NOT LIKE 'auto_%'
      `) as Row[];
    }

    return { entries: rows.map(mapEntryRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get journal entries', { error: err }, 'accounting');
    throw err;
  }
}

export async function getJournalEntryById(companyId: string,
  id: string
): Promise<(JournalEntry & { lines: JournalLine[] }) | null> {
  try {
    const entryRows = (await sql`
      SELECT je.*, fp.period_name AS fiscal_period_name
      FROM gl_journal_entries je
      LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
      WHERE je.id = ${id} AND je.company_id = ${companyId}
    `) as Row[];
    if (entryRows.length === 0) return null;

    const lineRows = (await sql`
      SELECT jl.*, a.account_code, a.account_name
      FROM gl_journal_lines jl
      JOIN gl_accounts a ON a.id = jl.gl_account_id
      WHERE jl.journal_entry_id = ${id}
      ORDER BY jl.created_at
    `) as Row[];

    return { ...mapEntryRow(entryRows[0]!), lines: lineRows.map(mapLineRow) };
  } catch (err) {
    log.error('Failed to get journal entry', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createJournalEntry(companyId: string,
  input: JournalEntryCreateInput,
  userId: string
): Promise<JournalEntry> {
  try {
    const validation = validateJournalEntry(input.lines);
    if (!validation.valid) throw new Error(`Invalid journal entry: ${validation.errors.join('; ')}`);

    let fiscalPeriodId = input.fiscalPeriodId;
    if (!fiscalPeriodId) {
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE start_date <= ${input.entryDate}::DATE AND end_date >= ${input.entryDate}::DATE
        LIMIT 1
      `) as Row[];
      if (periodRows.length > 0) fiscalPeriodId = String(periodRows[0]!.id);
    }

    const safeUserId = await resolveUserUuid(userId);

    const rows = (await sql`
      INSERT INTO gl_journal_entries (
        company_id, entry_date, fiscal_period_id, description, source,
        source_document_id, created_by
      ) VALUES (
        ${companyId}::UUID, ${input.entryDate}, ${fiscalPeriodId || null},
        ${input.description || null}, ${input.source || 'manual'},
        ${input.sourceDocumentId || null}, ${safeUserId}::UUID
      )
      RETURNING *
    `) as Row[];

    const entryRow = rows[0] as Row;
    const entryId = String(entryRow.id);

    for (const line of input.lines) {
      await sql`
        INSERT INTO gl_journal_lines (
          journal_entry_id, gl_account_id, debit, credit,
          description, project_id, cost_center_id, bu_id, vat_type
        ) VALUES (
          ${entryId}::UUID, ${line.glAccountId}::UUID,
          ${line.debit}, ${line.credit},
          ${line.description || null},
          ${line.projectId || null},
          ${line.costCenterId || null},
          ${line.buId || null},
          ${line.vatType || null}
        )
      `;
    }

    log.info('Created journal entry', {
      entryId: String(entryRow.id),
      entryNumber: String(entryRow.entry_number),
      lineCount: input.lines.length,
    }, 'accounting');

    return mapEntryRow(entryRow);
  } catch (err) {
    log.error('Failed to create journal entry', { error: err }, 'accounting');
    throw err;
  }
}

export async function getTrialBalance(companyId: string, fiscalPeriodId: string, costCentreId?: string): Promise<TrialBalanceRow[]> {
  try {
    if (!costCentreId) {
      // Calculate from journal lines directly (not the summary table which may be stale)
      const rows = (await sql`
        SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
          COALESCE(SUM(jl.debit), 0) AS debit_balance,
          COALESCE(SUM(jl.credit), 0) AS credit_balance
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.fiscal_period_id = ${fiscalPeriodId}::UUID
        GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance
        HAVING COALESCE(SUM(jl.debit), 0) != 0 OR COALESCE(SUM(jl.credit), 0) != 0
        ORDER BY ga.account_code
      `) as Row[];
      return rows.map(r => ({
        accountCode: String(r.account_code),
        accountName: String(r.account_name),
        accountType: String(r.account_type),
        normalBalance: String(r.normal_balance) as 'debit' | 'credit',
        debitBalance: Number(r.debit_balance),
        creditBalance: Number(r.credit_balance),
      }));
    }

    const rows = (await sql`
      SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
        COALESCE(SUM(jl.debit), 0) AS total_debit,
        COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.fiscal_period_id = ${fiscalPeriodId}::UUID
        AND jl.cost_center_id = ${costCentreId}::UUID
      GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance
      HAVING COALESCE(SUM(jl.debit), 0) != 0 OR COALESCE(SUM(jl.credit), 0) != 0
      ORDER BY ga.account_code
    `) as Row[];

    return rows.map(r => {
      const net = Number(r.total_debit) - Number(r.total_credit);
      return {
        accountCode: String(r.account_code),
        accountName: String(r.account_name),
        accountType: String(r.account_type),
        normalBalance: String(r.normal_balance) as 'debit' | 'credit',
        debitBalance: net > 0 ? net : 0,
        creditBalance: net < 0 ? Math.abs(net) : 0,
      };
    });
  } catch (err) {
    log.error('Failed to get trial balance', { fiscalPeriodId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * Neon Database Client
 * Standalone serverless PostgreSQL connection for the Accounting app
 * Uses @neondatabase/serverless with retry logic and proper config
 */

import { neon, neonConfig } from '@neondatabase/serverless';
import pg from 'pg';

/** Shared DB row type — import this instead of declaring local `type Row` */
export type DbRow = Record<string, unknown>;
import { log } from '@/lib/logger';

// Enable connection caching for better performance
neonConfig.fetchConnectionCache = true;

// Configure transport for Node.js environments (not in browser/edge)
declare const EdgeRuntime: unknown;

const isNodeEnv =
  typeof window === 'undefined' &&
  typeof EdgeRuntime === 'undefined';

if (isNodeEnv) {
  const useHttpTransport = process.env.NEON_USE_HTTP === 'true';

  if (!useHttpTransport) {
    // WebSocket transport - faster for Node.js
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const ws = require('ws');
      neonConfig.webSocketConstructor = ws;
      log.info('Using WebSocket transport', {}, 'Neon');
    } catch {
      log.info('WebSocket not available, falling back to HTTP', {}, 'Neon');
    }
  } else {
    log.info('Using HTTP transport (NEON_USE_HTTP=true)', {}, 'Neon');
  }

  // Configure WebSocket proxy (Neon v2 protocol)
  neonConfig.wsProxy = (host: string, port: number | string) => `${host}:${port}/v2`;

  // Use secure WebSocket connections
  neonConfig.useSecureWebSocket = true;

  // Pipeline authentication for faster connections
  neonConfig.pipelineConnect = 'password';

  // Enable automatic retries on transient errors
  neonConfig.fetchFunction = async (...args: Parameters<typeof fetch>) => {
    const maxRetries = 3;
    let lastError: unknown;

    for (let i = 0; i < maxRetries; i++) {
      try {
        const response = await fetch(...args);
        if (!response.ok && response.status >= 500 && i < maxRetries - 1) {
          // Retry on server errors with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
        return response;
      } catch (error) {
        lastError = error;
        if (i < maxRetries - 1) {
          // Exponential backoff: 100ms, 200ms, 400ms
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
      }
    }
    throw lastError || new Error('Request failed after retries');
  };
}

/**
 * Get the DATABASE_URL, throwing a clear error if not set
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL is not set. Please configure it in your environment.');
  }
  return url;
}

/**
 * Serverless SQL client for use in API routes and edge functions.
 * Use tagged template literals: sql`SELECT * FROM table WHERE id = ${id}`
 */
export const sql = neon(getDatabaseUrl());

/**
 * Execute multiple queries in a transaction using the Neon serverless driver.
 *
 * IMPORTANT: The Neon HTTP driver is stateless — each tagged template call is an
 * independent HTTP request. Issuing BEGIN/COMMIT as separate calls does NOT
 * guarantee they run on the same connection. We use the official `transaction()`
 * API from @neondatabase/serverless which batches queries into a single HTTP request.
 *
 * @param queries - Array of query-producing functions that receive the sql client
 * @returns Array of query results
 *
 * @example
 * const results = await transaction([
 *   (sql) => sql`INSERT INTO accounts (name) VALUES (${'Cash'}) RETURNING id`,
 *   (sql) => sql`UPDATE balances SET amount = 0 WHERE account_id = ${id}`,
 * ]);
 */
export async function transaction(
  queriesFn: (txSql: typeof sql) => Array<ReturnType<typeof sql>>
): Promise<unknown[]> {
  try {
    // Reuse module-level sql client instead of creating a new neon() client per call
    const results = await sql.transaction(
      (tx) => queriesFn(tx as unknown as typeof sql) as any,
      { isolationLevel: 'ReadCommitted' }
    );
    return results as unknown[];
  } catch (error) {
    log.error(
      'Transaction failed',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

/**
 * Execute a sequential, multi-step transaction using a dedicated pool client.
 *
 * Unlike `transaction()` above (which batches static queries in a single HTTP
 * round-trip), `withTransaction` allows intermediate `await` calls inside the
 * callback — necessary when later queries depend on IDs returned by earlier
 * inserts (INSERT … RETURNING id → INSERT … WHERE fk = id).
 *
 * The pool client issues genuine BEGIN / COMMIT / ROLLBACK, giving full ACID
 * guarantees. Any error thrown inside `fn` triggers an automatic ROLLBACK.
 *
 * @example
 * const invoiceId = await withTransaction(async (tx) => {
 *   const [row] = await tx`INSERT INTO invoices (total) VALUES (${total}) RETURNING id`;
 *   await tx`INSERT INTO invoice_items (invoice_id) VALUES (${row.id})`;
 *   return String(row.id);
 * });
 */
/**
 * Derive a direct (non-pooler) connection URL from the DATABASE_URL.
 * The Neon pooler uses PgBouncer in transaction mode which doesn't support
 * session-level BEGIN/COMMIT via the pg driver. The direct URL bypasses
 * PgBouncer and gives a full PostgreSQL session.
 *
 * Neon pooler hostname: ep-xxx-pooler.region.aws.neon.tech
 * Neon direct hostname: ep-xxx.region.aws.neon.tech
 */
function getDirectUrl(): string {
  const url = getDatabaseUrl();
  // Remove '-pooler' from the hostname and 'channel_binding=require' from query params
  return url.replace('-pooler.', '.').replace('&channel_binding=require', '').replace('?channel_binding=require', '?');
}

let _pgPool: pg.Pool | null = null;

function getPool(): pg.Pool {
  if (!_pgPool) {
    _pgPool = new pg.Pool({
      connectionString: getDirectUrl(),
      max: 5,
      connectionTimeoutMillis: 15000,
      idleTimeoutMillis: 30000,
      ssl: { rejectUnauthorized: false },
    });
    _pgPool.on('error', (err) => {
      log.warn('pg pool background error', { message: err.message }, 'Neon');
    });
  }
  return _pgPool;
}

// Type for a transaction-scoped sql tagged-template function
export type TxSql = (strings: TemplateStringsArray, ...values: unknown[]) => Promise<unknown[]>;

export async function withTransaction<T>(fn: (tx: TxSql) => Promise<T>): Promise<T> {
  const pool = getPool();
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Wrap the pool client's parameterised query as a tagged-template function
    // so callers can use tx`SELECT ...` instead of raw client.query strings.
    const tx: TxSql = async (strings, ...values) => {
      let text = '';
      strings.forEach((s, i) => {
        text += s;
        if (i < values.length) text += `$${i + 1}`;
      });
      const result = await client.query(text, values as unknown[]);
      return result.rows as unknown[];
    };

    const result = await fn(tx);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    log.error(
      'withTransaction rolled back',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  } finally {
    client.release();
  }
}

export default sql;

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Customer Payment Service
 */

import { sql } from '@/lib/neon';
import { randomUUID } from 'crypto';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type {
  CustomerPayment,
  CustomerPaymentAllocation,
  CustomerPaymentCreateInput,
  CustomerPaymentStatus,
} from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

type Row = Record<string, unknown>;

interface PaymentFilters {
  status?: CustomerPaymentStatus;
  clientId?: string;
  limit?: number;
  offset?: number;
}

export async function getCustomerPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: CustomerPayment[];
  total: number;
}> {
  try {
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Record<string, unknown>[];
    let countRows: Record<string, unknown>[];

    if (filters?.clientId) {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.client_id = ${filters.clientId}::UUID AND cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM customer_payments WHERE client_id = ${filters.clientId}::UUID AND company_id = ${companyId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.status = ${filters.status} AND cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM customer_payments WHERE status = ${filters.status} AND company_id = ${companyId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_payments WHERE company_id = ${companyId}`) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get customer payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCustomerPaymentById(companyId: string, 
  id: string
): Promise<(CustomerPayment & { allocations: CustomerPaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT cp.*, c.name AS client_name
      FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
      WHERE cp.id = ${id} AND cp.company_id = ${companyId}
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT cpa.*, ci.invoice_number
      FROM customer_payment_allocations cpa
      LEFT JOIN customer_invoices ci ON ci.id = cpa.invoice_id
      WHERE cpa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createCustomerPayment(companyId: string, 
  input: CustomerPaymentCreateInput,
  userId: string
): Promise<CustomerPayment> {
  try {
    // Validate allocations against invoice balances
    for (const alloc of input.allocations) {
      const invRows = (await sql`
        SELECT total_amount, amount_paid FROM customer_invoices WHERE id = ${alloc.invoiceId}::UUID
      `) as Row[];
      if (invRows.length === 0) throw new Error(`Invoice ${alloc.invoiceId} not found`);
      const balance = Number(invRows[0]!.total_amount) - Number(invRows[0]!.amount_paid);
      if (alloc.amount > balance + 0.01) {
        throw new Error(`Allocation R${alloc.amount.toFixed(2)} exceeds invoice balance R${balance.toFixed(2)}`);
      }
    }

    const totalAllocated = input.allocations.reduce((s, a) => s + a.amount, 0);
    if (Math.abs(totalAllocated - input.totalAmount) > 0.01) {
      throw new Error(`Allocations total R${totalAllocated.toFixed(2)} does not match payment R${input.totalAmount.toFixed(2)}`);
    }

    // Pre-generate UUID so all queries can be batched atomically via HTTP transaction
    const paymentId = randomUUID();

    await sql.transaction((tx) => [
      tx`
        INSERT INTO customer_payments (
          id, company_id, client_id, payment_date, total_amount, payment_method,
          bank_reference, bank_account_id, description, project_id, created_by
        ) VALUES (
          ${paymentId}::UUID, ${companyId}::UUID, ${input.clientId}::UUID, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankReference || null},
          ${input.bankAccountId || null}, ${input.description || null},
          ${input.projectId || null}, ${userId}::UUID
        )
      `,
      ...input.allocations.map(alloc =>
        tx`
          INSERT INTO customer_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `
      ),
    ] as ReturnType<typeof tx>[]);

    const paymentRows = (await sql`SELECT cp.*, c.name AS client_name FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id WHERE cp.id = ${paymentId}::UUID`) as Row[];
    const paymentRow = paymentRows[0]!;

    log.info('Created customer payment', { paymentId, totalAmount: input.totalAmount }, 'accounting');
    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create customer payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function confirmCustomerPayment(companyId: string, 
  id: string,
  userId: string
): Promise<CustomerPayment> {
  try {
    const payment = await getCustomerPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot confirm payment with status: ${payment.status}`);

    // Auto-post GL: DR Bank, CR Accounts Receivable
    const arAccount = await getSystemAccount('receivable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT id FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');
    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      { glAccountId: String(bankAccount.id), debit: payment.totalAmount, credit: 0,
        description: `Customer payment ${payment.paymentNumber}` },
      { glAccountId: arAccount.id, debit: 0, credit: payment.totalAmount,
        description: `Customer payment ${payment.paymentNumber}` },
    ];

    const je = await createJournalEntry(companyId, {
      entryDate: payment.paymentDate,
      description: `Customer payment ${payment.paymentNumber}`,
      source: 'auto_payment',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    // Update invoice balances and mark payment confirmed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}::UUID
        `;
        await tx`
          UPDATE customer_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END, paid_at = CASE WHEN (total_amount - amount_paid) <= 0.01 THEN NOW() ELSE paid_at END
          WHERE id = ${alloc.invoiceId}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE customer_payments
        SET status = 'confirmed', confirmed_by = ${userId}::UUID, confirmed_at = NOW(),
            gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Confirmed customer payment', { id, journalEntryId: je.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to confirm customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCustomerPayment(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CustomerPayment> {
  try {
    const payment = await getCustomerPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'confirmed') {
      throw new Error(`Cannot cancel payment with status: ${payment.status}`);
    }

    // Reverse GL journal entry
    if (payment.glJournalEntryId) {
      await reverseJournalEntry(companyId, payment.glJournalEntryId, userId);
    }

    // Reverse invoice balances + cancel payment atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE customer_invoices
          SET amount_paid = GREATEST(0, amount_paid - ${alloc.amountAllocated}),
              status = CASE
                WHEN GREATEST(0, amount_paid - ${alloc.amountAllocated}) <= 0.01 THEN 'approved'
                WHEN GREATEST(0, amount_paid - ${alloc.amountAllocated}) < total_amount THEN 'partially_paid'
                ELSE status
              END,
              paid_at = CASE WHEN GREATEST(0, amount_paid - ${alloc.amountAllocated}) <= 0.01 THEN NULL ELSE paid_at END
          WHERE id = ${alloc.invoiceId}::UUID AND company_id = ${companyId}
        `;
      }

      return (await tx`
        UPDATE customer_payments
        SET status = 'cancelled', cancelled_by = ${userId}::UUID,
            cancelled_at = NOW(), cancel_reason = ${reason || null}
        WHERE id = ${id} AND company_id = ${companyId} RETURNING *
      `) as Row[];
    }) as Row[];

    log.info('Cancelled customer payment', { id, reason }, 'accounting');
    return mapPaymentRow(updated[0]!);
  } catch (err) {
    log.error('Failed to cancel customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function postCustomerInvoiceToGL(companyId: string, invoiceId: string, userId: string): Promise<string> {
  try {
    const invRows = (await sql`
      SELECT ci.*, c.name AS client_name
      FROM customer_invoices ci LEFT JOIN customers c ON c.id = ci.client_id
      WHERE ci.id = ${invoiceId}::UUID
    `) as Row[];
    if (invRows.length === 0) throw new Error(`Invoice ${invoiceId} not found`);
    const inv = invRows[0]!;

    if (inv.gl_journal_entry_id) return String(inv.gl_journal_entry_id);

    const arAccount = await getSystemAccount('receivable');
    const revenueAccount = await getSystemAccount('default_revenue');
    const vatAccount = await getSystemAccount('vat_output');

    const lines: JournalLineInput[] = [
      { glAccountId: arAccount.id, debit: Number(inv.total_amount), credit: 0,
        description: `AR: ${inv.invoice_number}` },
      { glAccountId: revenueAccount.id, debit: 0, credit: Number(inv.subtotal),
        description: `Revenue: ${inv.invoice_number}` },
    ];

    if (Number(inv.tax_amount) > 0) {
      lines.push({
        glAccountId: vatAccount.id, debit: 0, credit: Number(inv.tax_amount),
        description: `VAT Output: ${inv.invoice_number}`,
      });
    }

    const je = await createJournalEntry(companyId, {
      entryDate: String(inv.invoice_date),
      description: `Customer invoice ${inv.invoice_number}`,
      source: 'auto_invoice',
      sourceDocumentId: invoiceId,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    await sql`UPDATE customer_invoices SET gl_journal_entry_id = ${je.id}::UUID WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID`;

    log.info('Posted customer invoice to GL', { invoiceId, journalEntryId: je.id }, 'accounting');
    return je.id;
  } catch (err) {
    log.error('Failed to post customer invoice to GL', { invoiceId, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): CustomerPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    clientId: String(row.client_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as CustomerPayment['paymentMethod'],
    bankReference: row.bank_reference ? String(row.bank_reference) : undefined,
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as CustomerPaymentStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    confirmedBy: row.confirmed_by ? String(row.confirmed_by) : undefined,
    confirmedAt: row.confirmed_at ? String(row.confirmed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    allocatedAmount: row.allocated_amount !== undefined ? Number(row.allocated_amount) : 0,
  };
}

function mapAllocationRow(row: Row): CustomerPaymentAllocation & { amount: number } {
  const amt = Number(row.amount_allocated || row.amount || 0);
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: amt,
    amount: amt,
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

