  year_label: string;
  start_date: Date | string;
  end_date: Date | string;
  periods_open: number;
  periods_closed: number;
  status: 'open' | 'all_closed';
  total_revenue: number;
  total_expenses: number;
  net_income: number;
}

export interface CloseYearResult {
  closingEntry: Record<string, unknown>;
  netIncome: number;
  message: string;
}

