/**
 * Natural Language Financial Query Service
 * Text-to-SQL with Claude, validation, formatting.
 * Pure business logic — no database dependencies.
 */

export interface SchemaTable {
  name: string;
  columns: string[];
  description: string;
}

export interface ParsedSQL {
  sql: string;
  explanation: string;
}

export interface SQLValidation {
  valid: boolean;
  error?: string;
  sanitizedSQL: string;
}

export type QueryIntent = 'revenue' | 'expense' | 'customer' | 'supplier' | 'cash' | 'tax' | 'payroll' | 'inventory' | 'general';

export interface QueryResult {
  rows: Record<string, unknown>[];
  columns: string[];
  numericColumns: string[];
  summary: string;
  rowCount: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// SCHEMA DESCRIPTION
// ═══════════════════════════════════════════════════════════════════════════

export function buildSchemaDescription(tables: SchemaTable[]): string {
  return tables.map(t =>
    `TABLE: ${t.name} (${t.columns.join(', ')}) — ${t.description}`
  ).join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// TEXT-TO-SQL PROMPT
// ═══════════════════════════════════════════════════════════════════════════

export function buildTextToSQLPrompt(question: string, schemaDesc: string, companyId?: string): string {
  const companyFilter = companyId
    ? `CRITICAL: Every query MUST include WHERE company_id = '${companyId}' on ALL tables that have a company_id column. Never omit this filter — omitting it is a security violation.`
    : '';

  return `You are a South African accounting database assistant. Generate a read-only PostgreSQL SELECT query to answer the user's question.

Database Schema:
${schemaDesc}

User Question: ${question}

Rules:
- Generate ONLY read-only SELECT queries (no INSERT, UPDATE, DELETE, DROP, ALTER, TRUNCATE)
- Use proper SQL aggregation (SUM, COUNT, AVG, etc.) where appropriate
- Use ZAR currency context (South African Rand)
- Format dates as YYYY-MM-DD
- Limit results to 100 rows max unless the user asks for a specific count
- Use table aliases for readability
${companyFilter}

Respond in JSON format:
{"sql": "SELECT ...", "explanation": "Brief explanation of what this query returns"}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// SQL RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

export function parseSQLResponse(response: string): ParsedSQL | null {
  if (!response || response.trim() === '') return null;

  // Try JSON parse first
  try {
    const jsonMatch = response.match(/\{[\s\S]*"sql"[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.sql && typeof parsed.sql === 'string' && parsed.sql.trim().toUpperCase().startsWith('SELECT') || parsed.sql.trim().toUpperCase().startsWith('WITH')) {
        return { sql: parsed.sql.trim(), explanation: String(parsed.explanation || '') };
      }
    }
  } catch { /* not JSON */ }

  // Try SQL code block
  const sqlBlock = response.match(/```(?:sql)?\s*\n?([\s\S]*?)\n?```/);
  if (sqlBlock) {
    const sql = sqlBlock[1]!.trim();
    if (sql.toUpperCase().startsWith('SELECT') || sql.toUpperCase().startsWith('WITH')) {
      const explanationMatch = response.replace(sqlBlock[0], '').trim();
      return { sql, explanation: explanationMatch.slice(0, 200) };
    }
  }

  // Try plain SQL
  const trimmed = response.trim();
  if (trimmed.toUpperCase().startsWith('SELECT') || trimmed.toUpperCase().startsWith('WITH')) {
    return { sql: trimmed, explanation: '' };
  }

  return null;
}

// ═══════════════════════════════════════════════════════════════════════════
// SQL VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

// DML/DDL keywords that must never appear in a read-only query
const FORBIDDEN_KEYWORDS = [
  'INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE', 'CREATE',
  'GRANT', 'REVOKE', 'EXEC', 'EXECUTE', 'UNION', 'INFORMATION_SCHEMA',
  'PG_CATALOG', 'INTO OUTFILE', 'LOAD_FILE',
  // PostgreSQL administrative / file-access / control keywords
  'COPY', 'DO', 'CALL', 'PREPARE', 'LISTEN', 'NOTIFY', 'LOAD', 'IMPORT',
  // PostgreSQL file-access and server-control functions
  'PG_READ_FILE', 'PG_READ_BINARY_FILE', 'PG_LS_DIR',
  'LO_IMPORT', 'LO_EXPORT', 'PG_SLEEP',
  // Runtime configuration manipulation
  'CURRENT_SETTING', 'SET_CONFIG', 'PG_TERMINATE_BACKEND', 'PG_CANCEL_BACKEND',
  // Additional hardening — admin surface
  'VACUUM', 'EXPLAIN',
];

// Dangerous function-call patterns that warrant a separate regex sweep
const FORBIDDEN_PATTERNS: Array<{ label: string; regex: RegExp }> = [
  // Any pg_ identifier (function call or schema prefix — covers pg_read_file, pg_catalog, etc.)
  { label: 'pg_ reference', regex: /\bpg_/i },
  // information_schema reference
  { label: 'information_schema reference', regex: /\binformation_schema\b/i },
  // dblink — cross-database tunnelling
  { label: 'dblink call', regex: /\bdblink\s*\(/i },
  // COPY with TO or FROM (data exfiltration / injection)
  { label: 'COPY TO/FROM', regex: /\bCOPY\b[\s\S]*?\b(TO|FROM)\b/i },
  // SET statement (session variable manipulation)
  { label: 'SET statement', regex: /\bSET\s+\w/i },
  // Dollar-quoted DO blocks
  { label: 'DO $$ block', regex: /\bDO\s*\$\$/i },
];

// Tables that NL queries are permitted to access — accounting & business data
const ALLOWED_TABLES = new Set([
  // General ledger
  'gl_journal_entries', 'gl_journal_lines', 'gl_accounts', 'gl_account_balances',
  'recurring_journals',
  // Customers
  'customers', 'customer_invoices', 'customer_invoice_items',
  'customer_payments', 'customer_payment_allocations',
  'customer_quotes', 'customer_quote_lines',
  'customer_sales_orders', 'customer_sales_order_items',
  'customer_write_offs', 'customer_categories', 'credit_notes',
  'recurring_invoices', 'dunning_communications',
  // Suppliers
  'suppliers', 'supplier_invoices', 'supplier_invoice_items',
  'supplier_payments', 'supplier_payment_allocations', 'supplier_payment_batches',
  'supplier_purchase_orders', 'supplier_purchase_order_items',
  'purchase_orders', 'supplier_categories',
  // Banking
  'bank_transactions', 'bank_accounts', 'bank_reconciliations',
  'bank_categorisation_rules', 'bank_import_batches',
  // Items & inventory
  'items', 'item_categories', 'stock_items', 'stock_adjustments',
  'products', 'product_categories',
  // Tax & compliance
  'vat_returns', 'vat_adjustments', 'sars_submissions',
  // Assets
  'assets', 'asset_categories', 'asset_depreciation_schedule', 'asset_disposals',
  // Periods & budgets
  'fiscal_periods', 'accounting_budgets', 'currencies', 'exchange_rates',
  // Projects & time
  'projects', 'project_time_entries', 'time_entries',
  // Cost centres & business units
  'cost_centres', 'business_units',
  // Payroll (read-only summaries)
  'payroll_runs', 'payslips', 'employees', 'leave_types',
  'leave_balances', 'leave_applications',
  // Documents
  'captured_documents',
]);

const MAX_LIMIT = 100;

export function validateGeneratedSQL(sql: string): SQLValidation {
  if (!sql || sql.trim() === '') {
    return { valid: false, error: 'Empty SQL', sanitizedSQL: '' };
  }

  const upper = sql.toUpperCase().trim();

  // Must start with SELECT or WITH
  if (!upper.startsWith('SELECT') && !upper.startsWith('WITH')) {
    return { valid: false, error: 'Query must be a SELECT statement', sanitizedSQL: '' };
  }

  // Check for forbidden keywords using word-boundary, case-insensitive match
  for (const kw of FORBIDDEN_KEYWORDS) {
    const regex = new RegExp(`\\b${kw}\\b`, 'i');
    if (regex.test(sql)) {
      return { valid: false, error: `Forbidden keyword: ${kw}`, sanitizedSQL: '' };
    }
  }

  // Check for dangerous function-call patterns
  for (const { label, regex } of FORBIDDEN_PATTERNS) {
    if (regex.test(sql)) {
      return { valid: false, error: `Forbidden pattern detected: ${label}`, sanitizedSQL: '' };
    }
  }

  // Reject any semicolons — prevents stacked queries entirely
  if (sql.includes(';')) {
    return { valid: false, error: 'Multiple statements not allowed', sanitizedSQL: '' };
  }

  // Extract CTE aliases so they pass the table allowlist
  const cteAliases = new Set<string>();
  const ctePattern = /\bWITH\s+(\w+)\s+AS\b/gi;
  let cteMatch: RegExpExecArray | null;
  while ((cteMatch = ctePattern.exec(sql)) !== null) {
    cteAliases.add(cteMatch[1]!.toLowerCase());
  }

  // Table allowlist — only accounting tables (and CTE aliases) may appear in FROM / JOIN clauses
  const tablePattern = /(?:FROM|JOIN)\s+(\w+)/gi;
  let tableMatch: RegExpExecArray | null;
  while ((tableMatch = tablePattern.exec(sql)) !== null) {
    const tableName = tableMatch[1]!.toLowerCase();
    if (!ALLOWED_TABLES.has(tableName) && !cteAliases.has(tableName)) {
      return { valid: false, error: `Table '${tableMatch[1]}' not allowed`, sanitizedSQL: '' };
    }
  }

  // Add LIMIT if not present
  let sanitizedSQL = sql.trim().replace(/;$/, '');
  if (!/\bLIMIT\b/i.test(sanitizedSQL)) {
    sanitizedSQL += ` LIMIT ${MAX_LIMIT}`;
  }

  return { valid: true, sanitizedSQL };
}

// ═══════════════════════════════════════════════════════════════════════════
// QUERY INTENT CLASSIFICATION
// ═══════════════════════════════════════════════════════════════════════════

const INTENT_PATTERNS: Array<{ intent: QueryIntent; patterns: RegExp[] }> = [
  { intent: 'revenue', patterns: [/\brevenue\b/i, /\bsales\b/i, /\bincome\b/i, /\bturnover\b/i, /\bbilling\b/i] },
  { intent: 'expense', patterns: [/\bexpens/i, /\bcost\b/i, /\bspend/i, /\bpurchas/i] },
  { intent: 'customer', patterns: [/\bcustomer/i, /\bclient/i, /\bdebtor/i, /\breceivable/i] },
  { intent: 'supplier', patterns: [/\bsupplier/i, /\bvendor/i, /\bcreditor/i, /\bpayable/i] },
  { intent: 'cash', patterns: [/\bcash\b/i, /\bbank\b/i, /\bbalance\b/i, /\bliquidity/i] },
  { intent: 'tax', patterns: [/\bvat\b/i, /\btax\b/i, /\bsars\b/i, /\bpaye\b/i] },
  { intent: 'payroll', patterns: [/\bpayroll\b/i, /\bsalary\b/i, /\bwage/i, /\bemploee/i] },
  { intent: 'inventory', patterns: [/\binventory\b/i, /\bstock\b/i, /\bproduct/i] },
];

export function classifyQueryIntent(question: string): QueryIntent {
  for (const { intent, patterns } of INTENT_PATTERNS) {
    if (patterns.some(p => p.test(question))) return intent;
  }
  return 'general';
}

// ═══════════════════════════════════════════════════════════════════════════
// RESULT FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

export function formatQueryResult(rows: Record<string, unknown>[], question: string): QueryResult {
  if (!rows || rows.length === 0) {
    return { rows: [], columns: [], numericColumns: [], summary: 'No results found for your query.', rowCount: 0 };
  }

  const columns = Object.keys(rows[0]!);
  const numericColumns = columns.filter(col =>
    rows.some(r => typeof r[col] === 'number' || (typeof r[col] === 'string' && !isNaN(Number(r[col])) && r[col] !== ''))
  );

  let summary: string;
  if (rows.length === 1 && columns.length === 1) {
    const value = rows[0]![columns[0]!];
    summary = `Result: ${value}`;
  } else if (rows.length === 1) {
    summary = columns.map(c => `${c}: ${rows[0]![c]}`).join(', ');
  } else {
    summary = `${rows.length} result${rows.length === 1 ? '' : 's'} returned.`;
  }

  return { rows, columns, numericColumns, summary, rowCount: rows.length };
}

/**
 * Natural Language Financial Query API
 * POST: ask a question in plain English, get data back
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, withWriteAccess} from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { checkRateLimit } from '@/lib/rateLimit';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';
import {
  buildTextToSQLPrompt, parseSQLResponse, validateGeneratedSQL,
  formatQueryResult, buildSchemaDescription, classifyQueryIntent,
  type SchemaTable,
} from '@/modules/accounting/services/nlQueryService';

type Row = Record<string, unknown>;

const SCHEMA_TABLES: SchemaTable[] = [
  { name: 'customer_invoices', columns: ['id', 'customer_id', 'invoice_number', 'invoice_date', 'due_date', 'total_amount', 'amount_paid', 'status', 'company_id'], description: 'Customer/sales invoices' },
  { name: 'customers', columns: ['id', 'name', 'email', 'payment_terms', 'is_active', 'company_id'], description: 'Customer master data' },
  { name: 'supplier_invoices', columns: ['id', 'supplier_id', 'invoice_number', 'invoice_date', 'total_amount', 'amount_paid', 'status', 'company_id'], description: 'Supplier/purchase invoices' },
  { name: 'suppliers', columns: ['id', 'name', 'email', 'is_active', 'company_id'], description: 'Supplier master data' },
  { name: 'gl_accounts', columns: ['id', 'account_code', 'account_name', 'account_type', 'is_active', 'company_id'], description: 'Chart of accounts (GL)' },
  { name: 'gl_journal_entries', columns: ['id', 'entry_number', 'entry_date', 'description', 'status', 'source'], description: 'Journal entries' },
  { name: 'gl_journal_lines', columns: ['id', 'journal_entry_id', 'gl_account_id', 'debit', 'credit', 'description'], description: 'Journal entry lines (debits/credits)' },
  { name: 'bank_transactions', columns: ['id', 'bank_account_id', 'date', 'description', 'amount', 'category', 'is_reconciled'], description: 'Imported bank transactions' },
  { name: 'products', columns: ['id', 'code', 'name', 'cost_price', 'selling_price', 'current_stock', 'company_id'], description: 'Products/inventory items' },
  { name: 'employees', columns: ['id', 'first_name', 'last_name', 'email', 'basic_salary', 'employment_type', 'company_id'], description: 'Employee master data' },
  { name: 'payslips', columns: ['id', 'employee_id', 'payroll_run_id', 'gross_pay', 'net_pay', 'paye', 'uif_employee'], description: 'Payslips per payroll run' },
  { name: 'projects', columns: ['id', 'project_number', 'name', 'client_id', 'status', 'budget_amount', 'total_revenue', 'total_cost'], description: 'Projects/jobs' },
];

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() || req.socket.remoteAddress || 'unknown';
  if (checkRateLimit(`nl-query:${ip}`, { maxRequests: 30, windowMs: 15 * 60 * 1000 })) {
    return res.status(429).json({ success: false, error: 'Rate limit exceeded' });
  }

  const { question } = req.body;
  if (!question || typeof question !== 'string' || question.trim().length < 3) {
    return apiResponse.badRequest(res, 'Please ask a question (minimum 3 characters)');
  }
  if (question.length > 500) {
    return apiResponse.badRequest(res, 'Question is too long (maximum 500 characters)');
  }

  const companyId = (req as CompanyApiRequest).companyId;
  const intent = classifyQueryIntent(question);
  const schemaDesc = buildSchemaDescription(SCHEMA_TABLES);
  const prompt = buildTextToSQLPrompt(question, schemaDesc, companyId);

  // Call Claude
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return apiResponse.success(res, {
      intent,
      message: 'Natural language queries require ANTHROPIC_API_KEY to be configured.',
      rows: [], columns: [], summary: 'AI not configured',
    });
  }

  try {
    const aiAbort = new AbortController();
    const aiTimeout = setTimeout(() => aiAbort.abort(), 10_000);
    let response: Response;
    try {
      response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
        },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 512,
          messages: [{ role: 'user', content: prompt }],
        }),
        signal: aiAbort.signal,
      });
    } finally {
      clearTimeout(aiTimeout);
    }

    if (!response.ok) {
      return apiResponse.success(res, { intent, message: 'AI service unavailable', rows: [], columns: [], summary: 'Service error' });
    }

    const data = await response.json() as { content?: { text?: string }[] };
    const text = data.content?.[0]?.text || '';
    const parsed = parseSQLResponse(text);

    if (!parsed) {
      return apiResponse.success(res, { intent, message: 'Could not generate a query for that question.', explanation: text, rows: [], columns: [], summary: 'Unable to parse' });
    }

    // Validate SQL
    const validation = validateGeneratedSQL(parsed.sql);
    if (!validation.valid) {
      return apiResponse.success(res, { intent, message: `Generated SQL was rejected: ${validation.error}`, rows: [], columns: [], summary: 'Query rejected' });
    }

    // Verify company_id appears in an actual "company_id = '<uuid>'" predicate,
    // not just anywhere in the string (e.g. a comment, alias, or lucky substring).
    const scopeRegex = new RegExp(`company_id\\s*=\\s*'${companyId}'`, 'i');
    if (!scopeRegex.test(validation.sanitizedSQL)) {
      log.warn('NL query missing company_id scope — rejected', { question, companyId }, 'ai');
      return apiResponse.success(res, { intent, message: 'Could not generate a properly scoped query. Please try again.', rows: [], columns: [], summary: 'Scope error' });
    }

    // Execute inside a transaction so SET LOCAL applies to the same connection.
    // Neon HTTP driver is stateless — each top-level sql`` call is a separate
    // HTTP request, so a bare SET statement_timeout would have no effect on the
    // next call.  sql.transaction() batches both statements into a single HTTP
    // request, guaranteeing SET LOCAL is honoured for the query that follows it.
    const [, rows] = await sql.transaction(
      (txn) => [
        txn`SET LOCAL statement_timeout = '5000'`,
        txn.unsafe(validation.sanitizedSQL) as any,
      ]
    ) as [unknown, Row[]];
    const formatted = formatQueryResult(rows as Record<string, unknown>[], question);

    log.info('NL query executed', { question, intent, rowCount: formatted.rowCount }, 'ai');

    return apiResponse.success(res, {
      intent,
      question,
      sql: validation.sanitizedSQL,
      explanation: parsed.explanation,
      ...formatted,
    });
  } catch (err) {
    log.error('NL query failed', { error: err }, 'ai');
    return apiResponse.success(res, { intent, message: 'Query execution failed', rows: [], columns: [], summary: 'Error' });
  }
}

export default withCompany(withErrorHandler(withWriteAccess(handler)));

