    `;
  }
  // Pass 2: wire parents
  for (const acc of COA_TEMPLATE.filter(a => a.parentCode)) {
    await sql`
      UPDATE gl_accounts
      SET parent_account_id = (
        SELECT id FROM gl_accounts WHERE company_id = ${companyId}::uuid AND account_code = ${acc.parentCode!}
      )
