export async function createJournalEntry(companyId: string,
  input: JournalEntryCreateInput,
  userId: string
): Promise<JournalEntry> {
  try {
    const validation = validateJournalEntry(input.lines);
    if (!validation.valid) throw new Error(`Invalid journal entry: ${validation.errors.join('; ')}`);

    let fiscalPeriodId = input.fiscalPeriodId;
    if (!fiscalPeriodId) {
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE start_date <= ${input.entryDate}::DATE AND end_date >= ${input.entryDate}::DATE
        LIMIT 1
      `) as Row[];
      if (periodRows.length > 0) fiscalPeriodId = String(periodRows[0]!.id);
    }

    const safeUserId = await resolveUserUuid(userId);

    const rows = (await sql`
      INSERT INTO gl_journal_entries (
        company_id, entry_date, fiscal_period_id, description, source,
        source_document_id, created_by
      ) VALUES (
        ${companyId}::UUID, ${input.entryDate}, ${fiscalPeriodId || null},
        ${input.description || null}, ${input.source || 'manual'},
        ${input.sourceDocumentId || null}, ${safeUserId}::UUID
      )
      RETURNING *
    `) as Row[];

    const entryRow = rows[0] as Row;
    const entryId = String(entryRow.id);

    for (const line of input.lines) {
      await sql`
        INSERT INTO gl_journal_lines (
          journal_entry_id, gl_account_id, debit, credit,
          description, project_id, cost_center_id, bu_id, vat_type
        ) VALUES (
          ${entryId}::UUID, ${line.glAccountId}::UUID,
          ${line.debit}, ${line.credit},
          ${line.description || null},
          ${line.projectId || null},
          ${line.costCenterId || null},
          ${line.buId || null},
          ${line.vatType || null}
        )
      `;
    }

    log.info('Created journal entry', {
      entryId: String(entryRow.id),
      entryNumber: String(entryRow.entry_number),
      lineCount: input.lines.length,
    }, 'accounting');

    return mapEntryRow(entryRow);
  } catch (err) {
    log.error('Failed to create journal entry', { error: err }, 'accounting');
    throw err;
  }
}

export async function getTrialBalance(companyId: string, fiscalPeriodId: string, costCentreId?: string): Promise<TrialBalanceRow[]> {
  try {
    if (!costCentreId) {
      // Calculate from journal lines directly (not the summary table which may be stale)
      const rows = (await sql`
        SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
          COALESCE(SUM(jl.debit), 0) AS debit_balance,
          COALESCE(SUM(jl.credit), 0) AS credit_balance
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.fiscal_period_id = ${fiscalPeriodId}::UUID
        GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance

export async function createAdjustment(companyId: string, 
  input: AdjustmentCreateInput,
  userId: string
): Promise<AccountingAdjustment> {
  const rows = (await sql`
    INSERT INTO accounting_adjustments (
      company_id, entity_type, entity_id, adjustment_type, amount, reason,
      adjustment_date, created_by
    ) VALUES (
      ${companyId}, ${input.entityType}, ${input.entityId}::UUID, ${input.adjustmentType},
      ${input.amount}, ${input.reason},
      ${input.adjustmentDate || new Date().toISOString().split('T')[0]},
      ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created adjustment', { id: rows[0]?.id, type: input.entityType }, 'accounting');
  return mapRow(rows[0]!);
}

export async function approveAdjustment(companyId: string, id: string, userId: string): Promise<AccountingAdjustment> {
  const adjRows = (await sql`SELECT * FROM accounting_adjustments WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!adjRows[0]) throw new Error('Adjustment not found');
  if (adjRows[0].status !== 'draft') throw new Error('Adjustment is not in draft status');

  const adj = adjRows[0];
  const amount = Number(adj.amount);
  const isCustomer = adj.entity_type === 'customer';
  const isDebit = adj.adjustment_type === 'debit';

  // GL accounts
  const balanceAccount = isCustomer
    ? await getSystemAccount('receivable')
    : await getSystemAccount('payable');
  const offsetAccount = isDebit
    ? await getSystemAccount('other_income')
    : await getSystemAccount('admin_expense');

  const lines: JournalLineInput[] = isDebit
    ? [
        { glAccountId: balanceAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: offsetAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ]
    : [
        { glAccountId: offsetAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: balanceAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ];

  const je = await createJournalEntry(companyId, {
    entryDate: String(adj.adjustment_date),
    description: `${isCustomer ? 'Customer' : 'Supplier'} adjustment ${adj.adjustment_number}`,
    source: 'auto_adjustment',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const updated = (await sql`
    UPDATE accounting_adjustments
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved adjustment', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelAdjustment(companyId: string, id: string): Promise<void> {
  await sql`UPDATE accounting_adjustments SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
}

function mapRow(row: Row): AccountingAdjustment {
  return {
    id: String(row.id),
    adjustmentNumber: row.adjustment_number ? String(row.adjustment_number) : '',

