/**
 * Receipt-to-Journal API
 * POST /api/accounting/receipt-to-journal
 * Body: { documentId } or multipart file upload
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  validateReceiptExtraction,
  mapMerchantToExpenseAccount,
  buildExpenseJournalFromReceipt,
  shouldAutoPostReceipt,
  parseReceiptType,
} from '@/modules/accounting/services/receiptToJournalService';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);

  const { companyId } = req;
  const userId: string = req.user?.id || req.user?.userId || '';
  const { documentId } = req.body as { documentId?: string };

  if (!documentId) return apiResponse.badRequest(res, 'documentId is required');

  // Fetch captured document
  const [doc] = (await sql`
    SELECT extracted_data, status FROM captured_documents
    WHERE id = ${documentId}::uuid AND company_id = ${companyId}
  `) as Row[];

  if (!doc) return apiResponse.notFound(res, 'Captured document', documentId);
  if (!doc.extracted_data) return apiResponse.badRequest(res, 'Document has no extracted data');

  const extracted = doc.extracted_data as ExtractedDocument;

  // Validate
  const validation = validateReceiptExtraction(extracted);
  if (!validation.valid) {
    return apiResponse.badRequest(res, `Validation failed: ${validation.errors.join(', ')}`);
  }

  // Get GL accounts
  const glAccounts = (await sql`
    SELECT id, account_code as code, account_name as name
    FROM gl_accounts WHERE company_id = ${companyId}
    ORDER BY account_code
  `) as Row[];

  // Map merchant to expense account
  const accountSuggestion = extracted.vendorName
    ? mapMerchantToExpenseAccount(extracted.vendorName, glAccounts.map(a => ({ id: a.id, code: a.code, name: a.name })))
    : null;

  const expenseAccountId = accountSuggestion?.id || glAccounts.find(a => a.code === '5100')?.id;
  const vatInputAccountId = glAccounts.find(a => a.code === '1140')?.id;
  const bankAccountId = glAccounts.find(a => a.code === '1110')?.id;

  if (!expenseAccountId || !vatInputAccountId || !bankAccountId) {
    return apiResponse.badRequest(res, 'Required GL accounts not found (expense, VAT input, bank)');
  }

  // Build journal entry
  const journalInput = buildExpenseJournalFromReceipt(extracted, { expenseAccountId, vatInputAccountId, bankAccountId });
  const receiptType = parseReceiptType(extracted);
  const autoPost = shouldAutoPostReceipt(extracted.totalAmount || 0, extracted.confidence, { maxAmount: 5000, minConfidence: 0.85 });

  // Get fiscal period
  const [period] = (await sql`
    SELECT id FROM fiscal_periods
    WHERE company_id = ${companyId} AND start_date <= ${journalInput.entryDate}::date AND end_date >= ${journalInput.entryDate}::date
    LIMIT 1
  `) as Row[];

  // Create journal entry
  const [je] = (await sql`
    INSERT INTO gl_journal_entries (
      company_id, entry_date, fiscal_period_id, description, source, status, created_by
    ) VALUES (
      ${companyId}, ${journalInput.entryDate}::date, ${period?.id || null}::uuid,
      ${journalInput.description}, 'auto_invoice',
      ${autoPost ? 'posted' : 'draft'}, ${userId}
    ) RETURNING id, status
  `) as Row[];

  if (!je) return apiResponse.internalError(res, null, 'Failed to create journal entry');

  // Create journal lines
  for (const line of journalInput.lines) {
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${je.id}::uuid, ${line.accountId}::uuid, ${line.debit}, ${line.credit}, ${line.description})
    `;
  }

  // Link document
  await sql`
    UPDATE captured_documents SET status = 'matched' WHERE id = ${documentId}::uuid AND company_id = ${companyId}
  `;

  log.info('Receipt-to-Journal completed', {
    documentId, journalId: je.id, receiptType, autoPost,
    amount: extracted.totalAmount, merchant: extracted.vendorName,
  }, 'receipt-journal');

  return apiResponse.success(res, {
    journalEntry: { id: je.id, status: je.status },
    receiptType,
    accountSuggestion: accountSuggestion ? { code: accountSuggestion.code, name: accountSuggestion.name } : null,
    autoPosted: autoPost,
    amount: extracted.totalAmount,
    warnings: validation.warnings,

/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;


async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  try {
    const userId = String(req.user?.id || 'system');

    // Calculate totals
    const rate = taxRate ?? 15;
    let subtotal = 0;
    for (const item of items) {
      subtotal += (item.quantity || 1) * item.unitPrice;
    }
    subtotal = Math.round(subtotal * 100) / 100;
    const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
    const totalAmount = subtotal + taxAmount;

    const today = new Date().toISOString().split('T')[0];
    const invDate = invoiceDate || today;
    const bpStart = billingPeriodStart || null;
    const bpEnd = billingPeriodEnd || null;

    // Find project from client (optional)
    let projectId: string | null = null;
    try {
      const projRows = (await sql`SELECT id FROM projects WHERE client_id = ${clientId}::UUID LIMIT 1`) as Row[];
      projectId = (projRows[0]?.['id'] as string | undefined) ?? null;
    } catch { /* projects table may not exist */ }

    // Insert invoice with retry on unique-constraint violation.
    // MAX()+1 races under concurrent load — if we collide, re-read MAX and try again
    // (up to 5 times with escalating offset so the series stays monotonic).
    let invoiceId = '';
    let invoiceNumber = '';
    for (let attempt = 0; attempt < 5; attempt++) {
      const maxRows = (await sql`
        SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)), 0) AS max_num
        FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number ~ '^INV-[0-9]+$'
      `) as Row[];
      const base = Number(maxRows[0]?.['max_num'] ?? 0) + 1 + attempt;
      invoiceNumber = `INV-${String(base).padStart(5, '0')}`;

      try {
        const invRows = (await sql`
          INSERT INTO customer_invoices (
            company_id, invoice_number, project_id, customer_id, client_id, billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
            notes, status, created_by
          ) VALUES (
            ${companyId}, ${invoiceNumber}, ${projectId}, ${clientId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
            ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
            ${dueDate || null}, ${notes || null}, 'draft', ${userId}
          ) RETURNING id
        `) as Row[];
        invoiceId = String(invRows[0]!.id);
        break;
      } catch (insertErr) {
        const msg = insertErr instanceof Error ? insertErr.message : String(insertErr);
        if (msg.includes('unique') && attempt < 4) continue;
        throw insertErr;
      }
    }

    for (const item of items) {
      const qty = item.quantity || 1;
      const lineAmount = Math.round(qty * item.unitPrice * 100) / 100;
      await sql`
        INSERT INTO customer_invoice_items (invoice_id, description, unit_price, quantity, amount, tax_rate)
        VALUES (${invoiceId}::UUID, ${item.description}, ${item.unitPrice}, ${qty}, ${lineAmount}, ${rate})
      `;
    }

    log.info('Customer invoice created', { invoiceNumber, totalAmount });
    return apiResponse.created(res, { id: invoiceId, invoiceNumber });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Invoice create failed', { error: msg });
    const clientMessage = process.env.NODE_ENV === 'development' ? msg : 'Failed to create invoice';
    return res.status(500).json({ success: false, error: { code: 'CREATE_FAILED', message: clientMessage } });
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

