  fiscalPeriodId: periods[0]?.id ?? null,
  periodStart: yearAgo,
  periodEnd: today,
  // withCompany resolves to admin's default (ISAFlow Demo) regardless of URL companyId.
  // Use a known account code from ISAFlow Demo so acct-exp always gets a valid account.
  glAccountCode: '4310',
  asAtDate: today,
};

