// Check what the neon transaction() API actually expects
const { neon } = await import('/home/hein/Workspace/IsaFlow/node_modules/@neondatabase/serverless/index.mjs');
const { readFileSync } = await import('fs');

const envContent = readFileSync('/home/hein/Workspace/IsaFlow/.env.local', 'utf-8');
const DATABASE_URL = envContent.match(/^DATABASE_URL=(.+)$/m)[1].trim();
const sql = neon(DATABASE_URL);

const testSQL = `SELECT c.id, c.name, SUM(ci.total_amount) as total_invoiced, (SUM(ci.total_amount) - SUM(ci.amount_paid)) as outstanding_balance FROM customers c LEFT JOIN customer_invoices ci ON c.id = ci.customer_id AND ci.company_id = '00000000-0000-0000-0000-000000000001' WHERE c.company_id = '00000000-0000-0000-0000-000000000001' AND c.is_active = true GROUP BY c.id, c.name HAVING (SUM(ci.total_amount) - SUM(ci.amount_paid)) > 0 ORDER BY outstanding_balance DESC LIMIT 5`;

// The handler calls: sql.transaction((txn) => [...]) 
// But neon's transaction() API:
