/**
 * WidgetGrid — Responsive 3-column grid that renders configured widgets.
 * // WORKING: Edit mode, add/remove widgets, reset to default layout.
 */

import { useState, useCallback } from 'react';
import { Plus, RotateCcw, GripVertical, X } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  type WidgetConfig,
  type WidgetType,
  WIDGET_SIZE_CLASS,
  WIDGET_CATALOGUE,
  DEFAULT_WIDGET_LAYOUT,
} from './widgetTypes';
import { BankSummaryWidget } from './widgets/BankSummaryWidget';
import { InvoicesOwedWidget } from './widgets/InvoicesOwedWidget';
import { BillsToPayWidget } from './widgets/BillsToPayWidget';
import { QuickActionsWidget } from './widgets/QuickActionsWidget';
import { RecentActivityWidget } from './widgets/RecentActivityWidget';
import { PnlSnapshotWidget } from './widgets/PnlSnapshotWidget';
import { VatSummaryWidget } from './widgets/VatSummaryWidget';

// ---------------------------------------------------------------------------
// Widget renderer
// ---------------------------------------------------------------------------

function renderWidget(type: WidgetType): React.ReactNode {
  switch (type) {
    case 'bank-summary':     return <BankSummaryWidget />;
    case 'invoices-owed':    return <InvoicesOwedWidget />;
    case 'bills-to-pay':     return <BillsToPayWidget />;
    case 'quick-actions':    return <QuickActionsWidget />;
    case 'recent-activity':  return <RecentActivityWidget />;
    case 'pnl-snapshot':     return <PnlSnapshotWidget />;
    case 'vat-summary':      return <VatSummaryWidget />;
    default:
      return (
        <Card>
          <p className="text-sm text-gray-500 dark:text-gray-400 capitalize">
            {type.replace(/-/g, ' ')} widget coming soon.
          </p>
        </Card>
      );
  }
}

// ---------------------------------------------------------------------------
// Add Widget Modal
// ---------------------------------------------------------------------------

interface AddWidgetModalProps {
  onAdd: (type: WidgetType, size: WidgetConfig['size']) => void;
  onClose: () => void;
  existingTypes: WidgetType[];
}

function AddWidgetModal({ onAdd, onClose, existingTypes }: AddWidgetModalProps) {
  const available = WIDGET_CATALOGUE.filter(w => !existingTypes.includes(w.type));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} aria-hidden="true" />
      <div className="relative z-10 w-full max-w-md mx-4 bg-white dark:bg-gray-900 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100">Add Widget</h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-md text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {available.length === 0 ? (
          <p className="text-sm text-gray-500 dark:text-gray-400">All available widgets are already on your dashboard.</p>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {available.map(w => (
              <button
                key={w.type}
                onClick={() => { onAdd(w.type, w.size); onClose(); }}
                className="flex flex-col items-start gap-1 p-3 rounded-lg border border-gray-200 dark:border-gray-700 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/20 transition-colors text-left"
              >
                <span className="text-sm font-medium text-gray-900 dark:text-gray-100">{w.title}</span>
                <span className="text-xs text-gray-500 dark:text-gray-400 capitalize">{w.size} size</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// WidgetGrid
// ---------------------------------------------------------------------------

interface WidgetGridProps {
  widgets: WidgetConfig[];
  editMode: boolean;
  onLayoutChange: (widgets: WidgetConfig[]) => void;
}

export function WidgetGrid({ widgets, editMode, onLayoutChange }: WidgetGridProps) {
  const [showAddModal, setShowAddModal] = useState(false);

  const handleRemove = useCallback((id: string) => {
    onLayoutChange(widgets.filter(w => w.id !== id));
  }, [widgets, onLayoutChange]);

  const handleAdd = useCallback((type: WidgetType, size: WidgetConfig['size']) => {
    const newWidget: WidgetConfig = {
      id: `${type}-${Date.now()}`,
      type,
      title: WIDGET_CATALOGUE.find(w => w.type === type)?.title ?? type,
      size,
    };
    onLayoutChange([...widgets, newWidget]);
  }, [widgets, onLayoutChange]);

  const handleReset = useCallback(() => {
    onLayoutChange(DEFAULT_WIDGET_LAYOUT);
  }, [onLayoutChange]);

  const existingTypes = widgets.map(w => w.type);

  return (
    <div className="space-y-4">
      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {widgets.map(widget => (
          <div
            key={widget.id}
            className={`relative ${WIDGET_SIZE_CLASS[widget.size]}`}
          >
            {/* Drag handle (visual only) */}
            {editMode && (
              <div className="absolute top-2 left-2 z-10 p-1 rounded cursor-grab text-gray-400 dark:text-gray-500">
                <GripVertical className="h-4 w-4" />
              </div>
            )}
            {/* Remove button */}
            {editMode && (
              <button
                onClick={() => handleRemove(widget.id)}
                className="absolute top-2 right-2 z-10 p-1 rounded-full bg-red-100 dark:bg-red-900/30 text-red-500 hover:bg-red-200 dark:hover:bg-red-900/60 transition-colors"
                aria-label={`Remove ${widget.title} widget`}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
            {/* Widget content */}
            <div className={editMode ? 'opacity-80 pointer-events-none select-none' : ''}>
              {renderWidget(widget.type)}
            </div>
          </div>
        ))}

        {/* Add Widget button in edit mode */}
        {editMode && (
          <div className="col-span-1">
            <button
              onClick={() => setShowAddModal(true)}
              className="w-full h-full min-h-[120px] flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/10 transition-colors text-gray-400 dark:text-gray-500 hover:text-teal-600 dark:hover:text-teal-400"
            >
              <Plus className="h-6 w-6" />
              <span className="text-sm font-medium">Add Widget</span>
            </button>
          </div>
        )}
      </div>

      {/* Edit mode controls */}
      {editMode && (
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleReset}
            className="flex items-center gap-1.5"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Reset to Suggested
          </Button>
        </div>
      )}

      {/* Add Widget Modal */}
      {showAddModal && (
        <AddWidgetModal
          onAdd={handleAdd}
          onClose={() => setShowAddModal(false)}
          existingTypes={existingTypes}
        />
      )}
    </div>
  );
}

/**
 * Purchase Order DB Service
 * All SQL for supplier_purchase_orders and supplier_purchase_order_items.
 * Pure business logic (validation, calculations) stays in procurementService.ts.
 */

import sql, { withTransaction, TxSql } from '@/lib/neon';

export interface PurchaseOrderItem {
  description: string;
  quantity: number;
  unit_price: number;
  tax_rate: number;
}

export interface CreatePurchaseOrderInput {
  companyId: string;
  userId: string;
  supplier_id: string;
  order_date: string;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items: PurchaseOrderItem[];
}

export interface UpdatePurchaseOrderInput {
  id: string;
  companyId: string;
  supplier_id?: string | null;
  order_date?: string | null;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items?: PurchaseOrderItem[];
}

export interface ListPurchaseOrdersInput {
  companyId: string;
  status?: string | null;
  search?: string | null;
  limit?: number;
  offset?: number;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function calcTotals(items: PurchaseOrderItem[]) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    const lineTax = Math.round(lineTotal * (item.tax_rate / 100) * 100) / 100;
    subtotal += lineTotal;
    taxAmount += lineTax;
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

async function insertLineItems(
  purchaseOrderId: string,
  items: PurchaseOrderItem[],
  tx?: TxSql,
) {
  const exec = tx ?? sql;
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    await exec`
      INSERT INTO supplier_purchase_order_items (
        purchase_order_id, description, quantity, unit_price, tax_rate,
        line_total, tax_amount
      ) VALUES (
        ${purchaseOrderId}::UUID,
        ${item.description},
        ${item.quantity},
        ${item.unit_price},
        ${item.tax_rate},
        ${Math.round(lineTotal * 100) / 100},
        ${Math.round(lineTax * 100) / 100}
      )
    `;
  }
}

async function fetchItems(purchaseOrderId: string) {
  return sql`
    SELECT * FROM supplier_purchase_order_items
    WHERE purchase_order_id = ${purchaseOrderId}::UUID
    ORDER BY created_at ASC
  `;
}

// ─── Order number ─────────────────────────────────────────────────────────────

export async function generateOrderNumber(companyId: string): Promise<string> {
  const rows = await sql`
    UPDATE company_document_numbers
    SET next_number = next_number + 1
    WHERE company_id = ${companyId}::UUID AND document_type = 'purchase_order'
    RETURNING prefix, next_number - 1 AS current_number, padding
  `;

  if (rows.length === 0) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, 'purchase_order', 'PO', 2, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
    return 'PO-0000001';
  }

  const row = rows[0]!;
  return `${row.prefix}-${String(row.current_number).padStart(row.padding, '0')}`;
}

// ─── Queries ──────────────────────────────────────────────────────────────────

export async function getPurchaseOrder(id: string, companyId: string) {
  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.id = ${id}::UUID AND po.company_id = ${companyId}::UUID
  `;
  if (orders.length === 0) return null;
  const items = await fetchItems(id);
  return { order: orders[0]!, items };
}

export async function listPurchaseOrders(input: ListPurchaseOrdersInput) {
  const { companyId, status, search, limit = 100, offset = 0 } = input;
  const take = Math.min(limit, 500);
  const statusFilter = status ?? null;
  const searchTerm = search ? `%${search}%` : null;

  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
    ORDER BY po.created_at DESC
    LIMIT ${take} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::INT AS total
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
  `;

  return { orders, total: countResult[0]?.total ?? 0 };
}

// ─── Mutations ────────────────────────────────────────────────────────────────

export async function createPurchaseOrder(input: CreatePurchaseOrderInput) {
  const { companyId, userId, items } = input;
  const orderNumber = await generateOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(items);

  const created = await sql`
    INSERT INTO supplier_purchase_orders (
      company_id, supplier_id, order_number, order_date, delivery_date,
      reference, notes, internal_notes, status,
      subtotal, tax_amount, total_amount, created_by
    ) VALUES (
      ${companyId}::UUID,
      ${input.supplier_id}::UUID,
      ${orderNumber},
      ${input.order_date}::DATE,
      ${input.delivery_date ?? null}::DATE,
      ${input.reference ?? null},
      ${input.notes ?? null},
      ${input.internal_notes ?? null},
      'draft',
      ${subtotal},
      ${taxAmount},
      ${totalAmount},
      ${userId}::UUID
    )
    RETURNING *
  `;

  const order = created[0]!;
  await insertLineItems(order.id, items);
  const orderItems = await fetchItems(order.id);
  return { order, items: orderItems };
}

export async function updatePurchaseOrder(input: UpdatePurchaseOrderInput) {
  const { id, companyId, items } = input;

  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  let subtotal: number | null = null;
  let taxAmount: number | null = null;
  let totalAmount: number | null = null;

  if (items && items.length > 0) {
    const totals = calcTotals(items);
    subtotal = totals.subtotal;
    taxAmount = totals.taxAmount;
    totalAmount = totals.totalAmount;
  }

  const { order: updated, items: orderItems } = await withTransaction(async (tx) => {
    const rows = await tx`
      UPDATE supplier_purchase_orders SET
        supplier_id    = COALESCE(${input.supplier_id ?? null}::UUID, supplier_id),
        order_date     = COALESCE(${input.order_date ?? null}::DATE, order_date),
        delivery_date  = COALESCE(${input.delivery_date ?? null}::DATE, delivery_date),
        reference      = COALESCE(${input.reference ?? null}, reference),
        notes          = COALESCE(${input.notes ?? null}, notes),
        internal_notes = COALESCE(${input.internal_notes ?? null}, internal_notes),
        subtotal       = COALESCE(${subtotal}, subtotal),
        tax_amount     = COALESCE(${taxAmount}, tax_amount),
        total_amount   = COALESCE(${totalAmount}, total_amount),
        updated_at     = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
      RETURNING *
    `;

    if (items && items.length > 0) {
      await tx`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
      await insertLineItems(id, items, tx);
    }

    const lineItems = await tx`
      SELECT * FROM supplier_purchase_order_items
      WHERE purchase_order_id = ${id}::UUID
      ORDER BY created_at ASC
    `;

    return { order: rows[0]!, items: lineItems };
  });

  return { order: updated, items: orderItems };
}

export async function deletePurchaseOrder(id: string, companyId: string) {
  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  await withTransaction(async (tx) => {
    await tx`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
    await tx`DELETE FROM supplier_purchase_orders WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID`;
  });

  return { deleted: true };
}

/**
 * Purchases by Supplier Report
 * Sage Parity: Suppliers > Reports > Purchases by Supplier
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { TrendingUp, Loader2, Download } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Row { supplierId: string; supplierName: string; invoiceCount: number; totalPurchases: number; paymentsMade: number; outstanding: number; }

export default function PurchasesBySupplierReport() {
  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const today = new Date();
  const [from, setFrom] = useState(new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0]);
  const [to, setTo] = useState(today.toISOString().split('T')[0]);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch(`/api/accounting/reports/purchases-by-supplier?from=${from}&to=${to}`, { credentials: 'include' });
      const json = await res.json();
      setRows(json.data || []);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, [from, to]);

  useEffect(() => { load(); }, [load]);

  const totals = rows.reduce((a, r) => ({
    invoiceCount: a.invoiceCount + r.invoiceCount,
    totalPurchases: a.totalPurchases + r.totalPurchases,
    paymentsMade: a.paymentsMade + r.paymentsMade,
    outstanding: a.outstanding + r.outstanding,
  }), { invoiceCount: 0, totalPurchases: 0, paymentsMade: 0, outstanding: 0 });

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-orange-500/10"><TrendingUp className="h-6 w-6 text-orange-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Purchases by Supplier</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Expenditure breakdown per supplier</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <input type="date" value={from} onChange={e => setFrom(e.target.value)} className="ff-input text-sm" />
              <span className="text-[var(--ff-text-tertiary)]">to</span>
              <input type="date" value={to} onChange={e => setTo(e.target.value)} className="ff-input text-sm" />
              <button onClick={() => window.open(`/api/accounting/reports/purchases-by-supplier?from=${from}&to=${to}&format=csv`, '_blank')}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-orange-600 hover:bg-orange-500 text-white rounded-lg">
                <Download className="h-4 w-4" /> CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {error && <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4">{error}</div>}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading ? (
              <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
            ) : rows.length === 0 ? (
              <div className="p-8 text-center text-[var(--ff-text-tertiary)]">No purchase data for this period</div>
            ) : (
              <table className="w-full text-sm">
                <thead><tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Supplier</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Invoices</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Total Purchases</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Paid</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Outstanding</th>
                </tr></thead>
                <tbody className="divide-y divide-[var(--ff-border-light)]">
                  {rows.map(r => (
                    <tr key={r.supplierId} className="hover:bg-[var(--ff-bg-tertiary)]">
                      <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{r.supplierName}</td>
                      <td className="px-4 py-3 text-right text-[var(--ff-text-secondary)]">{r.invoiceCount}</td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{fmt(r.totalPurchases)}</td>
                      <td className="px-4 py-3 text-right font-mono text-teal-400">{fmt(r.paymentsMade)}</td>
                      <td className="px-4 py-3 text-right font-mono text-amber-400">{fmt(r.outstanding)}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot><tr className="border-t-2 border-[var(--ff-border-medium)] bg-[var(--ff-bg-tertiary)] font-bold">
                  <td className="px-4 py-3 text-[var(--ff-text-primary)]">TOTAL</td>
                  <td className="px-4 py-3 text-right text-[var(--ff-text-secondary)]">{totals.invoiceCount}</td>
                  <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{fmt(totals.totalPurchases)}</td>
                  <td className="px-4 py-3 text-right font-mono text-teal-400">{fmt(totals.paymentsMade)}</td>
                  <td className="px-4 py-3 text-right font-mono text-amber-400">{fmt(totals.outstanding)}</td>
                </tr></tfoot>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

