// Execute the validated SQL via sql.transaction() so that SET LOCAL statement_timeout
// is guaranteed to be honoured on the same connection as the query.
//
// IMPORTANT: Neon's transaction() callback only accepts tagged-template calls
// (which return NeonQueryPromise). txn.unsafe() returns UnsafeRawSql — a different
// class — which transaction() rejects at runtime. To get around this, we pass the
// raw SQL string as a tagged template via a helper that inlines it safely.
//
// Because the SQL has already been:
//   1. Generated by Claude with explicit company_id predicates
//   2. Validated for forbidden keywords, forbidden patterns, and table allowlist
//   3. Confirmed to contain a company_id = '<uuid>' predicate
// it is safe to inline as a raw template string at this point.
const [, rows] = await sql.transaction(
  (txn) => [
    txn`SET LOCAL statement_timeout = '5000'`,
    txn.unsafe(validation.sanitizedSQL),
  ],
  { isolationLevel: 'ReadCommitted' }
) as [unknown, Row[]];
const formatted = formatQueryResult(rows as Record<string, unknown>[], question);

