  phone: '',
  mobile: '',
  fax: '',
  web_address: '',
  vat_number: '',
  registration_number: '',
  contact_person: '',
  payment_terms: '30',
  payment_terms_type: 'days',
  credit_limit: '',
  billing_address: '',
  shipping_address: '',
  notes: '',
  is_active: true,
  category_id: '',
  cash_sale: false,
