  // Table allowlist — only accounting tables (and CTE aliases) may appear in FROM / JOIN clauses.
  // The regex deliberately excludes FROM tokens that appear inside parentheses (e.g. EXTRACT(YEAR FROM ...))
  // by requiring the FROM/JOIN keyword to be preceded by whitespace or a comma/semicolon — not by a word
  // character or open-paren. This prevents matching table aliases inside function calls.
  const tablePattern = /(?<![(\w])(?:FROM|JOIN)\s+(\w+)/gi;
