/**
 * Supplier POs by Supplier Report API
 * GET /api/accounting/reports-supplier-pos
 *   ?status=draft|sent|approved|received|cancelled
 *   &date_from=YYYY-MM-DD
 *   &date_to=YYYY-MM-DD
 *
 * Returns purchase orders grouped by supplier with totals.
 * Sage Accounting parity: Suppliers > Reports > Purchase Orders by Supplier
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import sql from '@/lib/neon';

export interface SupplierPoRow {
  id: string;
  orderNumber: string;
  orderDate: string;
  deliveryDate: string | null;
  reference: string | null;
  status: string;
  totalAmount: number;
  taxAmount: number;
  subtotal: number;
}

export interface SupplierPoGroup {
  supplierId: string;
  supplierName: string;
  poCount: number;
  totalValue: number;
  pos: SupplierPoRow[];
}

export interface SupplierPosReportResponse {
  suppliers: SupplierPoGroup[];
  grandTotal: number;
  grandPoCount: number;
}

function toDateString(val: Date | string | null | undefined): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString().split('T')[0]!;
  return String(val).split('T')[0]!;
}

async function getSupplierPosReport(
  companyId: string,
  status: string | null,
  dateFrom: string | null,
  dateTo: string | null,
): Promise<SupplierPosReportResponse> {
  const statusFilter = status ?? null;
  const fromFilter = dateFrom ?? null;
  const toFilter = dateTo ?? null;

  const rows = await sql`
    SELECT
      po.id,
      po.order_number,
      po.order_date,
      po.delivery_date,
      po.reference,
      po.status,
      po.total_amount,
      po.tax_amount,
      po.subtotal,
      po.supplier_id,
      COALESCE(s.name, 'Unknown Supplier') AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s
      ON s.id = po.supplier_id
      AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (${fromFilter}::DATE IS NULL OR po.order_date >= ${fromFilter}::DATE)
      AND (${toFilter}::DATE IS NULL OR po.order_date <= ${toFilter}::DATE)
    ORDER BY supplier_name ASC, po.order_date DESC
  `;

  // Group by supplier in application layer
  const supplierMap = new Map<string, SupplierPoGroup>();

  for (const row of rows) {
    const supplierId = String(row.supplier_id ?? 'unknown');
    const supplierName = String(row.supplier_name);

    if (!supplierMap.has(supplierId)) {
      supplierMap.set(supplierId, {
        supplierId,
        supplierName,
        poCount: 0,
        totalValue: 0,
        pos: [],
      });
    }

    const group = supplierMap.get(supplierId)!;
    const totalAmount = Number(row.total_amount ?? 0);

    group.poCount += 1;
    group.totalValue = Math.round((group.totalValue + totalAmount) * 100) / 100;
    group.pos.push({
      id: String(row.id),
      orderNumber: String(row.order_number),
      orderDate: toDateString(row.order_date as Date | string) ?? '',
      deliveryDate: toDateString(row.delivery_date as Date | string | null),
      reference: row.reference ? String(row.reference) : null,
      status: String(row.status),
      totalAmount,
      taxAmount: Number(row.tax_amount ?? 0),
      subtotal: Number(row.subtotal ?? 0),
    });
  }

  const suppliers = Array.from(supplierMap.values());
  const grandTotal = Math.round(suppliers.reduce((s, g) => s + g.totalValue, 0) * 100) / 100;
  const grandPoCount = suppliers.reduce((s, g) => s + g.poCount, 0);

  return { suppliers, grandTotal, grandPoCount };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { status, date_from, date_to } = req.query;

  const statusVal = status && typeof status === 'string' ? status : null;
  const dateFromVal = date_from && typeof date_from === 'string' ? date_from : null;
  const dateToVal = date_to && typeof date_to === 'string' ? date_to : null;

  try {
    const report = await getSupplierPosReport(companyId, statusVal, dateFromVal, dateToVal);
    return apiResponse.success(res, report);
  } catch (err) {
    log.error('Supplier POs report failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to generate supplier POs report');
  }
}

export default withCompany(withErrorHandler(handler as Parameters<typeof withCompany>[0]));

/**
 * Payroll Runs API
 * GET  /api/payroll/payroll-runs  - List all payroll runs
 * POST /api/payroll/payroll-runs  - Create a new payroll run
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { listPayrollRuns, createPayrollRun } from '@/modules/payroll/payrollService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const runs = await listPayrollRuns(companyId);
      return apiResponse.success(res, runs);
    } catch (err) {
      log.error('payroll runs GET failed', { error: err }, 'payroll-api');
      return apiResponse.internalError(res, err, 'Failed to fetch payroll runs');
    }
  }

  if (req.method === 'POST') {
    try {
      const { period_start, period_end } = req.body;

      if (!period_start || !period_end) {
        return apiResponse.badRequest(res, 'period_start and period_end are required');
      }

      const userId = req.user.id;
      const run = await createPayrollRun(companyId, period_start, period_end, userId);
      return apiResponse.success(res, run);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create payroll run';
      log.error('payroll runs POST failed', { error: err }, 'payroll-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(handler));

/**
 * Payroll Runs List Page
 * Displays all payroll runs with status, totals, and action links.
 * Route: /payroll/runs
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { CalendarDays, Loader2, AlertCircle, Plus } from 'lucide-react';
import Link from 'next/link';
import { apiFetch } from '@/lib/apiFetch';

interface PayrollRunItem {
  id: string;
  period_start: string;
  period_end: string;
  run_date: string;
  status: string;
  total_gross: number;
  total_net: number;
  total_paye: number;
  total_company_cost: number;
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-yellow-500/10 text-yellow-400',
    processing: 'bg-blue-500/10 text-blue-400',
    completed: 'bg-teal-500/10 text-teal-400',
    reversed: 'bg-red-500/10 text-red-400',
  };
  return (
    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/10 text-gray-400'}`}>
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
}

export default function PayrollRunsPage() {
  const [runs, setRuns] = useState<PayrollRunItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const loadRuns = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/payroll/payroll-runs');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      setRuns((json.data ?? json) as PayrollRunItem[]);
    } catch {
      setError('Failed to load payroll runs');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadRuns();
  }, [loadRuns]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <CalendarDays className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">Payroll Runs</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Process and manage payroll</p>
              </div>
            </div>
            <Link
              href="/payroll/runs/new"
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
            >
              <Plus className="h-4 w-4" />
              New Payroll Run
            </Link>
          </div>
        </div>

        <div className="p-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="flex items-center justify-center gap-2 text-red-400 py-12">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : runs.length === 0 ? (
            <div className="text-center py-16">
              <CalendarDays className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)] font-medium">No payroll runs yet</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">Create your first payroll run</p>
              <Link
                href="/payroll/runs/new"
                className="inline-flex items-center gap-2 mt-4 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
              >
                <Plus className="h-4 w-4" />
                New Payroll Run
              </Link>
            </div>
          ) : (
            <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Period</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Run Date</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Status</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Total Gross</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Total PAYE</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Total Net</th>
                    <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Company Cost</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {runs.map((run) => (
                    <tr
                      key={run.id}
                      className="border-b border-[var(--ff-border-primary)] last:border-0 hover:bg-[var(--ff-bg-tertiary)] transition-colors"
                    >
                      <td className="py-3 px-4 text-[var(--ff-text-primary)]">
                        {formatDate(run.period_start)} - {formatDate(run.period_end)}
                      </td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{formatDate(run.run_date)}</td>
                      <td className="py-3 px-4"><StatusBadge status={run.status} /></td>
                      <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(run.total_gross)}</td>
                      <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(run.total_paye)}</td>
                      <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)] font-medium">{formatCurrency(run.total_net)}</td>
                      <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(run.total_company_cost)}</td>
                      <td className="py-3 px-4">
                        <Link
                          href={`/payroll/runs/${run.id}`}
                          className="text-teal-400 hover:text-teal-300 text-xs font-medium transition-colors"
                        >
                          View
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

