              12-month total: <span className="font-medium text-gray-900 dark:text-gray-100">{fmtCurrency(total)}</span>
            </span>
          )}
        </div>
      }
    >
      {loading ? (
        <div className="space-y-3">
          <Skeleton variant="heading" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
