                tickLine={false}
                axisLine={false}
                className="text-gray-500 dark:text-gray-400"
                interval={1}
              />
              <YAxis
                tickFormatter={(v: number) => fmtCurrency(v)}
                tick={{ fontSize: 10, fill: 'currentColor' }}
                tickLine={false}
                axisLine={false}
                className="text-gray-500 dark:text-gray-400"
