/**
 * Accounting Module — thin shell with tab routing
 * Tab content lives in src/components/accounting/dashboard/
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { useAuth } from '@/contexts/AuthContext';
import { useCompany } from '@/contexts/CompanyContext';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import Link from 'next/link';
import {
  Calculator, BookOpen, FileSpreadsheet, Calendar, BarChart3, Plus, Loader2,
} from 'lucide-react';
import { OverviewTab } from '@/components/accounting/dashboard/OverviewTab';
import { ChartOfAccountsTab } from '@/components/accounting/dashboard/ChartOfAccountsTab';
import { JournalEntriesTab } from '@/components/accounting/dashboard/JournalEntriesTab';
import { FiscalPeriodsTab } from '@/components/accounting/dashboard/FiscalPeriodsTab';
import { ReportsTab } from '@/components/accounting/dashboard/ReportsTab';
import { type WidgetConfig, DEFAULT_WIDGET_LAYOUT } from '@/components/dashboard/widgetTypes';

type AccountingTab = 'overview' | 'chart-of-accounts' | 'journal-entries' | 'fiscal-periods' | 'reports';

const TABS: { id: AccountingTab; label: string; icon: React.ElementType }[] = [
  { id: 'overview',          label: 'Overview',          icon: Calculator     },
  { id: 'chart-of-accounts', label: 'Chart of Accounts', icon: BookOpen       },
  { id: 'journal-entries',   label: 'Journal Entries',   icon: FileSpreadsheet },
  { id: 'fiscal-periods',    label: 'Fiscal Periods',    icon: Calendar       },
  { id: 'reports',           label: 'Reports',            icon: BarChart3      },
];

export default function AccountingPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  const { activeCompany, companies, loading: companiesLoading } = useCompany();
  const [activeTab, setActiveTab] = useState<AccountingTab>('overview');
  const [isMounted, setIsMounted] = useState(false);
  const [widgetLayout, setWidgetLayout] = useState<WidgetConfig[]>(DEFAULT_WIDGET_LAYOUT);

  useEffect(() => { setIsMounted(true); }, []);

  // Defensive guard: if a real authenticated user somehow lands here with
  // zero companies (deep link, bookmark, stale session), send them through
  // onboarding rather than showing a skeleton dashboard with 400-ing APIs.
  //
  // CRITICAL: wait for BOTH auth and company loads to finish. CompanyContext
  // will briefly report `loading: false, companies: []` on a fresh mount
  // before AuthContext has finished its own bootstrap, and without the
  // authLoading/user gate we'd race into a false redirect loop.
  useEffect(() => {
    if (!isMounted || authLoading || companiesLoading) return;
    if (!user) return;
    if (companies.length === 0) {
      void router.replace('/onboarding');
    }
  }, [isMounted, authLoading, companiesLoading, user, companies.length, router]);

  // Sync tab from URL query param
  useEffect(() => {
    if (!isMounted) return;
    const tab = router.query.tab as AccountingTab;
    if (tab && TABS.some(t => t.id === tab)) setActiveTab(tab);
  }, [router.query.tab, isMounted]);

  const handleTabChange = useCallback((tab: AccountingTab) => {
    setActiveTab(tab);
    router.push({ pathname: '/accounting', query: { tab } }, undefined, { shallow: true });
  }, [router]);

  // Load and persist widget layout
  useEffect(() => {
    if (!isMounted) return;
    apiFetch('/api/accounting/widget-layout')
      .then(res => res.json())
      .then((json: { data?: { layout?: WidgetConfig[] } }) => {
        const layout = json.data?.layout;
        if (Array.isArray(layout) && layout.length > 0) setWidgetLayout(layout);
      })
      .catch(err => log.error('Failed to load widget layout', { error: err }, 'accounting-page'));
  }, [isMounted]);

  const handleLayoutChange = useCallback((layout: WidgetConfig[]) => {
    setWidgetLayout(layout);
    apiFetch('/api/accounting/widget-layout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ layout }),
    }).catch(err => log.error('Failed to save widget layout', { error: err }, 'accounting-page'));
  }, []);

  // Suppress unused-var lint — layout callbacks kept for future widget editing
  void widgetLayout;
  void handleLayoutChange;

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <div className="text-center">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500 mx-auto mb-2" />
            <p className="text-[var(--ff-text-secondary)]">Loading accounting module...</p>
          </div>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Page Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]" data-tour="dashboard">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-teal-500/10">
                  <Calculator className="h-6 w-6 text-teal-500" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                    {activeCompany?.tradingName || activeCompany?.name || 'ISAFlow'}
                  </h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
                    General Ledger, Journal Entries &amp; Financial Reports
                  </p>
                </div>
              </div>
              {activeTab === 'journal-entries' && (
                <Link
                  href="/accounting/journal-entries/new"
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium"
                >
                  <Plus className="h-4 w-4" />
                  New Journal Entry
                </Link>
              )}
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="px-6 border-t border-[var(--ff-border-light)]">
            <nav className="flex gap-0 -mb-px overflow-x-auto" aria-label="Accounting tabs">
              {TABS.map(tab => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button
                    key={tab.id}
                    onClick={() => handleTabChange(tab.id)}
                    className={`
                      flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap
                      ${isActive
                        ? 'border-teal-500 text-teal-600'
                        : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-[var(--ff-border-medium)]'
                      }
                    `}
                  >
                    <Icon className="h-4 w-4" />
                    {tab.label}
                  </button>
                );
              })}
            </nav>
          </div>
        </div>

        {/* Tab Content */}
        <div className="p-6">
          {activeTab === 'overview'          && <OverviewTab />}
          {activeTab === 'chart-of-accounts' && <ChartOfAccountsTab />}
          {activeTab === 'journal-entries'   && <JournalEntriesTab />}
          {activeTab === 'fiscal-periods'    && <FiscalPeriodsTab />}
          {activeTab === 'reports'           && <ReportsTab />}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Widget type definitions for the Adaptive Widget Dashboard.
 * // WORKING: Full type definitions, no any.
 */

export type WidgetType =
  | 'bank-summary'
  | 'invoices-owed'
  | 'bills-to-pay'
  | 'cash-position'
  | 'pnl-snapshot'
  | 'tasks-reminders'
  | 'recent-activity'
  | 'ai-insights'
  | 'quick-actions'
  | 'vat-summary'
  | 'kpi-cards'
  | 'setup-guide'
  | 'todo'
  | 'sales_history'
  | 'top_customers';

export type WidgetSize = 'sm' | 'md' | 'lg';

export interface WidgetConfig {
  id: string;
  type: WidgetType;
  title: string;
  size: WidgetSize;
}

/** Maps WidgetSize to CSS grid column span class */
export const WIDGET_SIZE_CLASS: Record<WidgetSize, string> = {
  sm: 'col-span-1',
  md: 'col-span-1 md:col-span-2',
  lg: 'col-span-1 md:col-span-2 xl:col-span-3',
};

/** Default adaptive widget layout */
export const DEFAULT_WIDGET_LAYOUT: WidgetConfig[] = [
  { id: 'quick-actions-1', type: 'quick-actions', title: 'Quick Actions', size: 'md' },
  { id: 'bank-summary-1', type: 'bank-summary', title: 'Bank Accounts', size: 'md' },
  { id: 'invoices-owed-1', type: 'invoices-owed', title: 'Invoices Owed', size: 'sm' },
  { id: 'bills-to-pay-1', type: 'bills-to-pay', title: 'Bills to Pay', size: 'sm' },
  { id: 'pnl-snapshot-1', type: 'pnl-snapshot', title: 'P&L Snapshot', size: 'md' },
  { id: 'recent-activity-1', type: 'recent-activity', title: 'Recent Activity', size: 'sm' },
];

/** Catalogue of all available widgets (for the Add Widget modal) */
export const WIDGET_CATALOGUE: Array<Pick<WidgetConfig, 'type' | 'title' | 'size'>> = [
  { type: 'bank-summary', title: 'Bank Accounts', size: 'md' },
  { type: 'invoices-owed', title: 'Invoices Owed', size: 'sm' },
  { type: 'bills-to-pay', title: 'Bills to Pay', size: 'sm' },
  { type: 'pnl-snapshot', title: 'P&L Snapshot', size: 'md' },
  { type: 'quick-actions', title: 'Quick Actions', size: 'md' },
  { type: 'recent-activity', title: 'Recent Activity', size: 'sm' },
  { type: 'vat-summary', title: 'VAT Summary', size: 'sm' },
  { type: 'kpi-cards', title: 'KPI Cards', size: 'lg' },
  { type: 'todo', title: 'To-Do / Overdue Actions', size: 'md' },
  { type: 'sales_history', title: 'Sales History', size: 'md' },
  { type: 'top_customers', title: 'Top Customers', size: 'md' },
];

/**
 * WidgetGrid — Responsive 3-column grid that renders configured widgets.
 * // WORKING: Edit mode, add/remove widgets, reset to default layout.
 */

import { useState, useCallback } from 'react';
import { Plus, RotateCcw, GripVertical, X } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  type WidgetConfig,
  type WidgetType,
  WIDGET_SIZE_CLASS,
  WIDGET_CATALOGUE,
  DEFAULT_WIDGET_LAYOUT,
} from './widgetTypes';
import { BankSummaryWidget } from './widgets/BankSummaryWidget';
import { InvoicesOwedWidget } from './widgets/InvoicesOwedWidget';
import { BillsToPayWidget } from './widgets/BillsToPayWidget';
import { QuickActionsWidget } from './widgets/QuickActionsWidget';
import { RecentActivityWidget } from './widgets/RecentActivityWidget';
import { PnlSnapshotWidget } from './widgets/PnlSnapshotWidget';
import { VatSummaryWidget } from './widgets/VatSummaryWidget';
import { TodoWidget } from './widgets/TodoWidget';
import { SalesHistoryWidget } from './widgets/SalesHistoryWidget';
import { TopCustomersWidget } from './widgets/TopCustomersWidget';

// ---------------------------------------------------------------------------
// Widget renderer
// ---------------------------------------------------------------------------

function renderWidget(type: WidgetType): React.ReactNode {
  switch (type) {
    case 'bank-summary':     return <BankSummaryWidget />;
    case 'invoices-owed':    return <InvoicesOwedWidget />;
    case 'bills-to-pay':     return <BillsToPayWidget />;
    case 'quick-actions':    return <QuickActionsWidget />;
    case 'recent-activity':  return <RecentActivityWidget />;
    case 'pnl-snapshot':     return <PnlSnapshotWidget />;
    case 'vat-summary':      return <VatSummaryWidget />;
    case 'todo':             return <TodoWidget />;
    case 'sales_history':    return <SalesHistoryWidget />;
    case 'top_customers':    return <TopCustomersWidget />;
    default:
      return (
        <Card>
          <p className="text-sm text-gray-500 dark:text-gray-400 capitalize">
            {type.replace(/-/g, ' ')} widget coming soon.
          </p>
        </Card>
      );
  }
}

// ---------------------------------------------------------------------------
// Add Widget Modal
// ---------------------------------------------------------------------------

interface AddWidgetModalProps {
  onAdd: (type: WidgetType, size: WidgetConfig['size']) => void;
  onClose: () => void;
  existingTypes: WidgetType[];
}

function AddWidgetModal({ onAdd, onClose, existingTypes }: AddWidgetModalProps) {
  const available = WIDGET_CATALOGUE.filter(w => !existingTypes.includes(w.type));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} aria-hidden="true" />
      <div className="relative z-10 w-full max-w-md mx-4 bg-white dark:bg-gray-900 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100">Add Widget</h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-md text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {available.length === 0 ? (
          <p className="text-sm text-gray-500 dark:text-gray-400">All available widgets are already on your dashboard.</p>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {available.map(w => (
              <button
                key={w.type}
                onClick={() => { onAdd(w.type, w.size); onClose(); }}
                className="flex flex-col items-start gap-1 p-3 rounded-lg border border-gray-200 dark:border-gray-700 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/20 transition-colors text-left"
              >
                <span className="text-sm font-medium text-gray-900 dark:text-gray-100">{w.title}</span>
                <span className="text-xs text-gray-500 dark:text-gray-400 capitalize">{w.size} size</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// WidgetGrid
// ---------------------------------------------------------------------------

interface WidgetGridProps {
  widgets: WidgetConfig[];
  editMode: boolean;
  onLayoutChange: (widgets: WidgetConfig[]) => void;
}

export function WidgetGrid({ widgets, editMode, onLayoutChange }: WidgetGridProps) {
  const [showAddModal, setShowAddModal] = useState(false);

  const handleRemove = useCallback((id: string) => {
    onLayoutChange(widgets.filter(w => w.id !== id));
  }, [widgets, onLayoutChange]);

  const handleAdd = useCallback((type: WidgetType, size: WidgetConfig['size']) => {
    const newWidget: WidgetConfig = {
      id: `${type}-${Date.now()}`,
      type,
      title: WIDGET_CATALOGUE.find(w => w.type === type)?.title ?? type,
      size,
    };
    onLayoutChange([...widgets, newWidget]);
  }, [widgets, onLayoutChange]);

  const handleReset = useCallback(() => {
    onLayoutChange(DEFAULT_WIDGET_LAYOUT);
  }, [onLayoutChange]);

  const existingTypes = widgets.map(w => w.type);

  return (
    <div className="space-y-4">
      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {widgets.map(widget => (
          <div
            key={widget.id}
            className={`relative ${WIDGET_SIZE_CLASS[widget.size]}`}
          >
            {/* Drag handle (visual only) */}
            {editMode && (
              <div className="absolute top-2 left-2 z-10 p-1 rounded cursor-grab text-gray-400 dark:text-gray-500">
                <GripVertical className="h-4 w-4" />
              </div>
            )}
            {/* Remove button */}
            {editMode && (
              <button
                onClick={() => handleRemove(widget.id)}
                className="absolute top-2 right-2 z-10 p-1 rounded-full bg-red-100 dark:bg-red-900/30 text-red-500 hover:bg-red-200 dark:hover:bg-red-900/60 transition-colors"
                aria-label={`Remove ${widget.title} widget`}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
            {/* Widget content */}
            <div className={editMode ? 'opacity-80 pointer-events-none select-none' : ''}>
              {renderWidget(widget.type)}
            </div>
          </div>
        ))}

        {/* Add Widget button in edit mode */}
        {editMode && (
          <div className="col-span-1">
            <button
              onClick={() => setShowAddModal(true)}
              className="w-full h-full min-h-[120px] flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/10 transition-colors text-gray-400 dark:text-gray-500 hover:text-teal-600 dark:hover:text-teal-400"
            >
              <Plus className="h-6 w-6" />
              <span className="text-sm font-medium">Add Widget</span>
            </button>
          </div>
        )}
      </div>

      {/* Edit mode controls */}
      {editMode && (
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleReset}
            className="flex items-center gap-1.5"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Reset to Suggested
          </Button>
        </div>
      )}

      {/* Add Widget Modal */}
      {showAddModal && (
        <AddWidgetModal
          onAdd={handleAdd}
          onClose={() => setShowAddModal(false)}
