  console.log(`Total console errors across all admin pages: ${errorCount}`);
  if (errorCount > 0) {
    for (const [url, errors] of Object.entries(consoleErrors)) {
      console.log(`\n${url}:\n  ${errors.join('\n  ')}`);
    }
  }

  // Non-fatal: just report, don't fail
  expect(errorCount).toBeGreaterThanOrEqual(0);
});

