-- Cost Centre & Business Unit dimension system

-- 1. Add cc_type column to cost_centres (cc1 = client-level, cc2 = project-level)
ALTER TABLE cost_centres ADD COLUMN IF NOT EXISTS cc_type VARCHAR(10) DEFAULT 'cc1';
ALTER TABLE cost_centres ADD COLUMN IF NOT EXISTS department VARCHAR(100);

-- Update unique constraint to be per company+cc_type+code
DROP INDEX IF EXISTS uq_cost_centres_company_code;
CREATE UNIQUE INDEX IF NOT EXISTS uq_cost_centres_company_type_code
  ON cost_centres(company_id, cc_type, code);

-- 2. Add cc1_id, cc2_id, bu_id to gl_journal_lines
ALTER TABLE gl_journal_lines ADD COLUMN IF NOT EXISTS cc1_id UUID;
ALTER TABLE gl_journal_lines ADD COLUMN IF NOT EXISTS cc2_id UUID;
ALTER TABLE gl_journal_lines ADD COLUMN IF NOT EXISTS bu_id UUID;

-- Backfill: copy existing cost_center_id to cc1_id
UPDATE gl_journal_lines SET cc1_id = cost_center_id
  WHERE cost_center_id IS NOT NULL AND cc1_id IS NULL;

-- Indexes for dimension filtering
CREATE INDEX IF NOT EXISTS idx_jl_cc1 ON gl_journal_lines(cc1_id) WHERE cc1_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_jl_cc2 ON gl_journal_lines(cc2_id) WHERE cc2_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_jl_bu ON gl_journal_lines(bu_id) WHERE bu_id IS NOT NULL;

-- 3. Create business_units table
CREATE TABLE IF NOT EXISTS business_units (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id),
  code VARCHAR(20) NOT NULL,
  name VARCHAR(255) NOT NULL,
  description TEXT,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(company_id, code)
);
CREATE INDEX IF NOT EXISTS idx_business_units_company ON business_units(company_id);

/**
 * Migration Parse API
 * POST /api/accounting/migration-parse
 * Accepts multipart/form-data: file, source, fileType
 * Returns parsed accounts/customers/suppliers array.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import formidable from 'formidable';
import fs from 'fs';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  parseAccountsFile,
  parseCustomersFile,
  parseSuppliersFile,
  autoMapAccounts,
  type MigrationSource,
} from '@/modules/accounting/services/migrationParserService';

export const config = { api: { bodyParser: false } };

const VALID_SOURCES: MigrationSource[] = ['xero', 'quickbooks', 'pastel'];
const VALID_FILE_TYPES = ['accounts', 'customers', 'suppliers'] as const;
type FileType = typeof VALID_FILE_TYPES[number];

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);
  }

  const ALLOWED_MIME_TYPES = [
    'text/csv', 'text/plain',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/octet-stream', // some browsers send this for .csv
  ];
  const form = formidable({
    maxFileSize: 10 * 1024 * 1024,
    keepExtensions: true,
    filter: (part) => !!part.mimetype && ALLOWED_MIME_TYPES.includes(part.mimetype),
  });

  const [fields, files] = await form.parse(req);
  const source = (Array.isArray(fields.source) ? fields.source[0] : fields.source) as string;
  const fileType = (Array.isArray(fields.fileType) ? fields.fileType[0] : fields.fileType) as string;

  if (!VALID_SOURCES.includes(source as MigrationSource)) {
    return apiResponse.badRequest(res, `Invalid source. Must be one of: ${VALID_SOURCES.join(', ')}`);
  }
  if (!VALID_FILE_TYPES.includes(fileType as FileType)) {
    return apiResponse.badRequest(res, `Invalid fileType. Must be one of: ${VALID_FILE_TYPES.join(', ')}`);
  }

  const uploadedFile = Array.isArray(files.file) ? files.file[0] : files.file;
  if (!uploadedFile) {
    return apiResponse.badRequest(res, 'No file uploaded');
  }

  let fileContent: string;
  try {
    fileContent = fs.readFileSync(uploadedFile.filepath, 'utf-8');
  } catch (err) {
    log.error('Failed to read uploaded file', { error: err }, 'migration');
    return apiResponse.badRequest(res, 'Could not read uploaded file');
  }

  const src = source as MigrationSource;

  try {
    if (fileType === 'accounts') {
      const parsed = parseAccountsFile(src, fileContent);
      const mapped = autoMapAccounts(src, parsed);
      log.info('Parsed accounts file', { source: src, count: mapped.length }, 'migration');
      return apiResponse.success(res, { parsed: mapped, count: mapped.length });
    }

    if (fileType === 'customers') {
      const parsed = parseCustomersFile(src, fileContent);
      log.info('Parsed customers file', { source: src, count: parsed.length }, 'migration');
      return apiResponse.success(res, { parsed, count: parsed.length });
    }

    const parsed = parseSuppliersFile(src, fileContent);
    log.info('Parsed suppliers file', { source: src, count: parsed.length }, 'migration');
    return apiResponse.success(res, { parsed, count: parsed.length });
  } finally {
    try { fs.unlinkSync(uploadedFile.filepath); } catch { /* ignore cleanup errors */ }
  }
}


