          emailUseForCommunication: c.emailUseForCommunication ?? c.email_use_for_communication ?? true,
          emailAlwaysCc: c.emailAlwaysCc ?? c.email_always_cc ?? false,
          emailUseServiceFrom: c.emailUseServiceFrom ?? c.email_use_service_from ?? false,
          warnDuplicateCustomerRef: c.warnDuplicateCustomerRef ?? c.warn_duplicate_customer_ref ?? true,
          warnDuplicateSupplierInv: c.warnDuplicateSupplierInv ?? c.warn_duplicate_supplier_inv ?? true,
          displayInactiveCustomersProcessing: c.displayInactiveCustomersProcessing ?? c.display_inactive_customers_processing ?? false,
          displayInactiveSuppliersProcessing: c.displayInactiveSuppliersProcessing ?? c.display_inactive_suppliers_processing ?? false,
          displayInactiveCustomersReports: c.displayInactiveCustomersReports ?? c.display_inactive_customers_reports ?? false,
          displayInactiveSuppliersReports: c.displayInactiveSuppliersReports ?? c.display_inactive_suppliers_reports ?? false,
          useInclusiveProcessing: c.useInclusiveProcessing ?? c.use_inclusive_processing ?? true,
          useAccountDefaultLineType: c.useAccountDefaultLineType ?? c.use_account_default_line_type ?? false,
          warnItemQtyBelowZero: c.warnItemQtyBelowZero ?? c.warn_item_qty_below_zero ?? true,
          blockItemQtyBelowZero: c.blockItemQtyBelowZero ?? c.block_item_qty_below_zero ?? false,
          warnItemCostZero: c.warnItemCostZero ?? c.warn_item_cost_zero ?? false,
          warnItemSellingBelowCost: c.warnItemSellingBelowCost ?? c.warn_item_selling_below_cost ?? false,
          displayInactiveItemsProcessing: c.displayInactiveItemsProcessing ?? c.display_inactive_items_processing ?? false,
          displayInactiveItemsReports: c.displayInactiveItemsReports ?? c.display_inactive_items_reports ?? false,
          salesOrdersReserveQty: c.salesOrdersReserveQty ?? c.sales_orders_reserve_qty ?? false,
          displayInactiveBundles: c.displayInactiveBundles ?? c.display_inactive_bundles ?? false,
          ageingMonthly: c.ageingMonthly ?? c.ageing_monthly ?? true,
          ageingBasedOn: c.ageingBasedOn ?? c.ageing_based_on ?? 'invoice_date',
          industry: c.industry ?? null,
          businessStructure: c.businessStructure ?? c.business_structure ?? null,
          socialFacebook: c.socialFacebook ?? c.social_facebook ?? null,
          socialLinkedin: c.socialLinkedin ?? c.social_linkedin ?? null,
          socialX: c.socialX ?? c.social_x ?? null,
        });
      }
    } catch {
      setError('Failed to load company');
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchSupplementary = useCallback(async (companyId: string) => {
    const [docsRes, numRes, msgRes, ccRes, buRes, dispRes] = await Promise.allSettled([
      apiFetch(`/api/accounting/company-documents?companyId=${companyId}`).then(r => r.json()),
      apiFetch('/api/accounting/company-settings?type=document-numbers').then(r => r.json()),
      apiFetch('/api/accounting/company-settings?type=messages').then(r => r.json()),
      apiFetch('/api/accounting/accounting-settings?key=enable_cost_centres').then(r => r.json()),
      apiFetch('/api/accounting/accounting-settings?key=enable_business_units').then(r => r.json()),
      apiFetch('/api/accounting/accounting-settings?key=document_display_fields').then(r => r.json()),
    ]);
    if (docsRes.status === 'fulfilled' && docsRes.value.data) setDocuments(docsRes.value.data as CompanyDocument[]);
    if (numRes.status === 'fulfilled' && numRes.value.data) setDocNumbers(numRes.value.data as DocumentNumber[]);
    if (msgRes.status === 'fulfilled' && msgRes.value.data) {
      const map: Record<string, string> = {};
      for (const m of msgRes.value.data as { messageType: string; message: string }[]) map[m.messageType] = m.message;
      setMessages(map);
    }
    setEnableCC(ccRes.status === 'fulfilled' && ccRes.value.data?.value === 'true');
    setEnableBU(buRes.status === 'fulfilled' && buRes.value.data?.value === 'true');
    setDimLoaded(true);
    if (dispRes.status === 'fulfilled' && dispRes.value.data?.value) {
      try { setDocDisplayFields(prev => ({ ...prev, ...(JSON.parse(dispRes.value.data.value as string) as Record<string, boolean>) })); } catch { /* keep defaults */ }
    }
  }, []);

  useEffect(() => {
    if (activeCompany?.id) {
      void fetchCompany(activeCompany.id);
      void fetchSupplementary(activeCompany.id);
    }
  }, [activeCompany?.id, fetchCompany, fetchSupplementary]);

  // ── Handlers ──────────────────────────────────────────────────────────────

  const update = (field: keyof Company, value: unknown) => {
    setCompany(prev => prev ? { ...prev, [field]: value } as Company : prev);
  };

  const handleSave = async () => {
    if (!company) return;
    setSaving(true); setError(''); setSaved(false);
    try {
      const res = await apiFetch('/api/accounting/companies', {
        method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(company),
      });
      if (!res.ok) throw new Error('Failed to save');
      await Promise.all([
        docNumbers.length > 0 && apiFetch('/api/accounting/company-settings?type=document-numbers', {
          method: 'PUT', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ updates: docNumbers.map(d => ({ documentType: d.documentType, prefix: d.prefix, nextNumber: d.nextNumber })) }),

/**
 * New Purchase Order Page
 * Route: /accounting/purchase-orders/new
 */
import { useState, useEffect } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { ShoppingCart, Save, ArrowLeft, Loader2, Plus, Trash2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { apiFetch } from '@/lib/apiFetch';

interface Supplier { id: string; name: string; }
interface LineItem { productId: string; description: string; quantity: string; unitPrice: string; taxRate: string; }
const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

export default function NewPurchaseOrderPage() {
  const router = useRouter();
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [form, setForm] = useState({ supplierId: '', orderDate: new Date().toISOString().split('T')[0], expectedDeliveryDate: '', notes: '', reference: '' });
  const [items, setItems] = useState<LineItem[]>([{ productId: '', description: '', quantity: '1', unitPrice: '0', taxRate: '15' }]);

  useEffect(() => {
    apiFetch('/api/accounting/suppliers-list', { credentials: 'include' }).then(r => r.json()).then(j => setSuppliers(j.data || [])).catch(() => {});
  }, []);

  const addItem = () => setItems(prev => [...prev, { productId: '', description: '', quantity: '1', unitPrice: '0', taxRate: '15' }]);
  const removeItem = (idx: number) => setItems(prev => prev.filter((_, i) => i !== idx));
  const updateItem = (idx: number, field: string, value: string) => setItems(prev => prev.map((item, i) => i === idx ? { ...item, [field]: value } : item));

  const subtotal = items.reduce((s, i) => s + Number(i.quantity || 0) * Number(i.unitPrice || 0), 0);
  const tax = items.reduce((s, i) => s + Number(i.quantity || 0) * Number(i.unitPrice || 0) * Number(i.taxRate || 0) / 100, 0);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault(); setError(''); setSaving(true);
    try {
      const res = await apiFetch('/api/accounting/purchase-orders', {
        method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, items: items.map(i => ({ ...i, quantity: Number(i.quantity), unitPrice: Number(i.unitPrice), taxRate: Number(i.taxRate) })) }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Failed');
      router.push('/accounting/purchase-orders');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setSaving(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <Link href="/accounting/purchase-orders" className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)]"><ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" /></Link>
            <div className="p-2 rounded-lg bg-orange-500/10"><ShoppingCart className="h-6 w-6 text-orange-500" /></div>
            <div><h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Purchase Order</h1><p className="text-sm text-[var(--ff-text-secondary)]">Create a purchase order for a supplier</p></div>
          </div>
        </div>
        <form onSubmit={handleSubmit} className="p-6 max-w-4xl space-y-6">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Order Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div><label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Supplier *</label>
                <select required value={form.supplierId} onChange={e => setForm(p => ({ ...p, supplierId: e.target.value }))} className="ff-select w-full">
                  <option value="">Select supplier...</option>
                  {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
              <div><label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Reference</label>
                <input type="text" value={form.reference} onChange={e => setForm(p => ({ ...p, reference: e.target.value }))} className="ff-input w-full" placeholder="Supplier quote ref" />
              </div>
              <div><label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Order Date *</label>
                <input type="date" required value={form.orderDate} onChange={e => setForm(p => ({ ...p, orderDate: e.target.value }))} className="ff-input w-full" />
              </div>
              <div><label className="block text-sm text-[var(--ff-text-secondary)] mb-1">Expected Delivery</label>
                <input type="date" value={form.expectedDeliveryDate} onChange={e => setForm(p => ({ ...p, expectedDeliveryDate: e.target.value }))} className="ff-input w-full" />
              </div>
            </div>
          </div>
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Line Items</h2>
              <button type="button" onClick={addItem} className="inline-flex items-center gap-1 text-xs text-teal-400 hover:text-teal-300"><Plus className="h-3 w-3" /> Add Item</button>
            </div>
            <table className="w-full text-sm">
              <thead><tr className="text-left text-[var(--ff-text-secondary)] border-b border-[var(--ff-border-light)]">
                <th className="pb-2">Description</th><th className="pb-2 w-24 text-right">Qty</th><th className="pb-2 w-32 text-right">Unit Price</th><th className="pb-2 w-20 text-right">VAT %</th><th className="pb-2 w-32 text-right">Total</th><th className="pb-2 w-10"></th>
              </tr></thead>
              <tbody>
                {items.map((item, idx) => {
                  const lineTotal = Number(item.quantity || 0) * Number(item.unitPrice || 0);
                  return (
                    <tr key={idx} className="border-b border-[var(--ff-border-light)]">
                      <td className="py-2 pr-2"><input type="text" required value={item.description} onChange={e => updateItem(idx, 'description', e.target.value)} className="ff-input w-full text-sm" placeholder="Item description" /></td>
                      <td className="py-2 pr-2"><input type="number" required min="0.01" step="0.01" value={item.quantity} onChange={e => updateItem(idx, 'quantity', e.target.value)} className="ff-input w-full text-sm text-right" /></td>
                      <td className="py-2 pr-2"><input type="number" required min="0" step="0.01" value={item.unitPrice} onChange={e => updateItem(idx, 'unitPrice', e.target.value)} className="ff-input w-full text-sm text-right" /></td>
                      <td className="py-2 pr-2"><input type="number" min="0" step="0.01" value={item.taxRate} onChange={e => updateItem(idx, 'taxRate', e.target.value)} className="ff-input w-full text-sm text-right" /></td>
                      <td className="py-2 text-right text-[var(--ff-text-primary)]">{fmt(lineTotal)}</td>
                      <td className="py-2">{items.length > 1 && <button type="button" onClick={() => removeItem(idx)} className="text-red-400 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button>}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="flex justify-end">
              <div className="text-sm space-y-1 w-48">
                <div className="flex justify-between"><span className="text-[var(--ff-text-secondary)]">Subtotal:</span><span className="text-[var(--ff-text-primary)]">{fmt(subtotal)}</span></div>
                <div className="flex justify-between"><span className="text-[var(--ff-text-secondary)]">VAT:</span><span className="text-[var(--ff-text-primary)]">{fmt(tax)}</span></div>
                <div className="flex justify-between font-bold border-t border-[var(--ff-border-light)] pt-1"><span className="text-[var(--ff-text-primary)]">Total:</span><span className="text-teal-400">{fmt(subtotal + tax)}</span></div>
              </div>
            </div>
          </div>
          <div className="flex justify-end gap-3">
            <Link href="/accounting/purchase-orders" className="px-4 py-2 rounded-lg border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] text-sm">Cancel</Link>
            <button type="submit" disabled={saving} className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
              {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />} Create PO
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Purchase Order Detail Page
 * View purchase order information
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, ClipboardList, Loader2, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const STATUS_COLORS: Record<string, string> = {
  draft: 'bg-gray-500/20 text-gray-400',
  pending: 'bg-amber-500/20 text-amber-400',
  approved: 'bg-blue-500/20 text-blue-400',
  sent: 'bg-indigo-500/20 text-indigo-400',
  received: 'bg-teal-500/20 text-teal-400',
  partially_received: 'bg-purple-500/20 text-purple-400',
  cancelled: 'bg-gray-500/20 text-gray-500',
  closed: 'bg-gray-500/20 text-gray-500',
};

interface PurchaseOrder {
  id: string;
  po_number: string;
  supplier_name: string | null;
  supplier_id: string | null;
  order_date: string | null;
  expected_delivery_date: string | null;
  status: string;
  subtotal: number;
  tax_amount: number;
  total: number;
  notes: string | null;
  reference: string | null;
  created_at: string;
}

export default function PurchaseOrderDetailPage() {
  const router = useRouter();
  const { poId } = router.query;
  const [po, setPo] = useState<PurchaseOrder | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!poId) return;
    loadPO();
  }, [poId]);

  const loadPO = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/purchase-orders?id=${poId}`);
      const json = await res.json();
      const data = json.data || json;
      // API may return a single object or an array — find matching record
      if (Array.isArray(data)) {
        const match = data.find((p: PurchaseOrder) => p.id === poId);
        setPo(match || null);
        if (!match) setError('Purchase order not found');
      } else {
        setPo(data);
      }
    } catch {
      setError('Failed to load purchase order');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
        </div>
      </AppLayout>
    );
  }

  if (!po) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh] flex-col">
          <AlertCircle className="h-8 w-8 text-red-400 mb-2" />
          <p className="text-[var(--ff-text-secondary)]">{error || 'Purchase order not found'}</p>
          <Link href="/accounting/purchase-orders" className="mt-4 text-sm text-blue-400 hover:text-blue-300">
            Back to Purchase Orders
          </Link>
        </div>
      </AppLayout>
    );
  }

  const fields: { label: string; value: string | number | null | undefined; highlight?: boolean }[] = [
    { label: 'PO Number', value: po.po_number, highlight: true },
    { label: 'Supplier', value: po.supplier_name },
    { label: 'Order Date', value: po.order_date?.split('T')[0] },
    { label: 'Expected Delivery', value: po.expected_delivery_date?.split('T')[0] },
    { label: 'Reference', value: po.reference },
    { label: 'Subtotal', value: fmt(Number(po.subtotal)) },
    { label: 'Tax', value: fmt(Number(po.tax_amount)) },
    { label: 'Total', value: fmt(Number(po.total)), highlight: true },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/purchase-orders" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Purchase Orders
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <ClipboardList className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{po.po_number}</h1>
              {po.supplier_name && (
                <p className="text-sm text-[var(--ff-text-secondary)]">{po.supplier_name}</p>
              )}
            </div>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${STATUS_COLORS[po.status] || 'bg-gray-500/20 text-gray-400'}`}>
              {po.status.replace(/_/g, ' ')}
            </span>
          </div>
        </div>

        {/* Details */}
        <div className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {fields.map((f, i) => (
              <div key={i} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
