        si.due_date, si.invoice_number, si.total_amount, si.amount_paid, si.balance
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.company_id = ${companyId}::UUID
        AND si.supplier_id = ${Number(supplierId)}
        AND si.status IN ('approved', 'partially_paid')
        AND si.balance > 0
        AND si.due_date IS NOT NULL
      ORDER BY si.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const buckets = calculateAgingBuckets(invoices, asAt);

    return {
      supplier: { id: String(supplierRows[0]!.id), name: String(supplierRows[0]!.name) },
      invoices,
      buckets: buckets.length > 0 ? buckets[0]! : null,
    };
  } catch (err) {
    log.error('Failed to get AP aging detail', { supplierId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module
 * AP/AR Aging Bucket Calculations
 *
 * Calculates aging buckets: Current, 30, 60, 90, 120+ days
 * Used for both Accounts Payable and Accounts Receivable.
 */

import type { AgingBucket, AgingBucketName, AgingInvoice } from '../types/ap.types';

/**
 * Classify a single invoice into an aging bucket based on due date.
 *
 * - Current: not yet due (due date >= as-at date)
 * - 30 days: 1-30 days overdue
 * - 60 days: 31-60 days overdue
 * - 90 days: 61-90 days overdue
 * - 120+ days: 91+ days overdue
 */
export function getAgingBucket(dueDate: Date, asAtDate: Date): AgingBucketName {
  const diffMs = asAtDate.getTime() - dueDate.getTime();
  const daysOverdue = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days120Plus';
}

/**
 * Calculate aging buckets for a set of invoices, grouped by entity (supplier or client).
 *
 * - Excludes zero-balance invoices
 * - Groups by entityId
 * - Sorts by total descending
 */
export function calculateAgingBuckets(
  invoices: AgingInvoice[],
  asAtDate: Date
): AgingBucket[] {
  // Filter out zero-balance invoices
  const outstanding = invoices.filter(inv => inv.balance > 0);

  if (outstanding.length === 0) return [];

  // Group by entity
  const grouped = new Map<string, AgingBucket>();

  for (const inv of outstanding) {
    const bucket = getAgingBucket(new Date(inv.dueDate), asAtDate);

    if (!grouped.has(inv.entityId)) {
      grouped.set(inv.entityId, {
        entityId: inv.entityId,
        entityName: inv.entityName,
        current: 0,
        days30: 0,
        days60: 0,
        days90: 0,
        days120Plus: 0,
        total: 0,
      });
    }

    const entry = grouped.get(inv.entityId)!;
    entry[bucket] += inv.balance;
    entry.total += inv.balance;
  }

  // Sort by total descending
  return Array.from(grouped.values()).sort((a, b) => b.total - a.total);
}

/**
 * Company-scoped authentication middleware.
 * Wraps withAuth and adds company context from X-Company-Id header
 * or the user's default company.
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { sql } from '@/lib/neon';
import { withAuth, type AuthenticatedNextApiRequest } from './middleware';
import { log } from '@/lib/logger';

export interface CompanyApiRequest extends AuthenticatedNextApiRequest {
  companyId: string;
  companyRole: string;
}

// Accept handlers that declare a more specific req type (e.g. CompanyApiRequest,
// AuthenticatedNextApiRequest) — the cast inside withCompany is safe because
// by the time handler is called, the request has been enriched with those fields.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type CompanyHandler = (req: any, res: NextApiResponse<any>) => any;

/**
 * Middleware that requires authentication AND resolves the active company.
 *
 * Company resolution order:
 * 1. X-Company-Id request header (set by frontend CompanyContext)
 * 2. User's default company (is_default = true in company_users)
 * 3. First company the user belongs to
 *
 * Attaches companyId and companyRole to the request object.
 */
export function withCompany(handler: CompanyHandler): NextApiHandler {
  return withAuth(async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const authReq = req as AuthenticatedNextApiRequest;
      const userId = authReq.user.id;

      // 1. Try X-Company-Id header
      const companyId = req.headers['x-company-id'] as string | undefined;

      if (companyId) {
        // Validate user has access to this specific company
        const access = await sql`
          SELECT role FROM company_users
          WHERE user_id = ${userId} AND company_id = ${companyId}::UUID
          LIMIT 1
        `;

        if (access.length === 0) {
          return res.status(403).json({
            success: false,
            error: { code: 'FORBIDDEN', message: 'You do not have access to this company' },
          });
        }

        (req as CompanyApiRequest).companyId = companyId;
        (req as CompanyApiRequest).companyRole = access[0]!.role as string;
        return handler(req, res);
      }

      // 2. Fall back to user's default or first company
      const companies = await sql`
        SELECT company_id, role, is_default
        FROM company_users
        WHERE user_id = ${userId}
        ORDER BY is_default DESC, created_at ASC
        LIMIT 1
      `;

      if (companies.length === 0) {
        return res.status(400).json({
          success: false,
          error: { code: 'NO_COMPANY', message: 'No company assigned. Please contact an administrator.' },
        });
      }

      (req as CompanyApiRequest).companyId = companies[0]!.company_id as string;
      (req as CompanyApiRequest).companyRole = companies[0]!.role as string;
      return handler(req, res);
    } catch (error) {
      log.error('Company middleware error', error instanceof Error ? { message: error.message } : { error }, 'CompanyMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'COMPANY_ERROR', message: 'Failed to resolve company context' },
      });
    }
  });
}

/**
 * Write-access gate — requires owner/admin/manager role for mutating methods.
 *
 * Wraps a handler that has already been enriched by withCompany (so
 * `req.companyRole` is populated). For any POST/PUT/PATCH/DELETE request
 * where the caller's per-company role is NOT owner/admin/manager (i.e. it's
 * "viewer" or some unknown future read-only role), returns 403 before the
 * handler runs. GET/HEAD/OPTIONS pass through unchanged.
 *
 * Usage:
 *   export default withCompany(withErrorHandler(withWriteAccess(handler)));
 *
 * Defaults apply to the vast majority of accounting endpoints. For a
 * stricter gate (e.g. "admins only") pass `{ allowedRoles: [...] }`.
 * For a looser gate (e.g. allowing viewers to save their own preferences)
 * pass `{ allowedRoles: null }` to disable this layer entirely — it's
 * explicit so a grep finds every exception.
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import type { CompanyApiRequest } from './withCompany';

const WRITE_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
export const DEFAULT_WRITE_ROLES = ['owner', 'admin', 'manager'] as const;

export type WriteRole = (typeof DEFAULT_WRITE_ROLES)[number];

interface WithWriteAccessOptions {
  /**
   * Roles allowed to mutate. Default: ['owner', 'admin', 'manager'].
   * Set to `null` to disable the gate for a specific endpoint (e.g. user
   * preferences where a viewer should be able to save their own state).
   */
  allowedRoles?: readonly string[] | null;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Handler = (req: any, res: NextApiResponse<any>) => unknown | Promise<unknown>;

export function withWriteAccess(
  handler: Handler,
  options: WithWriteAccessOptions = {},
): NextApiHandler {
  const allowed = options.allowedRoles === undefined ? DEFAULT_WRITE_ROLES : options.allowedRoles;

  return async (req: NextApiRequest, res: NextApiResponse) => {
    // Explicit opt-out: allowedRoles: null → no gate.
    if (allowed === null) {
      return handler(req, res);
    }

    // Read-only methods always pass through.
    const method = (req.method ?? 'GET').toUpperCase();
    if (!WRITE_METHODS.has(method)) {
      return handler(req, res);
    }

    const companyReq = req as CompanyApiRequest;
    const role = companyReq.companyRole;

    // If withCompany didn't run first (misuse), fail closed.
    if (!role) {
      return apiResponse.forbidden(
        res,
        'Write access check failed: no company role on request.',
      );
    }

    if (!allowed.includes(role)) {
      return apiResponse.forbidden(
        res,
        `Your role (${role}) does not allow this action.`,
      );
    }

    return handler(req, res);
  };
}

/**
 * Supplier Purchase Orders API
 * GET    /api/accounting/supplier-purchase-orders           - List purchase orders
 * GET    /api/accounting/supplier-purchase-orders?id=UUID   - Get single order with items
 * POST   /api/accounting/supplier-purchase-orders           - Create purchase order
 * PUT    /api/accounting/supplier-purchase-orders           - Update draft purchase order
 * DELETE /api/accounting/supplier-purchase-orders           - Delete draft purchase order
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import type { AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getPurchaseOrder,
  listPurchaseOrders,
  createPurchaseOrder,
  updatePurchaseOrder,
  deletePurchaseOrder,
} from '@/modules/accounting/services/purchaseOrderService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  // ── GET ───────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { id, status, search, limit, offset } = req.query;

      if (id) {
        const result = await getPurchaseOrder(String(id), companyId);
        if (!result) return apiResponse.notFound(res, 'Purchase order');
        return apiResponse.success(res, result);
      }

      const result = await listPurchaseOrders({
        companyId,
        status: status ? String(status) : null,
        search: search ? String(search) : null,
        limit: Number(limit) || 100,
        offset: Number(offset) || 0,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get purchase orders', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get purchase orders');
    }
  }

  // ── POST ──────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const { supplier_id, order_date, delivery_date, reference, notes, internal_notes, items } =
        req.body;

      if (!supplier_id || !order_date || !Array.isArray(items) || items.length === 0) {
        return apiResponse.badRequest(
          res,
          'supplier_id, order_date, and at least one item are required'
        );
      }

      const result = await createPurchaseOrder({
        companyId,
        userId: req.user.id,
        supplier_id,
        order_date,
        delivery_date: delivery_date ?? null,
        reference: reference ?? null,
        notes: notes ?? null,
        internal_notes: internal_notes ?? null,
        items,
      });

      return apiResponse.created(res, result);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create purchase order';
      log.error('Failed to create purchase order', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  // ── PUT ───────────────────────────────────────────────────────────────────
  if (req.method === 'PUT') {
    try {
      const { id, supplier_id, order_date, delivery_date, reference, notes, internal_notes, items } =
        req.body;

      if (!id) return apiResponse.badRequest(res, 'id is required');

      const result = await updatePurchaseOrder({
        id,
        companyId,
        supplier_id: supplier_id ?? null,
        order_date: order_date ?? null,
        delivery_date: delivery_date ?? null,
        reference: reference !== undefined ? reference : null,
        notes: notes !== undefined ? notes : null,
        internal_notes: internal_notes !== undefined ? internal_notes : null,
        items: Array.isArray(items) && items.length > 0 ? items : undefined,
      });

      if ('error' in result) {
        if (result.error === 'not_found') return apiResponse.notFound(res, 'Purchase order');
        return apiResponse.badRequest(res, 'Only draft purchase orders can be updated');
      }

      return apiResponse.success(res, result);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update purchase order';
      log.error('Failed to update purchase order', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  // ── DELETE ────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    try {
      const { id } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');

      const result = await deletePurchaseOrder(id, companyId);

      if ('error' in result) {
        if (result.error === 'not_found') return apiResponse.notFound(res, 'Purchase order');
        return apiResponse.badRequest(res, 'Only draft purchase orders can be deleted');
      }

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to delete purchase order', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to delete purchase order');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
}

