/**
 * AP Aging Export API
 * GET — export accounts payable aging report as CSV
 *   ?as_at_date=YYYY-MM-DD   (optional, defaults to today)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAPAging } from '@/modules/accounting/services/apAgingService';
import { csvCell } from '@/lib/csv';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const { companyId } = req as CompanyApiRequest;

  try {
    const asAtDate = req.query.as_at_date ? String(req.query.as_at_date) : undefined;

    const buckets = await getAPAging(companyId, asAtDate);

    const totalCurrent = buckets.reduce((s, r) => s + r.current, 0);
    const total30 = buckets.reduce((s, r) => s + r.days30, 0);
    const total60 = buckets.reduce((s, r) => s + r.days60, 0);
    const total90 = buckets.reduce((s, r) => s + r.days90, 0);
    const total120Plus = buckets.reduce((s, r) => s + r.days120Plus, 0);
    const grandTotal = buckets.reduce((s, r) => s + r.total, 0);

    const csvLines = [
      'Supplier,Current,30 Days,60 Days,90 Days,120+ Days,Total',
      ...buckets.map(r =>
        [
          csvCell(r.entityName),
          r.current.toFixed(2),
          r.days30.toFixed(2),
          r.days60.toFixed(2),
          r.days90.toFixed(2),
          r.days120Plus.toFixed(2),
          r.total.toFixed(2),
        ].join(',')
      ),
      [
        csvCell('TOTALS'),
        totalCurrent.toFixed(2),
        total30.toFixed(2),
        total60.toFixed(2),
        total90.toFixed(2),
        total120Plus.toFixed(2),
        grandTotal.toFixed(2),
      ].join(','),
    ];

    const csv = csvLines.join('\n');
    const filename = `ap-aging-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export AP aging', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export AP aging');
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Admin Feature Flag Detail API
 * GET   /api/admin/features/[id] — Get a specific feature flag
 * PATCH /api/admin/features/[id] — Update name, description, or is_global
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import {
  getFeatureFlag,
  updateFeatureFlag,
} from '@/modules/admin/services/featureFlagService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';


async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const flag = await getFeatureFlag(id);
      if (!flag) return apiResponse.notFound(res, 'FeatureFlag', id);
      return apiResponse.success(res, flag);
    } catch (err) {
      log.error('Failed to get feature flag', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get feature flag');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const { name, description, is_global } = req.body as {
        name?: string;
        description?: string;
        is_global?: boolean;
      };

      await updateFeatureFlag(id, { name, description, is_global });

      await logAdminAction(
        req.user.id,
        'feature_flag.update',
        'feature_flag',
        id,
        { name, description, is_global },
        getIp(req)
      );

      const updated = await getFeatureFlag(id);
      if (!updated) return apiResponse.notFound(res, 'FeatureFlag', id);
      return apiResponse.success(res, updated);
    } catch (err) {
      log.error('Failed to update feature flag', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update feature flag');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH']);
}

export default withAdmin(handler);

