/**
 * Admin Platform QA — comprehensive walkthrough of all /admin/* pages
 * Runs against http://localhost:3200
 */
import { test, expect, Page } from '@playwright/test';
import fs from 'fs';
import path from 'path';

const BASE = 'http://localhost:3200';
const SCREENSHOT_DIR = path.join(process.cwd(), 'tests/e2e/screenshots/admin-qa');

// Ensure screenshot dir exists
if (!fs.existsSync(SCREENSHOT_DIR)) {
  fs.mkdirSync(SCREENSHOT_DIR, { recursive: true });
}

async function loginAsAdmin(page: Page) {
  const res = await page.request.post(`${BASE}/api/auth/login`, {
    data: { email: 'admin@isaflow.co.za', password: 'admin123' },
  });
  if (res.status() !== 200) {
    throw new Error(`Login failed: ${res.status()} — ${await res.text()}`);
  }
}

async function screenshot(page: Page, name: string) {
  await page.screenshot({
    path: path.join(SCREENSHOT_DIR, `${name}.png`),
    fullPage: true,
  });
}

async function getConsoleErrors(page: Page): Promise<string[]> {
  const errors: string[] = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  return errors;
}

// ─── 1. LOGIN ────────────────────────────────────────────────────────────────
test('login as admin', async ({ page }) => {
  await page.goto(`${BASE}/login`);
  await page.fill('input[type="email"]', 'admin@isaflow.co.za');
  await page.fill('input[type="password"]', 'admin123');
  await page.click('button[type="submit"]');
  await page.waitForTimeout(3000);
  const url = page.url();
  await screenshot(page, '01-login');
  expect(url).not.toContain('/login');
});

