// ─── 10. BILLING OVERVIEW ────────────────────────────────────────────────────
test('10. Billing Overview /admin/billing/overview', async () => {
  const ok = await goto('/admin/billing/overview', 'Billing Overview');
  await ss(sharedPage, '10-billing-overview');
