/**
 * Migration Session API
 * GET  /api/accounting/migration/session — active in-progress session for company
 * POST /api/accounting/migration/session — create new session { sourceSystem }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { createSession, completeSession, mapSessionRow } from '@/modules/accounting/services/migrationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const rows = await sql`
      SELECT * FROM migration_sessions
      WHERE company_id = ${companyId}::UUID AND status = 'in_progress'
      ORDER BY started_at DESC
      LIMIT 1
    `;

    if (rows.length === 0) {
      return apiResponse.success(res, { session: null });
    }

    return apiResponse.success(res, { session: mapSessionRow(rows[0]!) });
  }

  if (req.method === 'POST') {
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const { sourceSystem, sessionId, action } = req.body as {
      sourceSystem?: string;
      sessionId?: string;
      action?: string;
    };

    // Handle "complete" action — mark session as completed
    if (action === 'complete' && sessionId) {
      const session = await completeSession(sessionId, companyId);
      log.info('Migration session completed', { companyId, sessionId }, 'migration');
      return apiResponse.success(res, { session });
    }

    // Default: create a new session
    if (!sourceSystem?.trim()) {
      return apiResponse.validationError(res, { sourceSystem: 'Source system is required' });
    }

    const session = await createSession(companyId, sourceSystem, userId);
    log.info('Migration session started', { companyId, sourceSystem, sessionId: session.id }, 'migration');
    return apiResponse.created(res, { session }, 'Migration session created');
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Migration Service — Session management
 * PRD: Customer Migration Wizard — Phase 1
 *
 * CRUD for migration_sessions. See also:
 *   migrationCoaService.ts  — Chart of accounts import
 *   migrationContactService.ts — Customers + suppliers import
 *   migrationImportService.ts  — Opening balances + AR/AP invoices
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;


// ── Shared types (re-exported for consumers) ─────────────────────────────────

export type MigrationStatus = 'in_progress' | 'completed' | 'abandoned';

export interface MigrationSession {
  id: string;
  companyId: string;
  sourceSystem: string | null;
  status: MigrationStatus;
  stepsCompleted: Record<string, boolean>;
  coaRecordsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: boolean;
  arInvoicesImported: number;
  apInvoicesImported: number;
  errors: MigrationError[];
  startedBy: string;
  startedAt: string;
  completedAt: string | null;
  notes: string | null;
}

export interface MigrationError {
  step: string;
  row?: number;
  field?: string;
  message: string;
}

export interface ImportResult {
  imported: number;
  skipped: number;
  errors: MigrationError[];
}

// ── Row mapper ───────────────────────────────────────────────────────────────

export function mapSessionRow(r: Row): MigrationSession {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    sourceSystem: r.source_system != null ? String(r.source_system) : null,
    status: r.status as MigrationStatus,
    stepsCompleted: (r.steps_completed as Record<string, boolean>) ?? {},
    coaRecordsImported: Number(r.coa_records_imported ?? 0),
    customersImported: Number(r.customers_imported ?? 0),
    suppliersImported: Number(r.suppliers_imported ?? 0),
    openingBalancesSet: Boolean(r.opening_balances_set),
    arInvoicesImported: Number(r.ar_invoices_imported ?? 0),
    apInvoicesImported: Number(r.ap_invoices_imported ?? 0),
    errors: (r.errors as MigrationError[]) ?? [],
    startedBy: String(r.started_by),
    startedAt: r.started_at instanceof Date ? r.started_at.toISOString() : String(r.started_at),
    completedAt: r.completed_at
      ? (r.completed_at instanceof Date ? r.completed_at.toISOString() : String(r.completed_at))
      : null,
    notes: r.notes != null ? String(r.notes) : null,
  };
}

// ── Public API ───────────────────────────────────────────────────────────────

export async function createSession(
  companyId: string,
  sourceSystem: string,
  userId: string,
): Promise<MigrationSession> {
  const rows = (await sql`
    INSERT INTO migration_sessions (company_id, source_system, started_by)
    VALUES (${companyId}::UUID, ${sourceSystem}, ${userId}::UUID)
    RETURNING *
  `) as Row[];
  log.info('Migration session created', { companyId, sourceSystem }, 'migration');
  return mapSessionRow(rows[0]!);
}

export async function getSession(
  sessionId: string,
  companyId: string,
): Promise<MigrationSession | null> {
  const rows = (await sql`
    SELECT * FROM migration_sessions
    WHERE id = ${sessionId}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];

