import { neon } from '@neondatabase/serverless';
import * as fs from 'node:fs';
const env = fs.readFileSync('/home/hein/Workspace/IsaFlow/.env.local', 'utf-8');
for (const line of env.split('\n')) {
  const m = line.match(/^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*)\s*$/);
  if (m && !process.env[m[1]!]) process.env[m[1]!] = m[2]!.replace(/^["']|["']$/g, '');
}
const sql = neon(process.env.DATABASE_URL!);
async function main() {
  // Check gl_accounts constraints
  const constraints = await sql`
    SELECT conname, contype, pg_get_constraintdef(oid) AS def
    FROM pg_constraint
    WHERE conrelid = 'gl_accounts'::regclass
    ORDER BY contype, conname
  `;
  console.log('\n=== gl_accounts constraints ===');
  for (const r of constraints as {conname: string, contype: string, def: string}[]) {
    console.log(`  ${r.contype}: ${r.conname} — ${r.def}`);
  }

  // Check what indexes exist on gl_accounts
  const indexes = await sql`
    SELECT indexname, indexdef
    FROM pg_indexes
    WHERE tablename = 'gl_accounts'
    ORDER BY indexname
  `;
  console.log('\n=== gl_accounts indexes ===');
  for (const r of indexes as {indexname: string, indexdef: string}[]) {
    console.log(`  ${r.indexname}: ${r.indexdef}`);
  }
}
main().catch(e => { console.error(e.message); process.exit(1); });

