/**
 * Admin — Feature Flags
 * View and edit all platform feature flags. Features are seeded via migration,
 * so create/delete is not exposed here — only name, description, and is_global.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2, Pencil, Globe, Lock, X, Check } from 'lucide-react';

interface FeatureFlag {
  id: string;
  code: string;
  name: string;
  description: string | null;
  is_global: boolean;
  created_at: string;
}

interface EditState {
  name: string;
  description: string;
  is_global: boolean;
}

function fmtDate(d: string) {
  return new Date(d).toLocaleDateString('en-ZA');
}

export default function AdminFeaturesPage() {
  const [flags, setFlags]         = useState<FeatureFlag[]>([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [editing, setEditing]     = useState<string | null>(null);
  const [editState, setEditState] = useState<EditState>({ name: '', description: '', is_global: false });
  const [saving, setSaving]       = useState(false);
  const [saveError, setSaveError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res  = await apiFetch('/api/admin/features');
      const json = await res.json() as { data?: FeatureFlag[]; message?: string };
      if (!res.ok) throw new Error(json.message || 'Failed to load features');
      setFlags(json.data ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load features');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  function openEdit(flag: FeatureFlag) {
    setEditing(flag.id);
    setEditState({
      name: flag.name,
      description: flag.description ?? '',
      is_global: flag.is_global,
    });
    setSaveError('');
  }

  function cancelEdit() {
    setEditing(null);
    setSaveError('');
  }

  async function saveEdit(id: string) {
    setSaving(true);
    setSaveError('');
    try {
      const res = await apiFetch(`/api/admin/features/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: editState.name.trim() || undefined,
          description: editState.description.trim() || undefined,
          is_global: editState.is_global,
        }),
      });
      const json = await res.json() as { data?: FeatureFlag; message?: string };
      if (!res.ok) throw new Error(json.message || 'Failed to save');

      setFlags((prev) =>
        prev.map((f) => (f.id === id && json.data ? json.data : f))
      );
      setEditing(null);
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : 'Failed to save');
    } finally {
      setSaving(false);
    }
  }

  return (
    <AdminLayout title="Feature Flags">
      <div className="mb-5 flex items-center justify-between">
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Feature flags control access to platform capabilities.
          Flags are seeded via migration — edit names, descriptions, and global availability here.
        </p>
        <span className="text-sm text-gray-500 dark:text-gray-400">{flags.length} flags</span>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <th className="px-4 py-3 font-medium">Code</th>
                <th className="px-4 py-3 font-medium">Name</th>
                <th className="px-4 py-3 font-medium">Description</th>
                <th className="px-4 py-3 font-medium">Global</th>
                <th className="px-4 py-3 font-medium">Created</th>
                <th className="px-4 py-3 font-medium w-16"></th>
              </tr>
            </thead>
            <tbody>
              {loading && flags.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center">
                    <Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" />
                  </td>
                </tr>
              )}
              {!loading && flags.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center text-gray-400">
                    No feature flags found
                  </td>
                </tr>
              )}

              {flags.map((flag) =>
                editing === flag.id ? (
                  // Edit row
                  <tr
                    key={flag.id}
                    className="border-b border-gray-100 dark:border-gray-800 last:border-0 bg-teal-50/40 dark:bg-teal-900/10"
                  >
                    <td className="px-4 py-3">
                      <code className="text-xs font-mono text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded">
                        {flag.code}
                      </code>
                    </td>
                    <td className="px-4 py-3">
                      <input
                        type="text"
                        value={editState.name}
                        onChange={(e) => setEditState((s) => ({ ...s, name: e.target.value }))}
                        className="w-full px-2 py-1 text-sm rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                        placeholder="Feature name"
                      />
                    </td>
                    <td className="px-4 py-3">
                      <input
                        type="text"
                        value={editState.description}
                        onChange={(e) => setEditState((s) => ({ ...s, description: e.target.value }))}
                        className="w-full px-2 py-1 text-sm rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                        placeholder="Description"
                      />
                    </td>
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => setEditState((s) => ({ ...s, is_global: !s.is_global }))}
                        className={`flex items-center gap-1.5 px-2 py-1 rounded text-xs font-medium transition-colors ${
                          editState.is_global
                            ? 'bg-teal-100 text-teal-700 dark:bg-teal-900/40 dark:text-teal-300'
                            : 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400'
                        }`}
                      >
                        {editState.is_global
                          ? <><Globe className="w-3 h-3" /> Global</>
                          : <><Lock className="w-3 h-3" /> Plan only</>
                        }
                      </button>
                    </td>
                    <td className="px-4 py-3 text-gray-400 text-xs">{fmtDate(flag.created_at)}</td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1">
                        {saveError && (
                          <span className="text-xs text-red-500 mr-1">{saveError}</span>
                        )}
                        <button
                          onClick={() => void saveEdit(flag.id)}
                          disabled={saving}
                          className="p-1.5 rounded text-teal-600 hover:bg-teal-50 dark:hover:bg-teal-900/20 disabled:opacity-40 transition-colors"
                          title="Save"
                        >
                          {saving
                            ? <Loader2 className="w-4 h-4 animate-spin" />
                            : <Check className="w-4 h-4" />
                          }
                        </button>
                        <button
                          onClick={cancelEdit}
                          disabled={saving}
                          className="p-1.5 rounded text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800 disabled:opacity-40 transition-colors"
                          title="Cancel"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ) : (
                  // Read-only row
                  <tr
                    key={flag.id}
                    className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 transition-colors"
                  >
                    <td className="px-4 py-3">
                      <code className="text-xs font-mono text-gray-600 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded">
                        {flag.code}
                      </code>
                    </td>
                    <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">
                      {flag.name}
                    </td>
                    <td className="px-4 py-3 text-gray-500 dark:text-gray-400 max-w-xs truncate">
                      {flag.description || <span className="italic text-gray-300 dark:text-gray-600">No description</span>}
                    </td>
                    <td className="px-4 py-3">
                      {flag.is_global ? (
                        <span className="flex items-center gap-1 text-xs text-teal-600 dark:text-teal-400">
                          <Globe className="w-3.5 h-3.5" /> Global
                        </span>
                      ) : (
                        <span className="flex items-center gap-1 text-xs text-gray-400">
                          <Lock className="w-3.5 h-3.5" /> Plan only
                        </span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-gray-400 text-xs whitespace-nowrap">
                      {fmtDate(flag.created_at)}
                    </td>
                    <td className="px-4 py-3">
                      <button
                        onClick={() => openEdit(flag)}
                        className="p-1.5 rounded text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                        title="Edit feature flag"
                      >
                        <Pencil className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                )
              )}
            </tbody>
          </table>
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * AdminLayout — wraps AppLayout with admin sidebar nav.
 * Enforces super_admin role; redirects non-admins to /login.
 */

import { useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { AdminNav } from './AdminNav';
import { useAuth } from '@/contexts/AuthContext';
import { Loader2 } from 'lucide-react';

interface AdminLayoutProps {
  children: React.ReactNode;
  title: string;
}

export function AdminLayout({ children, title }: AdminLayoutProps) {
  const { user, loading } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!loading && (!user || user.role !== 'super_admin')) {
      void router.replace('/login');
    }
  }, [user, loading, router]);

  if (loading || !user || user.role !== 'super_admin') {
    return (
      <AppLayout>
        <div className="flex items-center justify-center h-64">
          <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="flex min-h-[calc(100vh-4rem)] -m-4 lg:-m-6">
        <AdminNav />
        <main className="flex-1 p-6 overflow-y-auto bg-white dark:bg-gray-950 min-w-0">
          <h1 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">{title}</h1>
          {children}
        </main>
      </div>
    </AppLayout>
  );
}

/**
 * Admin — Subscription List
 * Filter, search, paginate subscriptions; add new subscription.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { AlertCircle, Loader2, Search, ChevronLeft, ChevronRight, Plus, X, Check } from 'lucide-react';

interface Subscription {
  id: string;
  company_id: string;
  company_name: string;
  plan_id: string;
  plan_name: string;
  plan_code: string;
  status: 'trial' | 'active' | 'past_due' | 'cancelled' | 'paused';
  billing_cycle: string;
  discount_percent: number;
  monthly_amount_cents: number;
  current_period_start: string | null;
  current_period_end: string | null;
  created_at: string;
}

interface Plan {
  id: string;
  name: string;
  code: string;
}

interface PagedResponse {
  items: Subscription[];
  total: number;
  page: number;
  limit: number;
}

interface SubForm {
  company_id: string;
  plan_id: string;
  billing_cycle: string;
  discount_pct: string;
}

const EMPTY_FORM: SubForm = { company_id: '', plan_id: '', billing_cycle: 'monthly', discount_pct: '0' };

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  past_due:  'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
  paused:    'bg-blue-500/10 text-blue-400',
};

export default function SubscriptionsPage() {
  const adminHref = useAdminHref();
  const [rows, setRows]         = useState<Subscription[]>([]);
  const [total, setTotal]       = useState(0);
  const [page, setPage]         = useState(1);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState('');
  const [search, setSearch]     = useState('');
  const [status, setStatus]     = useState('');
  const [plans, setPlans]       = useState<Plan[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm]         = useState<SubForm>(EMPTY_FORM);
  const [formError, setFormError] = useState('');
  const [saving, setSaving]     = useState(false);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const LIMIT = 25;
  void adminHref; // used for future navigation

  const load = useCallback(async (q: string, st: string, pg: number) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ page: String(pg), limit: String(LIMIT) });
      if (q)  params.set('search', q);
      if (st) params.set('status', st);
      const res  = await apiFetch(`/api/admin/billing/subscriptions?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load subscriptions');
      const d = json.data as PagedResponse;
      setRows(d.items);
      setTotal(d.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, []);

  const loadPlans = useCallback(async () => {
    try {
      const res  = await apiFetch('/api/admin/billing/plans');
      const json = await res.json();
      if (res.ok) setPlans((json.data ?? []) as Plan[]);
    } catch { /* non-critical */ }
  }, []);

  useEffect(() => { void loadPlans(); }, [loadPlans]);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      void load(search, status, 1);
    }, 300);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [search, status, load]);

  useEffect(() => { void load(search, status, page); }, [page]); // eslint-disable-line react-hooks/exhaustive-deps

  const totalPages = Math.max(1, Math.ceil(total / LIMIT));

  async function handleAdd() {
    setFormError('');
    if (!form.company_id.trim()) { setFormError('Company ID is required'); return; }
    if (!form.plan_id)           { setFormError('Plan is required'); return; }
    setSaving(true);
    try {
      const res  = await apiFetch('/api/admin/billing/subscriptions', {
        method: 'POST',
        body: JSON.stringify({
          company_id:    form.company_id,
          plan_id:       form.plan_id,
          billing_cycle: form.billing_cycle,
          discount_pct:  parseFloat(form.discount_pct) || 0,
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to create subscription');
      setShowForm(false);
      setForm(EMPTY_FORM);
      void load(search, status, 1);
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setSaving(false);
    }
  }

  return (
    <AdminLayout title="Subscriptions">
      {/* Toolbar */}
      <div className="flex gap-3 flex-wrap mb-5">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Search company..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500" />
        </div>
        <select value={status} onChange={e => { setStatus(e.target.value); setPage(1); }}
          className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
          <option value="">All statuses</option>
          <option value="trial">Trial</option>
          <option value="active">Active</option>
          <option value="past_due">Past Due</option>
          <option value="cancelled">Cancelled</option>
          <option value="paused">Paused</option>
        </select>
        <span className="text-sm text-gray-500 dark:text-gray-400 self-center ml-auto">{total} total</span>
        <button onClick={() => { setShowForm(true); setFormError(''); setForm(EMPTY_FORM); }}
          className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors">
          <Plus className="w-4 h-4" /> Add Subscription
        </button>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Add Subscription Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl w-full max-w-md">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200 dark:border-gray-700">
