/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 * Uses useAdminPrefix hook for subdomain-aware navigation.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
  ToggleRight,
} from 'lucide-react';

interface NavDef {
  label: string;
  /** Relative path without /admin prefix, e.g. '' for dashboard, '/companies' etc. */
  path: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Navigation definitions with relative paths — full hrefs built dynamically via useAdminHref */
const NAV_DEFS: NavDef[] = [
  { label: 'Dashboard',   path: '',                          icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies',                icon: Building2 },
  { label: 'Users',       path: '/users',                    icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
    ],
  },
  { label: 'Features',    path: '/features',   icon: ToggleRight },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',   path: '/analytics',  icon: BarChart2 },
  { label: 'Components',  path: '/components', icon: Palette },
  { label: 'Settings',    path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const buildHref = useAdminHref();

  const isActive = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    if (adminPath === '') return router.asPath === href;
    return router.asPath.startsWith(href);
  };

  const isSectionOpen = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    return router.asPath.startsWith(href);
  };

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {NAV_DEFS.map(item => {
          const Icon = item.icon;
          const href = buildHref(`/admin${item.path}`);

          if (item.disabled) {
            return (
              <div
                key={item.path}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.path);
            return (
              <div key={item.path}>
                <Link
                  href={href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.path) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.path) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childHref = buildHref(`/admin${child.path}`);
                      const childActive = router.asPath === childHref;
                      return (
                        <Link
                          key={child.path}
                          href={childHref}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.path);
          return (
            <Link
              key={item.path}
              href={href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

/**
 * Admin Company Features API
 * GET    /api/admin/companies/[id]/features — Effective features for a company
 * POST   /api/admin/companies/[id]/features — Set a feature override
 * DELETE /api/admin/companies/[id]/features — Remove a feature override
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import {
  getCompanyEffectiveFeatures,
  setCompanyFeatureOverride,
  removeCompanyFeatureOverride,
} from '@/modules/admin/services/featureFlagService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';


async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const features = await getCompanyEffectiveFeatures(companyId);
      return apiResponse.success(res, features);
    } catch (err) {
      log.error('Failed to get company features', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get company features');
    }
  }

  if (req.method === 'POST') {
    try {
      const { feature_id, enabled, reason } = req.body as {
        feature_id?: string;
        enabled?: boolean;
        reason?: string;
      };

      if (!feature_id) return apiResponse.badRequest(res, 'feature_id is required');
      if (enabled === undefined || enabled === null) {
        return apiResponse.badRequest(res, 'enabled is required');
      }
      if (!reason) return apiResponse.badRequest(res, 'reason is required');

      await setCompanyFeatureOverride(
        companyId,
        feature_id,
        enabled,
        reason,
        req.user.id
      );

      await logAdminAction(
        req.user.id,
        'company_feature.override_set',
        'company',
        companyId,
        { feature_id, enabled, reason },
        getIp(req)
      );

      const updated = await getCompanyEffectiveFeatures(companyId);
      return apiResponse.success(res, updated);
    } catch (err) {
      log.error('Failed to set company feature override', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to set feature override');
    }
  }

  if (req.method === 'DELETE') {
    try {
      const { feature_id } = req.body as { feature_id?: string };

      if (!feature_id) return apiResponse.badRequest(res, 'feature_id is required');

      await removeCompanyFeatureOverride(companyId, feature_id);

      await logAdminAction(
        req.user.id,
        'company_feature.override_removed',
        'company',
        companyId,
        { feature_id },
        getIp(req)
      );

      const updated = await getCompanyEffectiveFeatures(companyId);
      return apiResponse.success(res, updated);
    } catch (err) {
      log.error('Failed to remove company feature override', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to remove feature override');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

export default withAdmin(handler);

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortColKey = filters.sort_by ?? '';
  if (sortColKey && !ALLOWED_SORT_COLUMNS[sortColKey]) throw new Error(`Invalid sort column: ${sortColKey}`);
  const sortCol = ALLOWED_SORT_COLUMNS[sortColKey] ?? 'c.created_at';
  const rawDir = (filters.sort_dir ?? 'desc').toUpperCase();
  if (rawDir !== 'ASC' && rawDir !== 'DESC') throw new Error('Invalid sort direction');
  const sortDir = rawDir === 'ASC' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getCompanyDetail(
  companyId: string
): Promise<AdminCompanyDetail | null> {
  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')    AS status,
      p.name                          AS plan_name,
      p.code                          AS plan_code,
      c.registration_number,
      c.vat_number,
      c.tax_number,
      c.address_line1,
      c.city,
      c.province,
      c.postal_code,
      c.phone,
      c.email,
      c.website,
      c.billing_email,
      c.billing_contact,
      c.stripe_customer_id,
      c.trial_ends_at,
      c.suspended_at,
      c.suspended_reason,
      c.metadata,
      c.created_at,
      c.updated_at                    AS last_active,
      (SELECT COUNT(*)
         FROM company_users cu
        WHERE cu.company_id = c.id)::int AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int AS mrr_cents
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.id = ${companyId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    name: r.name as string,
    trading_name: r.trading_name as string | null,
    status: r.status as string,
    plan_name: r.plan_name as string | null,
    plan_code: r.plan_code as string | null,
    user_count: r.user_count as number,
    mrr_cents: r.mrr_cents as number,
    created_at: toIso(r.created_at) ?? '',
    last_active: toIso(r.last_active),
    registration_number: r.registration_number as string | null,
    vat_number: r.vat_number as string | null,
    tax_number: r.tax_number as string | null,
    address_line1: r.address_line1 as string | null,
    city: r.city as string | null,
    province: r.province as string | null,
    postal_code: r.postal_code as string | null,
    phone: r.phone as string | null,
    email: r.email as string | null,
    website: r.website as string | null,
    billing_email: r.billing_email as string | null,
    billing_contact: r.billing_contact as string | null,
    stripe_customer_id: r.stripe_customer_id as string | null,
    trial_ends_at: toIso(r.trial_ends_at),
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    metadata: (r.metadata ?? {}) as Record<string, unknown>,
  };
}

export async function updateCompany(
  companyId: string,
  data: Partial<AdminCompanyDetail>
): Promise<void> {
  // Only update safe, explicitly listed fields
  const {
    name, trading_name, phone, email, website,
    billing_email, billing_contact,
    address_line1, city, province, postal_code,
  } = data;

  await sql`
    UPDATE companies SET
      name             = COALESCE(${name ?? null}, name),
      trading_name     = COALESCE(${trading_name ?? null}, trading_name),
      phone            = COALESCE(${phone ?? null}, phone),
      email            = COALESCE(${email ?? null}, email),
      website          = COALESCE(${website ?? null}, website),
      billing_email    = COALESCE(${billing_email ?? null}, billing_email),
      billing_contact  = COALESCE(${billing_contact ?? null}, billing_contact),
      address_line1    = COALESCE(${address_line1 ?? null}, address_line1),
      city             = COALESCE(${city ?? null}, city),
      province         = COALESCE(${province ?? null}, province),
      postal_code      = COALESCE(${postal_code ?? null}, postal_code),
      updated_at       = NOW()
    WHERE id = ${companyId}
  `;

  log.info('updateCompany', { companyId }, 'AdminCompanyService');
}

export async function suspendCompany(
  companyId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'suspended',
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('suspendCompany', { companyId, reason }, 'AdminCompanyService');
}

export async function activateCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'active',
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('activateCompany', { companyId }, 'AdminCompanyService');
}

/** Soft delete — sets status='deleted', preserves data for audit trail. */
export async function deleteCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status     = 'deleted',
        updated_at = NOW()
    WHERE id = ${companyId}
  `;
  log.info('deleteCompany (soft)', { companyId }, 'AdminCompanyService');
}

export async function getCompanyUsers(
  companyId: string
): Promise<{ id: string; name: string; email: string; role: string; last_login: string | null }[]> {
  const rows = await sql`
    SELECT u.id, COALESCE(u.first_name || ' ' || u.last_name, u.email) AS name, u.email, cu.role, u.last_login
    FROM company_users cu JOIN users u ON u.id = cu.user_id
    WHERE cu.company_id = ${companyId} ORDER BY cu.role, u.email
  `;

  return (rows as Row[]).map((r) => ({
    id: r.id as string,
    name: r.name as string,
    email: r.email as string,
    role: r.role as string,
    last_login: r.last_login != null
      ? (r.last_login instanceof Date ? r.last_login.toISOString() : r.last_login as string)
      : null,
  }));
}

