import { apiFetch } from '@/lib/apiFetch';
import { formatDate } from '@/utils/formatters';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  ArrowLeft, AlertCircle, Loader2, Building2, ShieldOff, ShieldCheck,
  Trash2, Download, UserCog,
} from 'lucide-react';
import Link from 'next/link';

interface CompanyDetail {
  id: string;
  name: string;
  registration_number: string | null;
  vat_number: string | null;
  email: string | null;
  phone: string | null;
  address_line1: string | null;
  city: string | null;
  province: string | null;
  postal_code: string | null;
  plan_name: string;
  billing_cycle: string;
  status: string;
  created_at: string;
  last_active: string | null;
}

interface CompanyUser {
  id: string;
  first_name: string;
  last_name: string;
  email: string;
  role: string;
  last_login: string | null;
}

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  suspended: 'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
};

function Field({ label, value }: { label: string; value: string | null | undefined }) {
  return (
    <div>
      <p className="text-xs text-gray-500 dark:text-gray-400 mb-0.5">{label}</p>
      <p className="text-sm text-gray-900 dark:text-white">{value || '\u2014'}</p>
    </div>
  );
}

export default function AdminCompanyDetailPage() {
  const router = useRouter();
  const adminHref = useAdminHref();
  const { id } = router.query;

  const [company, setCompany]   = useState<CompanyDetail | null>(null);
  const [users, setUsers]       = useState<CompanyUser[]>([]);
  const [loading, setLoading]   = useState(true);
  const [usersLoading, setUsersLoading] = useState(false);
  const [error, setError]       = useState('');
  const [activeTab, setActiveTab] = useState<'info' | 'users'>('info');
  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError]     = useState('');
  const [suspendOpen, setSuspendOpen] = useState(false);
  const [suspendReason, setSuspendReason] = useState('');
  const [deleteOpen, setDeleteOpen]   = useState(false);

  const load = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setLoading(true); setError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load company');
      setCompany(json.data as CompanyDetail);
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setLoading(false); }
  }, [id]);

  const loadUsers = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setUsersLoading(true);
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/users`);
      const json = await res.json();
      if (res.ok) setUsers((json.data as CompanyUser[]) || []);
    } catch { /* non-critical */ }
    finally { setUsersLoading(false); }
  }, [id]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (activeTab === 'users') void loadUsers(); }, [activeTab, loadUsers]);

  async function handleSuspend() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/suspend`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: suspendReason }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setSuspendOpen(false); setSuspendReason(''); void load();
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); }
    finally { setActionLoading(false); }
  }

  async function handleActivate() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/activate`, { method: 'POST' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      void load();
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); }
    finally { setActionLoading(false); }
  }

  async function handleDelete() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      void router.push(adminHref('/admin/companies'));
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); setActionLoading(false); }
  }

  async function handleExport() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res = await apiFetch(`/api/admin/companies/${id}/export`);
      if (!res.ok) { const json = await res.json(); throw new Error(json.message || 'Export failed'); }
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `company-${id}-export.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Export failed'); }
    finally { setActionLoading(false); }
  }

  async function handleImpersonate() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/impersonate`, { method: 'POST' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Impersonation failed');
      const token = (json.data as { token: string })?.token;
      if (token) window.open(`/accounting?impersonate=${token}`, '_blank');
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Impersonation failed'); }
    finally { setActionLoading(false); }
  }

  const address = company
    ? [company.address_line1, company.city, company.province, company.postal_code].filter(Boolean).join(', ')
    : null;

  return (
    <AdminLayout title="Company Detail">
      <Link href={adminHref('/admin/companies')}
        className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-900 dark:hover:text-white mb-5 transition-colors">
        <ArrowLeft className="w-4 h-4" /> Back to Companies
      </Link>

      {[error, actionError].filter(Boolean).map((msg, i) => (
        <div key={i} className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {msg}
        </div>
      ))}

      {loading && <div className="flex items-center justify-center py-24"><Loader2 className="w-6 h-6 animate-spin text-teal-500" /></div>}

      {company && (
        <>
          <div className="flex items-start justify-between gap-4 mb-6 flex-wrap">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-teal-500/10 rounded-lg"><Building2 className="w-6 h-6 text-teal-500" /></div>
              <div>
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">{company.name}</h2>
                <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[company.status] ?? ''}`}>{company.status}</span>
              </div>
            </div>
            <div className="flex gap-2 flex-wrap">
              <button onClick={() => void handleExport()} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors disabled:opacity-50">
                <Download className="w-4 h-4" /> Export Data
              </button>
              <button onClick={() => void handleImpersonate()} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-blue-400 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-500/10 transition-colors disabled:opacity-50">
                <UserCog className="w-4 h-4" /> Impersonate
              </button>
              {company.status !== 'suspended'
                ? <button onClick={() => setSuspendOpen(true)} disabled={actionLoading}
                    className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-yellow-400 text-yellow-600 hover:bg-yellow-50 dark:hover:bg-yellow-500/10 transition-colors disabled:opacity-50">
                    <ShieldOff className="w-4 h-4" /> Suspend
                  </button>
                : <button onClick={() => void handleActivate()} disabled={actionLoading}
                    className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-teal-400 text-teal-600 hover:bg-teal-50 dark:hover:bg-teal-500/10 transition-colors disabled:opacity-50">
                    <ShieldCheck className="w-4 h-4" /> Activate
                  </button>
              }
              <button onClick={() => setDeleteOpen(true)} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-red-400 text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-colors disabled:opacity-50">
                <Trash2 className="w-4 h-4" /> Delete
              </button>
            </div>
          </div>

          <div className="flex gap-1 mb-5 border-b border-gray-200 dark:border-gray-700">
            {(['info', 'users'] as const).map(tab => (
              <button key={tab} onClick={() => setActiveTab(tab)}
                className={`px-4 py-2 text-sm font-medium capitalize border-b-2 -mb-px transition-colors ${
                  activeTab === tab ? 'border-teal-500 text-teal-600 dark:text-teal-400' : 'border-transparent text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>
                {tab}
              </button>
            ))}
          </div>

          {activeTab === 'info' && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
              <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl p-5 shadow-sm">
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-4">Company Information</h3>
                <div className="grid grid-cols-2 gap-4">
                  <Field label="Registration #" value={company.registration_number} />
                  <Field label="VAT Number"      value={company.vat_number} />
                  <Field label="Email"           value={company.email} />
                  <Field label="Phone"           value={company.phone} />
                  <Field label="Created"         value={formatDate(company.created_at)} />
                  <Field label="Last Active"     value={formatDate(company.last_active)} />
                  <div className="col-span-2"><Field label="Address" value={address} /></div>
                </div>
              </div>
              <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl p-5 shadow-sm">
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-4">Subscription</h3>
                <div className="grid grid-cols-2 gap-4">
                  <Field label="Plan"          value={company.plan_name} />
                  <Field label="Billing Cycle" value={company.billing_cycle} />
                  <Field label="Status"        value={company.status} />
                </div>
              </div>
            </div>
          )}

          {activeTab === 'users' && (
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
              {usersLoading
                ? <div className="flex items-center justify-center py-12"><Loader2 className="w-5 h-5 animate-spin text-teal-500" /></div>
                : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                          <th className="px-4 py-3 font-medium">Name</th>
                          <th className="px-4 py-3 font-medium">Email</th>
                          <th className="px-4 py-3 font-medium">Role</th>
                          <th className="px-4 py-3 font-medium">Last Login</th>
                        </tr>
                      </thead>
                      <tbody>
                        {users.length === 0 && <tr><td colSpan={4} className="px-4 py-8 text-center text-gray-400">No users</td></tr>}
                        {users.map(u => (
                          <tr key={u.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0">
                            <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{u.first_name} {u.last_name}</td>
                            <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{u.email}</td>
                            <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{u.role}</td>
                            <td className="px-4 py-3 text-gray-500 dark:text-gray-400">{formatDate(u.last_login)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )
              }
            </div>
          )}
        </>
      )}

      <ConfirmModal
        open={suspendOpen}
        title="Suspend Company"
        message="This will immediately prevent all users from accessing the company. Provide a reason below."
        confirmLabel="Suspend"
        confirmClass="bg-yellow-500 hover:bg-yellow-600"
        loading={actionLoading}
        onConfirm={() => void handleSuspend()}
        onCancel={() => setSuspendOpen(false)}
      >
        <textarea rows={3} value={suspendReason} onChange={e => setSuspendReason(e.target.value)}
          placeholder="Reason for suspension..."
          className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-yellow-500 resize-none"
        />
      </ConfirmModal>

      <ConfirmModal
        open={deleteOpen}
        title="Delete Company"
        message={<>This action is <strong>permanent</strong>. All data for <strong>{company?.name}</strong> will be deleted and cannot be recovered.</>}
        confirmLabel="Delete Permanently"
        loading={actionLoading}
        onConfirm={() => void handleDelete()}
        onCancel={() => setDeleteOpen(false)}
      />
    </AdminLayout>
  );
}

/**
 * Admin Usage Analytics API
 * GET /api/admin/analytics/usage — DAU/WAU/MAU, feature adoption, churn signals
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getUsageAnalytics } from '@/modules/admin/services/analyticsService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const analytics = await getUsageAnalytics();
      return apiResponse.success(res, analytics);
    } catch (err) {
      log.error('Failed to get usage analytics', { error: err }, 'admin-analytics-api');
      return apiResponse.badRequest(res, 'Failed to get usage analytics');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

export default withAdmin(handler);

/**
 * Feature Flag Service
 * Resolves effective features per company based on global flags, plan features,
 * and company-level overrides. Used by both the admin platform and feature gating middleware.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  FeatureFlag,
  CompanyEffectiveFeature,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

export async function listFeatureFlags(): Promise<FeatureFlag[]> {
  const rows = await sql`
    SELECT id, code, name, description, is_global, created_at
    FROM feature_flags
    ORDER BY code ASC
  `;

  log.info(`listFeatureFlags: ${rows.length} flags`, {}, 'FeatureFlagService');

  return (rows as Row[]).map((r) => ({
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    is_global: r.is_global as boolean,
    created_at: toIso(r.created_at),
  }));
}

export async function getFeatureFlag(id: string): Promise<FeatureFlag | null> {
  const rows = await sql`
    SELECT id, code, name, description, is_global, created_at
    FROM feature_flags
    WHERE id = ${id}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    is_global: r.is_global as boolean,
    created_at: toIso(r.created_at),
  };
}

export async function updateFeatureFlag(
  id: string,
  data: { name?: string; description?: string; is_global?: boolean }
): Promise<void> {
  await sql`
    UPDATE feature_flags
    SET
      name        = COALESCE(${data.name ?? null}, name),
      description = COALESCE(${data.description ?? null}, description),
      is_global   = COALESCE(${data.is_global ?? null}, is_global)
    WHERE id = ${id}
  `;

  log.info('updateFeatureFlag', { id, data }, 'FeatureFlagService');
}

export async function getCompanyEffectiveFeatures(
  companyId: string
): Promise<CompanyEffectiveFeature[]> {
  // Fetch all flags, plan memberships and overrides in parallel
  const [flagRows, planRows, overrideRows] = await Promise.all([
    sql`
      SELECT id, code, name, is_global
      FROM feature_flags
      ORDER BY code ASC
    `,
    sql`
      SELECT pf.feature_id
      FROM plan_features pf
      JOIN companies c ON c.plan_id = pf.plan_id
      WHERE c.id = ${companyId}
    `,
    sql`
      SELECT feature_id, enabled
      FROM company_feature_overrides
      WHERE company_id = ${companyId}
    `,
  ]);

  const planFeatureIds = new Set(
    (planRows as Row[]).map((r) => r.feature_id as string)
  );

  const overrideMap = new Map<string, boolean>(
    (overrideRows as Row[]).map((r) => [r.feature_id as string, r.enabled as boolean])
  );

  return (flagRows as Row[]).map((r) => {
    const id = r.id as string;
    const isGlobal = r.is_global as boolean;
    const inPlan = planFeatureIds.has(id);
    const override = overrideMap.get(id);

    let enabled: boolean;
    let source: 'global' | 'plan' | 'override';

    if (override !== undefined) {
      // Override always wins
      enabled = override;
      source = 'override';
    } else if (isGlobal) {
      enabled = true;
      source = 'global';
    } else if (inPlan) {
      enabled = true;
      source = 'plan';
    } else {
      enabled = false;
      source = 'plan';
    }

    return {
      code: r.code as string,
      name: r.name as string,
      enabled,
      source,
    };
  });
}

export async function setCompanyFeatureOverride(
  companyId: string,
  featureId: string,
  enabled: boolean,
  reason: string,
  setBy: string
): Promise<void> {
  await sql`
    INSERT INTO company_feature_overrides
      (company_id, feature_id, enabled, reason, set_by, created_at)
    VALUES
      (${companyId}, ${featureId}, ${enabled}, ${reason}, ${setBy}, NOW())
    ON CONFLICT (company_id, feature_id)
    DO UPDATE SET
      enabled    = EXCLUDED.enabled,
      reason     = EXCLUDED.reason,
      set_by     = EXCLUDED.set_by,
      created_at = NOW()
  `;

  log.info('setCompanyFeatureOverride', { companyId, featureId, enabled }, 'FeatureFlagService');
}

export async function removeCompanyFeatureOverride(
  companyId: string,
  featureId: string
): Promise<void> {
  await sql`
    DELETE FROM company_feature_overrides
    WHERE company_id = ${companyId}
      AND feature_id = ${featureId}
  `;

  log.info('removeCompanyFeatureOverride', { companyId, featureId }, 'FeatureFlagService');
}

export async function hasFeature(
  companyId: string,
  featureCode: string
): Promise<boolean> {
  const rows = await sql`
    SELECT
      ff.is_global,
      EXISTS (
        SELECT 1
        FROM plan_features pf
        JOIN companies c ON c.plan_id = pf.plan_id
        WHERE c.id = ${companyId}
          AND pf.feature_id = ff.id
      ) AS in_plan,
      cfo.enabled AS override_enabled
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo
      ON cfo.feature_id = ff.id
      AND cfo.company_id = ${companyId}
    WHERE ff.code = ${featureCode}
    LIMIT 1
  `;

  if (rows.length === 0) return false;

  const r = rows[0] as Row;
  const overrideEnabled = r.override_enabled as boolean | null;

  // Override takes precedence
  if (overrideEnabled !== null) return overrideEnabled;
  // Then global flag
  if (r.is_global as boolean) return true;
  // Then plan membership
  return r.in_plan as boolean;
}

/**
 * Admin Analytics Service
 * Platform health, usage analytics, and settings for ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { PlatformHealth, UsageAnalytics, PlatformSettings } from '../types/admin.types';
type Row = Record<string, unknown>;


function toISOString(value: unknown): string | null {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

export async function getPlatformHealth(): Promise<PlatformHealth> {
  const [activeUsers, apiCalls, dbSize, topCompanies] = await Promise.all([
    getActiveUserCounts(),
    getApiCallCount(),
    getDbSizeMb(),
    getTopCompaniesBySize(),
  ]);

  const health: PlatformHealth = {
    active_users_24h: activeUsers.h24,
    active_users_7d: activeUsers.d7,
    active_users_30d: activeUsers.d30,
    total_api_calls_24h: apiCalls.total,
    error_count_24h: apiCalls.errors,
    error_rate_percent: apiCalls.total > 0
      ? Math.round((apiCalls.errors / apiCalls.total) * 10000) / 100
      : 0,
    db_size_mb: dbSize,
    top_companies_by_size: topCompanies,
  };

  log.info('Platform health fetched', {
    active_users_24h: health.active_users_24h,
    db_size_mb: health.db_size_mb,
  }, 'analyticsService');

  return health;
}

async function getActiveUserCounts(): Promise<{ h24: number; d7: number; d30: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '24 hours') AS h24,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')   AS d7,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days')  AS d30
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    h24: parseInt(row.h24 as string, 10) || 0,
    d7: parseInt(row.d7 as string, 10) || 0,
    d30: parseInt(row.d30 as string, 10) || 0,
  };
}

async function getApiCallCount(): Promise<{ total: number; errors: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE action ILIKE 'error%') AS errors
    FROM admin_audit_log
    WHERE created_at >= NOW() - INTERVAL '24 hours'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10) || 0,
    errors: parseInt(row.errors as string, 10) || 0,
  };
}

async function getDbSizeMb(): Promise<number> {
  const rows = await sql`
    SELECT ROUND(pg_database_size(current_database()) / 1048576.0, 2) AS size_mb
  `;
  const val = (rows[0] as Row).size_mb;
  return parseFloat(val as string) || 0;
}

async function getTopCompaniesBySize(): Promise<PlatformHealth['top_companies_by_size']> {
  // Proxy company "size" by counting rows in major tables grouped by company_id
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name AS company_name,
      (
        COALESCE((SELECT COUNT(*) FROM gl_journal_entries je WHERE je.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM customer_invoices ci WHERE COALESCE(ci.client_id, ci.customer_id) IS NOT NULL AND ci.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM bank_transactions bt WHERE bt.company_id = c.id), 0)
      )::float / 1000.0 AS size_mb
    FROM companies c
    WHERE c.status IS DISTINCT FROM 'deleted'
    ORDER BY size_mb DESC
    LIMIT 10
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    size_mb: parseFloat(row.size_mb as string) || 0,
  }));
}

export async function getUsageAnalytics(): Promise<UsageAnalytics> {
  const [engagement, featureAdoption, revenueByPlan, churnSignals] = await Promise.all([
    getEngagementCounts(),
    getFeatureAdoption(),
    getRevenueByPlan(),
    getChurnSignals(),
  ]);

  const stickiness = engagement.mau > 0
    ? Math.round((engagement.dau / engagement.mau) * 10000) / 100
    : 0;

  const analytics: UsageAnalytics = {
    dau: engagement.dau,
    wau: engagement.wau,
    mau: engagement.mau,
    stickiness_percent: stickiness,
    // top_pages requires a page_views tracking table — not yet implemented
    top_pages: [],
    feature_adoption: featureAdoption,
    revenue_by_plan: revenueByPlan,
    churn_signals: churnSignals,
  };

  log.info('Usage analytics fetched', {
    dau: analytics.dau,
    mau: analytics.mau,
    churn_signals: analytics.churn_signals.length,
  }, 'analyticsService');

  return analytics;
}

async function getEngagementCounts(): Promise<{ dau: number; wau: number; mau: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '1 day')   AS dau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')  AS wau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS mau
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    dau: parseInt(row.dau as string, 10) || 0,
    wau: parseInt(row.wau as string, 10) || 0,
    mau: parseInt(row.mau as string, 10) || 0,
  };
}

async function getFeatureAdoption(): Promise<UsageAnalytics['feature_adoption']> {
  const totalRow = await sql`SELECT COUNT(*) AS total FROM companies WHERE status IS DISTINCT FROM 'deleted'`;
  const total = parseInt((totalRow[0] as Row).total as string, 10) || 1;

  const rows = await sql`
    SELECT
      ff.name AS feature,
      COUNT(DISTINCT cfo.company_id) AS user_count
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo ON cfo.feature_id = ff.id AND cfo.enabled = true
    GROUP BY ff.id, ff.name
    ORDER BY user_count DESC
  `;

  return (rows as Row[]).map((row) => ({
    feature: row.feature as string,
    user_count: parseInt(row.user_count as string, 10) || 0,
    adoption_percent: Math.round(((parseInt(row.user_count as string, 10) || 0) / total) * 10000) / 100,
  }));
}

async function getRevenueByPlan(): Promise<UsageAnalytics['revenue_by_plan']> {
  const rows = await sql`
    SELECT
      p.name AS plan_name,
      COUNT(s.id) AS company_count,
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM plans p
    LEFT JOIN subscriptions s ON s.plan_id = p.id AND s.status IN ('active', 'trial')
    GROUP BY p.id, p.name
    ORDER BY mrr_cents DESC
  `;
  return (rows as Row[]).map((row) => ({
    plan_name: row.plan_name as string,
    mrr_cents: parseInt(row.mrr_cents as string, 10) || 0,
    company_count: parseInt(row.company_count as string, 10) || 0,
  }));
}

async function getChurnSignals(): Promise<UsageAnalytics['churn_signals']> {
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name     AS company_name,
      EXTRACT(DAY FROM NOW() - MAX(u.last_login))::int AS days_inactive,
      MAX(u.last_login) AS last_login
    FROM companies c
    INNER JOIN company_users cu ON cu.company_id = c.id
    INNER JOIN users u ON u.id = cu.user_id AND u.is_active = true
    WHERE c.status IS DISTINCT FROM 'deleted'
    GROUP BY c.id, c.name
    HAVING MAX(u.last_login) < NOW() - INTERVAL '14 days'
        OR MAX(u.last_login) IS NULL
    ORDER BY days_inactive DESC NULLS LAST
    LIMIT 20
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    days_inactive: parseInt(row.days_inactive as string, 10) || 0,
    last_login: toISOString(row.last_login),
  }));
}

