async function getPlatformSummary(): Promise<UsageAnalytics['platform_summary']> {
  const [countRow, dbRow] = await Promise.all([
    sql`
      SELECT
        (SELECT COUNT(*) FROM companies WHERE status IS DISTINCT FROM 'deleted')::int           AS total_companies,
        (SELECT COUNT(*) FROM users WHERE is_active = true)::int                               AS total_users,
        (SELECT COUNT(*) FROM customer_invoices)::int                                          AS total_invoices,
