      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setFeatures((json.data as EffectiveFeature[]) || []);
    }
  } catch (err) {
    setActionError(err instanceof Error ? err.message : 'Failed to toggle feature');
  } finally {
    setFeatureToggling(null);
