      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `company-${id}-export.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Export failed'); }
    finally { setActionLoading(false); }
  }

  async function handleFeatureToggle(feature: EffectiveFeature) {
    if (!id || typeof id !== 'string') return;
    setFeatureToggling(feature.id);
    try {
      if (feature.source === 'override') {
        // If currently overridden, toggle the override value
        const res  = await apiFetch(`/api/admin/companies/${id}/features`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ feature_id: feature.id, enabled: !feature.enabled, reason: 'Toggled via admin panel' }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed');
        setFeatures((json.data as EffectiveFeature[]) || []);
      } else {
        // Set an override to flip the current effective value
        const res  = await apiFetch(`/api/admin/companies/${id}/features`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ feature_id: feature.id, enabled: !feature.enabled, reason: 'Toggled via admin panel' }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed');
        setFeatures((json.data as EffectiveFeature[]) || []);
      }
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to toggle feature');
    } finally {
      setFeatureToggling(null);
    }
  }

  async function handleFeatureClearOverride(feature: EffectiveFeature) {
    if (!id || typeof id !== 'string') return;
    setFeatureToggling(feature.id);
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/features`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feature_id: feature.id }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setFeatures((json.data as EffectiveFeature[]) || []);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to clear override');
    } finally {
      setFeatureToggling(null);
    }
  }

  async function handleImpersonate() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/impersonate`, { method: 'POST' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Impersonation failed');
      const token = (json.data as { token: string })?.token;
      if (token) window.open(`/accounting?impersonate=${token}`, '_blank');
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Impersonation failed'); }
    finally { setActionLoading(false); }
  }

