  console.log('║   RESULTS                                         ║');
  console.log('╚═══════════════════════════════════════════════════╝');
  console.log(`  PASS: ${passed}  FAIL: ${failed}  SKIP: ${skipped}  TOTAL: ${results.length}`);

  if (failed > 0) {
