      console.log(`    ✗ ${r.step}`);
      if (r.error) console.log(`      ${r.error.substring(0, 200)}`);
    }
  }

  process.exit(failed > 0 ? 1 : 0);
}

main().catch((err: unknown) => {
  console.error('Fatal error:', err);
  process.exit(1);
});

