/**
 * Customer Detail Page
 * Tabs: Overview | Delivery Addresses | Contacts
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, User, MapPin, Users, Loader2, AlertCircle, CheckCircle2, XCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { DeliveryAddressesTab } from '@/components/accounting/customers/DeliveryAddressesTab';
import { ContactsTab } from '@/components/accounting/customers/ContactsTab';

interface Customer {
  id: string;
  name: string;
  email: string | null;
  phone: string | null;
  contact_person: string | null;
  vat_number: string | null;
  registration_number: string | null;
  payment_terms: number | null;
  credit_limit: number | null;
  is_active: boolean;
  created_at: string;
}

type Tab = 'overview' | 'addresses' | 'contacts';

const TABS: { id: Tab; label: string; icon: typeof User }[] = [
  { id: 'overview', label: 'Overview', icon: User },
  { id: 'addresses', label: 'Delivery Addresses', icon: MapPin },
  { id: 'contacts', label: 'Contacts', icon: Users },
];

export default function CustomerDetailPage() {
  const router = useRouter();
  const { customerId } = router.query;
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState<Tab>('overview');

  useEffect(() => {
    if (!customerId) return;
    void loadCustomer();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  const loadCustomer = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/customers?id=${customerId as string}`);
      const json = await res.json() as { data?: Customer | Customer[] } | Customer | Customer[];
      const data = (json as { data?: Customer | Customer[] }).data ?? json;
      if (Array.isArray(data)) {
        const match = data.find((c: Customer) => c.id === customerId);
        setCustomer(match ?? null);
        if (!match) setError('Customer not found');
      } else {
        setCustomer(data as Customer);
      }
    } catch {
      setError('Failed to load customer');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
        </div>
      </AppLayout>
    );
  }

  if (!customer) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh] flex-col">
          <AlertCircle className="h-8 w-8 text-red-400 mb-2" />
          <p className="text-[var(--ff-text-secondary)]">{error || 'Customer not found'}</p>
          <Link href="/accounting/customers" className="mt-4 text-sm text-blue-400 hover:text-blue-300">
            Back to Customers
          </Link>
        </div>
      </AppLayout>
    );
  }

  const fields: { label: string; value: string | number | null | undefined; highlight?: boolean }[] = [
    { label: 'Name', value: customer.name, highlight: true },
    { label: 'Email', value: customer.email },
    { label: 'Phone', value: customer.phone },
    { label: 'Contact Person', value: customer.contact_person },
    { label: 'VAT Number', value: customer.vat_number },
    { label: 'Registration Number', value: customer.registration_number },
    { label: 'Payment Terms', value: customer.payment_terms ? `${customer.payment_terms} days` : null },
    {
      label: 'Credit Limit',
      value: customer.credit_limit != null
        ? new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(Number(customer.credit_limit))
        : null,
    },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/customers" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Customers
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <User className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{customer.name}</h1>
              {customer.email && <p className="text-sm text-[var(--ff-text-secondary)]">{customer.email}</p>}
            </div>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${customer.is_active ? 'bg-teal-500/20 text-teal-400' : 'bg-gray-500/20 text-gray-400'}`}>
              {customer.is_active ? 'Active' : 'Inactive'}
            </span>
          </div>

          {/* Tab bar */}
          <div className="flex gap-1 mt-4 border-b border-[var(--ff-border-light)] -mx-6 px-6">
            {TABS.map(tab => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${activeTab === tab.id ? 'border-blue-500 text-blue-400' : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}
                >
                  <Icon className="h-4 w-4" />
                  {tab.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* Tab content */}
        <div className="p-6">
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {fields.map((f, i) => (
                  <div key={i} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                    <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{f.label}</p>
                    <p className={`text-lg font-semibold mt-1 ${f.highlight ? 'text-blue-400' : 'text-[var(--ff-text-primary)]'}`}>
                      {f.value || '—'}
                    </p>
                  </div>
                ))}
              </div>

              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] uppercase mb-2">Status</p>
                <div className="flex items-center gap-2">
                  {customer.is_active
                    ? <><CheckCircle2 className="h-5 w-5 text-teal-400" /><span className="text-sm text-teal-400 font-medium">Active Customer</span></>
                    : <><XCircle className="h-5 w-5 text-gray-400" /><span className="text-sm text-gray-400 font-medium">Inactive Customer</span></>}
                </div>
                {customer.created_at && (
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-2">
                    Created: {customer.created_at.split('T')[0]}
                  </p>
                )}
              </div>
            </div>
          )}

          {activeTab === 'addresses' && typeof customerId === 'string' && (
            <DeliveryAddressesTab customerId={customerId} />
          )}

          {activeTab === 'contacts' && typeof customerId === 'string' && (
            <ContactsTab customerId={customerId} />
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Logger Service
 * Proper logging replacement for console.* statements
 * Zero Tolerance Enforcement: No console.* statements allowed
 */

// Global type declarations for log storage
declare global {
  interface Window {
    __appLogs?: LogEntry[];
  }

  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace NodeJS {
    interface Process {
      __appLogs?: LogEntry[];
    }
  }
}

export interface LogData {
  [key: string]: any;
}

export interface LogEntry {
  timestamp: string;
  level: 'debug' | 'info' | 'warn' | 'error';
  component: string | undefined;
  message: string;
  data: LogData | undefined;
  formattedMessage: string;
}

export interface LoggerOptions {
  enableConsole?: boolean;
  enableFile?: boolean;
  level?: 'debug' | 'info' | 'warn' | 'error';
}

/**
 * Logger class for structured logging
 * Replaces all console.* statements in the application
 */
class Logger {
  private options: LoggerOptions = {
    enableConsole: process.env.NODE_ENV === 'development',
    enableFile: false,
    level: 'info',
  };

  constructor(options?: Partial<LoggerOptions>) {
    this.options = { ...this.options, ...options };
  }

  /**
   * Log debug messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  debug(message: string, data?: LogData, component?: string): void {
    this.log('debug', message, data, component);
  }

  /**
   * Log info messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  info(message: string, data?: LogData, component?: string): void {
    this.log('info', message, data, component);
  }

  /**
   * Log warning messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  warn(message: string, data?: LogData, component?: string): void {
    this.log('warn', message, data, component);
  }

  /**
   * Log error messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  error(message: string, data?: LogData, component?: string): void {
    this.log('error', message, data, component);
  }

  /**
   * Internal logging method
   * @param level - Log level
   * @param message - Log message
   * @param data - Additional data
   * @param component - Component name
   */
  private log(
    level: 'debug' | 'info' | 'warn' | 'error',
    message: string,
    data?: LogData,
    component?: string
  ): void {
    if (!this.shouldLog(level)) return;

    const timestamp = new Date().toISOString();
    const prefix = component ? `[${component}]` : '';
    const logMessage = `${timestamp} [${level.toUpperCase()}] ${prefix} ${message}`;

    // Store logs in memory for development (could be sent to external service in production)
    const logEntry = {
      timestamp,
      level,
      component,
      message,
      data,
      formattedMessage: logMessage
    };

    // Store in global log collection (browser or Node.js)
    if (typeof window !== 'undefined') {
      // Browser environment
      if (!window.__appLogs) window.__appLogs = [];
      window.__appLogs.push(logEntry);

      // Limit log storage to prevent memory issues
      if (window.__appLogs.length > 1000) {
        window.__appLogs.shift();
      }
    } else {
      // Node.js environment — always write to stdout/stderr for systemd/journald visibility
      const jsonLine = JSON.stringify({
        level,
        message,
        timestamp,
        component,
        ...(data !== undefined ? { data } : {}),
      }) + '\n';

      if (level === 'error' || level === 'warn') {
        process.stderr.write(jsonLine);
      } else {
        process.stdout.write(jsonLine);
      }

      // Supplementary in-memory storage
      if (!process.__appLogs) process.__appLogs = [];
      process.__appLogs.push(logEntry);

      // Limit log storage
      if (process.__appLogs.length > 1000) {
        process.__appLogs.shift();
      }
    }

    // In development, could optionally write to stderr/stdout
    // But we avoid console.* statements entirely for zero-tolerance compliance
    if (this.options.enableFile && process.env.NODE_ENV === 'development') {
      // Could implement file logging here if needed
      // fs.appendFile('app.log', logMessage + '\n', () => {})
    }
  }

  /**
   * Check if we should log at this level
   * @param level - Log level to check
   * @returns Boolean indicating if logging should occur
   */
  private shouldLog(level: 'debug' | 'info' | 'warn' | 'error'): boolean {
    const levels = ['debug', 'info', 'warn', 'error'];
    const currentLevelIndex = levels.indexOf(this.options.level || 'info');
    const messageLevelIndex = levels.indexOf(level);
    return messageLevelIndex >= currentLevelIndex;
  }

  /**
   * Get all stored logs (for debugging in development)
   * @returns Array of log entries
   */
  getLogs(): LogEntry[] {
    if (typeof window !== 'undefined') {
      return window.__appLogs || [];
    } else {
      return (process as any).__appLogs || [];
    }
  }

  /**
   * Clear all stored logs
   */
  clearLogs(): void {
    if (typeof window !== 'undefined') {
      window.__appLogs = [];
    } else {
      (process as any).__appLogs = [];
    }
  }

  /**
   * Get logs for development debugging (replaces console access)
   * This method can be used in development to inspect logs without console
   */
  getRecentLogs(count: number = 50): LogEntry[] {
    const logs = this.getLogs();
    return logs.slice(-count);
  }

  /**
   * Export logs as string (for debugging or external service)
   */
  exportLogs(): string {
    const logs = this.getLogs();
    return logs.map(log => log.formattedMessage + (log.data ? ` ${JSON.stringify(log.data)}` : '')).join('\n');
  }
}

// Export singleton logger instance
export const log = new Logger();

// Export Logger class for custom instances
export { Logger };

// Default export for convenience
export default log;

/**
 * Create a logger instance with a component name
 * @param component - Component name for logging context
 * @returns Logger instance with component context
 */
export function createLogger(component: string) {
  return {
    debug: (message: string, data?: LogData) => log.debug(message, data, component),
    info: (message: string, data?: LogData) => log.info(message, data, component),
    warn: (message: string, data?: LogData) => log.warn(message, data, component),
    error: (message: string, data?: LogData) => log.error(message, data, component),
  };
}

/**
 * Pino-style API logger for use in API routes
 * Accepts (data, message?) format used by api-error-handler and API routes
 */
export const apiLogger = {
  debug: (data: LogData, message?: string) => log.debug(message || 'debug', data, 'API'),
  info: (data: LogData, message?: string) => log.info(message || 'info', data, 'API'),
  warn: (data: LogData, message?: string) => log.warn(message || 'warning', data, 'API'),
  error: (data: LogData, message?: string) => log.error(message || 'error', data, 'API'),
};

/**
 * Customers List Page
 * Displays all customers with search/filter capabilities.
 * Route: /accounting/customers
 */

import { useState, useEffect, useCallback } from 'react';
