/**
 * Customers List Page
 * Displays all customers with search/filter capabilities.
 * Route: /accounting/customers
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, Loader2, AlertCircle, Plus, Search } from 'lucide-react';
import Link from 'next/link';
import { apiFetch } from '@/lib/apiFetch';

interface Customer {
  id: string;
  name: string;
  email: string | null;
  phone: string | null;
  contact_person: string | null;
  payment_terms: number;
  is_active: boolean;
  vat_number: string | null;
}

function StatusBadge({ active }: { active: boolean }) {
  return (
    <span
      className={`px-2 py-0.5 rounded-full text-xs font-medium ${
        active
          ? 'bg-teal-500/10 text-teal-400'
          : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]'
      }`}
    >
      {active ? 'Active' : 'Inactive'}
    </span>
  );
}

export default function CustomersPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');

  // Debounce search input
  useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(t);
  }, [search]);

  const loadCustomers = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (debouncedSearch) params.set('q', debouncedSearch);
      const res = await apiFetch(`/api/accounting/customers?${params}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      setCustomers((json.data ?? json) as Customer[]);
    } catch {
      setError('Failed to load customers');
    } finally {
      setIsLoading(false);
    }
  }, [debouncedSearch]);

  useEffect(() => {
    loadCustomers();
  }, [loadCustomers]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Users className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">Customers</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Manage your customer accounts</p>
              </div>
            </div>
            <Link
              href="/accounting/customers/new"
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
            >
              <Plus className="h-4 w-4" />
              New Customer
            </Link>
          </div>
        </div>

        <div className="p-6">
          {/* Search bar */}
          <div className="flex items-center gap-3 mb-6">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[var(--ff-text-tertiary)]" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search by name, email or VAT..."
                className="pl-9 pr-4 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] text-sm w-72 focus:outline-none focus:ring-1 focus:ring-teal-500"
              />
            </div>
            {!isLoading && (
              <span className="text-sm text-[var(--ff-text-secondary)]">
                {customers.length} customer{customers.length !== 1 ? 's' : ''}
              </span>
            )}
          </div>

          {/* Content */}
          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="flex items-center justify-center gap-2 text-red-400 py-12">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : customers.length === 0 ? (
            <div className="text-center py-16">
              <Users className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)] font-medium">No customers found</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                {search ? 'Try a different search term' : 'Add your first customer to get started'}
              </p>
              {!search && (
                <Link
                  href="/accounting/customers/new"
                  className="inline-flex items-center gap-2 mt-4 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
                >
                  <Plus className="h-4 w-4" />
                  New Customer
                </Link>
              )}
            </div>
          ) : (
            <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Name</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Email</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Phone</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Contact Person</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Payment Terms</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {customers.map((c) => (
                    <tr
                      key={c.id}
                      className="border-b border-[var(--ff-border-primary)] last:border-0 hover:bg-[var(--ff-bg-tertiary)] transition-colors"
                    >
                      <td className="py-3 px-4">
                        <Link
                          href={`/accounting/customers/${c.id}`}
                          className="font-medium text-[var(--ff-text-primary)] hover:text-teal-400 transition-colors"
                        >
                          {c.name}
                        </Link>
                        {c.vat_number && (
                          <div className="text-xs text-[var(--ff-text-tertiary)] mt-0.5">VAT: {c.vat_number}</div>
                        )}
                      </td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{c.email ?? '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{c.phone ?? '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{c.contact_person ?? '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">
                        {c.payment_terms} day{c.payment_terms !== 1 ? 's' : ''}
                      </td>
                      <td className="py-3 px-4">
                        <StatusBadge active={c.is_active} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Customers API
 * GET  /api/accounting/customers         - List customers (optional ?q= search)
 * POST /api/accounting/customers         - Create a new customer
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  // ─── GET: List customers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        // Search queries are not cached — results change with every keystroke
        rows = (await sql`
          SELECT
            id, name, email, phone, contact_person,
            payment_terms, credit_limit, is_active,
            vat_number, registration_number,
            created_at
          FROM customers
          WHERE company_id = ${companyId}
            AND deleted_at IS NULL
            AND (name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR vat_number ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm})
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = await cacheThrough(
          CACHE_KEYS.customers(companyId),
          async () => (await sql`
            SELECT
              id, name, email, phone, contact_person,
              payment_terms, credit_limit, is_active,
              vat_number, registration_number,
              created_at
            FROM customers
            WHERE company_id = ${companyId}
              AND deleted_at IS NULL
            ORDER BY name ASC
            LIMIT 200
          `) as Row[],
          CACHE_TTL.REFERENCE_DATA,
        );
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Return empty list if table does not yet exist
      if (message.includes('does not exist')) {
        return apiResponse.success(res, []);
      }
      log.error('customers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch customers');
    }
  }

  // ─── POST: Create customer ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const b = req.body as Record<string, unknown>;
      const name = b.name as string | undefined;

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Customer name is required');
      }

      const s = (k: string) => { const v = b[k]; return typeof v === 'string' && v.trim() ? v.trim() : null; };
      const n = (k: string) => { const v = b[k]; return v !== undefined && v !== null && v !== '' ? Number(v) : null; };
      const bool = (k: string, def = false) => { const v = b[k]; return typeof v === 'boolean' ? v : def; };

      const rows = (await sql`
        INSERT INTO customers (
          company_id, name, email, phone, mobile, fax, web_address,
          vat_number, registration_number,
          billing_address, shipping_address, contact_person,
          payment_terms, payment_terms_type, credit_limit, is_active, notes,
          category_id, cash_sale, opening_balance, opening_balance_date,
          accepts_electronic_invoices, auto_allocate_receipts,
          statement_distribution, default_discount, default_vat_type,
          subject_to_drc_vat, invoices_viewable_online,
          sales_rep_id, default_price_list
        ) VALUES (
          ${companyId},
          ${name.trim()},
          ${s('email')},
          ${s('phone')},
          ${s('mobile')},
          ${s('fax')},
          ${s('web_address')},
          ${s('vat_number')},
          ${s('registration_number')},
          ${s('billing_address')},
          ${s('shipping_address')},
          ${s('contact_person')},
          ${n('payment_terms') ?? 30},
          ${s('payment_terms_type') ?? 'days'},
          ${n('credit_limit')},
          ${bool('is_active', true)},
          ${s('notes')},
          ${s('category_id') ? s('category_id') : null}::uuid,
          ${bool('cash_sale')},
          ${n('opening_balance') ?? 0},
          ${s('opening_balance_date')}::date,
          ${bool('accepts_electronic_invoices')},
          ${bool('auto_allocate_receipts')},
          ${s('statement_distribution') ?? 'email'},
          ${n('default_discount') ?? 0},
          ${s('default_vat_type')},
          ${bool('subject_to_drc_vat')},
          ${bool('invoices_viewable_online', true)},
          ${s('sales_rep_id') ? s('sales_rep_id') : null}::uuid,
          ${s('default_price_list')}
        )
        RETURNING *
      `) as Row[];

      cache.invalidate(CACHE_KEYS.customers(companyId));
      log.info('Customer created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('customers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create customer');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}

