  const [row] = await sql`
    UPDATE captured_documents
    SET status = 'rejected',
        notes = COALESCE(${notes}, notes)
    WHERE id = ${id}::uuid AND company_id = ${companyId}::uuid
    RETURNING *
  ` as Record<string, unknown>[];

