          <FileText className="h-3.5 w-3.5 text-[var(--ff-text-tertiary)] shrink-0" />
          <span>{customer.invoiceCount} invoice{customer.invoiceCount !== 1 ? 's' : ''}</span>
        </div>
      </div>
    </div>
  );
}

