  1	/**
  2	 * Document Capture Action API
  3	 * POST /api/accounting/document-capture-action
  4	 *   { id, action: 'confirm' | 'match_bank_tx' | 'reject', data?: {...} }
  5	 */
  6	
  7	import type { NextApiRequest, NextApiResponse } from 'next';
  8	import { withErrorHandler } from '@/lib/api-error-handler';
  9	import { apiResponse } from '@/lib/apiResponse';
 10	import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
 11	import { log } from '@/lib/logger';
 12	import { sql } from '@/lib/neon';
 13	import type { CapturedDocumentAction, CapturedDocument } from '@/modules/accounting/types/documentCapture.types';
 14	
 15	function mapRow(row: Record<string, unknown>): CapturedDocument {
 16	  return {
 17	    id: row.id as string,
 18	    fileName: row.file_name as string,
 19	    fileType: row.file_type as string,
 20	    fileSize: row.file_size as number | null,
 21	    documentType: row.document_type as string | null,
 22	    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
 23	    vendorName: row.vendor_name as string | null,
 24	    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
 25	    referenceNumber: row.reference_number as string | null,
 26	    totalAmount: row.total_amount !== null && row.total_amount !== undefined ? parseFloat(String(row.total_amount)) : null,
 27	    vatAmount: row.vat_amount !== null && row.vat_amount !== undefined ? parseFloat(String(row.vat_amount)) : null,
 28	    status: (row.status as CapturedDocument['status']) || 'pending',
 29	    matchedInvoiceId: row.matched_invoice_id as string | null,
 30	    matchedBankTxId: row.matched_bank_tx_id as string | null,
 31	    notes: row.notes as string | null,
 32	    uploadedBy: row.uploaded_by as string | null,
 33	    createdAt: new Date(row.created_at as string).toISOString(),
 34	  };
 35	}
 36	
 37	async function handler(req: NextApiRequest, res: NextApiResponse) {
 38	  if (req.method !== 'POST') {
 39	    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
 40	  }
 41	
 42	  const { id, action, data } = req.body as {
 43	    id: string;
 44	    action: CapturedDocumentAction;
 45	    data?: Record<string, unknown>;
 46	  };
 47	
 48	  if (!id || !action) {
 49	    return apiResponse.badRequest(res, 'Missing required fields: id, action');
 50	  }
 51	
 52	  if (!['confirm', 'match_bank_tx', 'reject'].includes(action)) {
 53	    return apiResponse.badRequest(res, 'Invalid action. Allowed: confirm, match_bank_tx, reject');
 54	  }
 55	
 56	  const { companyId } = req as CompanyApiRequest;
 57	
 58	  // Verify document exists
 59	  const [existing] = await sql`
 60	    SELECT * FROM captured_documents WHERE id = ${id}::uuid AND company_id = ${companyId}
 61	  ` as Record<string, unknown>[];
 62	
 63	  if (!existing) {
 64	    return apiResponse.notFound(res, 'Captured document', id);
 65	  }
 66	
 67	  try {
 68	    if (action === 'confirm') {
 69	      return handleConfirm(res, id, data);
 70	    }
 71	
 72	    if (action === 'match_bank_tx') {
 73	      return handleMatchBankTx(res, id, data);
 74	    }
 75	
 76	    if (action === 'reject') {
 77	      return handleReject(res, id, data);
 78	    }
 79	
 80	    return apiResponse.badRequest(res, 'Unknown action');
 81	  } catch (err) {
 82	    const msg = err instanceof Error ? err.message : String(err);
 83	    log.error('Document capture action failed', { error: msg, action, id }, 'document-capture');
 84	    return apiResponse.internalError(res, err, `Action failed: ${msg}`);
 85	  }
 86	}
 87	
 88	/** Confirm — mark as reviewed, optionally update extracted fields */
 89	async function handleConfirm(
 90	  res: NextApiResponse,
 91	  id: string,
 92	  data?: Record<string, unknown>,
 93	) {
 94	  const updates: Record<string, unknown> = {};
 95	  if (data?.vendorName !== undefined) updates.vendor_name = data.vendorName;
 96	  if (data?.documentDate !== undefined) updates.document_date = data.documentDate;
 97	  if (data?.referenceNumber !== undefined) updates.reference_number = data.referenceNumber;
 98	  if (data?.totalAmount !== undefined) updates.total_amount = data.totalAmount;
 99	  if (data?.vatAmount !== undefined) updates.vat_amount = data.vatAmount;
100	  if (data?.documentType !== undefined) updates.document_type = data.documentType;
101	  if (data?.notes !== undefined) updates.notes = data.notes;
102	
103	  const [row] = await sql`
104	    UPDATE captured_documents
105	    SET status = 'reviewed',
106	
107	        vendor_name = COALESCE(${(updates.vendor_name as string) || null}, vendor_name),
108	        document_date = COALESCE(${(updates.document_date as string) || null}::date, document_date),
109	        reference_number = COALESCE(${(updates.reference_number as string) || null}, reference_number),
110	        total_amount = COALESCE(${updates.total_amount !== undefined ? Number(updates.total_amount) : null}::numeric, total_amount),
111	        vat_amount = COALESCE(${updates.vat_amount !== undefined ? Number(updates.vat_amount) : null}::numeric, vat_amount),
112	        document_type = COALESCE(${(updates.document_type as string) || null}, document_type),
113	        notes = COALESCE(${(updates.notes as string) || null}, notes)
114	    WHERE id = ${id}::uuid
115	    RETURNING *
116	  ` as Record<string, unknown>[];
117	
118	  log.info('Document confirmed', { id }, 'document-capture');
119	  return apiResponse.success(res, mapRow(row as Record<string, unknown>), 'Document confirmed');
120	}
121	
122	/** Match to bank transaction */
123	async function handleMatchBankTx(
124	  res: NextApiResponse,
125	  id: string,
126	  data?: Record<string, unknown>,
127	) {
128	  const bankTxId = data?.bankTxId as string;
129	  if (!bankTxId) {
130	    return apiResponse.badRequest(res, 'bankTxId is required for match_bank_tx action');
131	  }
132	
133	  // Verify bank transaction exists
134	  const [bankTx] = await sql`
135	    SELECT id FROM bank_transactions WHERE id = ${bankTxId}::uuid
136	  ` as Record<string, unknown>[];
137	
138	  if (!bankTx) {
139	    return apiResponse.notFound(res, 'Bank transaction', bankTxId);
140	  }
141	
142	  const [row] = await sql`
143	    UPDATE captured_documents
144	    SET status = 'matched',
145	        matched_bank_tx_id = ${bankTxId}::uuid
146	    WHERE id = ${id}::uuid
147	    RETURNING *
148	  ` as Record<string, unknown>[];
149	
150	  log.info('Document matched to bank transaction', { id, bankTxId }, 'document-capture');
151	  return apiResponse.success(res, mapRow(row as Record<string, unknown>), 'Document matched to bank transaction');
152	}
153	
154	/** Reject — mark as rejected */
155	async function handleReject(
156	  res: NextApiResponse,
157	  id: string,
158	  data?: Record<string, unknown>,
159	) {
160	  const notes = (data?.notes as string) || null;
161	
162	  const [row] = await sql`
163	    UPDATE captured_documents
164	    SET status = 'rejected',
165	        notes = COALESCE(${notes}, notes)
166	    WHERE id = ${id}::uuid
167	    RETURNING *
168	  ` as Record<string, unknown>[];
169	
170	  log.info('Document rejected', { id }, 'document-capture');
171	  return apiResponse.success(res, mapRow(row as Record<string, unknown>), 'Document rejected');
172	}
173	
174	 
175	export default withCompany(withErrorHandler(withWriteAccess(handler)));

