import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { notify } from '@/utils/toast';
import { formatCurrencyAmount } from '@/modules/accounting/services/multiCurrencyService';
import { TrendingUp, Loader2, AlertCircle, Trash2, Plus, ArrowRight, RefreshCw } from 'lucide-react';

interface Currency {
  code: string;
  name: string;
  symbol: string;
}

interface ExchangeRate {
  id: string;
  fromCurrency: string;
  toCurrency: string;
  rate: number;
  effectiveDate: string;
}

interface ConvertResult {
  result: number;
  rate: number;
  effectiveDate: string;
}

const today = new Date().toISOString().split('T')[0]!;

function AddRateForm({
  currencies,
  onAdded,
}: {
  currencies: Currency[];
  onAdded: () => void;
}) {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('ZAR');
  const [rate, setRate] = useState('');
  const [date, setDate] = useState(today);
  const [saving, setSaving] = useState(false);

  const handleAdd = useCallback(async () => {
    if (!from || !to || !rate || !date) {
      notify.error('All fields are required');
      return;
    }
    if (from === to) {
      notify.error('From and To currencies must differ');
      return;
    }
    const rateVal = parseFloat(rate);
    if (isNaN(rateVal) || rateVal <= 0) {
      notify.error('Rate must be a positive number');
      return;
    }
    setSaving(true);
    try {
      const res = await apiFetch('/api/accounting/exchange-rates', {
        method: 'POST',
        body: JSON.stringify({ fromCurrency: from, toCurrency: to, rate: rateVal, effectiveDate: date }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json.message || 'Failed to add rate');
        return;
      }
      notify.success(`Rate ${from}/${to} added`);
      setRate('');
      onAdded();
    } catch {
      notify.error('Failed to add exchange rate');
    } finally {
      setSaving(false);
    }
