/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;


async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  try {
    const userId = String(req.user?.id || 'system');

    // Calculate totals
    const rate = taxRate ?? 15;
    let subtotal = 0;
    for (const item of items) {
      subtotal += (item.quantity || 1) * item.unitPrice;
    }
    subtotal = Math.round(subtotal * 100) / 100;
    const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
    const totalAmount = subtotal + taxAmount;

    const today = new Date().toISOString().split('T')[0];
    const invDate = invoiceDate || today;
    const bpStart = billingPeriodStart || null;
    const bpEnd = billingPeriodEnd || null;

    // Find project from client (optional)
    let projectId: string | null = null;
    try {
      const projRows = (await sql`SELECT id FROM projects WHERE client_id = ${clientId}::UUID AND company_id = ${companyId} LIMIT 1`) as Row[];
      projectId = (projRows[0]?.['id'] as string | undefined) ?? null;
    } catch { /* projects table may not exist */ }

    // Insert invoice with retry on unique-constraint violation.
    // MAX()+1 races under concurrent load — if we collide, re-read MAX and try again
    // (up to 5 times with escalating offset so the series stays monotonic).
    let invoiceId = '';
    let invoiceNumber = '';
    for (let attempt = 0; attempt < 5; attempt++) {
      const maxRows = (await sql`
        SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)), 0) AS max_num
        FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number ~ '^INV-[0-9]+$'
      `) as Row[];
      const base = Number(maxRows[0]?.['max_num'] ?? 0) + 1 + attempt;
      invoiceNumber = `INV-${String(base).padStart(5, '0')}`;

      try {
        const invRows = (await sql`
          INSERT INTO customer_invoices (
            company_id, invoice_number, project_id, customer_id, client_id, billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
            notes, status, created_by
          ) VALUES (
            ${companyId}, ${invoiceNumber}, ${projectId}, ${clientId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
            ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
            ${dueDate || null}, ${notes || null}, 'draft', ${userId}
          ) RETURNING id
        `) as Row[];
        invoiceId = String(invRows[0]!.id);
        break;
      } catch (insertErr) {
        const msg = insertErr instanceof Error ? insertErr.message : String(insertErr);
        if (msg.includes('unique') && attempt < 4) continue;
        throw insertErr;
      }
    }

    for (const item of items) {
      const qty = item.quantity || 1;
      const lineAmount = Math.round(qty * item.unitPrice * 100) / 100;
      await sql`
        INSERT INTO customer_invoice_items (invoice_id, description, unit_price, quantity, amount, tax_rate)
        VALUES (${invoiceId}::UUID, ${item.description}, ${item.unitPrice}, ${qty}, ${lineAmount}, ${rate})
      `;
    }

    log.info('Customer invoice created', { invoiceNumber, totalAmount });
    return apiResponse.created(res, { id: invoiceId, invoiceNumber });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Invoice create failed', { error: msg });
    const clientMessage = process.env.NODE_ENV === 'development' ? msg : 'Failed to create invoice';
    return res.status(500).json({ success: false, error: { code: 'CREATE_FAILED', message: clientMessage } });
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Customer Quotes Action API
 * POST — perform actions on a quote (send, accept, decline, convert)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withWriteAccess} from '@/lib/auth';
import { updateQuoteStatus, convertToInvoice } from '@/modules/accounting/services/quoteService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { companyId } = req as CompanyApiRequest;
  const { id, action } = req.body;
  if (!id || !action) return apiResponse.badRequest(res, 'id and action are required');

  const userId = req.user.id;

  switch (action) {
    case 'send': {
      const quote = await updateQuoteStatus(companyId, id, 'sent');
      if (!quote) return apiResponse.notFound(res, 'Quote', id);
      return apiResponse.success(res, quote);
    }
    case 'accept': {
      const quote = await updateQuoteStatus(companyId, id, 'accepted');
      if (!quote) return apiResponse.notFound(res, 'Quote', id);
      return apiResponse.success(res, quote);
    }
    case 'decline': {
      const quote = await updateQuoteStatus(companyId, id, 'declined');
      if (!quote) return apiResponse.notFound(res, 'Quote', id);
      return apiResponse.success(res, quote);
    }
    case 'convert': {
      const result = await convertToInvoice(companyId, id, userId);
      if (!result) return apiResponse.badRequest(res, 'Quote must be accepted to convert');
      return apiResponse.success(res, result);
    }
    default:
      return apiResponse.badRequest(res, `Unknown action: ${action}`);
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Write-access gate — requires owner/admin/manager role for mutating methods.
 *
 * Wraps a handler that has already been enriched by withCompany (so
 * `req.companyRole` is populated). For any POST/PUT/PATCH/DELETE request
 * where the caller's per-company role is NOT owner/admin/manager (i.e. it's
 * "viewer" or some unknown future read-only role), returns 403 before the
 * handler runs. GET/HEAD/OPTIONS pass through unchanged.
 *
 * Usage:
 *   export default withCompany(withErrorHandler(withWriteAccess(handler)));
 *
 * Defaults apply to the vast majority of accounting endpoints. For a
 * stricter gate (e.g. "admins only") pass `{ allowedRoles: [...] }`.
 * For a looser gate (e.g. allowing viewers to save their own preferences)
 * pass `{ allowedRoles: null }` to disable this layer entirely — it's
 * explicit so a grep finds every exception.
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import type { CompanyApiRequest } from './withCompany';

const WRITE_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
export const DEFAULT_WRITE_ROLES = ['owner', 'admin', 'manager'] as const;

export type WriteRole = (typeof DEFAULT_WRITE_ROLES)[number];

interface WithWriteAccessOptions {
  /**
   * Roles allowed to mutate. Default: ['owner', 'admin', 'manager'].
   * Set to `null` to disable the gate for a specific endpoint (e.g. user
   * preferences where a viewer should be able to save their own state).
   */
  allowedRoles?: readonly string[] | null;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Handler = (req: any, res: NextApiResponse<any>) => unknown | Promise<unknown>;

export function withWriteAccess(
  handler: Handler,
  options: WithWriteAccessOptions = {},
): NextApiHandler {
  const allowed = options.allowedRoles === undefined ? DEFAULT_WRITE_ROLES : options.allowedRoles;

  return async (req: NextApiRequest, res: NextApiResponse) => {
    // Explicit opt-out: allowedRoles: null → no gate.
    if (allowed === null) {
      return handler(req, res);
    }

    // Read-only methods always pass through.
    const method = (req.method ?? 'GET').toUpperCase();
    if (!WRITE_METHODS.has(method)) {
      return handler(req, res);
    }

    const companyReq = req as CompanyApiRequest;
    const role = companyReq.companyRole;

    // If withCompany didn't run first (misuse), fail closed.
    if (!role) {
      return apiResponse.forbidden(
        res,
        'Write access check failed: no company role on request.',
      );
    }

    if (!allowed.includes(role)) {
      return apiResponse.forbidden(
        res,
        `Your role (${role}) does not allow this action.`,
      );
    }

    return handler(req, res);
  };
}

