interface Customer {
  id: string;
  name: string;
  email: string | null;
  phone: string | null;
  contact_person: string | null;
  payment_terms: number;
  is_active: boolean;
  vat_number: string | null;
}

type BulkAction = 'activate' | 'deactivate' | 'export';

const MATCH_LABEL: Record<DuplicatePair['match_reason'], string> = {
  email: 'Same email',
  vat: 'Same VAT',
  name: 'Similar name',
};

const MATCH_COLOR: Record<DuplicatePair['match_reason'], string> = {
  email: 'bg-blue-500/10 text-blue-400',
  vat: 'bg-purple-500/10 text-purple-400',
  name: 'bg-amber-500/10 text-amber-400',
};

function StatusBadge({ active }: { active: boolean }) {
  return (
    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${
      active ? 'bg-teal-500/10 text-teal-400' : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]'
    }`}>
      {active ? 'Active' : 'Inactive'}
    </span>
  );
}

interface BulkBarProps {
  count: number;
  loading: boolean;
  errorMsg: string;
  onAction: (a: BulkAction) => void;
  onClear: () => void;
}

function BulkBar({ count, loading, errorMsg, onAction, onClear }: BulkBarProps) {
  return (
    <div className="mb-4 flex items-center gap-3 px-4 py-2.5 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] shadow-sm">
      <CheckSquare className="h-4 w-4 text-teal-400 shrink-0" />
      <span className="text-sm font-medium text-[var(--ff-text-primary)]">{count} selected</span>
      <div className="flex items-center gap-2 ml-2">
        <button onClick={() => onAction('activate')} disabled={loading}
          className="px-3 py-1.5 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-xs font-medium transition-colors">
          Activate
        </button>
        <button onClick={() => onAction('deactivate')} disabled={loading}
          className="px-3 py-1.5 rounded-lg bg-yellow-600 hover:bg-yellow-700 disabled:opacity-50 text-white text-xs font-medium transition-colors">
          Deactivate
        </button>
        <button onClick={() => onAction('export')} disabled={loading}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-[var(--ff-bg-tertiary)] hover:bg-[var(--ff-border-primary)] disabled:opacity-50 text-[var(--ff-text-primary)] text-xs font-medium border border-[var(--ff-border-primary)] transition-colors">
          <Download className="h-3.5 w-3.5" />Export CSV
        </button>
      </div>
      {loading && <Loader2 className="h-4 w-4 animate-spin text-teal-400" />}
      {errorMsg && <span className="text-xs text-red-400">{errorMsg}</span>}
      <button onClick={onClear} title="Clear selection"
        className="ml-auto p-1 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] transition-colors">
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

export default function CustomersPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [bulkLoading, setBulkLoading] = useState(false);
  const [bulkError, setBulkError] = useState('');
  const headerCheckRef = useRef<HTMLInputElement>(null);

  // Duplicate detection state
  const [showDuplicates, setShowDuplicates] = useState(false);
  const [duplicates, setDuplicates] = useState<DuplicatePair[]>([]);
  const [isDupLoading, setIsDupLoading] = useState(false);
  const [dupError, setDupError] = useState('');
  const [mergeTarget, setMergeTarget] = useState<{ a: MergeCandidate; b: MergeCandidate } | null>(null);

  useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(t);
  }, [search]);

  const loadCustomers = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (debouncedSearch) params.set('q', debouncedSearch);
      const res = await apiFetch(`/api/accounting/customers?${params}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = (await res.json()) as { data?: Customer[] } | Customer[];
      setCustomers(((json as { data?: Customer[] }).data ?? (json as Customer[])));
    } catch {
      setError('Failed to load customers');
    } finally {
      setIsLoading(false);
    }
  }, [debouncedSearch]);

  useEffect(() => { void loadCustomers(); }, [loadCustomers]);
  useEffect(() => { setSelected(new Set()); }, [customers]);

  const allChecked = customers.length > 0 && customers.every((c) => selected.has(c.id));
  const someChecked = customers.some((c) => selected.has(c.id)) && !allChecked;

  useEffect(() => {
    if (headerCheckRef.current) headerCheckRef.current.indeterminate = someChecked;
  }, [someChecked]);

  function toggleAll() {
    setSelected(allChecked ? new Set() : new Set(customers.map((c) => c.id)));
  }

  function toggleOne(id: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }

  const handleBulkAction = useCallback(async (action: BulkAction) => {
    if (selected.size === 0) return;
    setBulkLoading(true);
    setBulkError('');
    try {
      const ids = Array.from(selected);
      const res = await apiFetch('/api/accounting/customers-bulk', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids, action }),
      });
      if (action === 'export') {
        if (!res.ok) throw new Error(`Export failed: HTTP ${res.status}`);
        const blob = await res.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'customers-export.csv';
        a.click();
        URL.revokeObjectURL(url);
        setSelected(new Set());
        return;
      }
      if (!res.ok) {
        const json = (await res.json()) as { message?: string };
        throw new Error(json.message ?? `HTTP ${res.status}`);
      }
      setSelected(new Set());
      void loadCustomers();
    } catch (err: unknown) {
      setBulkError(err instanceof Error ? err.message : 'Bulk action failed');
    } finally {
      setBulkLoading(false);
    }
  }, [selected, loadCustomers]);

  const handleFindDuplicates = async () => {
    if (showDuplicates) {
      setShowDuplicates(false);
      return;
    }
    setIsDupLoading(true);
    setDupError('');
    setShowDuplicates(true);
    try {
      const res = await apiFetch('/api/accounting/customer-duplicates');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = (await res.json()) as { data?: DuplicatePair[] } | DuplicatePair[];
      setDuplicates((json as { data?: DuplicatePair[] }).data ?? (json as DuplicatePair[]));
    } catch {
      setDupError('Failed to load duplicate candidates');
    } finally {
      setIsDupLoading(false);
    }
  };

  const openMergeModal = (pair: DuplicatePair) => {
    setMergeTarget({
      a: { id: pair.id_a, name: pair.name_a, email: pair.email_a, vat: pair.vat_a, invoiceCount: pair.invoice_count_a },
      b: { id: pair.id_b, name: pair.name_b, email: pair.email_b, vat: pair.vat_b, invoiceCount: pair.invoice_count_b },
    });
  };

  const handleMerged = (targetId: string) => {
    setMergeTarget(null);
    setDuplicates((prev) => prev.filter((p) => p.id_a !== targetId && p.id_b !== targetId));
    void loadCustomers();
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Users className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">Customers</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Manage your customer accounts</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => void handleFindDuplicates()}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-lg border border-[var(--ff-border-primary)] hover:border-teal-500/50 bg-[var(--ff-bg-secondary)] hover:bg-teal-500/5 text-[var(--ff-text-secondary)] hover:text-teal-400 text-sm font-medium transition-colors"
              >
                <GitMerge className="h-4 w-4" />
                Find Duplicates
                {showDuplicates ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
              </button>
              <Link href="/accounting/customers/new"
                className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors">
                <Plus className="h-4 w-4" />New Customer
              </Link>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Duplicate detection panel */}
          {showDuplicates && (
            <div className="rounded-lg border border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)] overflow-hidden">
              <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--ff-border-primary)]">
                <div className="flex items-center gap-2">
                  <GitMerge className="h-4 w-4 text-teal-500" />
                  <span className="text-sm font-medium text-[var(--ff-text-primary)]">Potential Duplicates</span>
                  {!isDupLoading && !dupError && (
                    <span className="text-xs text-[var(--ff-text-tertiary)]">
                      ({duplicates.length} pair{duplicates.length !== 1 ? 's' : ''} found)
                    </span>
                  )}
                </div>
                <button onClick={() => setShowDuplicates(false)} aria-label="Close duplicates panel"
                  className="p-1 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] transition-colors">
                  <X className="h-4 w-4" />
                </button>
              </div>
              <div className="p-4">
                {isDupLoading ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
                  </div>
                ) : dupError ? (
                  <div className="flex items-center justify-center gap-2 text-red-400 py-6">
                    <AlertCircle className="h-4 w-4" />
                    <span className="text-sm">{dupError}</span>
                  </div>
                ) : duplicates.length === 0 ? (
                  <div className="text-center py-8">
                    <GitMerge className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
                    <p className="text-sm text-[var(--ff-text-secondary)]">No duplicate customers found</p>
                    <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">Your customer list looks clean!</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {duplicates.map((pair) => (
                      <div key={`${pair.id_a}-${pair.id_b}`}
                        className="flex items-center gap-3 p-3 rounded-lg border border-[var(--ff-border-primary)] bg-[var(--ff-bg-primary)] hover:border-teal-500/30 transition-colors">
                        <span className={`shrink-0 px-2 py-0.5 rounded-full text-xs font-medium ${MATCH_COLOR[pair.match_reason]}`}>
                          {MATCH_LABEL[pair.match_reason]}
                        </span>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">{pair.name_a}</p>
                          {pair.email_a && <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{pair.email_a}</p>}
                          <p className="text-xs text-[var(--ff-text-tertiary)]">{pair.invoice_count_a} invoice{pair.invoice_count_a !== 1 ? 's' : ''}</p>
                        </div>
                        <GitMerge className="h-4 w-4 text-[var(--ff-text-tertiary)] shrink-0" />
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">{pair.name_b}</p>
                          {pair.email_b && <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{pair.email_b}</p>}
                          <p className="text-xs text-[var(--ff-text-tertiary)]">{pair.invoice_count_b} invoice{pair.invoice_count_b !== 1 ? 's' : ''}</p>
                        </div>
                        <button onClick={() => openMergeModal(pair)}
                          className="shrink-0 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-xs font-medium transition-colors">
                          <GitMerge className="h-3.5 w-3.5" />Merge
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          <div className="flex items-center gap-3">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[var(--ff-text-tertiary)]" />
              <input type="text" value={search} onChange={(e) => setSearch(e.target.value)}
                placeholder="Search by name, email or VAT..."
                className="pl-9 pr-4 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] text-sm w-72 focus:outline-none focus:ring-1 focus:ring-teal-500" />
            </div>
            {!isLoading && (
              <span className="text-sm text-[var(--ff-text-secondary)]">
                {customers.length} customer{customers.length !== 1 ? 's' : ''}
              </span>
            )}
          </div>

          {selected.size > 0 && (
            <BulkBar count={selected.size} loading={bulkLoading} errorMsg={bulkError}
              onAction={(a) => void handleBulkAction(a)}
              onClear={() => { setSelected(new Set()); setBulkError(''); }} />
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="flex items-center justify-center gap-2 text-red-400 py-12">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : customers.length === 0 ? (
            <div className="text-center py-16">
              <Users className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)] font-medium">No customers found</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                {search ? 'Try a different search term' : 'Add your first customer to get started'}
              </p>
              {!search && (
                <Link href="/accounting/customers/new"
                  className="inline-flex items-center gap-2 mt-4 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors">
                  <Plus className="h-4 w-4" />New Customer
                </Link>
              )}
            </div>
          ) : (
            <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                    <th className="py-3 px-4 w-10">
                      <input type="checkbox" ref={headerCheckRef} checked={allChecked}
                        onChange={toggleAll} aria-label="Select all customers"
                        className="rounded border-[var(--ff-border-primary)] bg-[var(--ff-bg-tertiary)] text-teal-500 focus:ring-teal-500 focus:ring-offset-0 cursor-pointer" />
                    </th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Name</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Email</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Phone</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Contact Person</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Payment Terms</th>
                    <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {customers.map((c) => (
                    <tr key={c.id}
                      className={`border-b border-[var(--ff-border-primary)] last:border-0 hover:bg-[var(--ff-bg-tertiary)] transition-colors${selected.has(c.id) ? ' bg-teal-500/5' : ''}`}>
                      <td className="py-3 px-4">
                        <input type="checkbox" checked={selected.has(c.id)} onChange={() => toggleOne(c.id)}
                          aria-label={`Select ${c.name}`}
                          className="rounded border-[var(--ff-border-primary)] bg-[var(--ff-bg-tertiary)] text-teal-500 focus:ring-teal-500 focus:ring-offset-0 cursor-pointer" />
                      </td>
                      <td className="py-3 px-4">
                        <Link href={`/accounting/customers/${c.id}`}
                          className="font-medium text-[var(--ff-text-primary)] hover:text-teal-400 transition-colors">
                          {c.name}
                        </Link>
                        {c.vat_number && (
                          <div className="text-xs text-[var(--ff-text-tertiary)] mt-0.5">VAT: {c.vat_number}</div>
                        )}
                      </td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{c.email ?? '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{c.phone ?? '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{c.contact_person ?? '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">
                        {c.payment_terms} day{c.payment_terms !== 1 ? 's' : ''}
                      </td>
                      <td className="py-3 px-4"><StatusBadge active={c.is_active} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

