    ? Math.round((engagement.dau / engagement.mau) * 10000) / 100
    : 0;

  const analytics: UsageAnalytics = {
    dau: engagement.dau,
    wau: engagement.wau,
    mau: engagement.mau,
    stickiness_percent: stickiness,
    top_pages: [],
    feature_adoption: featureAdoption,
    revenue_by_plan: revenueByPlan,
    churn_signals: churnSignals,
    platform_summary: summary,
  };

  log.info('Usage analytics fetched', {
    dau: analytics.dau,
    mau: analytics.mau,
    churn_signals: analytics.churn_signals.length,
  }, 'analyticsService');

  return analytics;
}

async function getPlatformSummary(): Promise<UsageAnalytics['platform_summary']> {
  const [countRow, dbRow] = await Promise.all([
    sql`
      SELECT
        (SELECT COUNT(*) FROM companies WHERE status IS DISTINCT FROM 'deleted')::int           AS total_companies,
        (SELECT COUNT(*) FROM users WHERE is_active = true)::int                               AS total_users,
        (SELECT COUNT(*) FROM customer_invoices)::int                                          AS total_invoices,
        (SELECT COUNT(*) FROM gl_journal_entries)::int                                         AS total_journal_entries,
        (SELECT COUNT(*) FROM bank_transactions)::int                                          AS total_bank_transactions
    `,
    sql`SELECT ROUND(pg_database_size(current_database()) / 1048576.0, 2) AS size_mb`,
  ]);

  const r = countRow[0] as Row;
  return {
    total_companies:         parseInt(r.total_companies as string, 10) || 0,
    total_users:             parseInt(r.total_users as string, 10) || 0,
    total_invoices:          parseInt(r.total_invoices as string, 10) || 0,
    total_journal_entries:   parseInt(r.total_journal_entries as string, 10) || 0,
    total_bank_transactions: parseInt(r.total_bank_transactions as string, 10) || 0,
    db_size_mb:              parseFloat((dbRow[0] as Row).size_mb as string) || 0,
  };
}

