/**
 * Exchange Rates Settings Page
 * Manage foreign currency exchange rates — add, view, delete, and convert.
 * WORKING: Full CRUD + currency converter widget using multi-currency APIs
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { notify } from '@/utils/toast';
import { formatCurrencyAmount } from '@/modules/accounting/services/multiCurrencyService';
import { TrendingUp, Loader2, AlertCircle, Trash2, Plus, ArrowRight, RefreshCw } from 'lucide-react';

interface Currency {
  code: string;
  name: string;
  symbol: string;
}

interface ExchangeRate {
  id: string;
  fromCurrency: string;
  toCurrency: string;
  rate: number;
  effectiveDate: string;
}

interface ConvertResult {
  result: number;
  rate: number;
  effectiveDate: string;
}

const today = new Date().toISOString().split('T')[0]!;

function AddRateForm({
  currencies,
  onAdded,
}: {
  currencies: Currency[];
  onAdded: () => void;
}) {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('ZAR');
  const [rate, setRate] = useState('');
  const [date, setDate] = useState(today);
  const [saving, setSaving] = useState(false);

  const handleAdd = useCallback(async () => {
    if (!from || !to || !rate || !date) {
      notify.error('All fields are required');
      return;
    }
    if (from === to) {
      notify.error('From and To currencies must differ');
      return;
    }
    const rateVal = parseFloat(rate);
    if (isNaN(rateVal) || rateVal <= 0) {
      notify.error('Rate must be a positive number');
      return;
    }
    setSaving(true);
    try {
      const res = await apiFetch('/api/accounting/exchange-rates', {
        method: 'POST',
        body: JSON.stringify({ fromCurrency: from, toCurrency: to, rate: rateVal, effectiveDate: date }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json.message || 'Failed to add rate');
        return;
      }
      notify.success(`Rate ${from}/${to} added`);
      setRate('');
      onAdded();
    } catch {
      notify.error('Failed to add exchange rate');
    } finally {
      setSaving(false);
    }
  }, [from, to, rate, date, onAdded]);

  return (
    <div className="p-5 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
      <div className="flex items-center gap-2 mb-4">
        <Plus className="h-4 w-4 text-teal-500" />
        <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Add Rate</h2>
      </div>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">From Currency</label>
          <select
            value={from}
            onChange={e => setFrom(e.target.value)}
            className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          >
            <option value="">Select...</option>
            {currencies.map(c => (
              <option key={c.code} value={c.code}>{c.code} — {c.name}</option>
            ))}
          </select>
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">To Currency</label>
          <select
            value={to}
            onChange={e => setTo(e.target.value)}
            className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          >
            <option value="">Select...</option>
            {currencies.map(c => (
              <option key={c.code} value={c.code}>{c.code} — {c.name}</option>
            ))}
          </select>
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Rate</label>
          <input
            type="number"
            step="any"
            min="0"
            placeholder="e.g. 18.523400"
            value={rate}
            onChange={e => setRate(e.target.value)}
            className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Effective Date</label>
          <input
            type="date"
            value={date}
            onChange={e => setDate(e.target.value)}
            className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          />
        </div>
      </div>
      <div className="flex justify-end mt-4">
        <button
          onClick={handleAdd}
          disabled={saving}
          className="px-4 py-2 bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white rounded-lg flex items-center gap-2 text-sm transition-colors"
        >
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
          Add Rate
        </button>
      </div>
    </div>
  );
}

function ConverterWidget({ currencies }: { currencies: Currency[] }) {
  const [amount, setAmount] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('ZAR');
  const [date, setDate] = useState(today);
  const [result, setResult] = useState<ConvertResult | null>(null);
  const [converting, setConverting] = useState(false);

  const handleConvert = useCallback(async () => {
    const amt = parseFloat(amount);
    if (isNaN(amt) || amt <= 0) { notify.error('Enter a valid amount'); return; }
    if (!from || !to) { notify.error('Select both currencies'); return; }
    setConverting(true);
    setResult(null);
    try {
      const res = await apiFetch('/api/accounting/exchange-rate-convert', {
        method: 'POST',
        body: JSON.stringify({ amount: amt, fromCurrency: from, toCurrency: to, date }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json.message || 'No rate available for this pair');
        return;
      }
      setResult(json.data as ConvertResult);
    } catch {
      notify.error('Conversion failed');
    } finally {
      setConverting(false);
    }
  }, [amount, from, to, date]);

  return (
    <div className="p-5 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
      <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] mb-4">Currency Converter</h2>
      <div className="flex flex-wrap items-end gap-3">
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Amount</label>
          <input
            type="number"
            step="any"
            min="0"
            placeholder="1000"
            value={amount}
            onChange={e => { setAmount(e.target.value); setResult(null); }}
            className="w-32 px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">From</label>
          <select
            value={from}
            onChange={e => { setFrom(e.target.value); setResult(null); }}
            className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          >
            <option value="">Select...</option>
            {currencies.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
          </select>
        </div>
        <ArrowRight className="h-4 w-4 text-[var(--ff-text-tertiary)] mb-2" />
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">To</label>
          <select
            value={to}
            onChange={e => { setTo(e.target.value); setResult(null); }}
            className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          >
            <option value="">Select...</option>
            {currencies.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
          <input
            type="date"
            value={date}
            onChange={e => { setDate(e.target.value); setResult(null); }}
            className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500"
          />
        </div>
        <button
          onClick={handleConvert}
          disabled={converting}
          className="px-4 py-2 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] hover:border-teal-500 text-[var(--ff-text-primary)] rounded-lg flex items-center gap-2 text-sm transition-colors disabled:opacity-50"
        >
          {converting ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Convert'}
        </button>
      </div>
      {result && (
        <div className="mt-4 px-4 py-3 rounded-lg bg-teal-500/10 border border-teal-500/20 text-sm text-[var(--ff-text-primary)]">
          {formatCurrencyAmount(parseFloat(amount), from)} ={' '}
          <span className="font-bold text-teal-400">{formatCurrencyAmount(result.result, to)}</span>
          {' '}
          <span className="text-[var(--ff-text-tertiary)]">
            (rate: {result.rate.toFixed(6)} on {result.effectiveDate})
          </span>
        </div>
      )}
    </div>
  );
}

export default function ExchangeRatesSettingsPage() {
  const [currencies, setCurrencies] = useState<Currency[]>([]);
  const [rates, setRates] = useState<ExchangeRate[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [deleting, setDeleting] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [currRes, ratesRes] = await Promise.all([
        apiFetch('/api/accounting/currencies'),
        apiFetch('/api/accounting/exchange-rates'),
      ]);
      const currJson = await currRes.json();
      const ratesJson = await ratesRes.json();
      setCurrencies(currJson.data?.currencies ?? []);
      setRates(ratesJson.data?.rates ?? []);
    } catch {
      setError('Failed to load exchange rate data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  const handleDelete = useCallback(async (id: string) => {
    setDeleting(id);
    try {
      const res = await apiFetch(`/api/accounting/exchange-rates?id=${encodeURIComponent(id)}`, {
        method: 'DELETE',
      });
      if (!res.ok) {
        const json = await res.json().catch(() => ({}));
        notify.error((json as { message?: string }).message || 'Failed to delete rate');
        return;
      }
      notify.success('Exchange rate deleted');
      setRates(prev => prev.filter(r => r.id !== id));
    } catch {
      notify.error('Failed to delete exchange rate');
    } finally {
      setDeleting(null);
    }
  }, []);

  const sortedRates = [...rates].sort((a, b) =>
    a.fromCurrency.localeCompare(b.fromCurrency) || b.effectiveDate.localeCompare(a.effectiveDate),
  );

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <TrendingUp className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Exchange Rates</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Manage foreign currency exchange rates</p>
              </div>
            </div>
            <button
              onClick={loadData}
              className="p-2 rounded-lg text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-primary)] transition-colors"
              title="Refresh"
            >
              <RefreshCw className="h-4 w-4" />
            </button>
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : error ? (
          <div className="flex items-center gap-2 text-red-400 py-12 justify-center">
            <AlertCircle className="h-5 w-5" />
            <span>{error}</span>
          </div>
        ) : (
          <div className="p-6 max-w-5xl space-y-6">
            <AddRateForm currencies={currencies} onAdded={loadData} />
            <ConverterWidget currencies={currencies} />

            <div>
              <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] mb-3">Current Rates</h2>
              {sortedRates.length === 0 ? (
                <p className="text-sm text-[var(--ff-text-secondary)] py-4">No exchange rates recorded yet.</p>
              ) : (
                <div className="rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                        <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">From</th>
                        <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">To</th>
                        <th className="text-right px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Rate</th>
                        <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Effective Date</th>
                        <th className="px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border-light)]">
                      {sortedRates.map(r => (
                        <tr key={r.id} className="bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-primary)] transition-colors">
                          <td className="px-4 py-3 font-mono font-semibold text-[var(--ff-text-primary)]">{r.fromCurrency}</td>
                          <td className="px-4 py-3 font-mono font-semibold text-[var(--ff-text-primary)]">{r.toCurrency}</td>
                          <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                            {r.rate.toFixed(6)}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{r.effectiveDate}</td>
                          <td className="px-4 py-3 text-right">
                            <button
                              onClick={() => handleDelete(r.id)}
                              disabled={deleting === r.id}
                              className="p-1.5 rounded-lg text-[var(--ff-text-tertiary)] hover:text-red-400 hover:bg-red-500/10 transition-colors disabled:opacity-50"
                              title="Delete rate"
                            >
                              {deleting === r.id
                                ? <Loader2 className="h-4 w-4 animate-spin" />
                                : <Trash2 className="h-4 w-4" />
                              }
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

