/**
 * Admin Companies List API
 * GET  /api/admin/companies — List all companies across the platform
 * POST /api/admin/companies — Create a new company
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { listCompanies, createCompany, getCompanyDetail } from '@/modules/admin/services/adminCompanyService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { search, status, plan, page, limit, sort_by, sort_dir } = req.query;
      const result = await listCompanies({
        search:   search   as string | undefined,
        status:   status   as string | undefined,
        plan:     plan     as string | undefined,
        page:     page     ? Number(page)  : undefined,
        limit:    limit    ? Number(limit) : undefined,
        sort_by:  sort_by  as string | undefined,
        sort_dir: sort_dir as 'asc' | 'desc' | undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to list companies', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list companies');
    }
  }

  if (req.method === 'POST') {
    try {
      const { name, trading_name, email, phone, plan_id } = req.body as {
        name?: string;
        trading_name?: string;
        email?: string;
        phone?: string;
        plan_id?: string;
      };

      if (!name?.trim()) return apiResponse.badRequest(res, 'Company name is required');

      const id = await createCompany({
        name:         name.trim(),
        trading_name: trading_name?.trim() || undefined,
        email:        email?.trim()        || undefined,
        phone:        phone?.trim()        || undefined,
        plan_id:      plan_id              || undefined,
      });

      const company = await getCompanyDetail(id);

      await logAdminAction(
        req.user.id,
        'company.create',
        'company',
        id,
        { name: name.trim() },
        getIp(req)
      );

      return apiResponse.created(res, company);
    } catch (err) {
      log.error('Failed to create company', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create company');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAdmin(handler);

