/**
 * Exchange Rate Convert API
 * POST — convert an amount between two currencies using the company's rates
 *
 * Body: { amount, fromCurrency, toCurrency, date? }
 * Returns: { result, rate, effectiveDate }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { convertAmount as convertAmountPure } from '@/modules/accounting/services/multiCurrencyService';
import { getLatestRate, getExchangeRates } from '@/modules/accounting/services/currencyService';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  const { amount, fromCurrency, toCurrency, date } = req.body as {
    amount: unknown;
    fromCurrency: unknown;
    toCurrency: unknown;
    date?: unknown;
  };

  // Validate required fields
  if (amount === undefined || amount === null) {
    return apiResponse.badRequest(res, 'amount is required');
  }
  if (!fromCurrency || typeof fromCurrency !== 'string' || fromCurrency.trim() === '') {
    return apiResponse.badRequest(res, 'fromCurrency is required');
  }
  if (!toCurrency || typeof toCurrency !== 'string' || toCurrency.trim() === '') {
    return apiResponse.badRequest(res, 'toCurrency is required');
  }

  const numAmount = Number(amount);
  if (isNaN(numAmount)) {
    return apiResponse.badRequest(res, 'amount must be a valid number');
  }

  const from = String(fromCurrency).toUpperCase().trim();
  const to = String(toCurrency).toUpperCase().trim();

  // Same-currency shortcut — no DB lookup needed
  if (from === to) {
    return apiResponse.success(res, {
      result: numAmount,
      rate: 1,
      effectiveDate: date ? String(date) : new Date().toISOString().split('T')[0],
    });
  }

  // Validate date format if provided
  const asOfDate = date ? String(date) : undefined;
  if (asOfDate && !/^\d{4}-\d{2}-\d{2}$/.test(asOfDate)) {
    return apiResponse.badRequest(res, 'date must be in YYYY-MM-DD format');
  }

  const resolvedDate = asOfDate ?? new Date().toISOString().split('T')[0]!;

  // Look up the most recent applicable rate from the DB
  const rate = await getLatestRate(companyId, from, to, resolvedDate);

  if (rate === null) {
    log.warn('Exchange rate not found for conversion', {
      companyId, from, to, date: resolvedDate,
    }, 'accounting');
    return apiResponse.notFound(res, 'Exchange rate', `${from}/${to} on or before ${resolvedDate}`);
  }

  // Determine the actual effectiveDate of the rate we used
  const rateRows = await getExchangeRates(companyId, { fromCurrency: from, toCurrency: to, limit: 1 });
  const effectiveDate = rateRows[0]?.effectiveDate ?? resolvedDate;

  // Delegate computation to the pure service function
  const result = convertAmountPure(numAmount, from, to, rate);

  log.info('Currency conversion', {
    companyId, from, to, amount: numAmount, rate, result,
  }, 'accounting');

  return apiResponse.success(res, { result, rate, effectiveDate });
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Exchange Rates API
 * GET  — list rates (optional from/to currency filters)
 * POST — set/update rate for a date
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withWriteAccess} from '@/lib/auth';
import {
  getExchangeRates,
  setExchangeRate,
  getLatestRate,
  convertAmount,
  deleteExchangeRate,
} from '@/modules/accounting/services/currencyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const { from, to, convert, amount, date } = req.query;

    // Convert endpoint: ?convert=true&from=USD&to=ZAR&amount=100&date=2026-02-26
    if (convert === 'true' && from && to && amount) {
      const result = await convertAmount(companyId,
        Number(amount), String(from), String(to), date ? String(date) : undefined
      );
      if (!result) return apiResponse.notFound(res, 'Exchange rate', `${from}/${to}`);
      return apiResponse.success(res, result);
    }

    // Latest rate: ?from=USD&to=ZAR&latest=true
    if (req.query.latest === 'true' && from && to) {
      const rate = await getLatestRate(companyId, String(from), String(to), date ? String(date) : undefined);
      if (rate === null) return apiResponse.notFound(res, 'Exchange rate', `${from}/${to}`);
      return apiResponse.success(res, { from, to, rate });
    }

    // List rates
    const rates = await getExchangeRates(companyId, {
      fromCurrency: from ? String(from) : undefined,
      toCurrency: to ? String(to) : undefined,
      limit: req.query.limit ? Number(req.query.limit) : undefined,
    });
    return apiResponse.success(res, rates);
  }

  if (req.method === 'POST') {
    const { fromCurrency, toCurrency, rate, effectiveDate, source } = req.body;
    if (!fromCurrency || !toCurrency || !rate || !effectiveDate) {
      return apiResponse.badRequest(res, 'fromCurrency, toCurrency, rate, effectiveDate required');
    }
    const numRate = Number(rate);
    if (isNaN(numRate) || numRate <= 0) {
      return apiResponse.badRequest(res, 'Exchange rate must be a positive number');
    }
    const result = await setExchangeRate(companyId,
      { fromCurrency, toCurrency, rate: numRate, effectiveDate, source },
      userId
    );
    return apiResponse.success(res, result);
  }

  if (req.method === 'DELETE') {
    const { id } = req.query;
    if (!id || typeof id !== 'string') {
      return apiResponse.badRequest(res, 'id query parameter is required');
    }
    await deleteExchangeRate(companyId, id);
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

