              <span className="text-sm text-[var(--ff-text-secondary)]">
                {customers.length} customer{customers.length !== 1 ? 's' : ''}
              </span>
            )}
          </div>

          {selected.size > 0 && (
            <BulkBar count={selected.size} loading={bulkLoading} errorMsg={bulkError}
              onAction={(a) => void handleBulkAction(a)}
              onClear={() => { setSelected(new Set()); setBulkError(''); }} />
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="flex items-center justify-center gap-2 text-red-400 py-12">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : customers.length === 0 ? (
            <div className="text-center py-16">
              <Users className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
