export interface ConvertResult {
  invoiceId: string;
  invoiceNumber: string;
}

async function nextInvoiceNumber(companyId: string, tx: typeof sql): Promise<string> {
  for (let attempt = 0; attempt < 5; attempt++) {
    const maxRows = (await tx`
      SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)), 0) AS max_num
      FROM customer_invoices
      WHERE company_id = ${companyId} AND invoice_number ~ '^INV-[0-9]+$'
    `) as Row[];
    const base = Number(maxRows[0]?.['max_num'] ?? 0) + 1 + attempt;
    const candidate = `INV-${String(base).padStart(5, '0')}`;
    const existing = (await tx`
      SELECT id FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number = ${candidate}
    `) as Row[];
    if (existing.length === 0) return candidate;
  }
  // Fallback: uuid suffix ensures uniqueness
  return `INV-${Date.now()}`;
}

export async function convertSalesOrderToInvoice(
  companyId: string,
  id: string,
  lineIds: string[] | undefined,
  userId: string,
): Promise<ConvertResult | null> {
  const order = await getSalesOrder(companyId, id);
  if (!order) return null;
  if (order.status !== 'confirmed' && order.status !== 'partially_invoiced') return null;

  const allItems = order.items ?? [];
  const selectedItems =
    lineIds && lineIds.length > 0
      ? allItems.filter((item) => lineIds.includes(item.id))
      : allItems;

  if (selectedItems.length === 0) return null;

  // Recalculate totals for selected lines only
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of selectedItems) {
    const lt = Math.round(item.quantity * item.unitPrice * 100) / 100;
    const lineTax = Math.round(lt * (item.taxRate / 100) * 100) / 100;
    subtotal += lt;
    taxAmount += lineTax;
  }
  subtotal = Math.round(subtotal * 100) / 100;
  taxAmount = Math.round(taxAmount * 100) / 100;
  const totalAmount = Math.round((subtotal + taxAmount) * 100) / 100;

  const today = new Date().toISOString().split('T')[0];

  const result = await withTransaction(async (tx) => {
    const invoiceNumber = await nextInvoiceNumber(companyId, tx);

    const invRows = (await tx`
      INSERT INTO customer_invoices (
        company_id, invoice_number, customer_id, client_id,
        invoice_date, due_date, subtotal, tax_rate, tax_amount, total_amount,
        notes, status, created_by
      ) VALUES (
        ${companyId}, ${invoiceNumber},
        ${order.customerId ?? null}, ${order.customerId ?? null},
        ${today}, ${order.deliveryDate ?? null},
        ${subtotal}, 15, ${taxAmount}, ${totalAmount},
        ${order.notes ? `Converted from ${order.orderNumber}. ${order.notes}` : `Converted from ${order.orderNumber}`},
        'draft', ${userId}
      ) RETURNING id
    `) as Row[];
    const invoiceId = String(invRows[0]!.id);

    for (const item of selectedItems) {
      const lineAmount = Math.round(item.quantity * item.unitPrice * 100) / 100;
      await tx`
        INSERT INTO customer_invoice_items (invoice_id, description, quantity, unit_price, amount, tax_rate)
        VALUES (
          ${invoiceId}::UUID, ${item.description}, ${item.quantity},
          ${item.unitPrice}, ${lineAmount}, ${item.taxRate}
        )
      `;
    }

    // Determine new SO status: fully invoiced if all lines are covered
    const invoicedItemIds = new Set(selectedItems.map((i) => i.id));
    const allInvoiced = allItems.every((i) => invoicedItemIds.has(i.id));
    const newStatus = allInvoiced ? 'invoiced' : 'partially_invoiced';

    await tx`
      UPDATE customer_sales_orders SET
        status = ${newStatus},
        invoiced_at = NOW(),
        invoice_id = ${invoiceId}::UUID,
        updated_at = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
    `;

    return { invoiceId, invoiceNumber };
  });

  log.info('Sales order converted to invoice', {
    salesOrderId: id,
    invoiceId: result.invoiceId,
    invoiceNumber: result.invoiceNumber,
  });
  return result;
}

/**
