    vi.mocked(sql).mockResolvedValueOnce([] as never);

    await expect(
      postJournalEntry(COMPANY_ID, ENTRY_ID, USER_ID)
    ).rejects.toThrow(`Journal entry ${ENTRY_ID} not found`);
