      ...validInput,
      invoiceNumber: 'ACME/2026/00042',
    };

    const inv = await createSupplierInvoice(COMPANY_ID, input, USER_ID);
    expect(inv.invoiceNumber).toBe('ACME/2026/00042');
  });
