// WORKING: pure computation — no DB, no side effects
export interface ExchangeRateInput {
  fromCurrency: string;
  toCurrency: string;
  rate: number;
  effectiveDate: string; // YYYY-MM-DD
}

export interface ExchangeRate extends ExchangeRateInput {
  id?: string;
}

export interface ConversionResult {
  amount: number;
  fromCurrency: string;
  toCurrency: string;
  rate: number;
}

export interface FXGainLoss {
  amount: number; // positive = gain, negative = loss
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

const CURRENCY_SYMBOLS: Record<string, string> = {
  ZAR: 'R',
  USD: '$',
  EUR: '€',
  GBP: '£',
};

/**
 * Convert `amount` from one currency to another using the provided rate.
 * Throws when rate ≤ 0.
 * Returns the original amount unchanged when fromCurrency === toCurrency.
 */
export function convertAmount(
  amount: number,
  fromCurrency: string,
  toCurrency: string,
  rate: number,
): number {
  if (rate <= 0) {
    throw new Error(`Exchange rate must be greater than 0, received ${rate}`);
  }
  if (fromCurrency === toCurrency) {
    return amount;
  }
  return Math.round(amount * rate * 100) / 100;
}

/**
 * Validate an ExchangeRateInput for correctness.
 * Returns { valid, errors } where errors is an array of human-readable messages.
 */
export function validateExchangeRate(input: ExchangeRateInput): ValidationResult {
  const errors: string[] = [];

  if (!input.fromCurrency || input.fromCurrency.trim() === '') {
    errors.push('fromCurrency is required');
  }

  if (!input.toCurrency || input.toCurrency.trim() === '') {
    errors.push('toCurrency is required');
  }

  if (
    input.fromCurrency &&
    input.toCurrency &&
    input.fromCurrency === input.toCurrency
  ) {
    errors.push('fromCurrency and toCurrency must not be the same currency');
  }

  if (input.rate <= 0) {
    errors.push('rate must be greater than 0');
  } else if (input.rate > 10000) {
    errors.push('rate exceeds maximum allowed value of 10000');
  }

  if (!ISO_DATE_RE.test(input.effectiveDate)) {
    errors.push('effectiveDate must be a valid date in YYYY-MM-DD format');
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Find the exchange rate applicable on `date` for the given currency pair.
 *
 * - Returns a synthetic rate of 1.0 when fromCurrency === toCurrency.
 * - Returns an exact match if one exists, otherwise the most-recent rate with
 *   effectiveDate ≤ date.
 * - Returns null when no suitable rate is found (including when date is before
 *   all available rates or the currency pair is absent).
 */
export function getExchangeRateForDate(
  rates: ExchangeRate[],
  fromCurrency: string,
  toCurrency: string,
  date: string,
): ExchangeRate | null {
  if (fromCurrency === toCurrency) {
    return { fromCurrency, toCurrency, rate: 1.0, effectiveDate: date };
  }

  const matching = rates.filter(
    (r) =>
      r.fromCurrency === fromCurrency &&
      r.toCurrency === toCurrency &&
      r.effectiveDate <= date,
  );

  if (matching.length === 0) return null;

  // Sort descending by date and take the most recent
  matching.sort((a, b) => (a.effectiveDate > b.effectiveDate ? -1 : 1));
  return matching[0] ?? null;
}

/**
 * Calculate FX gain or loss on a foreign-currency asset/liability.
 *
 * Formula: (originalRate - currentRate) * originalAmount
 *   positive → gain (domestic currency strengthened)
 *   negative → loss (domestic currency weakened)
 *
 * Result is expressed in the domestic (ZAR) reporting currency.
 */
export function calculateFXGainLoss(
  originalAmount: number,
  originalRate: number,
  currentRate: number,
  _currency: string,
): number {
  if (originalAmount === 0) return 0;
  return Math.round((originalRate - currentRate) * originalAmount * 100) / 100;
}

/**
 * Format `amount` as a localised currency string.
 *
 * Known symbols: ZAR → R, USD → $, EUR → €, GBP → £
 * Unknown codes use the ISO code as the prefix.
 *
 * Example output: "R 1,234.56"
 */
export function formatCurrencyAmount(amount: number, currencyCode: string): string {
  const symbol = CURRENCY_SYMBOLS[currencyCode] ?? currencyCode;
  const formatted = amount.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  return `${symbol} ${formatted}`;
}

/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;


async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  try {
    const userId = String(req.user?.id || 'system');

    // Calculate totals
    const rate = taxRate ?? 15;
    let subtotal = 0;
    for (const item of items) {
      subtotal += (item.quantity || 1) * item.unitPrice;
    }
    subtotal = Math.round(subtotal * 100) / 100;
    const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
    const totalAmount = subtotal + taxAmount;

    const today = new Date().toISOString().split('T')[0];
    const invDate = invoiceDate || today;
    const bpStart = billingPeriodStart || null;
    const bpEnd = billingPeriodEnd || null;

    // Find project from client (optional)
    let projectId: string | null = null;
    try {
      const projRows = (await sql`SELECT id FROM projects WHERE client_id = ${clientId}::UUID AND company_id = ${companyId} LIMIT 1`) as Row[];
      projectId = (projRows[0]?.['id'] as string | undefined) ?? null;
    } catch { /* projects table may not exist */ }

    // Insert invoice with retry on unique-constraint violation.
    // MAX()+1 races under concurrent load — if we collide, re-read MAX and try again
    // (up to 5 times with escalating offset so the series stays monotonic).
    let invoiceId = '';
    let invoiceNumber = '';
    for (let attempt = 0; attempt < 5; attempt++) {
      const maxRows = (await sql`
        SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)), 0) AS max_num
        FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number ~ '^INV-[0-9]+$'
      `) as Row[];
      const base = Number(maxRows[0]?.['max_num'] ?? 0) + 1 + attempt;
      invoiceNumber = `INV-${String(base).padStart(5, '0')}`;

      try {
        const invRows = (await sql`
          INSERT INTO customer_invoices (
            company_id, invoice_number, project_id, customer_id, client_id, billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
            notes, status, created_by
          ) VALUES (
            ${companyId}, ${invoiceNumber}, ${projectId}, ${clientId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
            ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
            ${dueDate || null}, ${notes || null}, 'draft', ${userId}
          ) RETURNING id
        `) as Row[];
        invoiceId = String(invRows[0]!.id);
        break;
      } catch (insertErr) {
        const msg = insertErr instanceof Error ? insertErr.message : String(insertErr);
        if (msg.includes('unique') && attempt < 4) continue;
        throw insertErr;
      }
    }

    for (const item of items) {
      const qty = item.quantity || 1;
      const lineAmount = Math.round(qty * item.unitPrice * 100) / 100;
      await sql`
        INSERT INTO customer_invoice_items (invoice_id, description, unit_price, quantity, amount, tax_rate)
        VALUES (${invoiceId}::UUID, ${item.description}, ${item.unitPrice}, ${qty}, ${lineAmount}, ${rate})
      `;
    }

    log.info('Customer invoice created', { invoiceNumber, totalAmount });
    return apiResponse.created(res, { id: invoiceId, invoiceNumber });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Invoice create failed', { error: msg });
    const clientMessage = process.env.NODE_ENV === 'development' ? msg : 'Failed to create invoice';
    return res.status(500).json({ success: false, error: { code: 'CREATE_FAILED', message: clientMessage } });
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

import { sql } from '@/lib/neon';
/**
 * Customer Invoices List API (cross-project)
 * GET /api/accounting/customer-invoices-list - All customer invoices across projects
 * Sage equivalent: Customers > Tax Invoices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';


async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  try {
    const { status, limit: limitParam = '50', offset = '0', q } = req.query;
    const limit = Math.min(Number(limitParam), 200);
    const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

    let invoices;
    if (status && status !== 'all') {
      invoices = await sql`
        SELECT
          ci.id, ci.invoice_number, ci.project_id,
          COALESCE(ci.client_id, ci.customer_id) as client_id,
          ci.total_amount, ci.amount_paid, ci.status,
          ci.invoice_date, ci.due_date, ci.sent_at, ci.paid_at,
          c.name as client_name
        FROM customer_invoices ci
        LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
        WHERE ci.company_id = ${companyId}
          AND ci.deleted_at IS NULL
          AND ci.status = ${status as string}
        ORDER BY ci.invoice_date DESC
        LIMIT ${Number(limit)} OFFSET ${Number(offset)}
      `;
    } else if (searchTerm) {
      invoices = await sql`
        SELECT
          ci.id, ci.invoice_number, ci.project_id,
          COALESCE(ci.client_id, ci.customer_id) as client_id,
          ci.total_amount, ci.amount_paid, ci.status,
          ci.invoice_date, ci.due_date, ci.sent_at, ci.paid_at,
          c.name as client_name
        FROM customer_invoices ci
        LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
        WHERE ci.company_id = ${companyId}
          AND ci.deleted_at IS NULL
          AND (ci.invoice_number ILIKE ${searchTerm} OR c.name ILIKE ${searchTerm})
        ORDER BY ci.invoice_date DESC
        LIMIT ${Number(limit)} OFFSET ${Number(offset)}
      `;
    } else {
      invoices = await sql`
        SELECT
          ci.id, ci.invoice_number, ci.project_id,
          COALESCE(ci.client_id, ci.customer_id) as client_id,
          ci.total_amount, ci.amount_paid, ci.status,
          ci.invoice_date, ci.due_date, ci.sent_at, ci.paid_at,
          c.name as client_name
        FROM customer_invoices ci
        LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
        WHERE ci.company_id = ${companyId}
          AND ci.deleted_at IS NULL
        ORDER BY ci.invoice_date DESC
        LIMIT ${Number(limit)} OFFSET ${Number(offset)}
      `;
    }

    return apiResponse.success(res, { invoices, total: invoices.length });
  } catch (err) {
    log.error('Failed to fetch customer invoices list', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to fetch customer invoices');
  }
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Customer Invoice Detail API
 * GET  ?id=UUID — single invoice with line items
 * PUT  { id, ...fields } — update draft invoice
 * POST { id, action } — status actions (approve, send, cancel)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { postCustomerInvoiceToGL } from '@/modules/accounting/services/customerPaymentService';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { id } = req.query;
    if (!id) return apiResponse.badRequest(res, 'id is required');

    try {
      const rows = (await sql`
        SELECT ci.id, ci.invoice_number, ci.customer_id, ci.client_id,
               ci.billing_period_start, ci.billing_period_end,
               ci.subtotal, ci.tax_rate, ci.tax_amount, ci.total_amount,
               ci.amount_paid, ci.status, ci.invoice_date, ci.due_date,
               ci.sent_at, ci.paid_at, ci.notes, ci.internal_notes,
               ci.project_id, ci.gl_journal_entry_id,
               ci.email_sent_at, ci.email_sent_to,
               ci.online_payment_enabled, ci.payment_url,
               ci.created_at, ci.updated_at,
               c.name AS client_name, c.email AS client_email
        FROM customer_invoices ci
        LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
        WHERE ci.id = ${id as string}::UUID AND ci.company_id = ${companyId}
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Invoice', id as string);

      const items = (await sql`
        SELECT cii.* FROM customer_invoice_items cii JOIN customer_invoices ci ON ci.id = cii.invoice_id WHERE cii.invoice_id = ${id as string}::UUID AND ci.company_id = ${companyId} ORDER BY cii.created_at
      `) as Row[];

      return apiResponse.success(res, { ...rows[0], items });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      log.error('Customer invoice detail GET error', { error: msg }, 'customer-invoice-detail');
      return apiResponse.internalError(res, err, `Failed to load invoice: ${msg}`);
    }
  }

  if (req.method === 'PUT') {
    const { id, notes, internalNotes, dueDate } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');

    await sql`
      UPDATE customer_invoices
      SET notes = COALESCE(${notes || null}, notes),
          internal_notes = COALESCE(${internalNotes || null}, internal_notes),
          due_date = COALESCE(${dueDate || null}, due_date),
          updated_at = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId} AND status = 'draft'
    `;
    log.info('Customer invoice updated', { id });
    return apiResponse.success(res, { updated: true });
  }

  if (req.method === 'POST') {
    const { id, action } = req.body;
    if (!id || !action) return apiResponse.badRequest(res, 'id and action required');

    const validActions: Record<string, string> = {
      approve: 'approved', send: 'sent', cancel: 'cancelled',
    };
    const newStatus = validActions[action];
    if (!newStatus) return apiResponse.badRequest(res, `Unknown action: ${action}`);

    await sql`UPDATE customer_invoices SET status = ${newStatus}, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}`;

    // Post to GL on approve (accrual accounting: DR AR, CR Revenue, CR VAT Output)
    let glJournalEntryId: string | null = null;
    if (action === 'approve') {
      try {
        const userId = (req as CompanyApiRequest).user?.id || 'system';
        glJournalEntryId = await postCustomerInvoiceToGL(companyId, id, userId);
        log.info('Customer invoice GL posted on approve', { id, glJournalEntryId });
      } catch (glErr) {
        log.error('GL posting failed on invoice approve (invoice still approved)', { id, error: glErr });
      }
    }

    log.info('Customer invoice action', { id, action, newStatus });
    return apiResponse.success(res, { id, status: newStatus, glJournalEntryId });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT', 'POST']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Supplier Invoices API
 * GET  /api/accounting/supplier-invoices - List invoices (with filters)
 * POST /api/accounting/supplier-invoices - Create draft invoice
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getSupplierInvoices,
  createSupplierInvoice,
} from '@/modules/accounting/services/supplierInvoiceService';
import type { SupplierInvoiceStatus } from '@/modules/accounting/types/ap.types';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { status, supplier_id, match_status, limit, offset } = req.query;
      const result = await getSupplierInvoices(companyId, {
        status: status as SupplierInvoiceStatus | undefined,
        supplierId: supplier_id ? String(supplier_id) : undefined,
        matchStatus: match_status as 'unmatched' | 'po_matched' | 'grn_matched' | 'fully_matched' | undefined,
        limit: limit ? Math.min(Number(limit), 200) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get supplier invoices', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get supplier invoices');
    }
  }

  if (req.method === 'POST') {
    try {
      const { invoiceNumber, supplierId, purchaseOrderId, grnId, invoiceDate,
        dueDate, taxRate, paymentTerms, reference, projectId, costCenterId,
        notes, items } = req.body;

      if (!invoiceNumber || !supplierId || !invoiceDate || !items || !Array.isArray(items) || items.length === 0) {
        return apiResponse.badRequest(res, 'invoiceNumber, supplierId, invoiceDate, and items are required');
      }

      // User identity comes from JWT (req.user), never from client request body
      const userId = req.user.id;

      const invoice = await createSupplierInvoice(companyId, {
        invoiceNumber, supplierId: String(supplierId), purchaseOrderId, grnId,
        invoiceDate, dueDate, taxRate: taxRate ? Number(taxRate) : undefined,
        paymentTerms, reference, projectId, costCenterId, notes, items,
      }, userId);

      return apiResponse.created(res, invoice);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create supplier invoice';
      log.error('Failed to create supplier invoice', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Create Customer Invoice (standalone)
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, FileText, Plus, Trash2, Loader2, Info, SlidersHorizontal } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { ScanAndFillButton } from '@/components/accounting/ScanAndFillButton';
import { fuzzyMatchClient } from '@/modules/accounting/utils/fuzzyMatch';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Client { id: string; name: string }
interface LineItem { key: string; description: string; quantity: number; unitPrice: number; incomeType: string; discount: number }

export default function NewCustomerInvoicePage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [scanBanner, setScanBanner] = useState<string | null>(null);
  const today = new Date().toISOString().split('T')[0];

  const [form, setForm] = useState({ clientId: '', invoiceDate: today, dueDate: '', billingPeriodStart: today, billingPeriodEnd: today, taxRate: 15, notes: '' });
  const [lines, setLines] = useState<LineItem[]>([{ key: '1', description: '', quantity: 1, unitPrice: 0, incomeType: 'other', discount: 0 }]);
  const [showDiscount, setShowDiscount] = useState(false);

  useEffect(() => {
    apiFetch('/api/accounting/customers', { credentials: 'include' }).then(r => r.json()).then(json => {
      const d = json.data || json;
      setClients(Array.isArray(d) ? d : d.clients || []);
    }).catch(() => { /* reference data load failure — non-critical, client dropdown will be empty */ });
  }, []);

  const updateLine = (key: string, field: string, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };
  const addLine = () => setLines(prev => [...prev, { key: String(Date.now()), description: '', quantity: 1, unitPrice: 0, incomeType: 'other', discount: 0 }]);
  const removeLine = (key: string) => setLines(prev => prev.length > 1 ? prev.filter(l => l.key !== key) : prev);

  const lineTotal = (l: LineItem) => l.quantity * l.unitPrice * (1 - (l.discount || 0) / 100);
  const subtotal = lines.reduce((s, l) => s + lineTotal(l), 0);
  const tax = subtotal * (form.taxRate / 100);
  const total = subtotal + tax;

  function handleExtracted(data: ExtractedDocument) {
    const updates: Partial<typeof form> = {};
    if (data.date) updates.invoiceDate = data.date;
    if (data.dueDate) updates.dueDate = data.dueDate;
    if (data.vatRate !== null) updates.taxRate = data.vatRate;

    setForm(f => ({ ...f, ...updates }));

    if (data.customerName && clients.length > 0) {
      const match = fuzzyMatchClient(data.customerName, clients);
      if (match) setForm(f => ({ ...f, clientId: String(match.id) }));
    }

    if (data.lineItems.length > 0) {
      setLines(data.lineItems.map(li => ({
        key: String(Date.now() + Math.random()),
        description: li.description,
        quantity: li.quantity ?? 1,
        unitPrice: li.unitPrice ?? 0,
        incomeType: 'other',
        discount: 0,
      })));
    }

    setScanBanner(`Auto-filled (${Math.round(data.confidence * 100)}% confidence). Review all fields.`);
  }

  const handleSubmit = async () => {
    if (!form.clientId) return setError('Select a client');
    const validLines = lines.filter(l => l.description && l.unitPrice > 0);
    if (validLines.length === 0) return setError('Add at least one line item');
    setSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/customer-invoices-create', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, items: validLines }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Failed to create');
      const d = json.data || json;
      router.push(`/accounting/customer-invoices/${d.id}`);
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed'); setSubmitting(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
