                    <td className="px-3 py-2"><button onClick={() => removeLine(l.key)} className="text-red-400 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
