/**
 * IRP5 Certificate Generation API
 * POST: generate IRP5 for an employee or batch
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { buildIRP5Certificate, validateIRP5Data, type IRP5EmployeeData } from '@/modules/accounting/services/irp5Service';

type Row = Record<string, unknown>;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    // List generated IRP5 certificates
    const { taxYear } = req.query;
    const yr = taxYear ? Number(taxYear) : new Date().getFullYear();
    const rows = await sql`
      SELECT e.id, e.first_name, e.last_name, e.id_number, e.tax_number,
        COALESCE(SUM(ps.gross_pay), 0) as total_gross,
        COALESCE(SUM(ps.paye), 0) as total_paye,
        COALESCE(SUM(ps.uif_employee), 0) as total_uif
      FROM employees e
      LEFT JOIN payslips ps ON ps.employee_id = e.id
      LEFT JOIN payroll_runs pr ON ps.payroll_run_id = pr.id AND EXTRACT(YEAR FROM pr.period_end) = ${yr}
      WHERE e.company_id = ${req.companyId}::UUID
      GROUP BY e.id, e.first_name, e.last_name, e.id_number, e.tax_number
      ORDER BY e.last_name
      LIMIT 500
    ` as Row[];
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const { employeeId, taxYear } = req.body;
    if (!employeeId) return apiResponse.badRequest(res, 'employeeId is required');
    const yr = taxYear || new Date().getFullYear();

    // Get employee — scoped to company
    const employees = await sql`SELECT * FROM employees WHERE id = ${employeeId} AND company_id = ${req.companyId}::UUID` as Row[];
    if (!employees[0]) return apiResponse.notFound(res, 'Employee', employeeId);
    const emp = employees[0] as any;

    // Validate
    const validation = validateIRP5Data({
      employeeName: `${emp.first_name} ${emp.last_name}`,
      idNumber: emp.id_number || '',
      taxNumber: emp.tax_number || '',
      grossSalary: 1,
      paye: 1,
    });
    if (!validation.valid) return apiResponse.badRequest(res, 'IRP5 validation failed', validation.errors);

    // Aggregate payslip data for the tax year
    const payslips = await sql`
      SELECT
        COALESCE(SUM(ps.gross_pay), 0) as gross_salary,
        COALESCE(SUM(ps.paye), 0) as paye,
        COALESCE(SUM(ps.uif_employee), 0) as uif_employee,
        COALESCE(SUM(ps.uif_employer), 0) as uif_employer,
        COALESCE(SUM(ps.sdl), 0) as sdl
      FROM payslips ps
      JOIN payroll_runs pr ON ps.payroll_run_id = pr.id
      WHERE ps.employee_id = ${employeeId}
        AND pr.company_id = ${req.companyId}::UUID
        AND pr.period_end >= ${`${yr - 1}-03-01`}
        AND pr.period_end <= ${`${yr}-02-28`}
    ` as Row[];

    const data = payslips[0] as any || {};
    const employeeData: IRP5EmployeeData = {
      grossSalary: Number(data.gross_salary || 0),
      commission: 0,
      overtime: 0,
      bonus: 0,
      travelAllowance: 0,
      pensionContribEmployee: 0,
      medicalAidEmployee: 0,
      retirementAnnuity: 0,
      paye: Number(data.paye || 0),
      uifEmployee: Number(data.uif_employee || 0),
      uifEmployer: Number(data.uif_employer || 0),
      sdl: Number(data.sdl || 0),
    };

    // Fetch company details for employer info
    const companyRows = await sql`SELECT name, vat_number FROM companies WHERE id = ${req.companyId}` as Row[];
    const company = companyRows[0] as Record<string, string> | undefined;

    const cert = buildIRP5Certificate({
      employeeData,
      employeeName: `${emp.first_name} ${emp.last_name}`,
      idNumber: emp.id_number || '',
      taxNumber: emp.tax_number || '',
      employerName: String(company?.name || 'Unknown Company'),
      employerPayeRef: String(company?.vat_number || ''),
      taxYear: yr,
      periodStart: `${yr - 1}-03-01`,
      periodEnd: `${yr}-02-28`,
    });

    log.info('IRP5 generated', { employeeId, taxYear: yr }, 'payroll');
    return apiResponse.success(res, cert);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler));

/**
 * EMP201 Monthly Return API
 * GET /api/payroll/payroll-emp201?month=YYYY-MM
 *
 * Aggregates PAYE, UIF, and SDL totals for a given month from payroll_runs
 * and payslips, scoped to the authenticated company.
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export interface Emp201Result {
  month: string;
  totalGross: number;
  totalPaye: number;
  totalUifEmployee: number;
  totalUifEmployer: number;
  totalSdl: number;
  totalLiability: number;
  employeeCount: number;
  payrollRunIds: string[];
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { month } = req.query;
  if (!month || typeof month !== 'string' || !/^\d{4}-\d{2}$/.test(month)) {
    return apiResponse.badRequest(res, 'month parameter is required in YYYY-MM format');
  }

  try {
    // Resolve the month to a date range
    const periodStart = `${month}-01`;
    // Last day of month via DATE_TRUNC + interval
    const runRows = (await sql`
      SELECT
        pr.id,
        pr.total_gross,
        pr.total_paye,
        pr.total_uif_employee,
        pr.total_uif_employer,
        pr.total_sdl
      FROM payroll_runs pr
      WHERE pr.company_id = ${companyId}::UUID
        AND pr.status IN ('draft', 'completed')
        AND pr.period_start >= ${periodStart}::DATE
        AND pr.period_start < (DATE_TRUNC('month', ${periodStart}::DATE) + INTERVAL '1 month')
      ORDER BY pr.period_start
    `) as Row[];

    if (runRows.length === 0) {
      const empty: Emp201Result = {
        month,
        totalGross: 0,
        totalPaye: 0,
        totalUifEmployee: 0,
        totalUifEmployer: 0,
        totalSdl: 0,
        totalLiability: 0,
        employeeCount: 0,
        payrollRunIds: [],
      };
      return apiResponse.success(res, empty);
    }

    const payrollRunIds = runRows.map((r: Row) => String(r.id));

    // Aggregate payslip-level totals for accuracy
    const aggRows = (await sql`
      SELECT
        COALESCE(SUM(ps.gross_pay), 0)     AS total_gross,
        COALESCE(SUM(ps.paye), 0)          AS total_paye,
        COALESCE(SUM(ps.uif_employee), 0)  AS total_uif_employee,
        COALESCE(SUM(ps.uif_employer), 0)  AS total_uif_employer,
        COALESCE(SUM(ps.sdl), 0)           AS total_sdl,
        COUNT(DISTINCT ps.employee_id)     AS employee_count
      FROM payslips ps
      WHERE ps.payroll_run_id = ANY(${payrollRunIds}::UUID[])
    `) as Row[];

    const agg = aggRows[0]!;
    const totalGross       = Math.round(Number(agg.total_gross) * 100) / 100;
    const totalPaye        = Math.round(Number(agg.total_paye) * 100) / 100;
    const totalUifEmployee = Math.round(Number(agg.total_uif_employee) * 100) / 100;
    const totalUifEmployer = Math.round(Number(agg.total_uif_employer) * 100) / 100;
    const totalSdl         = Math.round(Number(agg.total_sdl) * 100) / 100;
    const employeeCount    = Number(agg.employee_count) || 0;

    const totalLiability = Math.round(
      (totalPaye + totalUifEmployee + totalUifEmployer + totalSdl) * 100
    ) / 100;

    const result: Emp201Result = {
      month,
      totalGross,
      totalPaye,
      totalUifEmployee,
      totalUifEmployer,
      totalSdl,
      totalLiability,
      employeeCount,
      payrollRunIds,
    };

    log.info('EMP201 fetched', { companyId, month, totalLiability }, 'payroll-emp201');
    return apiResponse.success(res, result);
  } catch (err) {
    log.error('EMP201 GET failed', { error: err }, 'payroll-emp201');
    return apiResponse.internalError(res, err, 'Failed to fetch EMP201 data');
  }
}

