 1	/**
 2	 * Client Portal — Invoices API
 3	 * GET — list invoices for the authenticated portal user's client
 4	 * Requires signed portal session cookie (JWT)
 5	 */
 6	
 7	import type { NextApiRequest, NextApiResponse } from 'next';
 8	import { withErrorHandler } from '@/lib/api-error-handler';
 9	import { apiResponse } from '@/lib/apiResponse';
10	import { getClientInvoices } from '@/modules/accounting/services/portalService';
11	import { jwtVerify } from 'jose';
12	import cookie from 'cookie';
13	
14	const PORTAL_SECRET = new TextEncoder().encode(
15	  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
16	);
17	
18	async function getPortalSession(req: NextApiRequest): Promise<{ clientId: string } | null> {
19	  const cookies = cookie.parse(req.headers.cookie || '');
20	  const token = cookies.portal_session;
21	  if (!token) return null;
22	  try {
23	    const { payload } = await jwtVerify(token, PORTAL_SECRET);
24	    return { clientId: payload.clientId as string };
25	  } catch {
26	    return null;
27	  }
28	}
29	
30	async function handler(req: NextApiRequest, res: NextApiResponse) {
31	  if (req.method !== 'GET') {
32	    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
33	  }
34	
35	  const session = await getPortalSession(req);
36	  if (!session) {
37	    return apiResponse.unauthorized(res, 'Portal authentication required');
38	  }
39	
40	  const clientId = req.query.clientId as string;
41	  if (!clientId) {
42	    return apiResponse.badRequest(res, 'clientId is required');
43	  }
44	
45	  // Enforce tenant isolation — user can only access their own client data
46	  if (session.clientId !== clientId) {
47	    return apiResponse.forbidden(res, 'Access denied — clientId mismatch');
48	  }
49	
50	  const invoices = await getClientInvoices(clientId);
51	  return apiResponse.success(res, { items: invoices });
52	}
53	
54	export default withErrorHandler(handler);

