 14	import { log } from '@/lib/logger';
 15	type Row = Record<string, unknown>;
 16	
 17	
 18	async function handler(req: NextApiRequest, res: NextApiResponse) {
 19	  if (req.method === 'GET') {
 20	    const token = req.query.token as string;
 21	    if (!token) return apiResponse.badRequest(res, 'token is required');
 22	    const link = await getPaymentLink(token);
 23	    if (!link) return apiResponse.notFound(res, 'Payment link');
 24	
 25	    // Enrich with invoice details and PayFast form data
 26	    const enriched: Record<string, unknown> = { ...link };
 27	    try {
 28	      const invoiceRows = (await sql`
 29	        SELECT ci.invoice_number, ci.due_date, ci.online_payment_enabled, ci.company_id,
 30	               co.name AS company_name
 31	        FROM customer_invoices ci
 32	        LEFT JOIN companies co ON co.id = ci.company_id
 33	        WHERE ci.id = ${link.invoiceId}::UUID
 34	      `) as Row[];
 35	
 36	      if (invoiceRows[0]) {
 37	        enriched.invoiceNumber = invoiceRows[0].invoice_number;
 38	        enriched.dueDate = invoiceRows[0].due_date;
 39	        enriched.companyName = invoiceRows[0].company_name;
 40	
 41	        // Generate PayFast form data if online payment is enabled
 42	        if (invoiceRows[0].online_payment_enabled) {
 43	          const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';
 44	          const companyId = invoiceRows[0].company_id as string;
 45	          try {
 46	            const formData = await generatePayFastForm(
 47	              companyId,
 48	              link.invoiceId,
 49	              `${appUrl}/portal/pay/${token}?payment_status=success`,
 50	              `${appUrl}/portal/pay/${token}?payment_status=cancelled`,
 51	              `${appUrl}/api/accounting/payment-gateway-itn`,
 52	            );
 53	            enriched.payfastFormData = formData;
 54	          } catch (e) {
 55	            log.error('Failed to generate PayFast form for portal', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
 56	          }
 57	        }
 58	      }
 59	    } catch (e) {
 60	      log.error('Failed to enrich payment link', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
 61	    }
 62	
 63	    return apiResponse.success(res, enriched);
 64	  }
 65	
 66	  if (req.method === 'POST') {
 67	    const { invoiceId, clientId, amount } = req.body;
 68	    if (!invoiceId || !clientId || !amount) {
 69	      return apiResponse.badRequest(res, 'invoiceId, clientId, and amount are required');
 70	    }
 71	
 72	    // Resolve the authenticated user's company
 73	    const userId = (req as AuthenticatedNextApiRequest).user.id;
 74	    const companyRows = (await sql`
 75	      SELECT company_id FROM company_users
 76	      WHERE user_id = ${userId}
 77	      ORDER BY is_default DESC, created_at ASC
 78	      LIMIT 1
 79	    `) as Row[];
 80	    if (companyRows.length === 0) {
 81	      return apiResponse.badRequest(res, 'No company assigned to this user');
 82	    }
 83	    const companyId = companyRows[0]!.company_id as string;
 84	
 85	    // Verify invoice belongs to this company
 86	    const invoice = (await sql`
 87	      SELECT id FROM customer_invoices
 88	      WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
 89	    `) as Row[];
 90	    if (invoice.length === 0) return apiResponse.notFound(res, 'Invoice not found');
 91	
 92	    const token = await createPaymentLink(invoiceId, clientId, Number(amount));
 93	    return apiResponse.success(res, { token, url: `/portal/pay/${token}` });
 94	  }
 95	
 96	  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
 97	}
