import { AppLayout } from '@/components/layout/AppLayout';
import { formatCurrency } from '@/utils/formatters';
import { FileText, Loader2, AlertCircle, Download, RefreshCw } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

// ── Types ─────────────────────────────────────────────────────────────────────

interface Irp5CertRow {
  employee_id: string;
  employee_number: string;
  first_name: string;
  last_name: string;
  id_number: string | null;
  tax_number: string | null;
  total_gross_income: number;
  total_paye: number;
  total_uif_employee: number;
  total_uif_employer: number;
  total_net_pay: number;
  certificate_number: string;
}

interface Irp5Response {
  taxYear: number;
  certificates: Irp5CertRow[];
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function getCurrentTaxYear(): number {
  const now = new Date();
  // SA tax year: March → February. If month >= 3, tax year = year + 1
  return now.getMonth() >= 2 ? now.getFullYear() + 1 : now.getFullYear();
}

function exportCsv(certs: Irp5CertRow[], taxYear: number) {
  const header = [
    'Certificate Number',
    'Employee Number',
    'Surname',
    'First Name',
    'ID Number',
    'Tax Number',
    'Gross Income',
    'PAYE',
    'UIF (Employee)',
    'UIF (Employer)',
    'Net Pay',
  ].join(',');

  const escape = (v: string | number | null | undefined) => {
    const s = String(v ?? '');
    return s.includes(',') || s.includes('"') ? `"${s.replace(/"/g, '""')}"` : s;
  };

  const lines = certs.map(c =>
    [
      c.certificate_number,
      c.employee_number,
      escape(c.last_name),
      escape(c.first_name),
      c.id_number ?? '',
      c.tax_number ?? '',
      c.total_gross_income,
      c.total_paye,
      c.total_uif_employee,
      c.total_uif_employer,
      c.total_net_pay,
    ].join(',')
  );

  const blob = new Blob([[header, ...lines].join('\r\n')], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `IRP5_Certificates_${taxYear}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

