  invoice_date: string;
  due_date: string | null;
  status: string;
  currency_code: string;
  subtotal: number;
  tax_amount: number;
  total_amount: number;
  amount_paid: number;
  notes: string | null;
  customer_name: string;
  company_name: string;
  company_logo_url: string | null;
  portal_viewed_at: string | null;
  items: PortalInvoiceLineItem[];
