/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Customer Payment Service
 */

import { sql, fmtDate, withTransaction } from '@/lib/neon';
import { randomUUID } from 'crypto';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type {
  CustomerPayment,
  CustomerPaymentAllocation,
  CustomerPaymentCreateInput,
  CustomerPaymentStatus,
} from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

type Row = Record<string, unknown>;

interface PaymentFilters {
  status?: CustomerPaymentStatus;
  clientId?: string;
  limit?: number;
  offset?: number;
}

export async function getCustomerPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: CustomerPayment[];
  total: number;
}> {
  try {
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Record<string, unknown>[];
    let countRows: Record<string, unknown>[];

    if (filters?.clientId) {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.client_id = ${filters.clientId}::UUID AND cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM customer_payments WHERE client_id = ${filters.clientId}::UUID AND company_id = ${companyId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.status = ${filters.status} AND cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM customer_payments WHERE status = ${filters.status} AND company_id = ${companyId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_payments WHERE company_id = ${companyId}`) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get customer payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCustomerPaymentById(companyId: string, 
  id: string
): Promise<(CustomerPayment & { allocations: CustomerPaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT cp.*, c.name AS client_name
      FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
      WHERE cp.id = ${id} AND cp.company_id = ${companyId}
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT cpa.*, ci.invoice_number
      FROM customer_payment_allocations cpa
      LEFT JOIN customer_invoices ci ON ci.id = cpa.invoice_id
      WHERE cpa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createCustomerPayment(companyId: string, 
  input: CustomerPaymentCreateInput,
  userId: string
): Promise<CustomerPayment> {
  try {
    // Validate allocations against invoice balances
    for (const alloc of input.allocations) {
      const invRows = (await sql`
        SELECT total_amount, amount_paid FROM customer_invoices WHERE id = ${alloc.invoiceId}::UUID
      `) as Row[];
      if (invRows.length === 0) throw new Error(`Invoice ${alloc.invoiceId} not found`);
      const balance = Number(invRows[0]!.total_amount) - Number(invRows[0]!.amount_paid);
      if (alloc.amount > balance + 0.01) {
        throw new Error(`Allocation R${alloc.amount.toFixed(2)} exceeds invoice balance R${balance.toFixed(2)}`);
      }
    }

    const totalAllocated = input.allocations.reduce((s, a) => s + a.amount, 0);
    if (Math.abs(totalAllocated - input.totalAmount) > 0.01) {
      throw new Error(`Allocations total R${totalAllocated.toFixed(2)} does not match payment R${input.totalAmount.toFixed(2)}`);
    }

    // Pre-generate UUID so all queries can be batched atomically via HTTP transaction
    const paymentId = randomUUID();

    await sql.transaction((tx) => [
      tx`
        INSERT INTO customer_payments (
          id, company_id, client_id, payment_date, total_amount, payment_method,
          bank_reference, bank_account_id, description, project_id, created_by
        ) VALUES (
          ${paymentId}::UUID, ${companyId}::UUID, ${input.clientId}::UUID, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankReference || null},
          ${input.bankAccountId || null}, ${input.description || null},
          ${input.projectId || null}, ${userId}::UUID
        )
      `,
      ...input.allocations.map(alloc =>
        tx`
          INSERT INTO customer_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `
      ),
    ] as ReturnType<typeof tx>[]);

    const paymentRows = (await sql`SELECT cp.*, c.name AS client_name FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id WHERE cp.id = ${paymentId}::UUID`) as Row[];
    const paymentRow = paymentRows[0]!;

    log.info('Created customer payment', { paymentId, totalAmount: input.totalAmount }, 'accounting');
    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create customer payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function confirmCustomerPayment(companyId: string, 
  id: string,
  userId: string
): Promise<CustomerPayment> {
  try {
    const payment = await getCustomerPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot confirm payment with status: ${payment.status}`);

    // Auto-post GL: DR Bank, CR Accounts Receivable
    const arAccount = await getSystemAccount('receivable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT id FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');
    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      { glAccountId: String(bankAccount.id), debit: payment.totalAmount, credit: 0,
        description: `Customer payment ${payment.paymentNumber}` },
      { glAccountId: arAccount.id, debit: 0, credit: payment.totalAmount,
        description: `Customer payment ${payment.paymentNumber}` },
    ];

    const je = await createJournalEntry(companyId, {
      entryDate: payment.paymentDate,
      description: `Customer payment ${payment.paymentNumber}`,
      source: 'auto_payment',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    // Update invoice balances and mark payment confirmed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}::UUID
        `;
        await tx`
          UPDATE customer_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END, paid_at = CASE WHEN (total_amount - amount_paid) <= 0.01 THEN NOW() ELSE paid_at END
          WHERE id = ${alloc.invoiceId}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE customer_payments
        SET status = 'confirmed', confirmed_by = ${userId}::UUID, confirmed_at = NOW(),
            gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Confirmed customer payment', { id, journalEntryId: je.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to confirm customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCustomerPayment(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CustomerPayment> {
  try {
    const payment = await getCustomerPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'confirmed') {
      throw new Error(`Cannot cancel payment with status: ${payment.status}`);
    }

    // Reverse GL journal entry
    if (payment.glJournalEntryId) {
      await reverseJournalEntry(companyId, payment.glJournalEntryId, userId);
    }

    // Reverse invoice balances + cancel payment atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE customer_invoices
          SET amount_paid = GREATEST(0, amount_paid - ${alloc.amountAllocated}),
              status = CASE
                WHEN GREATEST(0, amount_paid - ${alloc.amountAllocated}) <= 0.01 THEN 'approved'
                WHEN GREATEST(0, amount_paid - ${alloc.amountAllocated}) < total_amount THEN 'partially_paid'
                ELSE status
              END,
              paid_at = CASE WHEN GREATEST(0, amount_paid - ${alloc.amountAllocated}) <= 0.01 THEN NULL ELSE paid_at END
          WHERE id = ${alloc.invoiceId}::UUID AND company_id = ${companyId}
        `;
      }

      // Note: customer_payments has no cancelled_by/cancelled_at/cancel_reason columns yet.
      // Store cancellation metadata in description field until a migration adds them.
      const cancelNote = reason ? ` [CANCELLED: ${reason}]` : ' [CANCELLED]';
      return (await tx`
        UPDATE customer_payments
        SET status = 'cancelled',
            description = COALESCE(description, '') || ${cancelNote}
        WHERE id = ${id} AND company_id = ${companyId} RETURNING *
      `) as Row[];
    }) as Row[];

    log.info('Cancelled customer payment', { id, reason }, 'accounting');
    return mapPaymentRow(updated[0]!);
  } catch (err) {
    log.error('Failed to cancel customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function postCustomerInvoiceToGL(companyId: string, invoiceId: string, userId: string): Promise<string> {
  try {
    const invRows = (await sql`
      SELECT ci.*, c.name AS client_name
      FROM customer_invoices ci LEFT JOIN customers c ON c.id = ci.client_id
      WHERE ci.id = ${invoiceId}::UUID
    `) as Row[];
    if (invRows.length === 0) throw new Error(`Invoice ${invoiceId} not found`);
    const inv = invRows[0]!;

    if (inv.gl_journal_entry_id) return String(inv.gl_journal_entry_id);

    const arAccount = await getSystemAccount('receivable');
    const revenueAccount = await getSystemAccount('default_revenue');
    const vatAccount = await getSystemAccount('vat_output');

    const lines: JournalLineInput[] = [
      { glAccountId: arAccount.id, debit: Number(inv.total_amount), credit: 0,
        description: `AR: ${inv.invoice_number}` },
      { glAccountId: revenueAccount.id, debit: 0, credit: Number(inv.subtotal),
        description: `Revenue: ${inv.invoice_number}` },
    ];

    if (Number(inv.tax_amount) > 0) {
      lines.push({
        glAccountId: vatAccount.id, debit: 0, credit: Number(inv.tax_amount),
        description: `VAT Output: ${inv.invoice_number}`,
      });
    }

    const je = await createJournalEntry(companyId, {
      entryDate: String(inv.invoice_date),
      description: `Customer invoice ${inv.invoice_number}`,
      source: 'auto_invoice',
      sourceDocumentId: invoiceId,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    await sql`UPDATE customer_invoices SET gl_journal_entry_id = ${je.id}::UUID WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID`;

    log.info('Posted customer invoice to GL', { invoiceId, journalEntryId: je.id }, 'accounting');
    return je.id;
  } catch (err) {
    log.error('Failed to post customer invoice to GL', { invoiceId, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): CustomerPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    clientId: String(row.client_id),
    paymentDate: fmtDate(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as CustomerPayment['paymentMethod'],
    bankReference: row.bank_reference ? String(row.bank_reference) : undefined,
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as CustomerPaymentStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    confirmedBy: row.confirmed_by ? String(row.confirmed_by) : undefined,
    confirmedAt: row.confirmed_at ? String(row.confirmed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    allocatedAmount: row.allocated_amount !== undefined ? Number(row.allocated_amount) : 0,
  };
}

function mapAllocationRow(row: Row): CustomerPaymentAllocation & { amount: number } {
  const amt = Number(row.amount_allocated || row.amount || 0);
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: amt,
    amount: amt,
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Allocation Service — Sage Process Bank equivalent (allocate, split, reverse)
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import { mapTxRow } from './bankTransactionQueryService';
import type { BankTransaction } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

type Row = Record<string, unknown>;

export type AllocationType = 'account' | 'supplier' | 'customer';

export interface SplitLine {
  contraAccountId: string;
  amount: number;
  description?: string;
  vatCode?: string;
}

// ── Allocate ──────────────────────────────────────────────────────────────────

/**
 * Allocate a bank transaction — Sage Process Bank equivalent.
 * Supports: account (GL), supplier (AP payment), customer (AR receipt).
 */
export async function allocateTransaction(
  companyId: string, bankTxId: string, contraAccountId: string | null, userId: string,
  description?: string, allocType: AllocationType = 'account', entityId?: string,
  vatCode?: string, cc1Id?: string, cc2Id?: string, buId?: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;
  if (tx.status !== 'imported') throw new Error(`Transaction already ${tx.status} — cannot allocate`);

  const totalAmount = Math.abs(Number(tx.amount));
  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? (tx.transaction_date.toISOString().split('T')[0] ?? '')
    : (String(tx.transaction_date).split('T')[0] ?? '');
  const isSpent = Number(tx.amount) < 0;

  const hasVat = vatCode === 'standard';
  const vatRate = hasVat ? 15 : 0;
  const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
  const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
  const vatAccountKey = isSpent ? 'vat_input' as const : 'vat_output' as const;
  const mapVatType = vatCode === 'standard' ? 'standard' as const
    : vatCode === 'zero_rated' ? 'zero_rated' as const
    : vatCode === 'exempt' ? 'exempt' as const : undefined;

  let lines: JournalLineInput[];
  let source: import('../types/gl.types').GLEntrySource;
  let entryDesc = '';
  let allocEntityName: string | null = null;

  if (allocType === 'supplier' && entityId) {
    const apAccountId = await getSystemAccountId('payable');
    const supRows = (await sql`SELECT name FROM suppliers WHERE id = ${entityId}::UUID`) as Row[];
    const supName = supRows.length > 0 ? String(supRows[0]!.name) : `Supplier #${entityId}`;
    allocEntityName = supName;
    entryDesc = description || `Payment to ${supName}`;
    source = 'auto_supplier_payment';
    lines = [
      { glAccountId: apAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
      { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
    ];
    if (hasVat) {
      const vatAcctId = await getSystemAccountId(vatAccountKey);
      lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else if (allocType === 'customer' && entityId) {
    const arAccountId = await getSystemAccountId('receivable');
    const custRows = (await sql`SELECT name FROM customers WHERE id = ${entityId}::UUID`) as Row[];
    const custName = custRows.length > 0 ? String(custRows[0]!.name) : `Customer #${entityId}`;
    allocEntityName = custName;
    entryDesc = description || `Receipt from ${custName}`;
    source = 'auto_payment';
    lines = [
      { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
      { glAccountId: arAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
    ];
    if (hasVat) {
      const vatAcctId = await getSystemAccountId(vatAccountKey);
      lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else {
    if (!contraAccountId) throw new Error('contraAccountId is required for account allocation');
    const acctRows = (await sql`SELECT account_code, account_name FROM gl_accounts WHERE id = ${contraAccountId}::UUID`) as Row[];
    allocEntityName = acctRows.length > 0 ? `${String(acctRows[0]!.account_code)} ${String(acctRows[0]!.account_name)}` : null;
    entryDesc = description || String(tx.description || 'Bank allocation');
    source = 'auto_bank_recon';
    if (!isSpent) {
      lines = [
        { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
        { glAccountId: contraAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
      ];
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
    } else {
      lines = [{ glAccountId: contraAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType }];
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        lines.push({ glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
      lines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
    }
  }

  const linesWithDims = lines.map(l =>
    l.glAccountId === bankAccountId ? l : { ...l, costCenterId: cc1Id || l.costCenterId, buId: buId || l.buId }
  );

  const je = await createJournalEntry(companyId, {
    entryDate: txDate, description: entryDesc, source, sourceDocumentId: bankTxId, lines: linesWithDims,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID LIMIT 1`) as Row[];
  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated', matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = ${allocType}, allocated_entity_name = ${allocEntityName},
          cc1_id = ${cc1Id || null}::UUID, cc2_id = ${cc2Id || null}::UUID,
          bu_id = ${buId || null}::UUID, updated_at = NOW()
      WHERE id = ${bankTxId}::UUID`;
  }

  if (allocType === 'customer' && entityId) {
    const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    let paymentUserId: string | null = userId;
    if (!uuidPattern.test(userId)) {
      const fallback = (await sql`SELECT id FROM users WHERE id::TEXT ~ '^[0-9a-f]{8}-' LIMIT 1`) as Row[];
      paymentUserId = fallback.length > 0 ? String(fallback[0]!.id) : null;
    }
    if (paymentUserId) {
      await sql`
        INSERT INTO customer_payments (
          company_id, client_id, payment_date, total_amount, payment_method,
          bank_reference, bank_account_id, description, status,
          gl_journal_entry_id, created_by, confirmed_by, confirmed_at
        ) VALUES (
          ${companyId}::UUID, ${entityId}::UUID, ${txDate}, ${totalAmount}, 'eft',
          ${tx.reference || tx.bank_reference || tx.description || null},
          ${bankAccountId}::UUID, ${entryDesc}, 'confirmed',
          ${je.id}::UUID, ${paymentUserId}::UUID, ${paymentUserId}::UUID, NOW()
        )`;
    }
  }

  log.info('Allocated bank transaction', { bankTxId, journalEntryId: je.id, allocType, entityId, contraAccountId }, 'accounting');
  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Split Allocate ────────────────────────────────────────────────────────────

export async function splitAllocateTransaction(
  companyId: string, bankTxId: string, lines: SplitLine[], userId: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;
  if (tx.status !== 'imported') throw new Error(`Transaction already ${tx.status} — cannot split allocate`);
  if (!lines || lines.length === 0) throw new Error('At least one split line is required');

  const totalAmount = Math.abs(Number(tx.amount));
  const linesTotal = lines.reduce((sum, l) => sum + Number(l.amount), 0);
  if (Math.abs(linesTotal - totalAmount) > 0.01) {
    throw new Error(`Split lines total R${linesTotal.toFixed(2)} does not equal transaction amount R${totalAmount.toFixed(2)}`);
  }

  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? (tx.transaction_date.toISOString().split('T')[0] ?? '')
    : (String(tx.transaction_date).split('T')[0] ?? '');
  const isSpent = Number(tx.amount) < 0;
  const entryDesc = String(tx.description || 'Split bank allocation');
  const journalLines: JournalLineInput[] = [];

  for (const line of lines) {
    const lineAmount = Number(line.amount);
    const hasVat = line.vatCode === 'standard';
    const netAmount = hasVat ? Math.round((lineAmount * 100 / 115) * 100) / 100 : lineAmount;
    const vatAmount = hasVat ? Math.round((lineAmount - netAmount) * 100) / 100 : 0;
    const vatAccountKey = isSpent ? 'vat_input' as const : 'vat_output' as const;
    const lineDesc = line.description || entryDesc;
    const mapVatType = line.vatCode === 'standard' ? 'standard' as const
      : line.vatCode === 'zero_rated' ? 'zero_rated' as const
      : line.vatCode === 'exempt' ? 'exempt' as const : undefined;
    if (isSpent) {
      journalLines.push({ glAccountId: line.contraAccountId, debit: netAmount, credit: 0, description: lineDesc, vatType: mapVatType });
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        journalLines.push({ glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: 'VAT @ 15%', vatType: 'standard' });
      }
    } else {
      journalLines.push({ glAccountId: line.contraAccountId, debit: 0, credit: netAmount, description: lineDesc, vatType: mapVatType });
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        journalLines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: 'VAT @ 15%', vatType: 'standard' });
      }
    }
  }

  if (isSpent) {
    journalLines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
  } else {
    journalLines.unshift({ glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc });
  }

  const je = await createJournalEntry(companyId, {
    entryDate: txDate, description: entryDesc, source: 'auto_bank_recon', sourceDocumentId: bankTxId, lines: journalLines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID LIMIT 1`) as Row[];
  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated', matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = 'account', allocated_entity_name = 'Split allocation', updated_at = NOW()
      WHERE id = ${bankTxId}::UUID`;
  }

  log.info('Split-allocated bank transaction', { bankTxId, journalEntryId: je.id, lineCount: lines.length }, 'accounting');
  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Reverse Reconciled ────────────────────────────────────────────────────────

export async function reverseReconciledTransaction(
  companyId: string, bankTxId: string, userId: string
): Promise<void> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  const tx = txRows[0];
  if (!tx) throw new Error('Transaction not found');
  if (tx.status !== 'allocated' && tx.status !== 'matched' && tx.status !== 'reconciled') {
    throw new Error('Can only reverse allocated, matched, or reconciled transactions');
  }
  if (tx.matched_journal_line_id) {
    const jlRows = (await sql`
      SELECT journal_entry_id FROM gl_journal_lines WHERE id = ${tx.matched_journal_line_id}::UUID`) as Row[];
    if (jlRows.length > 0 && jlRows[0]!.journal_entry_id) {
      const { reverseJournalEntry } = await import('./journalEntryService');
      try {
        await reverseJournalEntry(companyId, String(jlRows[0]!.journal_entry_id), userId);
      } catch (e) {
        throw new Error(`Cannot reverse: ${e instanceof Error ? e.message : 'Journal reversal failed'}`);
      }
    }
  }
  await sql`
    UPDATE bank_transactions
    SET status = 'imported', matched_journal_line_id = NULL, reconciliation_id = NULL,
        linked_po_id = NULL, linked_asset_id = NULL, linked_fleet_fuel_id = NULL,
        linked_fleet_service_id = NULL, allocation_type = NULL, allocated_entity_name = NULL,
        updated_at = NOW()
    WHERE id = ${bankTxId}::UUID`;
  log.info('Reversed reconciled bank transaction', { bankTxId, userId }, 'accounting');
}

/**
 * Recurring Transactions Page — WS-8.4
 * Manage recurring journal/invoice templates and execute them on demand.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { useCompany } from '@/contexts/CompanyContext';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import { RefreshCw, Plus, Play, Trash2, Edit2, Loader2, AlertCircle, CheckCircle, XCircle, Calendar } from 'lucide-react';
import {
  RecurringModal, buildTemplateInput,
  type TemplateFormState, ENTITY_LABELS, FREQ_LABELS,
} from '@/components/accounting/recurring-transactions/RecurringModal';
import type { RecurringTemplate } from '@/modules/accounting/services/recurringTransactionService';

const BTN_PRIMARY = 'inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium';
const BTN_GHOST = 'inline-flex items-center gap-2 px-3 py-1.5 text-sm text-[var(--ff-text-secondary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-primary)] transition-colors';

type ExecResult = { entityType: string; entityId: string; posted: boolean } | 'error';

const DEFAULT_FORM: TemplateFormState = {
  name: '', entityType: 'journal_entry', frequency: 'monthly',
  nextRunDate: new Date().toISOString().split('T')[0]!,
  isActive: true, autoPost: false, templateData: '{}',
};

export default function RecurringTransactionsPage() {
  const { activeCompany } = useCompany();
  const [isMounted, setIsMounted] = useState(false);
  const [templates, setTemplates] = useState<RecurringTemplate[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [form, setForm] = useState<TemplateFormState>(DEFAULT_FORM);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [executing, setExecuting] = useState<string | null>(null);
  const [execResults, setExecResults] = useState<Record<string, ExecResult>>({});

  useEffect(() => { setIsMounted(true); }, []);

  const fetchTemplates = useCallback(async () => {
    if (!activeCompany) return;
    setLoading(true);
    setError(null);
    try {
      const res = await apiFetch('/api/accounting/recurring-transactions');
      const json = await res.json() as { data: RecurringTemplate[] };
      setTemplates(json.data);
    } catch (err) {
      log.error('Failed to fetch recurring templates', { error: err }, 'recurring-page');
      setError('Failed to load templates');
    } finally {
      setLoading(false);
    }
  }, [activeCompany]);

  useEffect(() => { if (isMounted) void fetchTemplates(); }, [isMounted, fetchTemplates]);

  const openCreate = () => { setEditId(null); setForm(DEFAULT_FORM); setFormError(null); setShowModal(true); };

  const openEdit = (t: RecurringTemplate) => {
    setEditId(t.id);
    setForm({
      name: t.name, entityType: t.entityType, frequency: t.frequency,
      nextRunDate: t.nextRunDate ?? new Date().toISOString().split('T')[0]!,
      isActive: t.isActive, autoPost: t.autoPost,
      templateData: JSON.stringify(t.templateData, null, 2),
    });
    setFormError(null);
    setShowModal(true);
  };

  const handleSave = async () => {
    setFormError(null);
    if (!form.name || !form.frequency || !form.entityType) {
      setFormError('Name, entity type, and frequency are required');
      return;
    }
    let parsed: Record<string, unknown>;
    try { parsed = JSON.parse(form.templateData || '{}') as Record<string, unknown>; }
    catch { setFormError('Template Data must be valid JSON'); return; }
    void parsed;
    setSaving(true);
    try {
      const body = { ...buildTemplateInput(form), ...(editId ? { id: editId } : {}) };
      await apiFetch('/api/accounting/recurring-transactions', {
        method: editId ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      setShowModal(false);
      await fetchTemplates();
    } catch (err) {
      log.error('Failed to save recurring template', { error: err }, 'recurring-page');
      setFormError('Failed to save template');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this recurring template?')) return;
    try {
      await apiFetch(`/api/accounting/recurring-transactions?id=${id}`, { method: 'DELETE' });
      await fetchTemplates();
    } catch (err) {
      log.error('Failed to delete template', { error: err }, 'recurring-page');
    }
  };

  const handleRunNow = async (id: string) => {
    setExecuting(id);
    try {
      const res = await apiFetch('/api/accounting/recurring-transactions-execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ templateId: id }),
      });
      const json = await res.json() as { data: { entityType: string; entityId: string; posted: boolean } };
      setExecResults(prev => ({ ...prev, [id]: json.data }));
      await fetchTemplates();
    } catch (err) {
      log.error('Failed to execute recurring template', { error: err }, 'recurring-page');
      setExecResults(prev => ({ ...prev, [id]: 'error' }));
    } finally {
      setExecuting(null);
    }
  };

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10"><RefreshCw className="h-6 w-6 text-teal-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Recurring Transactions</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Automate repeating journals, invoices, and more</p>
              </div>
            </div>
            <button onClick={openCreate} className={BTN_PRIMARY}><Plus className="h-4 w-4" /> New Template</button>
          </div>
        </div>

        <div className="px-6 py-6">
          {error && (
            <div className="flex items-center gap-2 p-3 mb-4 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}
          {loading ? (
            <div className="flex justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-teal-500" /></div>
          ) : templates.length === 0 ? (
            <div className="text-center py-16 text-[var(--ff-text-secondary)]">
              <Calendar className="h-12 w-12 mx-auto mb-3 opacity-30" />
              <p className="font-medium">No recurring templates</p>
              <p className="text-sm mt-1">Create a template to automate repeating transactions.</p>
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="border-b border-[var(--ff-border-light)]">
                    <tr className="text-xs text-[var(--ff-text-secondary)]">
                      <th className="text-left px-5 py-3">Name</th>
                      <th className="text-left px-4 py-3">Type</th>
                      <th className="text-left px-4 py-3">Frequency</th>
                      <th className="text-left px-4 py-3">Next Run</th>
                      <th className="text-left px-4 py-3">Last Run</th>
                      <th className="text-left px-4 py-3">Status</th>
                      <th className="text-right px-5 py-3">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {templates.map(t => {
                      const res = execResults[t.id];
                      return (
                        <tr key={t.id} className="border-b border-[var(--ff-border-light)] last:border-0 hover:bg-[var(--ff-bg-primary)] transition-colors">
                          <td className="px-5 py-3 font-medium text-[var(--ff-text-primary)]">{t.name}</td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{ENTITY_LABELS[t.entityType]}</td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{FREQ_LABELS[t.frequency]}</td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {t.nextRunDate ? new Date(t.nextRunDate).toLocaleDateString('en-ZA') : '—'}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {t.lastRunDate ? new Date(t.lastRunDate).toLocaleDateString('en-ZA') : '—'}
                          </td>
                          <td className="px-4 py-3">
                            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${t.isActive ? 'bg-green-500/15 text-green-400' : 'bg-gray-500/15 text-gray-400'}`}>
                              {t.isActive ? 'Active' : 'Paused'}
                            </span>
                            {t.autoPost && (
                              <span className="ml-1.5 text-xs px-2 py-0.5 rounded-full bg-blue-500/15 text-blue-400 font-medium">Auto-post</span>
                            )}
                          </td>
                          <td className="px-5 py-3">
                            <div className="flex items-center justify-end gap-2">
                              {res && res !== 'error' && (
                                <span className="flex items-center gap-1 text-xs text-green-400"><CheckCircle className="h-3.5 w-3.5" /> Created</span>
                              )}
                              {res === 'error' && (
                                <span className="flex items-center gap-1 text-xs text-red-400"><XCircle className="h-3.5 w-3.5" /> Failed</span>
                              )}
                              <button onClick={() => void handleRunNow(t.id)} disabled={executing === t.id || !t.isActive} className={BTN_GHOST}>
                                {executing === t.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Play className="h-3.5 w-3.5" />}
                                Run Now
                              </button>
                              <button onClick={() => openEdit(t)} className={BTN_GHOST}><Edit2 className="h-3.5 w-3.5" /></button>
                              <button onClick={() => void handleDelete(t.id)} className="p-1.5 text-red-400 hover:bg-red-500/10 rounded-lg transition-colors">
                                <Trash2 className="h-4 w-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>

      {showModal && (
        <RecurringModal
          form={form}
          isEdit={!!editId}
          saving={saving}
          formError={formError}
          onChange={updates => setForm(prev => ({ ...prev, ...updates }))}
          onSave={() => void handleSave()}
          onClose={() => setShowModal(false)}
        />
      )}
    </AppLayout>
  );
}

