/**
 * Recurring Invoice Service
 * Phase 1 Sage Alignment: Auto-generate customer invoices on schedule
 */

import { sql, withTransaction, fmtDate } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  RecurringInvoice,
  RecurringInvoiceCreateInput,
} from '../types/ar.types';

type Row = Record<string, unknown>;

export async function getRecurringInvoices(companyId: string, filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringInvoice[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.client_id = ${filters.clientId}::UUID
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices
      WHERE company_id = ${companyId} AND client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.status = ${filters.status}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringInvoice(companyId: string, 
  input: RecurringInvoiceCreateInput,
  userId: string
): Promise<RecurringInvoice> {
  const taxRate = input.taxRate ?? 15;
  const subtotal = input.lineItems.reduce(
    (s, li) => s + li.quantity * li.unitPrice, 0
  );
  const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const rows = (await sql`
    INSERT INTO recurring_invoices (
      company_id, template_name, client_id, project_id, frequency, next_run_date,
      end_date, description, line_items, subtotal, tax_rate, tax_amount,
      total_amount, payment_terms, created_by
    ) VALUES (
      ${companyId}, ${input.templateName}, ${input.clientId}::UUID,
      ${input.projectId || null}, ${input.frequency}, ${input.nextRunDate},
      ${input.endDate || null}, ${input.description || null},
      ${JSON.stringify(input.lineItems)}::JSONB, ${subtotal}, ${taxRate},
      ${taxAmount}, ${totalAmount}, ${input.paymentTerms || '30 days'}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring invoice', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_invoices SET status = ${status} WHERE id = ${id} AND company_id = ${companyId}`;
  log.info('Updated recurring invoice status', { id, status }, 'accounting');
}

export async function generateInvoiceFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_invoices WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!rows[0]) throw new Error('Recurring invoice not found');
  const ri = rows[0];
  if (ri.status !== 'active') throw new Error('Recurring invoice is not active');

  const nextDate = advanceDate(String(ri.next_run_date), String(ri.frequency));
  const endDate = ri.end_date ? String(ri.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  // Generate next invoice number
  const numRows = (await sql`
    SELECT MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)) AS max_num
    FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number LIKE 'INV-%'
  `) as Row[];
  const nextNum = (Number(numRows[0]?.max_num) || 0) + 1;
  const invoiceNumber = `INV-${String(nextNum).padStart(5, '0')}`;

  const invoiceId = await withTransaction(async (tx) => {
    const inv = (await tx`
      INSERT INTO customer_invoices (
        company_id, invoice_number, client_id, customer_id, project_id,
        invoice_date, due_date, subtotal, tax_amount, total_amount,
        status, notes, created_by
      ) VALUES (
        ${companyId}::UUID, ${invoiceNumber}, ${ri.client_id}::UUID, ${ri.client_id}::UUID,
        ${ri.project_id || null},
        CURRENT_DATE, CURRENT_DATE + INTERVAL '30 days',
        ${Number(ri.subtotal)}, ${Number(ri.tax_amount)}, ${Number(ri.total_amount)},
        'approved', ${ri.description || ri.template_name}, ${userId}::UUID
      ) RETURNING id
    `) as Row[];

    await tx`
      UPDATE recurring_invoices
      SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
          run_count = run_count + 1, status = ${newStatus}
      WHERE id = ${id}
    `;

    return String(inv[0]!.id);
  });

  log.info('Generated invoice from recurring', { recurringId: id, invoiceId }, 'accounting');
  return invoiceId;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringInvoice {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    clientId: String(row.client_id),
    projectId: row.project_id ? String(row.project_id) : undefined,
    frequency: String(row.frequency) as RecurringInvoice['frequency'],
    nextRunDate: fmtDate(row.next_run_date),
    endDate: row.end_date ? fmtDate(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? fmtDate(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringInvoice['status'],
    description: row.description ? String(row.description) : undefined,
    lineItems: Array.isArray(row.line_items) ? row.line_items as RecurringInvoice['lineItems'] : JSON.parse(typeof row.line_items === 'string' ? row.line_items : '[]'),
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

import { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

/**
 * Standard API Response Types
 */
export interface ApiSuccessResponse<T = any> {
  success: true;
  data: T;
  message?: string;
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any;
  };
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiPaginatedResponse<T = any> extends ApiSuccessResponse<T[]> {
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

export type ApiResponse<T = any> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Standard error codes
 */
export enum ErrorCode {
  // Client errors (400-499)
  BAD_REQUEST = 'BAD_REQUEST',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  METHOD_NOT_ALLOWED = 'METHOD_NOT_ALLOWED',
  CONFLICT = 'CONFLICT',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  RATE_LIMIT = 'RATE_LIMIT',
  PAYLOAD_TOO_LARGE = 'PAYLOAD_TOO_LARGE',

  // Server errors (500-599)
  INTERNAL_ERROR = 'INTERNAL_ERROR',
  DATABASE_ERROR = 'DATABASE_ERROR',
  SERVICE_UNAVAILABLE = 'SERVICE_UNAVAILABLE',
  GATEWAY_TIMEOUT = 'GATEWAY_TIMEOUT',

  // Business logic errors
  BUSINESS_RULE_VIOLATION = 'BUSINESS_RULE_VIOLATION',
  INSUFFICIENT_PERMISSIONS = 'INSUFFICIENT_PERMISSIONS',
  RESOURCE_LOCKED = 'RESOURCE_LOCKED',
  DEPENDENCY_ERROR = 'DEPENDENCY_ERROR',
}

/**
 * HTTP status code mapping
 */
const STATUS_CODE_MAP: Record<ErrorCode, number> = {
  // Client errors
  [ErrorCode.BAD_REQUEST]: 400,
  [ErrorCode.UNAUTHORIZED]: 401,
  [ErrorCode.FORBIDDEN]: 403,
  [ErrorCode.NOT_FOUND]: 404,
  [ErrorCode.METHOD_NOT_ALLOWED]: 405,
  [ErrorCode.CONFLICT]: 409,
  [ErrorCode.VALIDATION_ERROR]: 422,
  [ErrorCode.RATE_LIMIT]: 429,
  [ErrorCode.PAYLOAD_TOO_LARGE]: 413,

  // Server errors
  [ErrorCode.INTERNAL_ERROR]: 500,
  [ErrorCode.DATABASE_ERROR]: 500,
  [ErrorCode.SERVICE_UNAVAILABLE]: 503,
  [ErrorCode.GATEWAY_TIMEOUT]: 504,

  // Business logic errors (usually 400 or 422)
  [ErrorCode.BUSINESS_RULE_VIOLATION]: 422,
  [ErrorCode.INSUFFICIENT_PERMISSIONS]: 403,
  [ErrorCode.RESOURCE_LOCKED]: 423,
  [ErrorCode.DEPENDENCY_ERROR]: 424,
};

/**
 * API Response Helper Class
 */
export class ApiResponseHelper {
  private static generateMeta(additionalMeta?: Record<string, any>) {
    return {
      timestamp: new Date().toISOString(),
      ...additionalMeta,
    };
  }

  /**
   * Send success response
   */
  static success<T>(
    res: NextApiResponse,
    data: T,
    message?: string,
    statusCode = 200,
    meta?: Record<string, any>
  ): void {
    const response: ApiSuccessResponse<T> = {
      success: true,
      data,
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send created response (201)
   */
  static created<T>(
    res: NextApiResponse,
    data: T,
    message = 'Resource created successfully',
    meta?: Record<string, any>
  ): void {
    this.success(res, data, message, 201, meta);
  }

  /**
   * Send no content response (204)
   */
  static noContent(res: NextApiResponse): void {
    res.status(204).end();
  }

  /**
   * Send paginated response
   */
  static paginated<T>(
    res: NextApiResponse,
    data: T[],
    pagination: {
      page: number;
      pageSize: number;
      total: number;
    },
    message?: string,
    meta?: Record<string, any>
  ): void {
    const totalPages = Math.ceil(pagination.total / pagination.pageSize);

    const response: ApiPaginatedResponse<T> = {
      success: true,
      data,
      pagination: {
        ...pagination,
        totalPages,
      },
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(200).json(response);
  }

  /**
   * Send error response
   */
  static error(
    res: NextApiResponse,
    code: ErrorCode,
    message: string,
    details?: any,
    meta?: Record<string, any>
  ): void {
    const statusCode = STATUS_CODE_MAP[code] || 500;

    const response: ApiErrorResponse = {
      success: false,
      error: {
        code,
        message,
        ...(details && { details }),
      },
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send bad request error response (400)
   */
  static badRequest(
    res: NextApiResponse,
    message: string,
    details?: any
  ): void {
    this.error(res, ErrorCode.BAD_REQUEST, message, details);
  }

  /**
   * Send validation error response
   */
  static validationError(
    res: NextApiResponse,
    errors: Record<string, string | string[]>,
    message = 'Validation failed'
  ): void {
    this.error(res, ErrorCode.VALIDATION_ERROR, message, errors);
  }

  /**
   * Send not found error response
   */
  static notFound(
    res: NextApiResponse,
    resource: string,
    identifier?: string | number
  ): void {
    const message = identifier
      ? `${resource} with identifier '${identifier}' not found`
      : `${resource} not found`;

    this.error(res, ErrorCode.NOT_FOUND, message);
  }

  /**
   * Send unauthorized error response
   */
  static unauthorized(
    res: NextApiResponse,
    message = 'Authentication required'
  ): void {
    this.error(res, ErrorCode.UNAUTHORIZED, message);
  }

  /**
   * Send forbidden error response
   */
  static forbidden(
    res: NextApiResponse,
    message = 'You do not have permission to perform this action'
  ): void {
    this.error(res, ErrorCode.FORBIDDEN, message);
  }

  /**
   * Send method not allowed error response
   */
  static methodNotAllowed(
    res: NextApiResponse,
    method: string,
    allowedMethods: string[]
  ): void {
    res.setHeader('Allow', allowedMethods.join(', '));
    this.error(
      res,
      ErrorCode.METHOD_NOT_ALLOWED,
      `Method ${method} not allowed. Allowed methods: ${allowedMethods.join(', ')}`
    );
  }

  /**
   * Send internal server error response
   */
  static internalError(
    res: NextApiResponse,
    error: Error | unknown,
    detailedMessage?: string
  ): void {
    // Log the actual error for debugging
    log.error('Internal Server Error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'ApiResponse');

    // In production, never expose internal error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const message = isDevelopment
      ? (detailedMessage || 'An internal error occurred')
      : 'An internal error occurred';
    const errorDetails = isDevelopment && error instanceof Error
      ? { stack: error.stack, originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.INTERNAL_ERROR, message, errorDetails);
  }

  /**
   * Send database error response
   */
  static databaseError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'A database error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Database Error', error instanceof Error ? { message: error.message } : { error }, 'ApiResponse');

    // In production, don't expose database error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.DATABASE_ERROR, message, errorDetails);
  }

  /**
   * Handle CORS headers
   */
  static setCorsHeaders(
    res: NextApiResponse,
    origin = '',
    methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    headers = ['Content-Type', 'Authorization']
  ): void {
    const allowedOrigins = [
      'https://app.isaflow.co.za',
      'https://admin.isaflow.co.za',
      'https://isaflow.co.za',
      ...(process.env.NODE_ENV === 'development'
        ? ['http://localhost:3101', 'http://localhost:3004']
        : []),
    ];
    const safeOrigin = origin && allowedOrigins.includes(origin) ? origin : '';
    if (!safeOrigin) return;
    res.setHeader('Access-Control-Allow-Origin', safeOrigin);
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
    res.setHeader('Access-Control-Allow-Headers', headers.join(', '));
  }

  /**
   * Handle OPTIONS request for CORS
   */
  static handleOptions(req: NextApiRequest, res: NextApiResponse): void {
    this.setCorsHeaders(res, req.headers.origin || '');
    res.status(200).end();
  }
}

