/**
 * BundleEditor — manage bundle component lines for an item
 * Shows a table of child items with quantities; allows add/remove/save.
 */
'use client';

import { useState, useEffect, useCallback } from 'react';
import { Plus, Trash2, Save, Loader2, Search } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface ItemOption {
  id: string;
  code: string | null;
  description: string | null;
  unit: string | null;
  selling_price_excl: number | null;
}

interface BundleLineLocal {
  child_item_id: string;
  child_code: string | null;
  child_description: string | null;
  child_unit: string | null;
  child_selling_price_excl: number | null;
  quantity: number;
}

interface Props {
  itemId: string;
  parentDescription?: string;
  onSaved?: () => void;
}

const fmt = (n: number | null | undefined) =>
  n != null
    ? new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(Number(n))
    : '—';

export function BundleEditor({ itemId, parentDescription, onSaved }: Props) {
  const [lines, setLines] = useState<BundleLineLocal[]>([]);
  const [allItems, setAllItems] = useState<ItemOption[]>([]);
  const [search, setSearch] = useState('');
  const [showSearch, setShowSearch] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState(false);

  const loadBundleLines = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch(`/api/accounting/item-bundles?itemId=${itemId}`);
      const json = await res.json() as { data?: BundleLineLocal[] };
      setLines((json.data ?? []) as BundleLineLocal[]);
    } catch {
      setError('Failed to load bundle lines');
    } finally {
      setLoading(false);
    }
  }, [itemId]);

  const loadItems = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/items?active=true');
      const json = await res.json() as { data?: ItemOption[] };
      setAllItems((json.data ?? []).filter((it: ItemOption) => it.id !== itemId));
    } catch {
      setAllItems([]);
    }
  }, [itemId]);

  useEffect(() => {
    void loadBundleLines();
    void loadItems();
  }, [loadBundleLines, loadItems]);

  const filteredItems = allItems.filter((it) => {
    if (!search) return true;
    const s = search.toLowerCase();
    return (
      (it.code ?? '').toLowerCase().includes(s) ||
      (it.description ?? '').toLowerCase().includes(s)
    );
  }).filter((it) => !lines.some((l) => l.child_item_id === it.id));

  const handleAddItem = (item: ItemOption) => {
    setLines((prev) => [
      ...prev,
      {
        child_item_id: item.id,
        child_code: item.code,
