      {error && (
        <p className="text-sm text-red-400 bg-red-500/10 rounded px-3 py-2">{error}</p>
      )}

      {/* Save */}
      <div className="flex items-center gap-3">
        <button
          onClick={handleSave}
          disabled={saving}
          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-sm rounded-lg font-medium transition-colors"
        >
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save Bundle
        </button>
        {saved && (
          <span className="text-sm text-teal-400">Bundle saved successfully</span>
        )}
      </div>
    </div>
  );
}

