/**
 * Financial Years — single period row in the expandable table
 */
import { Lock, LockOpen, RefreshCw, Loader2 } from 'lucide-react';
import type { FiscalPeriod, FiscalPeriodStatus } from '@/modules/accounting/types/gl.types';
