/**
 * Statement Email Service
 * Formats customer account statements as HTML email bodies and sends them.
 * Called by the bulk-send API route.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { sendEmail } from './emailService';
import type { EmailResult } from './emailService';
import { BRAND } from '@/lib/email-templates';

type Row = Record<string, unknown>;

// ─── Types ────────────────────────────────────────────────────────────────────

interface StatementTransaction {
  date: string;
  type: 'invoice' | 'payment' | 'credit_note';
  reference: string;
  debit: number;
  credit: number;
  balance: number;
}

interface StatementPayload {
  customer: { id: string; name: string; email: string | null };
  fromDate: string;
  toDate: string;
  transactions: StatementTransaction[];
  summary: {
    totalInvoiced: number;
    totalPaid: number;
    totalCredits: number;
    balance: number;
  };
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function toISODate(val: unknown): string {
  if (!val) return '1970-01-01';
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? '1970-01-01';
  const s = String(val);
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0] ?? '1970-01-01';
  const d = new Date(s);
  return isNaN(d.getTime()) ? '1970-01-01' : (d.toISOString().split('T')[0] ?? '1970-01-01');
}

const fmtZAR = (n: number): string =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const fmtDate = (d: string): string => {
  const parts = d.split('T')[0]?.split('-') ?? [];
  return parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : d;
};

function escHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ─── Statement Fetcher ────────────────────────────────────────────────────────

export async function fetchStatementData(
  companyId: string,
  customerId: string,
  asAtDate: string
): Promise<StatementPayload | null> {
  const oneYearAgo = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000)
    .toISOString().split('T')[0] as string;

  const customerRows = await sql`
    SELECT id, name, email
    FROM customers
    WHERE id = ${customerId}::UUID AND company_id = ${companyId}::UUID
  ` as Row[];

  if (customerRows.length === 0) return null;
  const cust = customerRows[0]!;

  const invoices = await sql`
    SELECT id, invoice_number, invoice_date, total_amount
    FROM customer_invoices
    WHERE COALESCE(client_id, customer_id) = ${customerId}::UUID
      AND company_id = ${companyId}::UUID
      AND status != 'cancelled'
      AND invoice_date <= ${asAtDate}::DATE
    ORDER BY invoice_date
  ` as Row[];

  const payments = await sql`
    SELECT cp.id, cp.payment_number, cp.payment_date,
      COALESCE(SUM(cpa.amount_allocated), cp.total_amount) AS amount_allocated
    FROM customer_payments cp
    LEFT JOIN customer_payment_allocations cpa ON cpa.payment_id = cp.id
    WHERE cp.client_id = ${customerId}::UUID
      AND cp.company_id = ${companyId}::UUID
      AND cp.status IN ('confirmed', 'reconciled')
      AND cp.payment_date <= ${asAtDate}::DATE
    GROUP BY cp.id, cp.payment_number, cp.payment_date, cp.total_amount
  ` as Row[];

  const creditNotes = await sql`
    SELECT id, credit_note_number, credit_date, total_amount
    FROM credit_notes
    WHERE client_id = ${customerId}::UUID
      AND company_id = ${companyId}::UUID
      AND type = 'customer'
      AND status = 'approved'
      AND credit_date <= ${asAtDate}::DATE
  ` as Row[];

  const transactions: StatementTransaction[] = [];

  for (const inv of invoices) {
    transactions.push({
      date: toISODate(inv.invoice_date),
      type: 'invoice',
      reference: String(inv.invoice_number ?? ''),
      debit: Number(inv.total_amount),
      credit: 0,
      balance: 0,
    });
  }
  for (const pmt of payments) {
    transactions.push({
      date: toISODate(pmt.payment_date),
      type: 'payment',
      reference: String(pmt.payment_number ?? ''),
      debit: 0,
      credit: Number(pmt.amount_allocated),
      balance: 0,
    });
  }
  for (const cn of creditNotes) {
    transactions.push({
      date: toISODate(cn.credit_date),
      type: 'credit_note',
      reference: String(cn.credit_note_number ?? ''),
      debit: 0,
      credit: Number(cn.total_amount),
      balance: 0,
    });
  }

  const typeOrder: Record<string, number> = { invoice: 0, credit_note: 1, payment: 2 };
  transactions.sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
  });

  let running = 0;
  let totalInvoiced = 0;
  let totalPaid = 0;
  let totalCredits = 0;

  for (const txn of transactions) {
    running += txn.debit - txn.credit;
    txn.balance = running;
    totalInvoiced += txn.debit;
    if (txn.type === 'payment') totalPaid += txn.credit;
    if (txn.type === 'credit_note') totalCredits += txn.credit;
  }

  return {
    customer: {
      id: String(cust.id),
      name: String(cust.name),
      email: cust.email ? String(cust.email) : null,
    },
    fromDate: oneYearAgo,
    toDate: asAtDate,
    transactions,
    summary: { totalInvoiced, totalPaid, totalCredits, balance: running },
  };
}

// ─── HTML Email Builder ───────────────────────────────────────────────────────

function buildStatementEmailHtml(
  data: StatementPayload,
  companyName: string,
  message?: string
): string {
  const typeLabels: Record<string, string> = {
    invoice: 'Invoice', payment: 'Payment', credit_note: 'Credit Note',
  };

  const txnRows = data.transactions
    .filter(t => t.date >= data.fromDate)
    .map(t => `
      <tr>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;">${fmtDate(t.date)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;">${typeLabels[t.type] ?? t.type}</td>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;">${escHtml(t.reference)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;text-align:right;">${t.debit > 0 ? fmtZAR(t.debit) : ''}</td>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;text-align:right;">${t.credit > 0 ? fmtZAR(t.credit) : ''}</td>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;text-align:right;font-weight:bold;">${fmtZAR(t.balance)}</td>
      </tr>`).join('');

  const balanceColor = data.summary.balance > 0 ? '#dc2626' : '#16a34a';
  const customMsg = message
    ? `<p style="font-size:14px;color:#1e293b;margin:0 0 16px;">${escHtml(message)}</p>`
    : '';

  return `<!DOCTYPE html>
<html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:${BRAND.outerBg};font-family:${BRAND.fontStack};">
<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${BRAND.outerBg};padding:24px 0;">
  <tr><td align="center">
    <table width="600" cellpadding="0" cellspacing="0" border="0" style="background:#fff;border-radius:8px;overflow:hidden;border:1px solid ${BRAND.borderColor};">
      <tr><td style="background:${BRAND.darkBg};padding:24px 32px;border-bottom:3px solid ${BRAND.primaryTeal};">
        <span style="color:#fff;font-size:22px;font-weight:bold;">STATEMENT</span>
        ${companyName ? `<span style="color:${BRAND.primaryTeal};font-size:14px;margin-left:12px;">${escHtml(companyName)}</span>` : ''}
      </td></tr>
      <tr><td style="padding:24px 32px;">
        <p style="font-size:16px;font-weight:bold;color:#1e293b;margin:0 0 4px;">Dear ${escHtml(data.customer.name)},</p>
        <p style="font-size:14px;color:#64748b;margin:0 0 16px;">Please find your account statement as at ${fmtDate(data.toDate)} below.</p>
        ${customMsg}
        <!-- Summary boxes -->
        <table width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-bottom:20px;">
          <tr>
            <td style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:4px;padding:12px;text-align:center;width:25%;">
              <div style="font-size:10px;color:#64748b;text-transform:uppercase;letter-spacing:0.05em;">Invoiced</div>
              <div style="font-size:16px;font-weight:bold;color:#1e293b;">${fmtZAR(data.summary.totalInvoiced)}</div>
            </td>
            <td style="width:4px;"></td>
            <td style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:4px;padding:12px;text-align:center;width:25%;">
              <div style="font-size:10px;color:#64748b;text-transform:uppercase;letter-spacing:0.05em;">Paid</div>
              <div style="font-size:16px;font-weight:bold;color:#16a34a;">${fmtZAR(data.summary.totalPaid)}</div>
            </td>
            <td style="width:4px;"></td>
            <td style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:4px;padding:12px;text-align:center;width:25%;">
              <div style="font-size:10px;color:#64748b;text-transform:uppercase;letter-spacing:0.05em;">Credits</div>
              <div style="font-size:16px;font-weight:bold;color:#0891b2;">${fmtZAR(data.summary.totalCredits)}</div>
            </td>
            <td style="width:4px;"></td>
            <td style="background:#fef2f2;border:1px solid #fecaca;border-radius:4px;padding:12px;text-align:center;width:25%;">
              <div style="font-size:10px;color:#64748b;text-transform:uppercase;letter-spacing:0.05em;">Balance Due</div>
              <div style="font-size:16px;font-weight:bold;color:${balanceColor};">${fmtZAR(data.summary.balance)}</div>
            </td>
          </tr>
        </table>
        <!-- Transactions table -->
        <table width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;">
          <thead>
            <tr style="background:#1a3a6b;">
              <th style="padding:8px;text-align:left;font-size:11px;color:#fff;font-weight:600;">Date</th>
              <th style="padding:8px;text-align:left;font-size:11px;color:#fff;font-weight:600;">Type</th>
              <th style="padding:8px;text-align:left;font-size:11px;color:#fff;font-weight:600;">Reference</th>
              <th style="padding:8px;text-align:right;font-size:11px;color:#fff;font-weight:600;">Debit</th>
              <th style="padding:8px;text-align:right;font-size:11px;color:#fff;font-weight:600;">Credit</th>
              <th style="padding:8px;text-align:right;font-size:11px;color:#fff;font-weight:600;">Balance</th>
            </tr>
          </thead>
          <tbody>${txnRows || '<tr><td colspan="6" style="padding:12px;text-align:center;color:#94a3b8;font-size:12px;">No transactions in this period</td></tr>'}</tbody>
        </table>
      </td></tr>
      <tr><td style="background:#f8fafc;padding:16px 32px;border-top:1px solid #e2e8f0;">
        <p style="font-size:12px;color:#94a3b8;margin:0;">
          ISAFlow &mdash; South African Cloud Accounting &nbsp;|&nbsp; This is an automated statement. Please do not reply to this email.
        </p>
      </td></tr>
    </table>
  </td></tr>
</table>
</body></html>`;
}

// ─── Main Send Function ───────────────────────────────────────────────────────

export async function sendStatementEmail(
  companyId: string,
  customerId: string,
  asAtDate: string,
  companyName: string,
  message?: string
): Promise<EmailResult> {
  const data = await fetchStatementData(companyId, customerId, asAtDate);

  if (!data) {
    return { success: false, error: 'Customer not found' };
  }

  if (!data.customer.email) {
    return { success: false, error: `No email address for ${data.customer.name}` };
  }

  const html = buildStatementEmailHtml(data, companyName, message);
  const subject = `Account Statement as at ${fmtDate(asAtDate)} — ${companyName || 'ISAFlow'}`;

  const result = await sendEmail({ to: data.customer.email, subject, html });

  if (result.success) {
    log.info('Statement email sent', {
      customerId,
      email: data.customer.email,
      asAtDate,
    }, 'statementEmailService');
  } else {
    log.error('Statement email failed', {
      customerId,
      email: data.customer.email,
      error: result.error,
    }, 'statementEmailService');
  }

  return result;
}

