        <p style="font-size:12px;color:#94a3b8;margin:0;">
          ISAFlow &mdash; South African Cloud Accounting &nbsp;|&nbsp; This is an automated statement. Please do not reply to this email.
        </p>
      </td></tr>
    </table>
  </td></tr>
</table>
</body></html>`;
}

// ─── Main Send Function ───────────────────────────────────────────────────────

export async function sendStatementEmail(
  companyId: string,
  customerId: string,
  asAtDate: string,
  companyName: string,
  message?: string
): Promise<EmailResult> {
  const data = await fetchStatementData(companyId, customerId, asAtDate);

  if (!data) {
    return { success: false, error: 'Customer not found' };
  }

  if (!data.customer.email) {
    return { success: false, error: `No email address for ${data.customer.name}` };
  }

  const html = buildStatementEmailHtml(data, companyName, message);
  const subject = `Account Statement as at ${fmtDate(asAtDate)} — ${companyName || 'ISAFlow'}`;

  const result = await sendEmail({ to: data.customer.email, subject, html });

  if (result.success) {
    log.info('Statement email sent', {
      customerId,
      email: data.customer.email,
      asAtDate,
    }, 'statementEmailService');
  } else {
    log.error('Statement email failed', {
      customerId,
      email: data.customer.email,
      error: result.error,
    }, 'statementEmailService');
  }

  return result;
}

