  selling_price_incl: number | null;
  cost_price: number | null;
  current_qty: number | null;
  unit: string | null;
  is_active: boolean;
  is_bundle: boolean;
  created_at: string;
}

const fmtCurrency = (v: number | null | undefined) =>
  v != null
    ? new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(Number(v))
    : null;

export default function ItemDetailPage() {
  const router = useRouter();
  const { itemId } = router.query;
  const [item, setItem] = useState<Item | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [isBundle, setIsBundle] = useState(false);
  const [togglingBundle, setTogglingBundle] = useState(false);

  useEffect(() => {
    if (!itemId) return;
    void loadItem();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemId]);

  const loadItem = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/items?id=${String(itemId)}`);
      const json = await res.json() as { data?: Item };
      const data = json.data;
      if (data && typeof data === 'object' && 'id' in data) {
        setItem(data as Item);
        setIsBundle(Boolean((data as Item).is_bundle));
      } else {
        setError('Item not found');
      }
    } catch {
      setError('Failed to load item');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleBundle = async () => {
    if (!item) return;
    setTogglingBundle(true);
    try {
      if (!isBundle) {
        // Enabling bundle: just flip the flag locally, BundleEditor will save
        setIsBundle(true);
      } else {
        // Disabling: delete all bundle lines via API
        const res = await apiFetch(
          `/api/accounting/item-bundles?itemId=${item.id}`,
          { method: 'DELETE' }
        );
        if (res.ok) {
          setIsBundle(false);
        }
      }
    } finally {
      setTogglingBundle(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
