              )}
            </div>
            <span
              className={`px-3 py-1 rounded-full text-sm font-medium ${
                item.is_active
                  ? 'bg-teal-500/20 text-teal-400'
                  : 'bg-gray-500/20 text-gray-400'
              }`}
            >
              {item.is_active ? 'Active' : 'Inactive'}
            </span>
            {isBundle && (
