/**
 * Recurring Invoices Management Page
 * Sage equivalent: Customers > Recurring Invoices
 * Manage templates, trigger runs, pause/resume, see due badges.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  Repeat, Plus, Pause, Play, XCircle, Zap, Loader2, Pencil,
  AlertCircle, CheckCircle, Clock, Download,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface RecurringInvoice {
  id: string;
  templateName: string;
  clientId: string;
  clientName?: string;
  frequency: string;
  nextRunDate: string;
  lastRunDate?: string;
  runCount: number;
  status: string;
  totalAmount: number;
  description?: string;
}

interface RunResult {
  generated: number;
  invoice_ids: string[];
  errors: string[];
}

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const fmtDate = (d: string | undefined): string => {
  if (!d) return '—';
  const s = typeof d === 'string' ? d : String(d);
  return s.split('T')[0] ?? s;
};

const isOverdue = (nextRunDate: string | undefined): boolean => {
  if (!nextRunDate) return false;
  return fmtDate(nextRunDate) <= new Date().toISOString().split('T')[0]!;
};

const FREQ_LABELS: Record<string, string> = {
  weekly: 'Weekly', monthly: 'Monthly', quarterly: 'Quarterly', annually: 'Annually',
};

const STATUS_BADGE: Record<string, string> = {
  active: 'bg-teal-500/10 text-teal-400',
  paused: 'bg-yellow-500/10 text-yellow-400',
  completed: 'bg-blue-500/10 text-blue-400',
  cancelled: 'bg-red-500/10 text-red-400',
};

const BTN_PRIMARY =
  'inline-flex items-center gap-2 px-4 py-2 bg-violet-600 text-white rounded-lg hover:bg-violet-700 transition-colors text-sm font-medium';
const BTN_GHOST =
  'inline-flex items-center gap-2 px-3 py-1.5 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-primary)] transition-colors text-sm';

export default function RecurringInvoicesPage() {
  const [items, setItems] = useState<RecurringInvoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<string>('');
  const [runAllBusy, setRunAllBusy] = useState(false);
  const [error, setError] = useState('');
  const [runResult, setRunResult] = useState<RunResult | null>(null);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => { setIsMounted(true); }, []);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices');
      const json = await res.json() as { data?: { items?: RecurringInvoice[] } };
      setItems(json.data?.items ?? []);
    } catch (err) {
      log.error('Failed to load recurring invoices', { error: err }, 'recurring-invoices-page');
      setError('Failed to load recurring invoices');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { if (isMounted) void load(); }, [isMounted, load]);

  const doAction = async (action: string, id: string) => {
    setBusy(id);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices-action', {
        method: 'POST',
        body: JSON.stringify({ action, id }),
      });
      if (!res.ok) {
        const json = await res.json() as { error?: { message?: string } };
        throw new Error(json.error?.message ?? 'Action failed');
      }
      await load();
    } catch (err) {
      log.error('Recurring invoice action failed', { action, id, error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Action failed');
    } finally {
      setBusy('');
    }
  };

  const runOne = async (id: string) => {
    setBusy(id);
    setError('');
    setRunResult(null);
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices-run', {
        method: 'POST',
        body: JSON.stringify({ recurring_invoice_id: id }),
      });
      const json = await res.json() as { data?: RunResult };
      if (!res.ok) throw new Error('Run failed');
      setRunResult(json.data ?? null);
      await load();
    } catch (err) {
      log.error('Recurring invoice run failed', { id, error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Run failed');
    } finally {
      setBusy('');
    }
  };

  const runAllDue = async () => {
    setRunAllBusy(true);
    setError('');
    setRunResult(null);
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices-run', {
        method: 'POST',
        body: JSON.stringify({}),
      });
      const json = await res.json() as { data?: RunResult };
      if (!res.ok) throw new Error('Run All failed');
      setRunResult(json.data ?? null);
      await load();
    } catch (err) {
      log.error('Run all due recurring invoices failed', { error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Run All failed');
    } finally {
      setRunAllBusy(false);
    }
  };

  const exportCSV = () => {
    const headers = ['Template', 'Client', 'Frequency', 'Next Run', 'Last Run', 'Amount', 'Status', 'Run Count'];
    const rows = items.map(i => [
      i.templateName, i.clientName ?? '', FREQ_LABELS[i.frequency] ?? i.frequency,
      fmtDate(i.nextRunDate), fmtDate(i.lastRunDate), i.totalAmount, i.status, i.runCount,
    ]);
    const csv = [headers, ...rows]
      .map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `recurring-invoices-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const dueCount = items.filter(i => i.status === 'active' && isOverdue(i.nextRunDate)).length;

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-violet-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-violet-500/10">
                <Repeat className="h-6 w-6 text-violet-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Recurring Invoices</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Automate repeating customer invoices
                  {dueCount > 0 && (
                    <span className="ml-2 px-2 py-0.5 bg-orange-500/20 text-orange-400 rounded-full text-xs font-medium">
                      {dueCount} due
                    </span>
                  )}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {dueCount > 0 && (
                <button
                  onClick={() => void runAllDue()}
                  disabled={runAllBusy}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  {runAllBusy
                    ? <Loader2 className="h-4 w-4 animate-spin" />
                    : <Zap className="h-4 w-4" />}
                  Run All Due ({dueCount})
                </button>
              )}
              <button onClick={exportCSV} className={BTN_GHOST}>
                <Download className="h-4 w-4" /> CSV
              </button>
              <Link href="/accounting/recurring-invoices/new" className={BTN_PRIMARY}>
                <Plus className="h-4 w-4" /> New Recurring Invoice
              </Link>
            </div>
          </div>
        </div>

        <div className="px-6 py-6 space-y-4">
          {/* Error banner */}
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}

          {/* Run result banner */}
          {runResult && (
            <div className={`flex items-start gap-2 p-3 rounded-lg border text-sm ${
              runResult.errors.length > 0
                ? 'bg-yellow-500/10 border-yellow-500/30 text-yellow-400'
                : 'bg-teal-500/10 border-teal-500/30 text-teal-400'
            }`}>
              <CheckCircle className="h-4 w-4 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium">
                  {runResult.generated} invoice{runResult.generated !== 1 ? 's' : ''} generated
                </p>
                {runResult.errors.length > 0 && (
                  <ul className="mt-1 text-xs space-y-0.5">
                    {runResult.errors.map((e, i) => <li key={i}>{e}</li>)}
                  </ul>
                )}
              </div>
            </div>
          )}

          {/* Table */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
            {loading ? (
              <div className="flex justify-center py-12">
                <Loader2 className="h-6 w-6 animate-spin text-violet-500" />
              </div>
            ) : items.length === 0 ? (
              <div className="text-center py-16 text-[var(--ff-text-secondary)]">
                <Repeat className="h-12 w-12 mx-auto mb-3 opacity-30" />
                <p className="font-medium">No recurring invoices</p>
                <p className="text-sm mt-1">
                  <Link href="/accounting/recurring-invoices/new" className="text-violet-400 hover:underline">
                    Create your first recurring invoice template
                  </Link>
                </p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="border-b border-[var(--ff-border-light)]">
                    <tr className="text-xs text-[var(--ff-text-secondary)]">
                      <th className="text-left px-5 py-3">Template</th>
                      <th className="text-left px-4 py-3">Customer</th>
                      <th className="text-left px-4 py-3">Frequency</th>
                      <th className="text-left px-4 py-3">Next Run</th>
                      <th className="text-left px-4 py-3">Last Run</th>
                      <th className="text-right px-4 py-3">Amount</th>
                      <th className="text-left px-4 py-3">Status</th>
                      <th className="text-right px-5 py-3">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {items.map(item => {
                      const due = item.status === 'active' && isOverdue(item.nextRunDate);
                      return (
                        <tr
                          key={item.id}
                          className={`border-b border-[var(--ff-border-light)] last:border-0 hover:bg-[var(--ff-bg-primary)] transition-colors ${due ? 'bg-orange-500/5' : ''}`}
                        >
                          <td className="px-5 py-3 font-medium text-[var(--ff-text-primary)]">
                            {item.templateName}
                            {item.description && (
                              <span className="block text-xs text-[var(--ff-text-secondary)] font-normal mt-0.5">
                                {item.description}
                              </span>
                            )}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {item.clientName ?? '—'}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {FREQ_LABELS[item.frequency] ?? item.frequency}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            <span className="flex items-center gap-1.5">
                              {fmtDate(item.nextRunDate)}
                              {due && (
                                <span className="flex items-center gap-0.5 text-xs px-1.5 py-0.5 bg-orange-500/20 text-orange-400 rounded-full font-medium">
                                  <Clock className="h-3 w-3" /> Due
                                </span>
                              )}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {fmtDate(item.lastRunDate)}
                          </td>
                          <td className="px-4 py-3 text-right text-[var(--ff-text-primary)] font-medium">
                            {fmt(item.totalAmount)}
                          </td>
                          <td className="px-4 py-3">
                            <span className={`text-xs px-2 py-0.5 rounded-full font-medium capitalize ${STATUS_BADGE[item.status] ?? ''}`}>
                              {item.status}
                            </span>
                          </td>
                          <td className="px-5 py-3">
                            <div className="flex items-center justify-end gap-1">
                              {item.status === 'active' && (
                                <>
                                  <button
                                    onClick={() => void runOne(item.id)}
                                    disabled={busy === item.id}
                                    title="Run Now"
                                    className="p-1.5 text-violet-400 hover:text-violet-300 hover:bg-violet-500/10 rounded-lg transition-colors disabled:opacity-40"
                                  >
                                    {busy === item.id
                                      ? <Loader2 className="h-4 w-4 animate-spin" />
                                      : <Zap className="h-4 w-4" />}
                                  </button>
                                  <button
                                    onClick={() => void doAction('pause', item.id)}
                                    disabled={busy === item.id}
                                    title="Pause"
                                    className="p-1.5 text-yellow-400 hover:text-yellow-300 hover:bg-yellow-500/10 rounded-lg transition-colors disabled:opacity-40"
                                  >
                                    <Pause className="h-4 w-4" />
                                  </button>
                                </>
                              )}
                              {item.status === 'paused' && (
                                <button
                                  onClick={() => void doAction('resume', item.id)}
                                  disabled={busy === item.id}
                                  title="Resume"
                                  className="p-1.5 text-teal-400 hover:text-teal-300 hover:bg-teal-500/10 rounded-lg transition-colors disabled:opacity-40"
                                >
                                  <Play className="h-4 w-4" />
                                </button>
                              )}
                              {(item.status === 'active' || item.status === 'paused') && (
                                <>
                                  <Link
                                    href={`/accounting/recurring-invoices/${item.id}`}
                                    title="Edit"
                                    className="p-1.5 text-blue-400 hover:text-blue-300 hover:bg-blue-500/10 rounded-lg transition-colors"
                                  >
                                    <Pencil className="h-4 w-4" />
                                  </Link>
                                  <button
                                    onClick={() => void doAction('cancel', item.id)}
                                    disabled={busy === item.id}
                                    title="Cancel"
                                    className="p-1.5 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-colors disabled:opacity-40"
                                  >
                                    <XCircle className="h-4 w-4" />
                                  </button>
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

