          </div>
          <button onClick={onClose} className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors">
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="px-6 py-4 space-y-4">
          {/* Year input */}
