/**
 * Email Service
 * Generic email sending via SMTP (nodemailer) + invoice-specific helpers
 * Gracefully handles missing SMTP configuration
 */

import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { generateInvoicePdf } from './invoicePdfService';
import { inviteEmailHtml, invoiceEmailHtml } from '@/lib/email-templates';
import type { InviteEmailData, InvoiceEmailData } from '@/lib/email-templates';
import { fireWebhook } from './webhookService';
type Row = Record<string, unknown>;


// ─── Types ──────────────────────────────────────────────────────────────────

export interface EmailAttachment {
  filename: string;
  content: Buffer;
  contentType: string;
}

export interface EmailOptions {
  to: string | string[];
  subject: string;
  html: string;
  attachments?: EmailAttachment[];
}

export interface EmailResult {
  success: boolean;
  messageId?: string;
  error?: string;
}

// ─── SMTP Configuration ────────────────────────────────────────────────────

interface SmtpConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  from: string;
}

function getSmtpConfig(): SmtpConfig | null {
  const host = process.env.SMTP_HOST;
  const port = process.env.SMTP_PORT;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  const from = process.env.SMTP_FROM || 'accounts@isaflow.co.za';

  if (!host || !user || !pass) {
    return null;
  }

  return {
    host,
    port: port ? parseInt(port, 10) : 587,
    user,
    pass,
    from,
  };
}

// ─── Generic Email Sender ───────────────────────────────────────────────────

export async function sendEmail(options: EmailOptions): Promise<EmailResult> {
  const config = getSmtpConfig();

  if (!config) {
    log.warn('SMTP not configured. Set SMTP_HOST, SMTP_USER, SMTP_PASS environment variables.', {}, 'emailService');
    return { success: false, error: 'SMTP not configured' };
  }

  try {
    // Dynamic import to avoid loading nodemailer when not needed
    const nodemailer = await import('nodemailer');

    const transporter = nodemailer.createTransport({
      host: config.host,
      port: config.port,
      secure: config.port === 465,
      auth: {
        user: config.user,
        pass: config.pass,
      },
      tls: {
        // Allow self-signed certs in dev; enforce TLS validation in production
        rejectUnauthorized: process.env.NODE_ENV === 'production',
      },
    });

    const recipients = Array.isArray(options.to) ? options.to.join(', ') : options.to;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const mailOptions: any = {
      from: config.from,
      to: recipients,
      subject: options.subject,
      html: options.html,
      attachments: options.attachments?.map((att) => ({
        filename: att.filename,
        content: att.content,
        contentType: att.contentType,
      })),
    };

    const info = await transporter.sendMail(mailOptions);

    log.info('Email sent', {
      messageId: info.messageId,
      to: recipients,
      subject: options.subject,
    }, 'emailService');

    return {
      success: true,
      messageId: info.messageId,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown email error';
    log.error('Failed to send email', { error: message, to: options.to }, 'emailService');
    return { success: false, error: message };
  }
}

// ─── Invoice Email ──────────────────────────────────────────────────────────

const fmtZAR = (amount: number): string =>
  'R ' + Number(amount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const fmtDate = (d: string | null | undefined): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

export async function sendInvoiceEmail(companyId: string, 
  invoiceId: string,
  recipientEmail: string
): Promise<EmailResult> {
  // Fetch invoice summary for email body
  const invoiceRows = (await sql`
    SELECT ci.invoice_number, ci.invoice_date, ci.due_date,
           ci.total_amount, ci.amount_paid,
           c.name AS client_name
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID
  `) as Row[];

  if (invoiceRows.length === 0) {
    throw new Error(`Invoice not found: ${invoiceId}`);
  }

  const invoiceRow = invoiceRows[0]!;
  const invoice = {
    invoice_number: String(invoiceRow.invoice_number ?? ''),
    invoice_date: invoiceRow.invoice_date != null ? String(invoiceRow.invoice_date) : null,
    due_date: invoiceRow.due_date != null ? String(invoiceRow.due_date) : null,
    total_amount: Number(invoiceRow.total_amount),
    amount_paid: Number(invoiceRow.amount_paid ?? 0),
    client_name: invoiceRow.client_name != null ? String(invoiceRow.client_name) : null,
  };
  const balance = invoice.total_amount - invoice.amount_paid;
  const companyName = 'IsaFlow';

  // Generate PDF
  const pdfBuffer = await generateInvoicePdf(companyId, invoiceId);

  // Build email HTML (table-based for email client compatibility)
  const invoiceData: InvoiceEmailData = {
    invoiceNumber: invoice.invoice_number,
    clientName: invoice.client_name || 'Valued Customer',
    invoiceDate: fmtDate(invoice.invoice_date),
    dueDate: fmtDate(invoice.due_date),
    totalAmount: fmtZAR(invoice.total_amount),
    balanceDue: fmtZAR(balance),
    companyName,
  };
  const html = invoiceEmailHtml(invoiceData);

  // Send email with PDF attachment
  const result = await sendEmail({
    to: recipientEmail,
    subject: `Invoice ${invoice.invoice_number} from ${companyName}`,
    html,
    attachments: [
      {
        filename: `${invoice.invoice_number || 'Invoice'}.pdf`,
        content: pdfBuffer,
        contentType: 'application/pdf',
      },
    ],
  });

  // Update tracking fields on the invoice
  if (result.success) {
    await sql`
      UPDATE customer_invoices
      SET email_sent_at = NOW(),
          email_sent_to = ${recipientEmail},
          email_message_id = ${result.messageId || null},
          updated_at = NOW()
      WHERE id = ${invoiceId}::UUID
    `;

    log.info('Invoice email sent and tracked', {
      invoiceId,
      recipientEmail,
      messageId: result.messageId,
    }, 'emailService');
  }

  return result;
}

// ─── Invite Email ───────────────────────────────────────────────────────────

export interface InviteEmailOptions {
  recipientEmail: string;
  inviteToken: string;
  companyName: string;
  inviterName: string;
  role: string;
  baseUrl: string;
}

export async function sendInviteEmail(options: InviteEmailOptions): Promise<EmailResult> {
  const inviteUrl = `${options.baseUrl}/invite/${options.inviteToken}`;

  const inviteData: InviteEmailData = {
    inviterName: options.inviterName,
    companyName: options.companyName,
    role: options.role,
    inviteUrl,
    recipientEmail: options.recipientEmail,
  };

  return sendEmail({
    to: options.recipientEmail,
    subject: `You've been invited to join ${options.companyName} on ISAFlow`,
    html: inviteEmailHtml(inviteData),
  });
}

/**
 * New Delivery Note Page
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Truck, Plus, Trash2, Loader2, ArrowLeft } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface CustomerOption {
  id: string;
  name?: string;
  company_name?: string;
  companyName?: string;
}

interface SalesOrderOption {
  id: string;
  orderNumber: string;
}

interface LineItem {
  description: string;
  quantity: number;
  unit: string;
}

const emptyLine = (): LineItem => ({ description: '', quantity: 1, unit: '' });

export default function NewDeliveryNotePage() {
  const router = useRouter();

  const [customers, setCustomers] = useState<CustomerOption[]>([]);
  const [salesOrders, setSalesOrders] = useState<SalesOrderOption[]>([]);
  const [loadingCustomers, setLoadingCustomers] = useState(true);
  const [loadingOrders, setLoadingOrders] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const [customerId, setCustomerId] = useState('');
  const [salesOrderId, setSalesOrderId] = useState('');
  const [deliveryDate, setDeliveryDate] = useState(new Date().toISOString().split('T')[0]!);
  const [deliveryAddress, setDeliveryAddress] = useState('');
  const [notes, setNotes] = useState('');
  const [lines, setLines] = useState<LineItem[]>([emptyLine()]);

  // Pre-fill from query string (e.g. coming from a Sales Order)
  const { sales_order_id, customer_id } = router.query;

  useEffect(() => {
    setLoadingCustomers(true);
    apiFetch('/api/accounting/customers')
      .then((r) => r.json())
      .then((json: { data?: CustomerOption[] } | CustomerOption[]) => {
        const list: CustomerOption[] = Array.isArray(json)
          ? json
          : Array.isArray((json as { data?: CustomerOption[] }).data)
            ? ((json as { data: CustomerOption[] }).data)
            : [];
        setCustomers(list.map((c) => ({ id: String(c.id), name: String((c as Record<string, unknown>).name ?? (c as Record<string, unknown>).company_name ?? '') })));
      })
      .catch(() => setError('Failed to load customers'))
      .finally(() => setLoadingCustomers(false));
  }, []);

  useEffect(() => {
    if (typeof customer_id === 'string' && customer_id) setCustomerId(customer_id);
    if (typeof sales_order_id === 'string' && sales_order_id) setSalesOrderId(sales_order_id);
  }, [customer_id, sales_order_id]);

  useEffect(() => {
    if (!customerId) {
      setSalesOrders([]);
      setSalesOrderId('');
      return;
    }
    setLoadingOrders(true);
    apiFetch(`/api/accounting/customer-sales-orders?status=confirmed`)
      .then((r) => r.json())
      .then((json: { data?: { orders?: SalesOrderOption[] } }) => {
        const all: SalesOrderOption[] = json?.data?.orders ?? [];
        setSalesOrders(all);
      })
      .catch(() => setSalesOrders([]))
      .finally(() => setLoadingOrders(false));
  }, [customerId]);

  const updateLine = (index: number, field: keyof LineItem, value: string | number) => {
    setLines((prev) => {
      const next = [...prev];
      next[index] = { ...next[index]!, [field]: value };
      return next;
    });
  };

  const removeLine = (index: number) => {
    setLines((prev) => prev.filter((_, i) => i !== index));
  };

  const addLine = () => setLines((prev) => [...prev, emptyLine()]);

  const handleSave = async (dispatchAfter: boolean) => {
    setError('');
    if (!customerId) { setError('Please select a customer'); return; }
    const validLines = lines.filter((l) => l.description.trim());
    if (validLines.length === 0) { setError('At least one line item with a description is required'); return; }

    setSaving(true);
    try {
      const res = await apiFetch('/api/accounting/delivery-notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customer_id: customerId,
          sales_order_id: salesOrderId || undefined,
          delivery_date: deliveryDate,
          delivery_address: deliveryAddress || undefined,
          notes: notes || undefined,
          lines: validLines,
        }),
      });
      const json = (await res.json()) as { data?: { id?: string }; error?: { message?: string } };
      if (!res.ok) {
        setError(json?.error?.message ?? 'Failed to create delivery note');
        return;
      }
      const noteId = json?.data?.id ?? '';
      if (dispatchAfter && noteId) {
        await apiFetch('/api/accounting/delivery-notes', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: noteId, status: 'dispatched' }),
        });
      }
      await router.push('/accounting/delivery-notes');
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to save delivery note');
    } finally {
      setSaving(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <button
              onClick={() => router.push('/accounting/delivery-notes')}
              className="p-1.5 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]"
            >
              <ArrowLeft className="h-4 w-4" />
            </button>
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Truck className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Delivery Note</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Create a new delivery note</p>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded text-sm">
              {error}
            </div>
          )}

          {/* Main form */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">
              Delivery Details
            </h2>

            <div className="grid grid-cols-2 gap-4">
              {/* Customer selector */}
              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Customer *</label>
                {loadingCustomers ? (
                  <div className="ff-input flex items-center gap-2 text-sm text-[var(--ff-text-tertiary)]">
                    <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading...
                  </div>
                ) : (
                  <select
                    value={customerId}
                    onChange={(e) => { setCustomerId(e.target.value); setSalesOrderId(''); }}
                    className="ff-input text-sm"
                  >
                    <option value="">Select customer...</option>
                    {customers.map((c) => (
                      <option key={c.id} value={c.id}>{c.name}</option>
                    ))}
                  </select>
                )}
              </div>

              {/* Delivery date */}
              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Delivery Date *</label>
                <input
                  type="date"
                  value={deliveryDate}
                  onChange={(e) => setDeliveryDate(e.target.value)}
                  className="ff-input text-sm"
                />
              </div>

              {/* Sales Order linkage */}
              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Linked Sales Order (optional)</label>
                {loadingOrders ? (
                  <div className="ff-input flex items-center gap-2 text-sm text-[var(--ff-text-tertiary)]">
                    <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading...
                  </div>
                ) : (
                  <select
                    value={salesOrderId}
                    onChange={(e) => setSalesOrderId(e.target.value)}
                    disabled={!customerId}
                    className="ff-input text-sm disabled:opacity-50"
                  >
                    <option value="">None</option>
                    {salesOrders.map((so) => (
                      <option key={so.id} value={so.id}>{so.orderNumber}</option>
                    ))}
                  </select>
                )}
              </div>

              {/* Delivery address */}
              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Delivery Address</label>
                <input
                  value={deliveryAddress}
                  onChange={(e) => setDeliveryAddress(e.target.value)}
                  placeholder="Delivery address..."
                  className="ff-input text-sm"
                />
              </div>
            </div>

            {/* Notes */}
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[var(--ff-text-secondary)]">Notes</label>
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                rows={2}
                placeholder="Additional notes..."
                className="ff-input text-sm resize-none"
              />
            </div>
          </div>

          {/* Line items */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-3">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">
              Line Items
            </h2>

            <div className="grid grid-cols-12 gap-2 text-xs text-[var(--ff-text-secondary)] px-1">
              <span className="col-span-6">Description *</span>
              <span className="col-span-3 text-right">Quantity</span>
              <span className="col-span-2">Unit</span>
              <span className="col-span-1" />
            </div>

            {lines.map((line, i) => (
              <div key={i} className="grid grid-cols-12 gap-2 items-center">
                <input
                  value={line.description}
                  onChange={(e) => updateLine(i, 'description', e.target.value)}
                  placeholder="Item description"
                  className="ff-input text-sm col-span-6"
                />
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={line.quantity}
                  onChange={(e) => updateLine(i, 'quantity', Number(e.target.value))}
                  className="ff-input text-sm col-span-3 text-right"
                />
                <input
                  value={line.unit}
                  onChange={(e) => updateLine(i, 'unit', e.target.value)}
                  placeholder="ea"
                  className="ff-input text-sm col-span-2"
                />
                <button
                  onClick={() => removeLine(i)}
                  disabled={lines.length === 1}
                  className="col-span-1 p-1.5 rounded hover:bg-red-500/10 text-red-400 disabled:opacity-30 justify-self-center"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            ))}

            <button
              onClick={addLine}
              className="flex items-center gap-1.5 text-xs text-teal-400 hover:text-teal-300 mt-1"
            >
              <Plus className="h-3.5 w-3.5" /> Add line
            </button>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3">
            <button
              onClick={() => router.push('/accounting/delivery-notes')}
              className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-secondary)] rounded-lg"
            >
              Cancel
            </button>
            <button
              onClick={() => handleSave(false)}
              disabled={saving}
              className="px-4 py-2 text-sm bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] rounded-lg disabled:opacity-50"
            >
              {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Save as Draft'}
            </button>
            <button
              onClick={() => handleSave(true)}
              disabled={saving}
              className="flex items-center gap-1.5 px-4 py-2 text-sm bg-teal-600 hover:bg-teal-500 text-white rounded-lg disabled:opacity-50"
            >
              {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <><Truck className="h-4 w-4" /> Save &amp; Dispatch</>}
            </button>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

