  }

  log.info('Split-allocated bank transaction', { bankTxId, journalEntryId: je.id, lineCount: lines.length }, 'accounting');
  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Reverse Reconciled ────────────────────────────────────────────────────────

export async function reverseReconciledTransaction(
  companyId: string, bankTxId: string, userId: string
): Promise<void> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  const tx = txRows[0];
  if (!tx) throw new Error('Transaction not found');
  if (tx.status !== 'allocated' && tx.status !== 'matched' && tx.status !== 'reconciled') {
    throw new Error('Can only reverse allocated, matched, or reconciled transactions');
  }
  if (tx.matched_journal_line_id) {
    const jlRows = (await sql`
      SELECT journal_entry_id FROM gl_journal_lines WHERE id = ${tx.matched_journal_line_id}::UUID`) as Row[];
    if (jlRows.length > 0 && jlRows[0]!.journal_entry_id) {
      const { reverseJournalEntry } = await import('./journalEntryService');
      try {
        await reverseJournalEntry(companyId, String(jlRows[0]!.journal_entry_id), userId);
      } catch (e) {
        throw new Error(`Cannot reverse: ${e instanceof Error ? e.message : 'Journal reversal failed'}`);
      }
    }
  }
  await sql`
    UPDATE bank_transactions
    SET status = 'imported', matched_journal_line_id = NULL, reconciliation_id = NULL,
        linked_po_id = NULL, linked_asset_id = NULL, linked_fleet_fuel_id = NULL,
        linked_fleet_service_id = NULL, allocation_type = NULL, allocated_entity_name = NULL,
        updated_at = NOW()
    WHERE id = ${bankTxId}::UUID`;
  log.info('Reversed reconciled bank transaction', { bankTxId, userId }, 'accounting');
}

tool_input.content:
/**
 * Timesheets Page — Week view with invoice conversion
 * Week grid (Mon–Sun), per-employee + per-customer filters,
 * inline Add Entry form, billable/non-billable totals,
 * "Create Invoice from Selected" for checked billable entries.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Clock, Plus, ChevronLeft, ChevronRight, FileText, Loader2, X, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ─── Types ────────────────────────────────────────────────────────────────── */

interface TimeEntry {
  id: string;
  userId: string;
  projectName: string | null;
  taskDescription: string;
  entryDate: string;
  hours: number;
  rate: number | null;
  billable: boolean;
  invoiced: boolean;
  customerId: string | null;
  customerName: string | null;
  status: string;
}

interface Customer { id: string; name: string }

/* ─── Week helpers ──────────────────────────────────────────────────────────── */

function getMondayOf(d: Date): Date {
  const day = d.getDay(); // 0=Sun
  const diff = day === 0 ? -6 : 1 - day;
  const m = new Date(d);
  m.setDate(d.getDate() + diff);
  m.setHours(0, 0, 0, 0);
  return m;
}

function addDays(d: Date, n: number): Date {
  const r = new Date(d);
  r.setDate(d.getDate() + n);
  return r;
}

function fmtISO(d: Date): string {
  return d.toISOString().split('T')[0] ?? '';
}

function fmtDisplay(d: Date): string {
  return d.toLocaleDateString('en-ZA', { weekday: 'short', day: 'numeric', month: 'short' });
}

function fmtWeekRange(monday: Date): string {
  const sunday = addDays(monday, 6);
  return `${monday.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' })} – ${sunday.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short', year: 'numeric' })}`;
}

const WEEK_DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const BLANK_FORM = {
  taskDescription: '',
  projectName: '',
  customerId: '',
  entryDate: fmtISO(new Date()),
  hours: '',
  rate: '',
  billable: true,
};

/* ─── Component ─────────────────────────────────────────────────────────────── */

export default function TimesheetsPage() {
  const [weekStart, setWeekStart] = useState<Date>(() => getMondayOf(new Date()));
  const [entries, setEntries] = useState<TimeEntry[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [filterCustomer, setFilterCustomer] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ ...BLANK_FORM });
  const [formBusy, setFormBusy] = useState(false);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [invoiceBusy, setInvoiceBusy] = useState(false);
  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null);

  /* load customers once */
  useEffect(() => {
    void apiFetch('/api/accounting/customers')
      .then(r => r.json())
      .then(res => {
        const d: Record<string, unknown>[] = Array.isArray(res.data) ? res.data : Array.isArray(res) ? res : [];
        setCustomers(d.map(c => ({
          id: String(c.id),
          name: String(c.name ?? c.companyName ?? c.company_name ?? ''),
        })));
      })
      .catch(() => { /* non-critical */ });
  }, []);

  const loadEntries = useCallback(async () => {
    setLoading(true);
    const from = fmtISO(weekStart);
    const to = fmtISO(addDays(weekStart, 6));
    const params = new URLSearchParams({ dateFrom: from, dateTo: to, limit: '200' });
    if (filterCustomer) params.set('customerId', filterCustomer);
    try {
      const res = await apiFetch(`/api/accounting/time-entries?${params.toString()}`);
      const json: { data?: { entries?: TimeEntry[] } } = await res.json() as { data?: { entries?: TimeEntry[] } };
      setEntries(json.data?.entries ?? []);
    } catch {
      showToast('Failed to load entries', false);
    }
    setLoading(false);
  }, [weekStart, filterCustomer]);

  useEffect(() => { void loadEntries(); }, [loadEntries]);

  /* auto-clear toast */
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(t);
  }, [toast]);

  function showToast(msg: string, ok: boolean) { setToast({ msg, ok }); }

  /* ── Week navigation ── */
  const prevWeek = () => setWeekStart(d => addDays(d, -7));
  const nextWeek = () => setWeekStart(d => addDays(d, 7));
  const goToday  = () => setWeekStart(getMondayOf(new Date()));

  /* ── Week day dates ── */
  const weekDates = WEEK_DAYS.map((_, i) => addDays(weekStart, i));

  /* ── Group entries by ISO date ── */
  const byDate = entries.reduce<Record<string, TimeEntry[]>>((acc, e) => {
    const key = String(e.entryDate).split('T')[0] ?? '';
    if (!acc[key]) acc[key] = [];
    acc[key]!.push(e);
    return acc;
  }, {});

  /* ── Totals ── */
  const totalHours    = entries.reduce((s, e) => s + e.hours, 0);
  const billableHours = entries.filter(e => e.billable).reduce((s, e) => s + e.hours, 0);
  const nonBillable   = totalHours - billableHours;

  /* ── Selection ── */
  const eligibleIds = entries.filter(e => e.billable && !e.invoiced).map(e => e.id);
  const toggleSelect = (id: string) => setSelected(prev => {
    const n = new Set(prev);
    if (n.has(id)) n.delete(id); else n.add(id);
    return n;
  });
  const toggleAll = () => setSelected(
    selected.size === eligibleIds.length ? new Set() : new Set(eligibleIds),
  );

  /* ── Form ── */
  const fc = (field: string, val: string | boolean) =>
    setForm(prev => ({ ...prev, [field]: val }));

  const handleSubmitForm = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.taskDescription.trim() || !form.hours) {
      showToast('Description and hours are required', false);
      return;
    }
    setFormBusy(true);
    try {
      const body = {
        taskDescription: form.taskDescription.trim(),
        projectName: form.projectName.trim() || undefined,
        customerId: form.customerId || undefined,
        entryDate: form.entryDate,
        hours: Number(form.hours),
        rate: form.rate ? Number(form.rate) : undefined,
        billable: form.billable,
      };
      const res = await apiFetch('/api/accounting/time-entries', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const j: { message?: string } = await res.json() as { message?: string };
        throw new Error(j.message ?? 'Failed');
      }
      showToast('Entry added', true);
      setShowForm(false);
      setForm({ ...BLANK_FORM });
      void loadEntries();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Save failed', false);
    }
    setFormBusy(false);
  };

  /* ── Create invoice from selected ── */
  const handleCreateInvoice = async () => {
    const ids = Array.from(selected);
    if (!ids.length) { showToast('Select entries first', false); return; }

    // Determine customer from first selected entry
    const firstEntry = entries.find(e => ids.includes(e.id));
    if (!firstEntry?.customerId) {
      showToast('Selected entries must have a customer assigned', false);
      return;
    }

    setInvoiceBusy(true);
    try {
      const res = await apiFetch('/api/accounting/time-entries-invoice', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          timeEntryIds: ids,
          customerId: firstEntry.customerId,
          invoiceDate: fmtISO(new Date()),
        }),
      });
      const j: { data?: { invoiceNumber?: string }; message?: string } =
        await res.json() as { data?: { invoiceNumber?: string }; message?: string };
      if (!res.ok) throw new Error(j.message ?? 'Failed');
      showToast(`Invoice ${j.data?.invoiceNumber ?? ''} created`, true);
      setSelected(new Set());
      void loadEntries();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Invoice failed', false);
    }
    setInvoiceBusy(false);
  };

  /* ─── Render ─────────────────────────────────────────────────────────────── */
  return (
    <AppLayout>
      <div className="p-6 max-w-7xl mx-auto space-y-5">

        {/* Header */}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <Clock className="w-7 h-7 text-blue-600 dark:text-blue-400" />
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Timesheets</h1>
          </div>
          <div className="flex items-center gap-2">
            {selected.size > 0 && (
              <button
                onClick={() => void handleCreateInvoice()}
                disabled={invoiceBusy}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-60 text-sm"
              >
                {invoiceBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
                Create Invoice ({selected.size})
              </button>
            )}
            <button
              onClick={() => setShowForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm"
            >
              <Plus className="w-4 h-4" /> Add Entry
            </button>
          </div>
        </div>

        {/* Toast */}
        {toast && (
          <div className={`flex items-center justify-between p-3 rounded-lg text-sm ${toast.ok ? 'bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300' : 'bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300'}`}>
            <span className="flex items-center gap-2">
              {toast.ok ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
              {toast.msg}
            </span>
            <button onClick={() => setToast(null)}><X className="w-3.5 h-3.5" /></button>
          </div>
        )}

        {/* Week navigator + filters */}
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-1">
            <button onClick={prevWeek} className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-800">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-sm font-medium text-gray-700 dark:text-gray-300 min-w-[200px] text-center">
              {fmtWeekRange(weekStart)}
            </span>
            <button onClick={nextWeek} className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-800">
              <ChevronRight className="w-4 h-4" />
            </button>
            <button onClick={goToday} className="ml-2 text-xs px-2 py-1 rounded border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800">
              Today
            </button>
          </div>
          <select
            value={filterCustomer}
            onChange={e => setFilterCustomer(e.target.value)}
            className="text-sm border border-gray-300 dark:border-gray-600 rounded px-2 py-1.5 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
          >
            <option value="">All Customers</option>
            {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </div>

        {/* Summary bar */}
        <div className="grid grid-cols-3 gap-4">
          {[
            { label: 'Total Hours', value: totalHours.toFixed(2), color: 'text-gray-900 dark:text-white' },
            { label: 'Billable', value: billableHours.toFixed(2), color: 'text-emerald-600 dark:text-emerald-400' },
            { label: 'Non-Billable', value: nonBillable.toFixed(2), color: 'text-amber-600 dark:text-amber-400' },
          ].map(s => (
            <div key={s.label} className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4 text-center">
              <p className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">{s.label}</p>
              <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
            </div>
          ))}
        </div>

        {/* Select-all + bulk hint */}
        {eligibleIds.length > 0 && (
          <div className="flex items-center gap-3 text-sm text-gray-500 dark:text-gray-400">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={selected.size === eligibleIds.length && eligibleIds.length > 0}
                onChange={toggleAll}
                className="rounded"
              />
              Select all billable uninvoiced ({eligibleIds.length})
            </label>
          </div>
        )}

        {/* Week grid */}
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
          </div>
        ) : (
          <div className="grid grid-cols-7 gap-2">
            {weekDates.map((date, i) => {
              const isoKey = fmtISO(date);
              const dayEntries = byDate[isoKey] ?? [];
              const dayHours = dayEntries.reduce((s, e) => s + e.hours, 0);
              const isToday = isoKey === fmtISO(new Date());

              return (
                <div
                  key={isoKey}
                  className={`rounded-xl border p-3 space-y-2 min-h-[140px] ${isToday ? 'border-blue-400 dark:border-blue-500 bg-blue-50/30 dark:bg-blue-900/10' : 'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800'}`}
                >
                  {/* Day header */}
                  <div className="text-center">
                    <p className={`text-xs font-semibold ${isToday ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>
                      {WEEK_DAYS[i]}
                    </p>
                    <p className={`text-sm ${isToday ? 'text-blue-700 dark:text-blue-300 font-bold' : 'text-gray-700 dark:text-gray-300'}`}>
                      {fmtDisplay(date).split(',')[0]}
                    </p>
                    {dayHours > 0 && (
                      <p className="text-xs text-gray-400 mt-0.5">{dayHours.toFixed(1)}h</p>
                    )}
                  </div>

                  {/* Entries */}
                  <div className="space-y-1.5">
                    {dayEntries.map(entry => (
                      <div
                        key={entry.id}
                        className={`rounded-lg p-2 text-xs border ${entry.billable ? 'border-emerald-200 dark:border-emerald-800 bg-emerald-50 dark:bg-emerald-900/20' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30'}`}
                      >
                        <div className="flex items-start justify-between gap-1">
                          {entry.billable && !entry.invoiced && (
                            <input
                              type="checkbox"
                              checked={selected.has(entry.id)}
                              onChange={() => toggleSelect(entry.id)}
                              className="mt-0.5 rounded flex-shrink-0"
                            />
                          )}
                          <div className="flex-1 min-w-0">
                            <p className="font-medium text-gray-800 dark:text-gray-200 truncate" title={entry.taskDescription}>
                              {entry.taskDescription}
                            </p>
                            {entry.customerName && (
                              <p className="text-gray-500 dark:text-gray-400 truncate">{entry.customerName}</p>
                            )}
                            {entry.projectName && (
                              <p className="text-gray-400 dark:text-gray-500 truncate">{entry.projectName}</p>
                            )}
                          </div>
                        </div>
                        <div className="flex items-center justify-between mt-1">
                          <span className="font-semibold text-gray-700 dark:text-gray-300">{entry.hours}h</span>
                          <span className={`px-1 rounded text-[10px] ${entry.invoiced ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400' : entry.billable ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}>
                            {entry.invoiced ? 'invoiced' : entry.billable ? 'billable' : 'non-bill'}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Quick add for this day */}
                  <button
                    onClick={() => { setForm({ ...BLANK_FORM, entryDate: isoKey }); setShowForm(true); }}
                    className="w-full text-xs text-gray-400 dark:text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 py-1"
                  >
                    + add
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Add Entry modal */}
        {showForm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl w-full max-w-lg p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Add Time Entry</h2>
                <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <form onSubmit={e => void handleSubmitForm(e)} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Description <span className="text-red-500">*</span>
                  </label>
                  <input
                    value={form.taskDescription}
                    onChange={e => fc('taskDescription', e.target.value)}
                    required
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    placeholder="What did you work on?"
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
                    <input
                      type="date"
                      value={form.entryDate}
                      onChange={e => fc('entryDate', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      Hours <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number" step="0.25" min="0.25"
                      value={form.hours}
                      onChange={e => fc('hours', e.target.value)}
                      required
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      placeholder="1.5"
                    />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Customer</label>
                    <select
                      value={form.customerId}
                      onChange={e => fc('customerId', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    >
                      <option value="">— None —</option>
                      {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Rate (R/h)</label>
                    <input
                      type="number" min="0" step="0.01"
                      value={form.rate}
                      onChange={e => fc('rate', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      placeholder="0.00"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Project</label>
                  <input
                    value={form.projectName}
                    onChange={e => fc('projectName', e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    placeholder="Optional project name"
                  />
                </div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.billable}
                    onChange={e => fc('billable', e.target.checked)}
                    className="rounded"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Billable</span>
                </label>
                <div className="flex gap-2 pt-2">
                  <button type="button" onClick={() => setShowForm(false)}
                    className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800">
                    Cancel
                  </button>
                  <button type="submit" disabled={formBusy}
                    className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 disabled:opacity-60 flex items-center justify-center gap-2">
                    {formBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
                    Save Entry
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * Timesheets Page — Week view with invoice conversion
 * Week grid (Mon–Sun), per-employee + per-customer filters,
 * inline Add Entry form, billable/non-billable totals,
 * "Create Invoice from Selected" for checked billable entries.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Clock, Plus, ChevronLeft, ChevronRight, FileText, Loader2, X, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ─── Types ────────────────────────────────────────────────────────────────── */

interface TimeEntry {
  id: string;
  userId: string;
  projectName: string | null;
  taskDescription: string;
  entryDate: string;
  hours: number;
  rate: number | null;
  billable: boolean;
  invoiced: boolean;
  customerId: string | null;
  customerName: string | null;
  status: string;
}

interface Customer { id: string; name: string }

/* ─── Week helpers ──────────────────────────────────────────────────────────── */

function getMondayOf(d: Date): Date {
  const day = d.getDay(); // 0=Sun
  const diff = day === 0 ? -6 : 1 - day;
  const m = new Date(d);
  m.setDate(d.getDate() + diff);
  m.setHours(0, 0, 0, 0);
  return m;
}

function addDays(d: Date, n: number): Date {
  const r = new Date(d);
  r.setDate(d.getDate() + n);
  return r;
}

function fmtISO(d: Date): string {
  return d.toISOString().split('T')[0] ?? '';
}

function fmtDisplay(d: Date): string {
  return d.toLocaleDateString('en-ZA', { weekday: 'short', day: 'numeric', month: 'short' });
}

function fmtWeekRange(monday: Date): string {
  const sunday = addDays(monday, 6);
  return `${monday.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' })} – ${sunday.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short', year: 'numeric' })}`;
}

const WEEK_DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const BLANK_FORM = {
  taskDescription: '',
  projectName: '',
  customerId: '',
  entryDate: fmtISO(new Date()),
  hours: '',
  rate: '',
  billable: true,
};

/* ─── Component ─────────────────────────────────────────────────────────────── */

export default function TimesheetsPage() {
  const [weekStart, setWeekStart] = useState<Date>(() => getMondayOf(new Date()));
  const [entries, setEntries] = useState<TimeEntry[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [filterCustomer, setFilterCustomer] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ ...BLANK_FORM });
  const [formBusy, setFormBusy] = useState(false);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [invoiceBusy, setInvoiceBusy] = useState(false);
  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null);

  /* load customers once */
  useEffect(() => {
    void apiFetch('/api/accounting/customers')
      .then(r => r.json())
      .then(res => {
        const d: Record<string, unknown>[] = Array.isArray(res.data) ? res.data : Array.isArray(res) ? res : [];
        setCustomers(d.map(c => ({
          id: String(c.id),
          name: String(c.name ?? c.companyName ?? c.company_name ?? ''),
        })));
      })
      .catch(() => { /* non-critical */ });
  }, []);

  const loadEntries = useCallback(async () => {
    setLoading(true);
    const from = fmtISO(weekStart);
    const to = fmtISO(addDays(weekStart, 6));
    const params = new URLSearchParams({ dateFrom: from, dateTo: to, limit: '200' });
    if (filterCustomer) params.set('customerId', filterCustomer);
    try {
      const res = await apiFetch(`/api/accounting/time-entries?${params.toString()}`);
      const json: { data?: { entries?: TimeEntry[] } } = await res.json() as { data?: { entries?: TimeEntry[] } };
      setEntries(json.data?.entries ?? []);
    } catch {
      showToast('Failed to load entries', false);
    }
    setLoading(false);
  }, [weekStart, filterCustomer]);

  useEffect(() => { void loadEntries(); }, [loadEntries]);

  /* auto-clear toast */
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(t);
  }, [toast]);

  function showToast(msg: string, ok: boolean) { setToast({ msg, ok }); }

  /* ── Week navigation ── */
  const prevWeek = () => setWeekStart(d => addDays(d, -7));
  const nextWeek = () => setWeekStart(d => addDays(d, 7));
  const goToday  = () => setWeekStart(getMondayOf(new Date()));

  /* ── Week day dates ── */
  const weekDates = WEEK_DAYS.map((_, i) => addDays(weekStart, i));

  /* ── Group entries by ISO date ── */
  const byDate = entries.reduce<Record<string, TimeEntry[]>>((acc, e) => {
    const key = String(e.entryDate).split('T')[0] ?? '';
    if (!acc[key]) acc[key] = [];
    acc[key]!.push(e);
    return acc;
  }, {});

  /* ── Totals ── */
  const totalHours    = entries.reduce((s, e) => s + e.hours, 0);
  const billableHours = entries.filter(e => e.billable).reduce((s, e) => s + e.hours, 0);
  const nonBillable   = totalHours - billableHours;

  /* ── Selection ── */
  const eligibleIds = entries.filter(e => e.billable && !e.invoiced).map(e => e.id);
  const toggleSelect = (id: string) => setSelected(prev => {
    const n = new Set(prev);
    if (n.has(id)) n.delete(id); else n.add(id);
    return n;
  });
  const toggleAll = () => setSelected(
    selected.size === eligibleIds.length ? new Set() : new Set(eligibleIds),
  );

  /* ── Form ── */
  const fc = (field: string, val: string | boolean) =>
    setForm(prev => ({ ...prev, [field]: val }));

  const handleSubmitForm = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.taskDescription.trim() || !form.hours) {
      showToast('Description and hours are required', false);
      return;
    }
    setFormBusy(true);
    try {
      const body = {
        taskDescription: form.taskDescription.trim(),
        projectName: form.projectName.trim() || undefined,
        customerId: form.customerId || undefined,
        entryDate: form.entryDate,
        hours: Number(form.hours),
        rate: form.rate ? Number(form.rate) : undefined,
        billable: form.billable,
      };
      const res = await apiFetch('/api/accounting/time-entries', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const j: { message?: string } = await res.json() as { message?: string };
        throw new Error(j.message ?? 'Failed');
      }
      showToast('Entry added', true);
      setShowForm(false);
      setForm({ ...BLANK_FORM });
      void loadEntries();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Save failed', false);
    }
    setFormBusy(false);
  };

  /* ── Create invoice from selected ── */
  const handleCreateInvoice = async () => {
    const ids = Array.from(selected);
    if (!ids.length) { showToast('Select entries first', false); return; }

    // Determine customer from first selected entry
    const firstEntry = entries.find(e => ids.includes(e.id));
    if (!firstEntry?.customerId) {
      showToast('Selected entries must have a customer assigned', false);
      return;
    }

    setInvoiceBusy(true);
    try {
      const res = await apiFetch('/api/accounting/time-entries-invoice', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          timeEntryIds: ids,
          customerId: firstEntry.customerId,
          invoiceDate: fmtISO(new Date()),
        }),
      });
      const j: { data?: { invoiceNumber?: string }; message?: string } =
        await res.json() as { data?: { invoiceNumber?: string }; message?: string };
      if (!res.ok) throw new Error(j.message ?? 'Failed');
      showToast(`Invoice ${j.data?.invoiceNumber ?? ''} created`, true);
      setSelected(new Set());
      void loadEntries();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Invoice failed', false);
    }
    setInvoiceBusy(false);
  };

  /* ─── Render ─────────────────────────────────────────────────────────────── */
  return (
    <AppLayout>
      <div className="p-6 max-w-7xl mx-auto space-y-5">

        {/* Header */}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <Clock className="w-7 h-7 text-blue-600 dark:text-blue-400" />
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Timesheets</h1>
          </div>
          <div className="flex items-center gap-2">
            {selected.size > 0 && (
              <button
                onClick={() => void handleCreateInvoice()}
                disabled={invoiceBusy}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-60 text-sm"
              >
                {invoiceBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
                Create Invoice ({selected.size})
              </button>
            )}
            <button
              onClick={() => setShowForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm"
            >
              <Plus className="w-4 h-4" /> Add Entry
            </button>
          </div>
        </div>

        {/* Toast */}
        {toast && (
          <div className={`flex items-center justify-between p-3 rounded-lg text-sm ${toast.ok ? 'bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300' : 'bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300'}`}>
            <span className="flex items-center gap-2">
              {toast.ok ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
              {toast.msg}
            </span>
            <button onClick={() => setToast(null)}><X className="w-3.5 h-3.5" /></button>
          </div>
        )}

        {/* Week navigator + filters */}
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-1">
            <button onClick={prevWeek} className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-800">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-sm font-medium text-gray-700 dark:text-gray-300 min-w-[200px] text-center">
              {fmtWeekRange(weekStart)}
            </span>
            <button onClick={nextWeek} className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-800">
              <ChevronRight className="w-4 h-4" />
            </button>
            <button onClick={goToday} className="ml-2 text-xs px-2 py-1 rounded border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800">
              Today
            </button>
          </div>
          <select
            value={filterCustomer}
            onChange={e => setFilterCustomer(e.target.value)}
            className="text-sm border border-gray-300 dark:border-gray-600 rounded px-2 py-1.5 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
          >
            <option value="">All Customers</option>
            {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </div>

        {/* Summary bar */}
        <div className="grid grid-cols-3 gap-4">
          {[
            { label: 'Total Hours', value: totalHours.toFixed(2), color: 'text-gray-900 dark:text-white' },
            { label: 'Billable', value: billableHours.toFixed(2), color: 'text-emerald-600 dark:text-emerald-400' },
            { label: 'Non-Billable', value: nonBillable.toFixed(2), color: 'text-amber-600 dark:text-amber-400' },
          ].map(s => (
            <div key={s.label} className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4 text-center">
              <p className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">{s.label}</p>
              <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
            </div>
          ))}
        </div>

        {/* Select-all + bulk hint */}
        {eligibleIds.length > 0 && (
          <div className="flex items-center gap-3 text-sm text-gray-500 dark:text-gray-400">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={selected.size === eligibleIds.length && eligibleIds.length > 0}
                onChange={toggleAll}
                className="rounded"
              />
              Select all billable uninvoiced ({eligibleIds.length})
            </label>
          </div>
        )}

        {/* Week grid */}
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
          </div>
        ) : (
          <div className="grid grid-cols-7 gap-2">
            {weekDates.map((date, i) => {
              const isoKey = fmtISO(date);
              const dayEntries = byDate[isoKey] ?? [];
              const dayHours = dayEntries.reduce((s, e) => s + e.hours, 0);
              const isToday = isoKey === fmtISO(new Date());

              return (
                <div
                  key={isoKey}
                  className={`rounded-xl border p-3 space-y-2 min-h-[140px] ${isToday ? 'border-blue-400 dark:border-blue-500 bg-blue-50/30 dark:bg-blue-900/10' : 'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800'}`}
                >
                  {/* Day header */}
                  <div className="text-center">
                    <p className={`text-xs font-semibold ${isToday ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>
                      {WEEK_DAYS[i]}
                    </p>
                    <p className={`text-sm ${isToday ? 'text-blue-700 dark:text-blue-300 font-bold' : 'text-gray-700 dark:text-gray-300'}`}>
                      {fmtDisplay(date).split(',')[0]}
                    </p>
                    {dayHours > 0 && (
                      <p className="text-xs text-gray-400 mt-0.5">{dayHours.toFixed(1)}h</p>
                    )}
                  </div>

                  {/* Entries */}
                  <div className="space-y-1.5">
                    {dayEntries.map(entry => (
                      <div
                        key={entry.id}
                        className={`rounded-lg p-2 text-xs border ${entry.billable ? 'border-emerald-200 dark:border-emerald-800 bg-emerald-50 dark:bg-emerald-900/20' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30'}`}
                      >
                        <div className="flex items-start justify-between gap-1">
                          {entry.billable && !entry.invoiced && (
                            <input
                              type="checkbox"
                              checked={selected.has(entry.id)}
                              onChange={() => toggleSelect(entry.id)}
                              className="mt-0.5 rounded flex-shrink-0"
                            />
                          )}
                          <div className="flex-1 min-w-0">
                            <p className="font-medium text-gray-800 dark:text-gray-200 truncate" title={entry.taskDescription}>
                              {entry.taskDescription}
                            </p>
                            {entry.customerName && (
                              <p className="text-gray-500 dark:text-gray-400 truncate">{entry.customerName}</p>
                            )}
                            {entry.projectName && (
                              <p className="text-gray-400 dark:text-gray-500 truncate">{entry.projectName}</p>
                            )}
                          </div>
                        </div>
                        <div className="flex items-center justify-between mt-1">
                          <span className="font-semibold text-gray-700 dark:text-gray-300">{entry.hours}h</span>
                          <span className={`px-1 rounded text-[10px] ${entry.invoiced ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400' : entry.billable ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}>
                            {entry.invoiced ? 'invoiced' : entry.billable ? 'billable' : 'non-bill'}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Quick add for this day */}
                  <button
                    onClick={() => { setForm({ ...BLANK_FORM, entryDate: isoKey }); setShowForm(true); }}
                    className="w-full text-xs text-gray-400 dark:text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 py-1"
                  >
                    + add
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Add Entry modal */}
        {showForm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl w-full max-w-lg p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Add Time Entry</h2>
                <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <form onSubmit={e => void handleSubmitForm(e)} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Description <span className="text-red-500">*</span>
                  </label>
                  <input
                    value={form.taskDescription}
                    onChange={e => fc('taskDescription', e.target.value)}
                    required
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    placeholder="What did you work on?"
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
                    <input
                      type="date"
                      value={form.entryDate}
                      onChange={e => fc('entryDate', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      Hours <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number" step="0.25" min="0.25"
                      value={form.hours}
                      onChange={e => fc('hours', e.target.value)}
                      required
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      placeholder="1.5"
                    />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Customer</label>
                    <select
                      value={form.customerId}
                      onChange={e => fc('customerId', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    >
                      <option value="">— None —</option>
                      {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Rate (R/h)</label>
                    <input
                      type="number" min="0" step="0.01"
                      value={form.rate}
                      onChange={e => fc('rate', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      placeholder="0.00"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Project</label>
                  <input
                    value={form.projectName}
                    onChange={e => fc('projectName', e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    placeholder="Optional project name"
                  />
                </div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.billable}
                    onChange={e => fc('billable', e.target.checked)}
                    className="rounded"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Billable</span>
                </label>
                <div className="flex gap-2 pt-2">
                  <button type="button" onClick={() => setShowForm(false)}
                    className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800">
                    Cancel
                  </button>
                  <button type="submit" disabled={formBusy}
                    className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 disabled:opacity-60 flex items-center justify-center gap-2">
                    {formBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
                    Save Entry
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

tool_response.content:
/**
 * Timesheets Page — Week view with invoice conversion
 * Week grid (Mon–Sun), per-employee + per-customer filters,
 * inline Add Entry form, billable/non-billable totals,
 * "Create Invoice from Selected" for checked billable entries.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Clock, Plus, ChevronLeft, ChevronRight, FileText, Loader2, X, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ─── Types ────────────────────────────────────────────────────────────────── */

interface TimeEntry {
  id: string;
  userId: string;
  projectName: string | null;
  taskDescription: string;
  entryDate: string;
  hours: number;
  rate: number | null;
  billable: boolean;
  invoiced: boolean;
  customerId: string | null;
  customerName: string | null;
  status: string;
}

interface Customer { id: string; name: string }

/* ─── Week helpers ──────────────────────────────────────────────────────────── */

function getMondayOf(d: Date): Date {
  const day = d.getDay(); // 0=Sun
  const diff = day === 0 ? -6 : 1 - day;
  const m = new Date(d);
  m.setDate(d.getDate() + diff);
  m.setHours(0, 0, 0, 0);
  return m;
}

function addDays(d: Date, n: number): Date {
  const r = new Date(d);
  r.setDate(d.getDate() + n);
  return r;
}

function fmtISO(d: Date): string {
  return d.toISOString().split('T')[0] ?? '';
}

function fmtDisplay(d: Date): string {
  return d.toLocaleDateString('en-ZA', { weekday: 'short', day: 'numeric', month: 'short' });
}

function fmtWeekRange(monday: Date): string {
  const sunday = addDays(monday, 6);
  return `${monday.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' })} – ${sunday.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short', year: 'numeric' })}`;
}

const WEEK_DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const BLANK_FORM = {
  taskDescription: '',
  projectName: '',
  customerId: '',
  entryDate: fmtISO(new Date()),
  hours: '',
  rate: '',
  billable: true,
};

/* ─── Component ─────────────────────────────────────────────────────────────── */

export default function TimesheetsPage() {
  const [weekStart, setWeekStart] = useState<Date>(() => getMondayOf(new Date()));
  const [entries, setEntries] = useState<TimeEntry[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [filterCustomer, setFilterCustomer] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ ...BLANK_FORM });
  const [formBusy, setFormBusy] = useState(false);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [invoiceBusy, setInvoiceBusy] = useState(false);
  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null);

  /* load customers once */
  useEffect(() => {
    void apiFetch('/api/accounting/customers')
      .then(r => r.json())
      .then(res => {
        const d: Record<string, unknown>[] = Array.isArray(res.data) ? res.data : Array.isArray(res) ? res : [];
        setCustomers(d.map(c => ({
          id: String(c.id),
          name: String(c.name ?? c.companyName ?? c.company_name ?? ''),
        })));
      })
      .catch(() => { /* non-critical */ });
  }, []);

  const loadEntries = useCallback(async () => {
    setLoading(true);
    const from = fmtISO(weekStart);
    const to = fmtISO(addDays(weekStart, 6));
    const params = new URLSearchParams({ dateFrom: from, dateTo: to, limit: '200' });
    if (filterCustomer) params.set('customerId', filterCustomer);
    try {
      const res = await apiFetch(`/api/accounting/time-entries?${params.toString()}`);
      const json: { data?: { entries?: TimeEntry[] } } = await res.json() as { data?: { entries?: TimeEntry[] } };
      setEntries(json.data?.entries ?? []);
    } catch {
      showToast('Failed to load entries', false);
    }
    setLoading(false);
  }, [weekStart, filterCustomer]);

  useEffect(() => { void loadEntries(); }, [loadEntries]);

  /* auto-clear toast */
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(t);
  }, [toast]);

  function showToast(msg: string, ok: boolean) { setToast({ msg, ok }); }

  /* ── Week navigation ── */
  const prevWeek = () => setWeekStart(d => addDays(d, -7));
  const nextWeek = () => setWeekStart(d => addDays(d, 7));
  const goToday  = () => setWeekStart(getMondayOf(new Date()));

  /* ── Week day dates ── */
  const weekDates = WEEK_DAYS.map((_, i) => addDays(weekStart, i));

  /* ── Group entries by ISO date ── */
  const byDate = entries.reduce<Record<string, TimeEntry[]>>((acc, e) => {
    const key = String(e.entryDate).split('T')[0] ?? '';
    if (!acc[key]) acc[key] = [];
    acc[key]!.push(e);
    return acc;
  }, {});

  /* ── Totals ── */
  const totalHours    = entries.reduce((s, e) => s + e.hours, 0);
  const billableHours = entries.filter(e => e.billable).reduce((s, e) => s + e.hours, 0);
  const nonBillable   = totalHours - billableHours;

  /* ── Selection ── */
  const eligibleIds = entries.filter(e => e.billable && !e.invoiced).map(e => e.id);
  const toggleSelect = (id: string) => setSelected(prev => {
    const n = new Set(prev);
    if (n.has(id)) n.delete(id); else n.add(id);
    return n;
  });
  const toggleAll = () => setSelected(
    selected.size === eligibleIds.length ? new Set() : new Set(eligibleIds),
  );

  /* ── Form ── */
  const fc = (field: string, val: string | boolean) =>
    setForm(prev => ({ ...prev, [field]: val }));

  const handleSubmitForm = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.taskDescription.trim() || !form.hours) {
      showToast('Description and hours are required', false);
      return;
    }
    setFormBusy(true);
    try {
      const body = {
        taskDescription: form.taskDescription.trim(),
        projectName: form.projectName.trim() || undefined,
        customerId: form.customerId || undefined,
        entryDate: form.entryDate,
        hours: Number(form.hours),
        rate: form.rate ? Number(form.rate) : undefined,
        billable: form.billable,
      };
      const res = await apiFetch('/api/accounting/time-entries', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const j: { message?: string } = await res.json() as { message?: string };
        throw new Error(j.message ?? 'Failed');
      }
      showToast('Entry added', true);
      setShowForm(false);
      setForm({ ...BLANK_FORM });
      void loadEntries();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Save failed', false);
    }
    setFormBusy(false);
  };

  /* ── Create invoice from selected ── */
  const handleCreateInvoice = async () => {
    const ids = Array.from(selected);
    if (!ids.length) { showToast('Select entries first', false); return; }

    // Determine customer from first selected entry
    const firstEntry = entries.find(e => ids.includes(e.id));
    if (!firstEntry?.customerId) {
      showToast('Selected entries must have a customer assigned', false);
      return;
    }

    setInvoiceBusy(true);
    try {
      const res = await apiFetch('/api/accounting/time-entries-invoice', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          timeEntryIds: ids,
          customerId: firstEntry.customerId,
          invoiceDate: fmtISO(new Date()),
        }),
      });
      const j: { data?: { invoiceNumber?: string }; message?: string } =
        await res.json() as { data?: { invoiceNumber?: string }; message?: string };
      if (!res.ok) throw new Error(j.message ?? 'Failed');
      showToast(`Invoice ${j.data?.invoiceNumber ?? ''} created`, true);
      setSelected(new Set());
      void loadEntries();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Invoice failed', false);
    }
    setInvoiceBusy(false);
  };

  /* ─── Render ─────────────────────────────────────────────────────────────── */
  return (
    <AppLayout>
      <div className="p-6 max-w-7xl mx-auto space-y-5">

        {/* Header */}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <Clock className="w-7 h-7 text-blue-600 dark:text-blue-400" />
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Timesheets</h1>
          </div>
          <div className="flex items-center gap-2">
            {selected.size > 0 && (
              <button
                onClick={() => void handleCreateInvoice()}
                disabled={invoiceBusy}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-60 text-sm"
              >
                {invoiceBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
                Create Invoice ({selected.size})
              </button>
            )}
            <button
              onClick={() => setShowForm(true)}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm"
            >
              <Plus className="w-4 h-4" /> Add Entry
            </button>
          </div>
        </div>

        {/* Toast */}
        {toast && (
          <div className={`flex items-center justify-between p-3 rounded-lg text-sm ${toast.ok ? 'bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300' : 'bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300'}`}>
            <span className="flex items-center gap-2">
              {toast.ok ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
              {toast.msg}
            </span>
            <button onClick={() => setToast(null)}><X className="w-3.5 h-3.5" /></button>
          </div>
        )}

        {/* Week navigator + filters */}
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-1">
            <button onClick={prevWeek} className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-800">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-sm font-medium text-gray-700 dark:text-gray-300 min-w-[200px] text-center">
              {fmtWeekRange(weekStart)}
            </span>
            <button onClick={nextWeek} className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-800">
              <ChevronRight className="w-4 h-4" />
            </button>
            <button onClick={goToday} className="ml-2 text-xs px-2 py-1 rounded border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800">
              Today
            </button>
          </div>
          <select
            value={filterCustomer}
            onChange={e => setFilterCustomer(e.target.value)}
            className="text-sm border border-gray-300 dark:border-gray-600 rounded px-2 py-1.5 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300"
          >
            <option value="">All Customers</option>
            {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </div>

        {/* Summary bar */}
        <div className="grid grid-cols-3 gap-4">
          {[
            { label: 'Total Hours', value: totalHours.toFixed(2), color: 'text-gray-900 dark:text-white' },
            { label: 'Billable', value: billableHours.toFixed(2), color: 'text-emerald-600 dark:text-emerald-400' },
            { label: 'Non-Billable', value: nonBillable.toFixed(2), color: 'text-amber-600 dark:text-amber-400' },
          ].map(s => (
            <div key={s.label} className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4 text-center">
              <p className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">{s.label}</p>
              <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
            </div>
          ))}
        </div>

        {/* Select-all + bulk hint */}
        {eligibleIds.length > 0 && (
          <div className="flex items-center gap-3 text-sm text-gray-500 dark:text-gray-400">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={selected.size === eligibleIds.length && eligibleIds.length > 0}
                onChange={toggleAll}
                className="rounded"
              />
              Select all billable uninvoiced ({eligibleIds.length})
            </label>
          </div>
        )}

        {/* Week grid */}
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
          </div>
        ) : (
          <div className="grid grid-cols-7 gap-2">
            {weekDates.map((date, i) => {
              const isoKey = fmtISO(date);
              const dayEntries = byDate[isoKey] ?? [];
              const dayHours = dayEntries.reduce((s, e) => s + e.hours, 0);
              const isToday = isoKey === fmtISO(new Date());

              return (
                <div
                  key={isoKey}
                  className={`rounded-xl border p-3 space-y-2 min-h-[140px] ${isToday ? 'border-blue-400 dark:border-blue-500 bg-blue-50/30 dark:bg-blue-900/10' : 'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800'}`}
                >
                  {/* Day header */}
                  <div className="text-center">
                    <p className={`text-xs font-semibold ${isToday ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>
                      {WEEK_DAYS[i]}
                    </p>
                    <p className={`text-sm ${isToday ? 'text-blue-700 dark:text-blue-300 font-bold' : 'text-gray-700 dark:text-gray-300'}`}>
                      {fmtDisplay(date).split(',')[0]}
                    </p>
                    {dayHours > 0 && (
                      <p className="text-xs text-gray-400 mt-0.5">{dayHours.toFixed(1)}h</p>
                    )}
                  </div>

                  {/* Entries */}
                  <div className="space-y-1.5">
                    {dayEntries.map(entry => (
                      <div
                        key={entry.id}
                        className={`rounded-lg p-2 text-xs border ${entry.billable ? 'border-emerald-200 dark:border-emerald-800 bg-emerald-50 dark:bg-emerald-900/20' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30'}`}
                      >
                        <div className="flex items-start justify-between gap-1">
                          {entry.billable && !entry.invoiced && (
                            <input
                              type="checkbox"
                              checked={selected.has(entry.id)}
                              onChange={() => toggleSelect(entry.id)}
                              className="mt-0.5 rounded flex-shrink-0"
                            />
                          )}
                          <div className="flex-1 min-w-0">
                            <p className="font-medium text-gray-800 dark:text-gray-200 truncate" title={entry.taskDescription}>
                              {entry.taskDescription}
                            </p>
                            {entry.customerName && (
                              <p className="text-gray-500 dark:text-gray-400 truncate">{entry.customerName}</p>
                            )}
                            {entry.projectName && (
                              <p className="text-gray-400 dark:text-gray-500 truncate">{entry.projectName}</p>
                            )}
                          </div>
                        </div>
                        <div className="flex items-center justify-between mt-1">
                          <span className="font-semibold text-gray-700 dark:text-gray-300">{entry.hours}h</span>
                          <span className={`px-1 rounded text-[10px] ${entry.invoiced ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400' : entry.billable ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}>
                            {entry.invoiced ? 'invoiced' : entry.billable ? 'billable' : 'non-bill'}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Quick add for this day */}
                  <button
                    onClick={() => { setForm({ ...BLANK_FORM, entryDate: isoKey }); setShowForm(true); }}
                    className="w-full text-xs text-gray-400 dark:text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 py-1"
                  >
                    + add
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Add Entry modal */}
        {showForm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl w-full max-w-lg p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Add Time Entry</h2>
                <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <form onSubmit={e => void handleSubmitForm(e)} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Description <span className="text-red-500">*</span>
                  </label>
                  <input
                    value={form.taskDescription}
                    onChange={e => fc('taskDescription', e.target.value)}
                    required
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    placeholder="What did you work on?"
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
                    <input
                      type="date"
                      value={form.entryDate}
                      onChange={e => fc('entryDate', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      Hours <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number" step="0.25" min="0.25"
                      value={form.hours}
                      onChange={e => fc('hours', e.target.value)}
                      required
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      placeholder="1.5"
                    />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Customer</label>
                    <select
                      value={form.customerId}
                      onChange={e => fc('customerId', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    >
                      <option value="">— None —</option>
                      {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Rate (R/h)</label>
                    <input
                      type="number" min="0" step="0.01"
                      value={form.rate}
                      onChange={e => fc('rate', e.target.value)}
                      className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      placeholder="0.00"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Project</label>
                  <input
                    value={form.projectName}
                    onChange={e => fc('projectName', e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    placeholder="Optional project name"
                  />
                </div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.billable}
                    onChange={e => fc('billable', e.target.checked)}
                    className="rounded"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Billable</span>
                </label>
                <div className="flex gap-2 pt-2">
                  <button type="button" onClick={() => setShowForm(false)}
                    className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800">
                    Cancel
                  </button>
                  <button type="submit" disabled={formBusy}
                    className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 disabled:opacity-60 flex items-center justify-center gap-2">
                    {formBusy ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
                    Save Entry
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

