              onToggleAll={toggleAll}
            />
          )}
        </div>
      </div>

      {showModal && (
        <ConfirmSendModal
          count={eligibleCount}
          asAtDate={asAtDate}
          isSending={isSending}
          onConfirm={() => { void handleSend(); }}
          onCancel={() => setShowModal(false)}
        />
      )}
    </AppLayout>
  );
}

