/**
 * Delivery Notes API
 * GET    — list delivery notes (status filter, pagination)
 * GET    — single note (?id=UUID)
 * POST   — create new delivery note
 * PATCH  — update status
 * DELETE — soft-delete (cancel)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import {
  withCompany,
  withWriteAccess,
  type CompanyApiRequest,
  type AuthenticatedNextApiRequest,
} from '@/lib/auth';
import {
  getDeliveryNotes,
  getDeliveryNote,
  createDeliveryNote,
  updateDeliveryNoteStatus,
  cancelDeliveryNote,
  type DeliveryNoteInput,
} from '@/modules/accounting/services/deliveryNoteService';
import { log } from '@/lib/logger';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { id, status, limit, offset } = req.query;

    if (id) {
      const note = await getDeliveryNote(companyId, id as string);
      if (!note) return apiResponse.notFound(res, 'Delivery Note', id as string);
      return apiResponse.success(res, note);
    }

    const result = await getDeliveryNotes(companyId, {
      status: status as string | undefined,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = String(req.user.id);
    const input = req.body as DeliveryNoteInput;

    if (!input.customer_id) return apiResponse.badRequest(res, 'customer_id is required');
    if (!Array.isArray(input.lines) || input.lines.length === 0) {
      return apiResponse.badRequest(res, 'At least one line item is required');
    }
    const validLines = input.lines.filter((l) => l.description?.trim());
    if (validLines.length === 0) {
      return apiResponse.badRequest(res, 'At least one line with a description is required');
    }

    log.info('Creating delivery note', { companyId, customerId: input.customer_id });
    const note = await createDeliveryNote(companyId, { ...input, lines: validLines }, userId);
    return apiResponse.created(res, note);
  }

  if (req.method === 'PATCH') {
    const { id, status } = req.body as { id?: string; status?: string };
    if (!id) return apiResponse.badRequest(res, 'id is required');
    if (!status) return apiResponse.badRequest(res, 'status is required');

    const allowed = ['draft', 'dispatched', 'delivered', 'cancelled'];
    if (!allowed.includes(status)) {
      return apiResponse.badRequest(res, `status must be one of: ${allowed.join(', ')}`);
    }

    log.info('Updating delivery note status', { companyId, id, status });
    const note = await updateDeliveryNoteStatus(companyId, id, status);
    if (!note) return apiResponse.notFound(res, 'Delivery Note', id);
    return apiResponse.success(res, note);
  }

  if (req.method === 'DELETE') {
    const { id } = req.body as { id?: string };
    if (!id) return apiResponse.badRequest(res, 'id is required');

    log.info('Cancelling delivery note', { companyId, id });
    const cancelled = await cancelDeliveryNote(companyId, id);
    if (!cancelled) return apiResponse.badRequest(res, 'Delivery note not found or already cancelled');
    return apiResponse.success(res, { cancelled: true });
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST', 'PATCH', 'DELETE']);
}

export default withCompany(withErrorHandler(withWriteAccess(handler as never)));

/**
 * Item Bundles API
 * GET    ?itemId=<id>  — list bundle lines for a parent item
 * POST                 — upsert bundle lines { item_id, lines: [{ child_item_id, quantity }] }
 * DELETE ?itemId=<id>  — remove all bundle lines and clear is_bundle flag
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess } from '@/lib/auth';
import { itemExists } from '@/modules/accounting/services/itemService';
import {
  getBundleLines,
  upsertBundleLines,
  deleteBundleLines,
  type BundleLine,
} from '@/modules/accounting/services/itemBundleService';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const companyId = req.companyId;

  /* ------------------------------------------------------------------ */
  /*  GET — fetch bundle lines for an item                               */
  /* ------------------------------------------------------------------ */
  if (req.method === 'GET') {
    const itemId = req.query.itemId ? String(req.query.itemId) : '';
    if (!itemId) {
      return apiResponse.badRequest(res, 'itemId query parameter is required');
    }
    const exists = await itemExists(companyId, itemId);
    if (!exists) return apiResponse.notFound(res, 'Item', itemId);

    const lines = await getBundleLines(companyId, itemId);
    return apiResponse.success(res, lines);
  }

  /* ------------------------------------------------------------------ */
  /*  POST — upsert bundle lines                                         */
  /* ------------------------------------------------------------------ */
  if (req.method === 'POST') {
    const body = req.body as Record<string, unknown>;
    const itemId = body.item_id ? String(body.item_id) : '';
    if (!itemId) {
      return apiResponse.validationError(res, { item_id: 'item_id is required' });
    }

    const exists = await itemExists(companyId, itemId);
    if (!exists) return apiResponse.notFound(res, 'Item', itemId);

    if (!Array.isArray(body.lines)) {
      return apiResponse.validationError(res, { lines: 'lines must be an array' });
    }

    const rawLines = body.lines as Record<string, unknown>[];
    const lines: BundleLine[] = [];

    for (let i = 0; i < rawLines.length; i++) {
      const l = rawLines[i];
      if (!l) continue;
      const childId = l.child_item_id ? String(l.child_item_id) : '';
      if (!childId) {
        return apiResponse.validationError(res, {
          lines: `Line ${i}: child_item_id is required`,
        });
      }
      if (childId === itemId) {
        return apiResponse.validationError(res, {
          lines: `Line ${i}: an item cannot be a component of itself`,
        });
      }
      const childExists = await itemExists(companyId, childId);
      if (!childExists) {
        return apiResponse.validationError(res, {
          lines: `Line ${i}: child item ${childId} not found`,
        });
      }
      const qty = Number(l.quantity);
      if (!qty || qty <= 0) {
        return apiResponse.validationError(res, {
          lines: `Line ${i}: quantity must be a positive number`,
        });
      }
      lines.push({ child_item_id: childId, quantity: qty, sort_order: i });
    }

    const result = await upsertBundleLines(companyId, itemId, lines);
    return apiResponse.success(res, result);
  }

  /* ------------------------------------------------------------------ */
  /*  DELETE — remove all bundle lines for an item                       */
  /* ------------------------------------------------------------------ */
  if (req.method === 'DELETE') {
    const itemId = req.query.itemId ? String(req.query.itemId) : '';
    if (!itemId) {
      return apiResponse.badRequest(res, 'itemId query parameter is required');
    }
    const exists = await itemExists(companyId, itemId);
    if (!exists) return apiResponse.notFound(res, 'Item', itemId);

    await deleteBundleLines(companyId, itemId);
    return apiResponse.success(res, { item_id: itemId, deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'DELETE']);
}

export default withCompany(withErrorHandler(withWriteAccess(handler as Parameters<typeof withWriteAccess>[0] )));

/**
 * Supplier Contacts API
 * GET    ?supplierId=X  — list contacts for a supplier
 * POST                  — create a new contact
 * DELETE ?id=X          — delete a contact
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

interface CreateBody {
  supplierId: string;
  fullName: string;
  role?: string;
  email?: string;
  phone?: string;
  isPrimary?: boolean;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  // ─── GET: List contacts for a supplier ─────────────────────────────────────
  if (req.method === 'GET') {
    const { supplierId } = req.query;
    if (!supplierId || typeof supplierId !== 'string') {
      return apiResponse.badRequest(res, 'supplierId is required');
    }

    try {
      const rows = (await sql`
        SELECT id, supplier_id, full_name, role, email, phone, is_primary, created_at
        FROM supplier_contacts
        WHERE supplier_id = ${supplierId}
          AND company_id  = ${companyId}
        ORDER BY is_primary DESC, full_name ASC
      `) as Row[];

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      if (message.includes('does not exist')) return apiResponse.success(res, []);
      log.error('supplier-contacts GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch contacts');
    }
  }

  // ─── POST: Create contact ───────────────────────────────────────────────────
  if (req.method === 'POST') {
    const body = req.body as CreateBody;
    const { supplierId, fullName } = body;

    if (!supplierId?.trim()) return apiResponse.badRequest(res, 'supplierId is required');
    if (!fullName?.trim())   return apiResponse.badRequest(res, 'fullName is required');

    const s = (v: string | undefined) => (v?.trim() || null);
    const isPrimary = body.isPrimary === true;

    try {
      // If marking as primary, clear existing primary first
      if (isPrimary) {
        await sql`
          UPDATE supplier_contacts
          SET is_primary = false
          WHERE supplier_id = ${supplierId} AND company_id = ${companyId}
        `;
      }

      const rows = (await sql`
        INSERT INTO supplier_contacts (
          supplier_id, company_id, full_name, role, email, phone, is_primary
        ) VALUES (
          ${supplierId}, ${companyId}, ${fullName.trim()},
          ${s(body.role)}, ${s(body.email)}, ${s(body.phone)}, ${isPrimary}
        )
        RETURNING *
      `) as Row[];

      log.info('Supplier contact created', { id: rows[0]?.id, supplierId, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('supplier-contacts POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create contact');
    }
  }

  // ─── DELETE: Remove contact ─────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    const { id } = req.query;
    if (!id || typeof id !== 'string') return apiResponse.badRequest(res, 'id is required');

    try {
      await sql`
        DELETE FROM supplier_contacts
        WHERE id = ${id} AND company_id = ${companyId}
      `;
      return apiResponse.success(res, { deleted: true });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('supplier-contacts DELETE failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to delete contact');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

export default withCompany(withErrorHandler(withWriteAccess(handler as never)));

/**
 * Supplier Activities API
 * GET    ?supplierId=X[&limit=50]  — list activities (newest first) with creator info
 * POST                             — create a new activity (created_by = authenticated user)
 * DELETE ?id=X                    — delete activity (own or admin/owner/manager role)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

type ActivityType =
  | 'note'
  | 'call'
  | 'email_sent'
  | 'email_received'
  | 'payment_made'
  | 'invoice_received'
  | 'status_change';

const VALID_ACTIVITY_TYPES = new Set<ActivityType>([
  'note', 'call', 'email_sent', 'email_received',
  'payment_made', 'invoice_received', 'status_change',
]);

interface CreateBody {
  supplierId: string;
  activity_type: ActivityType;
  subject?: string;
  description: string;
}

function isActivityType(v: unknown): v is ActivityType {
  return typeof v === 'string' && VALID_ACTIVITY_TYPES.has(v as ActivityType);
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId, user } = req as CompanyApiRequest;

  // ─── GET: List activities for a supplier ───────────────────────────────────
  if (req.method === 'GET') {
    const { supplierId, limit } = req.query;
    if (!supplierId || typeof supplierId !== 'string') {
      return apiResponse.badRequest(res, 'supplierId is required');
    }

    const limitNum = Math.min(parseInt(typeof limit === 'string' ? limit : '50', 10) || 50, 200);

    try {
      const rows = (await sql`
        SELECT
          sa.id,
          sa.supplier_id,
          sa.activity_type,
          sa.subject,
          sa.description,
          sa.created_at,
          sa.created_by,
          u.email        AS created_by_email,
          u.first_name   AS created_by_first_name,
          u.last_name    AS created_by_last_name
        FROM supplier_activities sa
        LEFT JOIN users u ON u.id = sa.created_by
        WHERE sa.supplier_id = ${supplierId}
          AND sa.company_id  = ${companyId}
        ORDER BY sa.created_at DESC
        LIMIT ${limitNum}
      `) as Row[];

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      if (message.includes('does not exist')) return apiResponse.success(res, []);
      log.error('supplier-activities GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch activities');
    }
  }

  // ─── POST: Create activity ─────────────────────────────────────────────────
  if (req.method === 'POST') {
    const body = req.body as CreateBody;
    const { supplierId, activity_type, description } = body;

    if (!supplierId?.trim()) return apiResponse.badRequest(res, 'supplierId is required');
    if (!isActivityType(activity_type)) {
      return apiResponse.badRequest(
        res,
        `activity_type must be one of: ${[...VALID_ACTIVITY_TYPES].join(', ')}`,
      );
    }
    if (!description?.trim()) return apiResponse.badRequest(res, 'description is required');

    const subject = body.subject?.trim() || null;

    try {
      const rows = (await sql`
        INSERT INTO supplier_activities (
          supplier_id, company_id, activity_type, subject, description, created_by
        ) VALUES (
          ${supplierId}, ${companyId}, ${activity_type}, ${subject}, ${description.trim()}, ${user.id}
        )
        RETURNING *
      `) as Row[];

      log.info('Supplier activity created', {
        id: rows[0]?.id,
        supplierId,
        activity_type,
        module: 'accounting',
      });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('supplier-activities POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create activity');
    }
  }

  // ─── DELETE: Remove activity ───────────────────────────────────────────────
  if (req.method === 'DELETE') {
    const { id } = req.query;
    if (!id || typeof id !== 'string') return apiResponse.badRequest(res, 'id is required');

    const companyReq = req as CompanyApiRequest;
    const isPrivileged = ['owner', 'admin', 'manager'].includes(companyReq.companyRole);

    try {
      const result = isPrivileged
        ? (await sql`
            DELETE FROM supplier_activities
            WHERE id = ${id} AND company_id = ${companyId}
            RETURNING id
          `) as Row[]
        : (await sql`
            DELETE FROM supplier_activities
            WHERE id = ${id} AND company_id = ${companyId} AND created_by = ${user.id}
            RETURNING id
          `) as Row[];

      if (result.length === 0) {
        return apiResponse.forbidden(res, 'Activity not found or you do not have permission to delete it');
      }

      return apiResponse.success(res, { deleted: true });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('supplier-activities DELETE failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to delete activity');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

export default withCompany(withErrorHandler(withWriteAccess(handler as never)));

/**
 * Customer Statements Bulk Send API
 * POST /api/accounting/customer-statements-send
 * Body: { customer_ids: string[], as_at_date: string, message?: string }
 * Returns: { sent: number, failed: number, errors: string[] }
 *
 * Fetches each customer's statement and emails it via statementEmailService.
 * All queries are company_id scoped.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { sendStatementEmail } from '@/modules/accounting/services/statementEmailService';

type Row = Record<string, unknown>;

async function getCompanyName(companyId: string): Promise<string> {
  try {
    const rows = await sql`
      SELECT value FROM accounting_settings
      WHERE company_id = ${companyId}::UUID AND key = 'company_name'
      LIMIT 1
    ` as Row[];
    return rows[0]?.value ? String(rows[0].value) : 'ISAFlow';
  } catch {
    return 'ISAFlow';
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  const body = req.body as {
    customer_ids?: unknown;
    as_at_date?: unknown;
    message?: unknown;
  };

  // Validate input
  if (!Array.isArray(body.customer_ids) || body.customer_ids.length === 0) {
    return apiResponse.badRequest(res, 'customer_ids must be a non-empty array');
  }

  const customerIds = body.customer_ids as unknown[];
  if (customerIds.some(id => typeof id !== 'string')) {
    return apiResponse.badRequest(res, 'all customer_ids must be strings');
  }

  const validIds = customerIds as string[];

  if (typeof body.as_at_date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(body.as_at_date)) {
    return apiResponse.badRequest(res, 'as_at_date must be a valid YYYY-MM-DD date string');
  }

  const asAtDate = body.as_at_date;
  const message = typeof body.message === 'string' ? body.message : undefined;

  // Verify all requested customer IDs belong to this company (IDOR guard)
  const owned = await sql`
    SELECT id FROM customers
    WHERE id = ANY(${validIds}::UUID[]) AND company_id = ${companyId}::UUID
  ` as Row[];

  const ownedIds = new Set(owned.map(r => String(r.id)));
  const unauthorized = validIds.filter(id => !ownedIds.has(id));
  if (unauthorized.length > 0) {
    log.warn('Unauthorized customer_ids in statement send request', {
      companyId,
      unauthorized,
    }, 'customer-statements-send');
    return apiResponse.forbidden(res, 'One or more customer IDs do not belong to this company');
  }

  const companyName = await getCompanyName(companyId);

  let sent = 0;
  let failed = 0;
  const errors: string[] = [];

  log.info('Starting bulk statement send', {
    companyId,
    count: validIds.length,
    asAtDate,
  }, 'customer-statements-send');

  for (const customerId of validIds) {
    const result = await sendStatementEmail(
      companyId,
      customerId,
      asAtDate,
      companyName,
      message
    );

    if (result.success) {
      sent++;
    } else {
      failed++;
      errors.push(result.error ?? `Failed to send to customer ${customerId}`);
    }
  }

  log.info('Bulk statement send complete', { sent, failed }, 'customer-statements-send');

  return apiResponse.success(res, { sent, failed, errors });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Recurring Invoices Run API
 * POST — run one recurring invoice by ID, or all currently due
 * Body: { recurring_invoice_id?: string }
 * Returns: { generated: number; invoice_ids: string[]; errors: string[] }
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import {
  withCompany,
  withWriteAccess,
  type AuthenticatedNextApiRequest,
  type CompanyApiRequest,
} from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { generateInvoiceFromRecurring } from '@/modules/accounting/services/recurringInvoiceService';
import type { DbRow } from '@/lib/neon';

interface RunResult {
  generated: number;
  invoice_ids: string[];
  errors: string[];
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const userId = req.user.id;
  const { recurring_invoice_id } = req.body as { recurring_invoice_id?: string };

  const result: RunResult = { generated: 0, invoice_ids: [], errors: [] };

  if (recurring_invoice_id) {
    // Run a single recurring invoice
    try {
      const invoiceId = await generateInvoiceFromRecurring(companyId, recurring_invoice_id, userId);
      result.generated = 1;
      result.invoice_ids = [invoiceId];
      log.info('Single recurring invoice run', { recurring_invoice_id, invoiceId }, 'recurring-run');
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to generate invoice';
      result.errors.push(`${recurring_invoice_id}: ${msg}`);
      log.error('Recurring invoice run failed', { recurring_invoice_id, error: err }, 'recurring-run');
    }
    return apiResponse.success(res, result);
  }

  // Run all due — next_run_date <= today, status = 'active'
  const dueRows = (await sql`
    SELECT id
    FROM recurring_invoices
    WHERE company_id = ${companyId}
      AND status = 'active'
      AND next_run_date <= CURRENT_DATE
    ORDER BY next_run_date ASC
  `) as DbRow[];

  if (dueRows.length === 0) {
    log.info('No due recurring invoices to run', { companyId }, 'recurring-run');
    return apiResponse.success(res, result);
  }

  for (const row of dueRows) {
    const id = String(row.id);
    try {
      const invoiceId = await generateInvoiceFromRecurring(companyId, id, userId);
      result.generated += 1;
      result.invoice_ids.push(invoiceId);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to generate invoice';
      result.errors.push(`${id}: ${msg}`);
      log.error('Bulk recurring run — single item failed', { id, error: err }, 'recurring-run');
    }
  }

  log.info('Bulk recurring invoice run complete', {
    total: dueRows.length,
    generated: result.generated,
    errors: result.errors.length,
  }, 'recurring-run');

  return apiResponse.success(res, result);
}

export default withCompany(withErrorHandler(withWriteAccess(handler as never)));

/**
 * Item Bundle Service — CRUD for item bundle lines
 * All queries scoped to company_id for multi-tenant safety.
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = DbRow;

export interface BundleLine {
  child_item_id: string;
  quantity: number;
  sort_order?: number;
}

export interface BundleLineRow {
  id: string;
  company_id: string;
  parent_item_id: string;
  child_item_id: string;
  quantity: number;
  sort_order: number;
  created_at: string;
  // joined from items
  child_code: string | null;
  child_description: string | null;
  child_unit: string | null;
  child_selling_price_excl: number | null;
}

export async function getBundleLines(
  companyId: string,
  parentItemId: string
): Promise<BundleLineRow[]> {
  const rows = await sql`
    SELECT
      bl.id,
      bl.company_id,
      bl.parent_item_id,
      bl.child_item_id,
      bl.quantity,
      bl.sort_order,
      bl.created_at,
      ci.code            AS child_code,
      ci.description     AS child_description,
      ci.unit            AS child_unit,
      ci.selling_price_excl AS child_selling_price_excl
    FROM item_bundle_lines bl
    JOIN items ci ON ci.id = bl.child_item_id
    WHERE bl.company_id = ${companyId}
      AND bl.parent_item_id = ${parentItemId}
    ORDER BY bl.sort_order ASC, bl.created_at ASC
  ` as Row[];
  return rows as unknown as BundleLineRow[];
}

export async function upsertBundleLines(
  companyId: string,
  parentItemId: string,
  lines: BundleLine[]
): Promise<BundleLineRow[]> {
  // Delete existing lines then re-insert (replace strategy)
  await sql`
    DELETE FROM item_bundle_lines
    WHERE company_id = ${companyId}
      AND parent_item_id = ${parentItemId}
  `;

  if (lines.length > 0) {
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!;
      await sql`
        INSERT INTO item_bundle_lines
          (company_id, parent_item_id, child_item_id, quantity, sort_order)
        VALUES
          (${companyId}, ${parentItemId}, ${line.child_item_id},
           ${line.quantity}, ${line.sort_order ?? i})
      `;
    }
  }

  // Mark parent as bundle
  await sql`
    UPDATE items
    SET is_bundle = true, updated_at = NOW()
    WHERE id = ${parentItemId} AND company_id = ${companyId}
  `;

  log.info('Bundle lines upserted', { parentItemId, lineCount: lines.length, companyId }, 'accounting');
  return getBundleLines(companyId, parentItemId);
}

export async function deleteBundleLines(
  companyId: string,
  parentItemId: string
): Promise<void> {
  await sql`
    DELETE FROM item_bundle_lines
    WHERE company_id = ${companyId}
      AND parent_item_id = ${parentItemId}
  `;
  await sql`
    UPDATE items
    SET is_bundle = false, updated_at = NOW()
    WHERE id = ${parentItemId} AND company_id = ${companyId}
  `;
  log.info('Bundle lines deleted', { parentItemId, companyId }, 'accounting');
}

export async function expandBundle(
  companyId: string,
  parentItemId: string
): Promise<BundleLineRow[]> {
  return getBundleLines(companyId, parentItemId);
}

/**
 * Delivery Note Service — CRUD with line items
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = DbRow;

export interface DeliveryNoteLine {
  id: string;
  deliveryNoteId: string;
  description: string;
  quantity: number;
  unit: string | null;
  itemId: string | null;
}

export interface DeliveryNote {
  id: string;
  deliveryNoteNumber: string;
  customerId: string;
  customerName: string;
  salesOrderId: string | null;
  invoiceId: string | null;
  deliveryDate: string;
  status: string;
  deliveryAddress: string | null;
  notes: string | null;
  createdBy: string | null;
  createdAt: string;
  updatedAt: string;
  lineCount?: number;
  lines?: DeliveryNoteLine[];
}

export interface DeliveryNoteLineInput {
  description: string;
  quantity: number;
  unit?: string;
  item_id?: string;
}

export interface DeliveryNoteInput {
  customer_id: string;
  sales_order_id?: string;
  invoice_id?: string;
  delivery_date?: string;
  delivery_address?: string;
  notes?: string;
  lines: DeliveryNoteLineInput[];
}

export interface DeliveryNoteFilters {
  status?: string;
  limit?: number;
  offset?: number;
}

function mapNote(r: Row): DeliveryNote {
  return {
    id: String(r.id),
    deliveryNoteNumber: String(r.delivery_note_number),
    customerId: String(r.customer_id),
    customerName: r.customer_name ? String(r.customer_name) : '',
    salesOrderId: r.sales_order_id != null ? String(r.sales_order_id) : null,
    invoiceId: r.invoice_id != null ? String(r.invoice_id) : null,
    deliveryDate:
      r.delivery_date instanceof Date
        ? r.delivery_date.toISOString().split('T')[0]!
        : String(r.delivery_date).split('T')[0]!,
    status: String(r.status),
    deliveryAddress: r.delivery_address != null ? String(r.delivery_address) : null,
    notes: r.notes != null ? String(r.notes) : null,
    createdBy: r.created_by != null ? String(r.created_by) : null,
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
    lineCount: r.line_count != null ? Number(r.line_count) : undefined,
  };
}

function mapLine(r: Row): DeliveryNoteLine {
  return {
    id: String(r.id),
    deliveryNoteId: String(r.delivery_note_id),
    description: String(r.description),
    quantity: Number(r.quantity),
    unit: r.unit != null ? String(r.unit) : null,
    itemId: r.item_id != null ? String(r.item_id) : null,
  };
}

async function nextDeliveryNoteNumber(companyId: string): Promise<string> {
  const rows = (await sql`
    INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number)
    VALUES (${companyId}::UUID, 'delivery_note', 'DN-', 1)
    ON CONFLICT (company_id, document_type)
    DO UPDATE SET next_number = company_document_numbers.next_number + 1
    RETURNING next_number - 1 AS current_number, prefix
  `) as Row[];

  if (rows.length === 0) return 'DN-00001';
  const num = Number(rows[0]!.current_number);
  const prefix = String(rows[0]!.prefix || 'DN-');
  return `${prefix}${String(num).padStart(5, '0')}`;
}

export async function getDeliveryNotes(
  companyId: string,
  filters?: DeliveryNoteFilters,
): Promise<{ notes: DeliveryNote[]; total: number }> {
  const limit = filters?.limit ?? 100;
  const offset = filters?.offset ?? 0;

  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT dn.*, c.name AS customer_name,
             COUNT(dnl.id) AS line_count
      FROM delivery_notes dn
      LEFT JOIN customers c ON c.id = dn.customer_id
      LEFT JOIN delivery_note_lines dnl ON dnl.delivery_note_id = dn.id
      WHERE dn.company_id = ${companyId}::UUID
        AND dn.status = ${filters.status}
      GROUP BY dn.id, c.name
      ORDER BY dn.delivery_date DESC
      LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM delivery_notes
      WHERE company_id = ${companyId}::UUID AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT dn.*, c.name AS customer_name,
             COUNT(dnl.id) AS line_count
      FROM delivery_notes dn
      LEFT JOIN customers c ON c.id = dn.customer_id
      LEFT JOIN delivery_note_lines dnl ON dnl.delivery_note_id = dn.id
      WHERE dn.company_id = ${companyId}::UUID
      GROUP BY dn.id, c.name
      ORDER BY dn.delivery_date DESC
      LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM delivery_notes
      WHERE company_id = ${companyId}::UUID
    `) as Row[];
  }

  return {
    notes: rows.map(mapNote),
    total: Number(countRows[0]?.cnt ?? 0),
  };
}

export async function getDeliveryNote(
  companyId: string,
  id: string,
): Promise<DeliveryNote | null> {
  const rows = (await sql`
    SELECT dn.*, c.name AS customer_name
    FROM delivery_notes dn
    LEFT JOIN customers c ON c.id = dn.customer_id
    WHERE dn.id = ${id}::UUID AND dn.company_id = ${companyId}::UUID
  `) as Row[];

  if (rows.length === 0) return null;
  const note = mapNote(rows[0]!);

  const lineRows = (await sql`
    SELECT * FROM delivery_note_lines
    WHERE delivery_note_id = ${id}::UUID
    ORDER BY created_at ASC
  `) as Row[];

  note.lines = lineRows.map(mapLine);
  return note;
}

export async function createDeliveryNote(
  companyId: string,
  input: DeliveryNoteInput,
  userId: string,
): Promise<DeliveryNote> {
  if (!input.customer_id) throw new Error('customer_id is required');
  if (!Array.isArray(input.lines) || input.lines.length === 0) {
    throw new Error('At least one line is required');
  }

  const noteNumber = await nextDeliveryNoteNumber(companyId);
  const deliveryDate = input.delivery_date ?? new Date().toISOString().split('T')[0];

  log.info('Creating delivery note', { companyId, noteNumber, customerId: input.customer_id });

  const salesOrderId = input.sales_order_id ?? null;
  const invoiceId = input.invoice_id ?? null;

  const noteRows = (await sql`
    INSERT INTO delivery_notes (
      company_id, customer_id, sales_order_id, invoice_id,
      delivery_note_number, delivery_date, delivery_address, notes, created_by
    ) VALUES (
      ${companyId}::UUID,
      ${input.customer_id}::UUID,
      ${salesOrderId}::UUID,
      ${invoiceId}::UUID,
      ${noteNumber},
      ${deliveryDate}::DATE,
      ${input.delivery_address ?? null},
      ${input.notes ?? null},
      ${userId}
    )
    RETURNING *
  `) as Row[];

  const noteId = String(noteRows[0]!.id);

  for (const line of input.lines) {
    const lineItemId = line.item_id ?? null;
    await sql`
      INSERT INTO delivery_note_lines (delivery_note_id, description, quantity, unit, item_id)
      VALUES (
        ${noteId}::UUID,
        ${line.description},
        ${line.quantity},
        ${line.unit ?? null},
        ${lineItemId}::UUID
      )
    `;
  }

  const created = await getDeliveryNote(companyId, noteId);
  if (!created) throw new Error('Failed to retrieve created delivery note');
  return created;
}

export async function updateDeliveryNoteStatus(
  companyId: string,
  id: string,
  status: string,
): Promise<DeliveryNote | null> {
  const allowed = ['draft', 'dispatched', 'delivered', 'cancelled'];
  if (!allowed.includes(status)) throw new Error(`Invalid status: ${status}`);

  const rows = (await sql`
    UPDATE delivery_notes
    SET status = ${status}, updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
    RETURNING id
  `) as Row[];

  if (rows.length === 0) return null;
  return getDeliveryNote(companyId, id);
}

export async function cancelDeliveryNote(
  companyId: string,
  id: string,
): Promise<boolean> {
  const rows = (await sql`
    UPDATE delivery_notes
    SET status = 'cancelled', updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
      AND status != 'cancelled'
    RETURNING id
  `) as Row[];

  return rows.length > 0;
}

/**
 * Supplier Detail Page
 * View supplier information
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Building2, Loader2, AlertCircle, CheckCircle2, XCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface Supplier {
  id: string;
  name: string;
  company_name: string | null;
  email: string | null;
  phone: string | null;
  contact_person: string | null;
  vat_number: string | null;
  payment_terms: number | null;
  is_active: boolean;
  created_at: string;
}

export default function SupplierDetailPage() {
  const router = useRouter();
  const { supplierId } = router.query;
  const [supplier, setSupplier] = useState<Supplier | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!supplierId) return;
    loadSupplier();
  }, [supplierId]);

  const loadSupplier = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/suppliers-list?id=${supplierId}`);
      const json = await res.json();
      const data = json.data || json;
      // API may return a single object or an array — find matching record
      if (Array.isArray(data)) {
        const match = data.find((s: Supplier) => s.id === supplierId);
        setSupplier(match || null);
        if (!match) setError('Supplier not found');
      } else {
        setSupplier(data);
      }
    } catch {
      setError('Failed to load supplier');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
        </div>
      </AppLayout>
    );
  }

  if (!supplier) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh] flex-col">
          <AlertCircle className="h-8 w-8 text-red-400 mb-2" />
          <p className="text-[var(--ff-text-secondary)]">{error || 'Supplier not found'}</p>
          <Link href="/accounting/suppliers" className="mt-4 text-sm text-blue-400 hover:text-blue-300">
            Back to Suppliers
          </Link>
        </div>
      </AppLayout>
    );
  }

  const fields: { label: string; value: string | number | null | undefined; highlight?: boolean }[] = [
    { label: 'Name', value: supplier.name, highlight: true },
    { label: 'Company Name', value: supplier.company_name },
    { label: 'Email', value: supplier.email },
    { label: 'Phone', value: supplier.phone },
    { label: 'Contact Person', value: supplier.contact_person },
    { label: 'VAT Number', value: supplier.vat_number },
    { label: 'Payment Terms', value: supplier.payment_terms ? `${supplier.payment_terms} days` : null },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/suppliers" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Suppliers
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <Building2 className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{supplier.name}</h1>
              {supplier.company_name && (
                <p className="text-sm text-[var(--ff-text-secondary)]">{supplier.company_name}</p>
              )}
            </div>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${supplier.is_active ? 'bg-teal-500/20 text-teal-400' : 'bg-gray-500/20 text-gray-400'}`}>
              {supplier.is_active ? 'Active' : 'Inactive'}
            </span>
          </div>
        </div>

        {/* Details */}
        <div className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {fields.map((f, i) => (
              <div key={i} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{f.label}</p>
                <p className={`text-lg font-semibold mt-1 ${f.highlight ? 'text-blue-400' : 'text-[var(--ff-text-primary)]'}`}>
                  {f.value || '—'}
                </p>
              </div>
            ))}
          </div>

          {/* Status card */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
            <p className="text-xs text-[var(--ff-text-tertiary)] uppercase mb-2">Status</p>
            <div className="flex items-center gap-2">
              {supplier.is_active
                ? <><CheckCircle2 className="h-5 w-5 text-teal-400" /><span className="text-sm text-teal-400 font-medium">Active Supplier</span></>
                : <><XCircle className="h-5 w-5 text-gray-400" /><span className="text-sm text-gray-400 font-medium">Inactive Supplier</span></>
              }
            </div>
            {supplier.created_at && (
              <p className="text-xs text-[var(--ff-text-tertiary)] mt-2">
                Created: {supplier.created_at.split('T')[0]}
              </p>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Statement Email Service
 * Fetches customer statement data and sends it as a formatted HTML email.
 * HTML template is in statementEmailTemplate.ts (kept separate for size).
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';
import { sendEmail } from './emailService';
import type { EmailResult } from './emailService';
import { buildStatementEmailHtml } from './statementEmailTemplate';

type Row = DbRow;

// ─── Types ────────────────────────────────────────────────────────────────────

interface StatementTransaction {
  date: string;
  type: 'invoice' | 'payment' | 'credit_note';
  reference: string;
  debit: number;
  credit: number;
  balance: number;
}

interface StatementPayload {
  customer: { id: string; name: string; email: string | null };
  fromDate: string;
  toDate: string;
  transactions: StatementTransaction[];
  summary: {
    totalInvoiced: number;
    totalPaid: number;
    totalCredits: number;
    balance: number;
  };
}

// ─── Date helper ─────────────────────────────────────────────────────────────

function toISODate(val: unknown): string {
  if (!val) return '1970-01-01';
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? '1970-01-01';
  const s = String(val);
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0] ?? '1970-01-01';
  const d = new Date(s);
  return isNaN(d.getTime()) ? '1970-01-01' : (d.toISOString().split('T')[0] ?? '1970-01-01');
}

const fmtDate = (d: string): string => {
  const parts = d.split('T')[0]?.split('-') ?? [];
  return parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : d;
};

// ─── Statement Fetcher ────────────────────────────────────────────────────────

export async function fetchStatementData(
  companyId: string,
  customerId: string,
  asAtDate: string
): Promise<StatementPayload | null> {
  const oneYearAgo = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000)
    .toISOString().split('T')[0] as string;

  const customerRows = await sql`
    SELECT id, name, email
    FROM customers
    WHERE id = ${customerId}::UUID AND company_id = ${companyId}::UUID
  ` as Row[];

  if (customerRows.length === 0) return null;
  const cust = customerRows[0]!;

  const [invoices, payments, creditNotes] = await Promise.all([
    sql`
      SELECT id, invoice_number, invoice_date, total_amount
      FROM customer_invoices
      WHERE COALESCE(client_id, customer_id) = ${customerId}::UUID
        AND company_id = ${companyId}::UUID
        AND status != 'cancelled'
        AND invoice_date <= ${asAtDate}::DATE
      ORDER BY invoice_date
    ` as Promise<Row[]>,

    sql`
      SELECT cp.id, cp.payment_number, cp.payment_date,
        COALESCE(SUM(cpa.amount_allocated), cp.total_amount) AS amount_allocated
      FROM customer_payments cp
      LEFT JOIN customer_payment_allocations cpa ON cpa.payment_id = cp.id
      WHERE cp.client_id = ${customerId}::UUID
        AND cp.company_id = ${companyId}::UUID
        AND cp.status IN ('confirmed', 'reconciled')
        AND cp.payment_date <= ${asAtDate}::DATE
      GROUP BY cp.id, cp.payment_number, cp.payment_date, cp.total_amount
    ` as Promise<Row[]>,

    sql`
      SELECT id, credit_note_number, credit_date, total_amount
      FROM credit_notes
      WHERE client_id = ${customerId}::UUID
        AND company_id = ${companyId}::UUID
        AND type = 'customer'
        AND status = 'approved'
        AND credit_date <= ${asAtDate}::DATE
    ` as Promise<Row[]>,
  ]);

  const transactions: StatementTransaction[] = [];

  for (const inv of invoices) {
    transactions.push({
      date: toISODate(inv.invoice_date),
      type: 'invoice',
      reference: String(inv.invoice_number ?? ''),
      debit: Number(inv.total_amount),
      credit: 0,
      balance: 0,
    });
  }
  for (const pmt of payments) {
    transactions.push({
      date: toISODate(pmt.payment_date),
      type: 'payment',
      reference: String(pmt.payment_number ?? ''),
      debit: 0,
      credit: Number(pmt.amount_allocated),
      balance: 0,
    });
  }
  for (const cn of creditNotes) {
    transactions.push({
      date: toISODate(cn.credit_date),
      type: 'credit_note',
      reference: String(cn.credit_note_number ?? ''),
      debit: 0,
      credit: Number(cn.total_amount),
      balance: 0,
    });
  }

  const typeOrder: Record<string, number> = { invoice: 0, credit_note: 1, payment: 2 };
  transactions.sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
  });

  let running = 0;
  let totalInvoiced = 0;
  let totalPaid = 0;
  let totalCredits = 0;

  for (const txn of transactions) {
    running += txn.debit - txn.credit;
    txn.balance = running;
    totalInvoiced += txn.debit;
    if (txn.type === 'payment') totalPaid += txn.credit;
    if (txn.type === 'credit_note') totalCredits += txn.credit;
  }

  return {
    customer: {
      id: String(cust.id),
      name: String(cust.name),
      email: cust.email ? String(cust.email) : null,
    },
    fromDate: oneYearAgo,
    toDate: asAtDate,
    transactions,
    summary: { totalInvoiced, totalPaid, totalCredits, balance: running },
  };
}

// ─── Main Send Function ───────────────────────────────────────────────────────

export async function sendStatementEmail(
  companyId: string,
  customerId: string,
  asAtDate: string,
  companyName: string,
  message?: string
): Promise<EmailResult> {
  const data = await fetchStatementData(companyId, customerId, asAtDate);

  if (!data) {
    return { success: false, error: 'Customer not found' };
  }

  if (!data.customer.email) {
    return { success: false, error: `No email address for ${data.customer.name}` };
  }

  const html = buildStatementEmailHtml({
    customerName: data.customer.name,
    asAtDate: data.toDate,
    fromDate: data.fromDate,
    companyName,
    message,
    summary: data.summary,
    transactions: data.transactions,
  });

  const subject = `Account Statement as at ${fmtDate(asAtDate)} — ${companyName || 'ISAFlow'}`;
  const result = await sendEmail({ to: data.customer.email, subject, html });

  if (result.success) {
    log.info('Statement email sent', {
      customerId,
      email: data.customer.email,
      asAtDate,
    }, 'statementEmailService');
  } else {
    log.error('Statement email failed', {
      customerId,
      email: data.customer.email,
      error: result.error,
    }, 'statementEmailService');
  }

  return result;
}

/**
 * Delivery Notes List Page
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Truck, Plus, Loader2, XCircle, CheckCircle, Send } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface DeliveryNote {
  id: string;
  deliveryNoteNumber: string;
  customerName: string;
  deliveryDate: string;
  status: string;
  lineCount: number;
}

const STATUS_BADGE: Record<string, string> = {
  draft: 'bg-gray-500/10 text-gray-400',
  dispatched: 'bg-blue-500/10 text-blue-400',
  delivered: 'bg-teal-500/10 text-teal-400',
  cancelled: 'bg-red-500/10 text-red-400',
};

const STATUS_LABEL: Record<string, string> = {
  draft: 'Draft',
  dispatched: 'Dispatched',
  delivered: 'Delivered',
  cancelled: 'Cancelled',
};

const TABS = ['all', 'draft', 'dispatched', 'delivered'] as const;

function formatDate(d: string): string {
  if (!d) return '\u2014';
  return String(d).split('T')[0] ?? d;
}

export default function DeliveryNotesPage() {
  const router = useRouter();
  const [notes, setNotes] = useState<DeliveryNote[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [tab, setTab] = useState<string>('all');
  const [patching, setPatching] = useState<string | null>(null);
  const [deleting, setDeleting] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (tab !== 'all') params.set('status', tab);
      const res = await apiFetch(`/api/accounting/delivery-notes?${params}`);
      const json = (await res.json()) as { data?: { notes?: DeliveryNote[]; total?: number } };
      const d = json.data ?? {};
      setNotes(d.notes ?? []);
      setTotal(d.total ?? 0);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load delivery notes');
    } finally {
      setLoading(false);
    }
  }, [tab]);

  useEffect(() => {
    void load();
  }, [load]);

  const handleStatusChange = async (id: string, status: string) => {
    setPatching(id);
    try {
      await apiFetch('/api/accounting/delivery-notes', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status }),
      });
      void load();
    } finally {
      setPatching(null);
    }
  };

  const handleCancel = async (id: string) => {
    if (!window.confirm('Cancel this delivery note?')) return;
    setDeleting(id);
    try {
      await apiFetch('/api/accounting/delivery-notes', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id }),
      });
      void load();
    } finally {
      setDeleting(null);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Truck className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Delivery Notes
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {total} delivery note{total !== 1 ? 's' : ''}
                </p>
              </div>
            </div>
            <button
              onClick={() => router.push('/accounting/delivery-notes/new')}
              className="flex items-center gap-1.5 px-4 py-2 bg-teal-600 hover:bg-teal-500 text-white rounded-lg text-sm"
            >
              <Plus className="h-4 w-4" /> New Delivery Note
            </button>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">
              {error}
            </div>
          )}

          {/* Tabs */}
          <div className="flex gap-1">
            {TABS.map((t) => (
              <button
                key={t}
                onClick={() => setTab(t)}
                className={`px-3 py-1.5 text-xs font-medium rounded-lg capitalize ${
                  tab === t
                    ? 'bg-teal-600 text-white'
                    : 'text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-secondary)]'
                }`}
              >
                {t === 'all' ? 'All' : STATUS_LABEL[t] ?? t}
              </button>
            ))}
          </div>

          {/* Table */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading ? (
              <div className="p-8 text-center">
                <Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" />
              </div>
            ) : notes.length === 0 ? (
              <div className="p-8 text-center text-[var(--ff-text-secondary)]">
                No delivery notes found
              </div>
            ) : (
              <table className="w-full">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                    <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">DN #</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Customer</th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Date</th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Lines</th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Status</th>
                    <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--ff-border-light)]">
                  {notes.map((n) => (
                    <tr
                      key={n.id}
                      className="hover:bg-[var(--ff-bg-tertiary)] transition-colors cursor-pointer"
                      onClick={() => router.push(`/accounting/delivery-notes/${n.id}`)}
                    >
                      <td className="px-4 py-3 text-sm font-mono text-teal-400">{n.deliveryNoteNumber}</td>
                      <td className="px-4 py-3 text-sm text-[var(--ff-text-primary)]">{n.customerName}</td>
                      <td className="px-4 py-3 text-sm text-[var(--ff-text-secondary)]">{formatDate(n.deliveryDate)}</td>
                      <td className="px-4 py-3 text-sm text-center text-[var(--ff-text-secondary)]">{n.lineCount ?? 0}</td>
                      <td className="px-4 py-3 text-center">
                        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_BADGE[n.status] ?? ''}`}>
                          {STATUS_LABEL[n.status] ?? n.status}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <div
                          className="flex justify-end gap-1"
                          onClick={(e) => e.stopPropagation()}
                        >
                          {n.status === 'draft' && (
                            <button
                              onClick={() => handleStatusChange(n.id, 'dispatched')}
                              disabled={patching === n.id}
                              title="Mark Dispatched"
                              className="flex items-center gap-1 px-2 py-1 rounded text-xs bg-blue-500/10 hover:bg-blue-500/20 text-blue-400 disabled:opacity-50"
                            >
                              {patching === n.id ? (
                                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                              ) : (
                                <Send className="h-3.5 w-3.5" />
                              )}
                              Dispatch
                            </button>
                          )}
                          {n.status === 'dispatched' && (
                            <button
                              onClick={() => handleStatusChange(n.id, 'delivered')}
                              disabled={patching === n.id}
                              title="Mark Delivered"
                              className="flex items-center gap-1 px-2 py-1 rounded text-xs bg-teal-500/10 hover:bg-teal-500/20 text-teal-400 disabled:opacity-50"
                            >
                              {patching === n.id ? (
                                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                              ) : (
                                <CheckCircle className="h-3.5 w-3.5" />
                              )}
                              Delivered
                            </button>
                          )}
                          {n.status !== 'cancelled' && n.status !== 'delivered' && (
                            <button
                              onClick={() => handleCancel(n.id)}
                              disabled={deleting === n.id}
                              title="Cancel"
                              className="p-1.5 rounded hover:bg-red-500/10 text-red-400 disabled:opacity-50"
                            >
                              {deleting === n.id ? (
                                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                              ) : (
                                <XCircle className="h-3.5 w-3.5" />
                              )}
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * New Delivery Note Page
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Truck, Loader2, ArrowLeft } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import {
  DeliveryNoteLineEditor,
  emptyLine,
  type LineItem,
} from '@/components/accounting/deliveryNotes/DeliveryNoteLineEditor';

interface CustomerOption {
  id: string;
  name?: string;
  company_name?: string;
  companyName?: string;
}

interface SalesOrderOption {
  id: string;
  orderNumber: string;
}

export default function NewDeliveryNotePage() {
  const router = useRouter();

  const [customers, setCustomers] = useState<CustomerOption[]>([]);
  const [salesOrders, setSalesOrders] = useState<SalesOrderOption[]>([]);
  const [loadingCustomers, setLoadingCustomers] = useState(true);
  const [loadingOrders, setLoadingOrders] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const [customerId, setCustomerId] = useState('');
  const [salesOrderId, setSalesOrderId] = useState('');
  const [deliveryDate, setDeliveryDate] = useState(new Date().toISOString().split('T')[0]!);
  const [deliveryAddress, setDeliveryAddress] = useState('');
  const [notes, setNotes] = useState('');
  const [lines, setLines] = useState<LineItem[]>([emptyLine()]);

  const { sales_order_id, customer_id } = router.query;

  useEffect(() => {
    setLoadingCustomers(true);
    apiFetch('/api/accounting/customers')
      .then((r) => r.json())
      .then((json: { data?: CustomerOption[] } | CustomerOption[]) => {
        const list: CustomerOption[] = Array.isArray(json)
          ? json
          : Array.isArray((json as { data?: CustomerOption[] }).data)
            ? ((json as { data: CustomerOption[] }).data)
            : [];
        setCustomers(
          list.map((c) => ({
            id: String(c.id),
            name: String(c.name ?? c.company_name ?? c.companyName ?? ''),
          })),
        );
      })
      .catch(() => setError('Failed to load customers'))
      .finally(() => setLoadingCustomers(false));
  }, []);

  useEffect(() => {
    if (typeof customer_id === 'string' && customer_id) setCustomerId(customer_id);
    if (typeof sales_order_id === 'string' && sales_order_id) setSalesOrderId(sales_order_id);
  }, [customer_id, sales_order_id]);

  useEffect(() => {
    if (!customerId) {
      setSalesOrders([]);
      setSalesOrderId('');
      return;
    }
    setLoadingOrders(true);
    apiFetch('/api/accounting/customer-sales-orders?status=confirmed')
      .then((r) => r.json())
      .then((json: { data?: { orders?: SalesOrderOption[] } }) => {
        setSalesOrders(json?.data?.orders ?? []);
      })
      .catch(() => setSalesOrders([]))
      .finally(() => setLoadingOrders(false));
  }, [customerId]);

  const handleSave = async (dispatchAfter: boolean) => {
    setError('');
    if (!customerId) { setError('Please select a customer'); return; }
    const validLines = lines.filter((l) => l.description.trim());
    if (validLines.length === 0) {
      setError('At least one line item with a description is required');
      return;
    }

    setSaving(true);
    try {
      const res = await apiFetch('/api/accounting/delivery-notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customer_id: customerId,
          sales_order_id: salesOrderId || undefined,
          delivery_date: deliveryDate,
          delivery_address: deliveryAddress || undefined,
          notes: notes || undefined,
          lines: validLines,
        }),
      });
      const json = (await res.json()) as {
        data?: { id?: string };
        error?: { message?: string };
      };
      if (!res.ok) {
        setError(json?.error?.message ?? 'Failed to create delivery note');
        return;
      }
      const noteId = json?.data?.id ?? '';
      if (dispatchAfter && noteId) {
        await apiFetch('/api/accounting/delivery-notes', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: noteId, status: 'dispatched' }),
        });
      }
      await router.push('/accounting/delivery-notes');
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to save delivery note');
    } finally {
      setSaving(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <button
              onClick={() => router.push('/accounting/delivery-notes')}
              className="p-1.5 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]"
            >
              <ArrowLeft className="h-4 w-4" />
            </button>
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Truck className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Delivery Note</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Create a new delivery note</p>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded text-sm">
              {error}
            </div>
          )}

          {/* Details card */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">
              Delivery Details
            </h2>
            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Customer *</label>
                {loadingCustomers ? (
                  <div className="ff-input flex items-center gap-2 text-sm text-[var(--ff-text-tertiary)]">
                    <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading...
                  </div>
                ) : (
                  <select
                    value={customerId}
                    onChange={(e) => { setCustomerId(e.target.value); setSalesOrderId(''); }}
                    className="ff-input text-sm"
                  >
                    <option value="">Select customer...</option>
                    {customers.map((c) => (
                      <option key={c.id} value={c.id}>
                        {String(c.name ?? c.company_name ?? c.companyName ?? '')}
                      </option>
                    ))}
                  </select>
                )}
              </div>

              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Delivery Date *</label>
                <input
                  type="date"
                  value={deliveryDate}
                  onChange={(e) => setDeliveryDate(e.target.value)}
                  className="ff-input text-sm"
                />
              </div>

              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">
                  Linked Sales Order (optional)
                </label>
                {loadingOrders ? (
                  <div className="ff-input flex items-center gap-2 text-sm text-[var(--ff-text-tertiary)]">
                    <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading...
                  </div>
                ) : (
                  <select
                    value={salesOrderId}
                    onChange={(e) => setSalesOrderId(e.target.value)}
                    disabled={!customerId}
                    className="ff-input text-sm disabled:opacity-50"
                  >
                    <option value="">None</option>
                    {salesOrders.map((so) => (
                      <option key={so.id} value={so.id}>{so.orderNumber}</option>
                    ))}
                  </select>
                )}
              </div>

              <div className="flex flex-col gap-1">
                <label className="text-xs text-[var(--ff-text-secondary)]">Delivery Address</label>
                <input
                  value={deliveryAddress}
                  onChange={(e) => setDeliveryAddress(e.target.value)}
                  placeholder="Delivery address..."
                  className="ff-input text-sm"
                />
              </div>
            </div>

            <div className="flex flex-col gap-1">
              <label className="text-xs text-[var(--ff-text-secondary)]">Notes</label>
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                rows={2}
                placeholder="Additional notes..."
                className="ff-input text-sm resize-none"
              />
            </div>
          </div>

          <DeliveryNoteLineEditor lines={lines} onChange={setLines} />

          {/* Actions */}
          <div className="flex justify-end gap-3">
            <button
              onClick={() => router.push('/accounting/delivery-notes')}
              className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-secondary)] rounded-lg"
            >
              Cancel
            </button>
            <button
              onClick={() => handleSave(false)}
              disabled={saving}
              className="px-4 py-2 text-sm bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-primary)] rounded-lg disabled:opacity-50"
            >
              {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Save as Draft'}
            </button>
            <button
              onClick={() => handleSave(true)}
              disabled={saving}
              className="flex items-center gap-1.5 px-4 py-2 text-sm bg-teal-600 hover:bg-teal-500 text-white rounded-lg disabled:opacity-50"
            >
              {saving ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <>
                  <Truck className="h-4 w-4" /> Save &amp; Dispatch
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Delivery Note Detail Page
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Truck, Loader2, ArrowLeft, Send, CheckCircle, XCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface DeliveryNoteLine {
  id: string;
  description: string;
  quantity: number;
  unit: string | null;
}

interface DeliveryNote {
  id: string;
  deliveryNoteNumber: string;
  customerName: string;
  customerId: string;
  salesOrderId: string | null;
  invoiceId: string | null;
  deliveryDate: string;
  status: string;
  deliveryAddress: string | null;
  notes: string | null;
  createdAt: string;
  lines?: DeliveryNoteLine[];
}

const STATUS_BADGE: Record<string, string> = {
  draft: 'bg-gray-500/10 text-gray-400',
  dispatched: 'bg-blue-500/10 text-blue-400',
  delivered: 'bg-teal-500/10 text-teal-400',
  cancelled: 'bg-red-500/10 text-red-400',
};

const STATUS_LABEL: Record<string, string> = {
  draft: 'Draft',
  dispatched: 'Dispatched',
  delivered: 'Delivered',
  cancelled: 'Cancelled',
};

function formatDate(d: string): string {
  if (!d) return '\u2014';
  return String(d).split('T')[0] ?? d;
}

export default function DeliveryNoteDetailPage() {
  const router = useRouter();
  const { id } = router.query;

  const [note, setNote] = useState<DeliveryNote | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [patching, setPatching] = useState(false);

  const load = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch(`/api/accounting/delivery-notes?id=${id}`);
      const json = (await res.json()) as { data?: DeliveryNote; error?: { message?: string } };
      if (!res.ok) {
        setError(json?.error?.message ?? 'Not found');
        return;
      }
      setNote(json.data ?? null);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load delivery note');
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => {
    void load();
  }, [load]);

  const handleStatusChange = async (status: string) => {
    if (!note) return;
    setPatching(true);
    try {
      await apiFetch('/api/accounting/delivery-notes', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: note.id, status }),
      });
      void load();
    } finally {
      setPatching(false);
    }
  };

  const handleCancel = async () => {
    if (!note || !window.confirm('Cancel this delivery note?')) return;
    setPatching(true);
    try {
      await apiFetch('/api/accounting/delivery-notes', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: note.id }),
      });
      await router.push('/accounting/delivery-notes');
    } finally {
      setPatching(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <button
                onClick={() => router.push('/accounting/delivery-notes')}
                className="p-1.5 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)]"
              >
                <ArrowLeft className="h-4 w-4" />
              </button>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Truck className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  {note ? note.deliveryNoteNumber : 'Delivery Note'}
                </h1>
                {note && (
                  <p className="text-sm text-[var(--ff-text-secondary)]">{note.customerName}</p>
                )}
              </div>
            </div>

            {note && (
              <div className="flex items-center gap-2">
                <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${STATUS_BADGE[note.status] ?? ''}`}>
                  {STATUS_LABEL[note.status] ?? note.status}
                </span>
                {note.status === 'draft' && (
                  <button
                    onClick={() => handleStatusChange('dispatched')}
                    disabled={patching}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 hover:bg-blue-500 text-white rounded-lg disabled:opacity-50"
                  >
                    {patching ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Send className="h-3.5 w-3.5" />}
                    Dispatch
                  </button>
                )}
                {note.status === 'dispatched' && (
                  <button
                    onClick={() => handleStatusChange('delivered')}
                    disabled={patching}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-teal-600 hover:bg-teal-500 text-white rounded-lg disabled:opacity-50"
                  >
                    {patching ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <CheckCircle className="h-3.5 w-3.5" />}
                    Mark Delivered
                  </button>
                )}
                {note.status !== 'cancelled' && note.status !== 'delivered' && (
                  <button
                    onClick={handleCancel}
                    disabled={patching}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-sm border border-red-500/30 hover:bg-red-500/10 text-red-400 rounded-lg disabled:opacity-50"
                  >
                    <XCircle className="h-3.5 w-3.5" />
                    Cancel
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded text-sm">
              {error}
            </div>
          )}

          {loading ? (
            <div className="p-8 text-center">
              <Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" />
            </div>
          ) : note ? (
            <>
              {/* Details card */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5">
                <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide mb-4">
                  Delivery Details
                </h2>
                <div className="grid grid-cols-2 gap-x-8 gap-y-3 text-sm">
                  <div>
                    <span className="text-[var(--ff-text-secondary)]">Customer</span>
                    <p className="text-[var(--ff-text-primary)] font-medium">{note.customerName}</p>
                  </div>
                  <div>
                    <span className="text-[var(--ff-text-secondary)]">Delivery Date</span>
                    <p className="text-[var(--ff-text-primary)]">{formatDate(note.deliveryDate)}</p>
                  </div>
                  {note.salesOrderId && (
                    <div>
                      <span className="text-[var(--ff-text-secondary)]">Sales Order</span>
                      <button
                        onClick={() => router.push(`/accounting/customer-sales-orders/${note.salesOrderId}`)}
                        className="block text-blue-400 hover:underline"
                      >
                        View order
                      </button>
                    </div>
                  )}
                  {note.invoiceId && (
                    <div>
                      <span className="text-[var(--ff-text-secondary)]">Invoice</span>
                      <button
                        onClick={() => router.push(`/accounting/customer-invoices/${note.invoiceId}`)}
                        className="block text-blue-400 hover:underline"
                      >
                        View invoice
                      </button>
                    </div>
                  )}
                  {note.deliveryAddress && (
                    <div className="col-span-2">
                      <span className="text-[var(--ff-text-secondary)]">Delivery Address</span>
                      <p className="text-[var(--ff-text-primary)] whitespace-pre-wrap">{note.deliveryAddress}</p>
                    </div>
                  )}
                  {note.notes && (
                    <div className="col-span-2">
                      <span className="text-[var(--ff-text-secondary)]">Notes</span>
                      <p className="text-[var(--ff-text-primary)] whitespace-pre-wrap">{note.notes}</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Line items */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                <div className="px-5 py-3 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">
                    Line Items
                  </h2>
                </div>
                <table className="w-full">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)]">
                      <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Description</th>
                      <th className="px-4 py-2.5 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Qty</th>
                      <th className="px-4 py-2.5 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Unit</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--ff-border-light)]">
                    {(note.lines ?? []).map((line) => (
                      <tr key={line.id} className="hover:bg-[var(--ff-bg-tertiary)]">
                        <td className="px-4 py-2.5 text-sm text-[var(--ff-text-primary)]">{line.description}</td>
                        <td className="px-4 py-2.5 text-sm text-right font-mono text-[var(--ff-text-primary)]">
                          {Number(line.quantity).toLocaleString('en-ZA')}
                        </td>
                        <td className="px-4 py-2.5 text-sm text-[var(--ff-text-secondary)]">{line.unit ?? ''}</td>
                      </tr>
                    ))}
                    {!note.lines?.length && (
                      <tr>
                        <td colSpan={3} className="px-4 py-4 text-center text-sm text-[var(--ff-text-secondary)]">
                          No line items
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>

              <p className="text-xs text-[var(--ff-text-tertiary)]">
                Created {formatDate(note.createdAt)}
              </p>
            </>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Recurring Invoices Page
 * Phase 1 Sage Alignment: Manage recurring invoice templates
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { Repeat, Plus, Pause, Play, XCircle, Zap, Loader2, Pencil, Save, Download, Clock, CheckCircle, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface RecurringInvoice {
  id: string; templateName: string; clientId: string; clientName?: string;
  frequency: string; nextRunDate: string; lastRunDate?: string; runCount: number;
  status: string; totalAmount: number; description?: string;
}
interface Client { id: string; company_name: string }
interface RunResult { generated: number; invoice_ids: string[]; errors: string[] }

const isOverdue = (d: string | undefined): boolean => {
  if (!d) return false;
  return d.split('T')[0]! <= new Date().toISOString().split('T')[0]!;
};

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const STATUS_BADGE: Record<string, string> = {
  active: 'bg-teal-500/10 text-teal-400',
  paused: 'bg-yellow-500/10 text-yellow-400',
  completed: 'bg-blue-500/10 text-blue-400',
  cancelled: 'bg-red-500/10 text-red-400',
};

export default function RecurringInvoicesPage() {
  const [items, setItems] = useState<RecurringInvoice[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [busy, setBusy] = useState('');
  const [runAllBusy, setRunAllBusy] = useState(false);
  const [error, setError] = useState('');
  const [runResult, setRunResult] = useState<RunResult | null>(null);
  const [editId, setEditId] = useState('');
  const [form, setForm] = useState({
    templateName: '', clientId: '', frequency: 'monthly',
    nextRunDate: '', description: '', lineDesc: '', lineQty: '1', linePrice: '',
  });

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices');
      const json = await res.json() as { data?: { items?: RecurringInvoice[] } };
      setItems(json.data?.items ?? []);
    } catch (err) {
      log.error('Failed to load recurring invoices', { error: err }, 'recurring-invoices-page');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    apiFetch('/api/accounting/customers').then(r => r.json()).then((res: { data?: unknown }) => {
      const d = res.data;
      setClients(Array.isArray(d) ? (d as Client[]) : ((d as { clients?: Client[] })?.clients ?? []));
    }).catch(err => {
      log.error('Failed to load customers', { error: err }, 'recurring-invoices-page');
    });
  }, []);

  const doAction = async (action: string, id: string) => {
    setBusy(id);
    setError('');
    try {
      await apiFetch('/api/accounting/recurring-invoices-action', {
        method: 'POST',
        body: JSON.stringify({ action, id }),
      });
      await load();
    } catch (err) {
      log.error('Recurring invoice action failed', { action, id, error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Action failed');
    } finally {
      setBusy('');
    }
  };

  const runOne = async (id: string) => {
    setBusy(id);
    setError('');
    setRunResult(null);
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices-run', {
        method: 'POST',
        body: JSON.stringify({ recurring_invoice_id: id }),
      });
      const json = await res.json() as { data?: RunResult };
      if (!res.ok) throw new Error('Run failed');
      setRunResult(json.data ?? null);
      await load();
    } catch (err) {
      log.error('Run recurring invoice failed', { id, error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Run failed');
    } finally {
      setBusy('');
    }
  };

  const runAllDue = async () => {
    setRunAllBusy(true);
    setError('');
    setRunResult(null);
    try {
      const res = await apiFetch('/api/accounting/recurring-invoices-run', {
        method: 'POST',
        body: JSON.stringify({}),
      });
      const json = await res.json() as { data?: RunResult };
      if (!res.ok) throw new Error('Run All failed');
      setRunResult(json.data ?? null);
      await load();
    } catch (err) {
      log.error('Run all due recurring invoices failed', { error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Run All failed');
    } finally {
      setRunAllBusy(false);
    }
  };

  const startEdit = (item: RecurringInvoice) => {
    setEditId(item.id);
    setForm({
      templateName: item.templateName, clientId: item.clientId,
      frequency: item.frequency, nextRunDate: item.nextRunDate?.split('T')[0] || '',
      description: '', lineDesc: '', lineQty: '1', linePrice: '',
    });
    setShowForm(true);
  };

  const resetForm = () => {
    setEditId('');
    setShowForm(false);
    setForm({ templateName: '', clientId: '', frequency: 'monthly', nextRunDate: '', description: '', lineDesc: '', lineQty: '1', linePrice: '' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setBusy('new');
    try {
      const method = editId ? 'PUT' : 'POST';
      const payload = editId
        ? { id: editId, templateName: form.templateName, frequency: form.frequency, nextRunDate: form.nextRunDate, description: form.description }
        : {
            templateName: form.templateName, clientId: form.clientId,
            frequency: form.frequency, nextRunDate: form.nextRunDate,
            description: form.description,
            lineItems: [{ description: form.lineDesc, quantity: Number(form.lineQty), unitPrice: Number(form.linePrice) }],
          };
      const res = await apiFetch('/api/accounting/recurring-invoices', {
        method,
        body: JSON.stringify(payload),
      });
      const json = await res.json() as { error?: { message?: string }; message?: string };
      if (!res.ok) throw new Error(json.error?.message ?? json.message ?? 'Failed');
      resetForm();
      await load();
    } catch (err) {
      log.error('Save recurring invoice failed', { error: err }, 'recurring-invoices-page');
      setError(err instanceof Error ? err.message : 'Failed');
    } finally { setBusy(''); }
  };

  const exportCSV = () => {
    const headers = ['Template', 'Client', 'Frequency', 'Next Run', 'Amount', 'Status', 'Run Count'];
    const rows = items.map(i => [i.templateName, i.clientName || '', i.frequency, i.nextRunDate?.split('T')[0] || '', i.totalAmount, i.status, i.runCount]);
    const csv = [headers, ...rows].map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
    a.download = `recurring-invoices-${new Date().toISOString().split('T')[0]}.csv`; a.click();
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-violet-500/10"><Repeat className="h-6 w-6 text-violet-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Recurring Invoices</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Automate repeating customer invoices
                  {items.filter(i => i.status === 'active' && isOverdue(i.nextRunDate)).length > 0 && (
                    <span className="ml-2 px-2 py-0.5 bg-orange-500/20 text-orange-400 rounded-full text-xs font-medium">
                      {items.filter(i => i.status === 'active' && isOverdue(i.nextRunDate)).length} due
                    </span>
                  )}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {items.filter(i => i.status === 'active' && isOverdue(i.nextRunDate)).length > 0 && (
                <button onClick={() => void runAllDue()} disabled={runAllBusy} className="inline-flex items-center gap-2 px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 text-sm font-medium disabled:opacity-50">
                  {runAllBusy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Zap className="h-4 w-4" />}
                  Run All Due ({items.filter(i => i.status === 'active' && isOverdue(i.nextRunDate)).length})
                </button>
              )}
              {items.length > 0 && (
                <button onClick={exportCSV} className="inline-flex items-center gap-2 px-3 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-primary)] text-sm">
                  <Download className="h-4 w-4" /> CSV
                </button>
              )}
              <Link href="/accounting/recurring-invoices/new" className="inline-flex items-center gap-2 px-4 py-2 bg-violet-600 text-white rounded-lg hover:bg-violet-700 text-sm font-medium">
                <Plus className="h-4 w-4" /> New Recurring Invoice
              </Link>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}
          {runResult && (
            <div className={`flex items-start gap-2 p-3 rounded-lg border text-sm ${runResult.errors.length > 0 ? 'bg-yellow-500/10 border-yellow-500/30 text-yellow-400' : 'bg-teal-500/10 border-teal-500/30 text-teal-400'}`}>
              <CheckCircle className="h-4 w-4 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium">{runResult.generated} invoice{runResult.generated !== 1 ? 's' : ''} generated</p>
                {runResult.errors.map((e, i) => <p key={i} className="text-xs mt-0.5">{e}</p>)}
              </div>
            </div>
          )}

          {showForm && (
            <form onSubmit={handleSubmit} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">{editId ? 'Edit Recurring Invoice' : 'New Recurring Invoice'}</h2>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <input value={form.templateName} onChange={e => setForm(f => ({ ...f, templateName: e.target.value }))} className="ff-input" placeholder="Template Name *" required />
                <select value={form.clientId} onChange={e => setForm(f => ({ ...f, clientId: e.target.value }))} className="ff-select" required>
                  <option value="">Select Client *</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.company_name}</option>)}
                </select>
                <select value={form.frequency} onChange={e => setForm(f => ({ ...f, frequency: e.target.value }))} className="ff-select">
                  <option value="weekly">Weekly</option><option value="monthly">Monthly</option>
                  <option value="quarterly">Quarterly</option><option value="annually">Annually</option>
                </select>
                <input type="date" value={form.nextRunDate} onChange={e => setForm(f => ({ ...f, nextRunDate: e.target.value }))} className="ff-input" required />
                <input value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} className="ff-input" placeholder="Description" />
              </div>
              {!editId && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <input value={form.lineDesc} onChange={e => setForm(f => ({ ...f, lineDesc: e.target.value }))} className="ff-input" placeholder="Line Item Description *" required />
                  <input type="number" value={form.lineQty} onChange={e => setForm(f => ({ ...f, lineQty: e.target.value }))} className="ff-input" placeholder="Qty" min="1" />
                  <input type="number" step="0.01" value={form.linePrice} onChange={e => setForm(f => ({ ...f, linePrice: e.target.value }))} className="ff-input" placeholder="Unit Price *" required />
                </div>
              )}
              <div className="flex justify-end gap-2">
                <button type="button" onClick={resetForm} className="px-4 py-2 text-sm text-[var(--ff-text-secondary)]">Cancel</button>
                <button type="submit" disabled={busy === 'new'} className="px-6 py-2 bg-violet-600 text-white rounded-lg text-sm font-medium disabled:opacity-50">
                  {busy === 'new' ? <Loader2 className="h-4 w-4 animate-spin" /> : editId ? <><Save className="h-4 w-4 inline mr-1" />Save</> : 'Create'}
                </button>
              </div>
            </form>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)] text-xs">
                <th className="px-4 py-3">Template</th><th className="px-4 py-3">Customer</th>
                <th className="px-4 py-3">Frequency</th><th className="px-4 py-3">Next Run</th>
                <th className="px-4 py-3">Last Run</th>
                <th className="px-4 py-3 text-right">Amount</th><th className="px-4 py-3">Status</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr></thead>
              <tbody>
                {loading && <tr><td colSpan={8} className="px-4 py-8 text-center text-[var(--ff-text-secondary)]"><Loader2 className="h-5 w-5 animate-spin mx-auto text-violet-500" /></td></tr>}
                {!loading && items.length === 0 && (
                  <tr><td colSpan={8} className="px-4 py-12 text-center">
                    <Repeat className="h-10 w-10 mx-auto mb-2 opacity-20 text-[var(--ff-text-secondary)]" />
                    <p className="text-[var(--ff-text-secondary)] text-sm">No recurring invoices</p>
                    <Link href="/accounting/recurring-invoices/new" className="text-violet-400 hover:underline text-xs mt-1 inline-block">Create your first template</Link>
                  </td></tr>
                )}
                {items.map(item => {
                  const due = item.status === 'active' && isOverdue(item.nextRunDate);
                  return (
                    <tr key={item.id} className={`border-b border-[var(--ff-border-light)] last:border-0 hover:bg-[var(--ff-bg-primary)] transition-colors ${due ? 'bg-orange-500/5' : ''}`}>
                      <td className="px-4 py-3">
                        <div className="font-medium text-[var(--ff-text-primary)]">{item.templateName}</div>
                        {item.description && <div className="text-xs text-[var(--ff-text-secondary)] mt-0.5">{item.description}</div>}
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{item.clientName ?? '—'}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">{item.frequency}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                        <span className="flex items-center gap-1.5">
                          {item.nextRunDate?.split('T')[0]}
                          {due && (
                            <span className="flex items-center gap-0.5 text-xs px-1.5 py-0.5 bg-orange-500/20 text-orange-400 rounded-full font-medium">
                              <Clock className="h-3 w-3" /> Due
                            </span>
                          )}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{item.lastRunDate ? item.lastRunDate.split('T')[0] : '—'}</td>
                      <td className="px-4 py-3 text-right font-medium text-[var(--ff-text-primary)]">{fmt(item.totalAmount)}</td>
                      <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded-full text-xs font-medium capitalize ${STATUS_BADGE[item.status] ?? ''}`}>{item.status}</span></td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          {item.status === 'active' && (
                            <>
                              <button onClick={() => void runOne(item.id)} disabled={busy === item.id} title="Run Now"
                                className="p-1.5 text-violet-400 hover:text-violet-300 hover:bg-violet-500/10 rounded-lg transition-colors disabled:opacity-40">
                                {busy === item.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Zap className="h-4 w-4" />}
                              </button>
                              <button onClick={() => void doAction('pause', item.id)} disabled={busy === item.id} title="Pause"
                                className="p-1.5 text-yellow-400 hover:text-yellow-300 hover:bg-yellow-500/10 rounded-lg transition-colors disabled:opacity-40">
                                <Pause className="h-4 w-4" />
                              </button>
                            </>
                          )}
                          {item.status === 'paused' && (
                            <button onClick={() => void doAction('resume', item.id)} disabled={busy === item.id} title="Resume"
                              className="p-1.5 text-teal-400 hover:text-teal-300 hover:bg-teal-500/10 rounded-lg transition-colors disabled:opacity-40">
                              <Play className="h-4 w-4" />
                            </button>
                          )}
                          {(item.status === 'active' || item.status === 'paused') && (
                            <>
                              <Link href={`/accounting/recurring-invoices/${item.id}`} title="Edit"
                                className="p-1.5 text-blue-400 hover:text-blue-300 hover:bg-blue-500/10 rounded-lg transition-colors">
                                <Pencil className="h-4 w-4" />
                              </Link>
                              <button onClick={() => void doAction('cancel', item.id)} disabled={busy === item.id} title="Cancel"
                                className="p-1.5 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-colors disabled:opacity-40">
                                <XCircle className="h-4 w-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * New Recurring Invoice Page
 * Create a recurring invoice template with full line items.
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ArrowLeft, Repeat, Plus, Trash2, Loader2, AlertCircle,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface Customer { id: string; name?: string; company_name?: string }
interface LineItem { key: string; description: string; quantity: number; unitPrice: number; glAccountId: string }

const FREQ_OPTIONS = [
  { value: 'weekly', label: 'Weekly' },
  { value: 'monthly', label: 'Monthly' },
  { value: 'quarterly', label: 'Quarterly' },
  { value: 'annually', label: 'Annually' },
];

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const newLine = (): LineItem => ({
  key: String(Date.now() + Math.random()),
  description: '', quantity: 1, unitPrice: 0, glAccountId: '',
});

export default function NewRecurringInvoicePage() {
  const router = useRouter();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const today = new Date().toISOString().split('T')[0]!;
  const [form, setForm] = useState({
    templateName: '',
    clientId: '',
    frequency: 'monthly',
    nextRunDate: today,
    endDate: '',
    description: '',
    taxRate: 15,
    paymentTerms: '30 days',
    autoSendEmail: false,
  });
  const [lines, setLines] = useState<LineItem[]>([newLine()]);

  useEffect(() => {
    apiFetch('/api/accounting/customers')
      .then(r => r.json())
      .then((json: { data?: unknown }) => {
        const d = json.data;
        const list = Array.isArray(d) ? d : (d as { clients?: Customer[] })?.clients ?? [];
        setCustomers(list as Customer[]);
      })
      .catch(err => {
        log.error('Failed to load customers for recurring invoice form', { error: err }, 'recurring-new');
      });
  }, []);

  const updateLine = (key: string, field: keyof Omit<LineItem, 'key'>, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };
  const addLine = () => setLines(prev => [...prev, newLine()]);
  const removeLine = (key: string) => {
    if (lines.length > 1) setLines(prev => prev.filter(l => l.key !== key));
  };

  const subtotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);
  const taxAmount = Math.round(subtotal * (form.taxRate / 100) * 100) / 100;
  const total = subtotal + taxAmount;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!form.clientId) { setError('Please select a customer'); return; }
    if (lines.some(l => !l.description)) { setError('All line items must have a description'); return; }
    if (lines.some(l => l.unitPrice <= 0)) { setError('All line items must have a unit price > 0'); return; }

    setSubmitting(true);
    try {
      const payload = {
        templateName: form.templateName || `Recurring - ${customers.find(c => c.id === form.clientId)?.company_name ?? customers.find(c => c.id === form.clientId)?.name ?? 'Invoice'}`,
        clientId: form.clientId,
        frequency: form.frequency,
        nextRunDate: form.nextRunDate,
        endDate: form.endDate || undefined,
        description: form.description || undefined,
        taxRate: form.taxRate,
        paymentTerms: form.paymentTerms,
        lineItems: lines.map(l => ({
          description: l.description,
          quantity: l.quantity,
          unitPrice: l.unitPrice,
          glAccountId: l.glAccountId || undefined,
        })),
      };

      const res = await apiFetch('/api/accounting/recurring-invoices', {
        method: 'POST',
        body: JSON.stringify(payload),
      });
      const json = await res.json() as { error?: { message?: string } };
      if (!res.ok) throw new Error(json.error?.message ?? 'Create failed');

      await router.push('/accounting/recurring-invoices');
    } catch (err) {
      log.error('Failed to create recurring invoice', { error: err }, 'recurring-new');
      setError(err instanceof Error ? err.message : 'Failed to create recurring invoice');
    } finally {
      setSubmitting(false);
    }
  };

  const inputCls = 'w-full px-3 py-2 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-sm text-[var(--ff-text-primary)] focus:outline-none focus:ring-1 focus:ring-violet-500';
  const labelCls = 'block text-xs font-medium text-[var(--ff-text-secondary)] mb-1';

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center gap-4">
            <Link
              href="/accounting/recurring-invoices"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)] transition-colors"
            >
              <ArrowLeft className="h-5 w-5" />
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-violet-500/10">
                <Repeat className="h-6 w-6 text-violet-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Recurring Invoice</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Set up a repeating invoice template</p>
              </div>
            </div>
          </div>
        </div>

        <form onSubmit={e => void handleSubmit(e)} className="px-6 py-6 max-w-4xl space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}

          {/* Template Details */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">Template Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className={labelCls}>Template Name</label>
                <input
                  className={inputCls}
                  value={form.templateName}
                  onChange={e => setForm(f => ({ ...f, templateName: e.target.value }))}
                  placeholder="e.g. Monthly Retainer — Acme Corp"
                />
              </div>
              <div>
                <label className={labelCls}>Customer *</label>
                <select
                  className={inputCls}
                  value={form.clientId}
                  onChange={e => setForm(f => ({ ...f, clientId: e.target.value }))}
                  required
                >
                  <option value="">Select customer…</option>
                  {customers.map(c => (
                    <option key={c.id} value={c.id}>{c.company_name ?? c.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className={labelCls}>Description</label>
                <input
                  className={inputCls}
                  value={form.description}
                  onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                  placeholder="Optional description shown on generated invoices"
                />
              </div>
              <div>
                <label className={labelCls}>Payment Terms</label>
                <select
                  className={inputCls}
                  value={form.paymentTerms}
                  onChange={e => setForm(f => ({ ...f, paymentTerms: e.target.value }))}
                >
                  <option value="7 days">7 days</option>
                  <option value="14 days">14 days</option>
                  <option value="30 days">30 days</option>
                  <option value="60 days">60 days</option>
                  <option value="COD">COD</option>
                </select>
              </div>
            </div>
          </div>

          {/* Schedule */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">Schedule</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className={labelCls}>Frequency *</label>
                <select
                  className={inputCls}
                  value={form.frequency}
                  onChange={e => setForm(f => ({ ...f, frequency: e.target.value }))}
                  required
                >
                  {FREQ_OPTIONS.map(o => (
                    <option key={o.value} value={o.value}>{o.label}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className={labelCls}>First Run Date *</label>
                <input
                  type="date"
                  className={inputCls}
                  value={form.nextRunDate}
                  onChange={e => setForm(f => ({ ...f, nextRunDate: e.target.value }))}
                  required
                />
              </div>
              <div>
                <label className={labelCls}>End Date (optional)</label>
                <input
                  type="date"
                  className={inputCls}
                  value={form.endDate}
                  onChange={e => setForm(f => ({ ...f, endDate: e.target.value }))}
                  min={form.nextRunDate}
                />
              </div>
            </div>
            <div className="flex items-center gap-3 pt-1">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={form.autoSendEmail}
                  onChange={e => setForm(f => ({ ...f, autoSendEmail: e.target.checked }))}
                  className="w-4 h-4 rounded border-[var(--ff-border-light)] text-violet-600 focus:ring-violet-500"
                />
                <span className="text-sm text-[var(--ff-text-secondary)]">
                  Auto-send email to customer on each invoice generation
                </span>
              </label>
            </div>
          </div>

          {/* Line Items */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5 space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">Line Items</h2>
              <button
                type="button"
                onClick={addLine}
                className="inline-flex items-center gap-1.5 text-xs text-violet-400 hover:text-violet-300 transition-colors"
              >
                <Plus className="h-3.5 w-3.5" /> Add Line
              </button>
            </div>

            <div className="hidden md:grid grid-cols-12 gap-2 text-xs text-[var(--ff-text-secondary)] px-1">
              <div className="col-span-5">Description</div>
              <div className="col-span-2">Qty</div>
              <div className="col-span-2">Unit Price</div>
              <div className="col-span-2 text-right">Line Total</div>
              <div className="col-span-1" />
            </div>

            {lines.map(line => (
              <div key={line.key} className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-5">
                  <input
                    className={inputCls}
                    value={line.description}
                    onChange={e => updateLine(line.key, 'description', e.target.value)}
                    placeholder="Description *"
                    required
                  />
                </div>
                <div className="col-span-2">
                  <input
                    type="number"
                    className={inputCls}
                    value={line.quantity}
                    min={0.01}
                    step="0.01"
                    onChange={e => updateLine(line.key, 'quantity', Number(e.target.value))}
                    required
                  />
                </div>
                <div className="col-span-2">
                  <input
                    type="number"
                    className={inputCls}
                    value={line.unitPrice}
                    min={0}
                    step="0.01"
                    onChange={e => updateLine(line.key, 'unitPrice', Number(e.target.value))}
                    required
                  />
                </div>
                <div className="col-span-2 text-right text-sm text-[var(--ff-text-primary)] pr-1">
                  {fmt(line.quantity * line.unitPrice)}
                </div>
                <div className="col-span-1 flex justify-end">
                  <button
                    type="button"
                    onClick={() => removeLine(line.key)}
                    disabled={lines.length === 1}
                    className="p-1 text-red-400 hover:text-red-300 disabled:opacity-30 transition-colors"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            ))}

            {/* Totals */}
            <div className="border-t border-[var(--ff-border-light)] pt-3 space-y-1 text-sm">
              <div className="flex justify-between text-[var(--ff-text-secondary)]">
                <span>Subtotal</span><span>{fmt(subtotal)}</span>
              </div>
              <div className="flex justify-between items-center text-[var(--ff-text-secondary)]">
                <div className="flex items-center gap-2">
                  <span>VAT</span>
                  <select
                    className="text-xs px-2 py-0.5 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded text-[var(--ff-text-secondary)]"
                    value={form.taxRate}
                    onChange={e => setForm(f => ({ ...f, taxRate: Number(e.target.value) }))}
                  >
                    <option value={0}>0%</option>
                    <option value={15}>15%</option>
                  </select>
                </div>
                <span>{fmt(taxAmount)}</span>
              </div>
              <div className="flex justify-between font-semibold text-[var(--ff-text-primary)] text-base pt-1">
                <span>Total</span><span>{fmt(total)}</span>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pb-8">
            <Link
              href="/accounting/recurring-invoices"
              className="px-5 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
            >
              Cancel
            </Link>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-2 px-6 py-2 bg-violet-600 text-white rounded-lg hover:bg-violet-700 transition-colors text-sm font-medium disabled:opacity-50"
            >
              {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Recurring Invoice
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Edit Recurring Invoice Page
 * Dedicated edit form for an existing recurring invoice template.
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ArrowLeft, Repeat, Plus, Trash2, Loader2, AlertCircle, Save,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface Customer { id: string; name?: string; company_name?: string }
interface LineItem { key: string; description: string; quantity: number; unitPrice: number; glAccountId: string }

const FREQ_OPTIONS = [
  { value: 'weekly', label: 'Weekly' },
  { value: 'monthly', label: 'Monthly' },
  { value: 'quarterly', label: 'Quarterly' },
  { value: 'annually', label: 'Annually' },
];

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const newLine = (): LineItem => ({
  key: String(Date.now() + Math.random()),
  description: '', quantity: 1, unitPrice: 0, glAccountId: '',
});

interface RawLineItem {
  description?: string;
  quantity?: number;
  unitPrice?: number;
  unit_price?: number;
  glAccountId?: string;
  gl_account_id?: string;
}

export default function EditRecurringInvoicePage() {
  const router = useRouter();
  const { id } = router.query as { id: string };

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    templateName: '',
    clientId: '',
    frequency: 'monthly',
    nextRunDate: '',
    endDate: '',
    description: '',
    taxRate: 15,
    paymentTerms: '30 days',
  });
  const [lines, setLines] = useState<LineItem[]>([newLine()]);

  useEffect(() => {
    apiFetch('/api/accounting/customers')
      .then(r => r.json())
      .then((json: { data?: unknown }) => {
        const d = json.data;
        const list = Array.isArray(d) ? d : (d as { clients?: Customer[] })?.clients ?? [];
        setCustomers(list as Customer[]);
      })
      .catch(err => {
        log.error('Failed to load customers', { error: err }, 'recurring-edit');
      });
  }, []);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    apiFetch('/api/accounting/recurring-invoices')
      .then(r => r.json())
      .then((json: { data?: { items?: Record<string, unknown>[] } }) => {
        const found = json.data?.items?.find(i => i.id === id);
        if (!found) { setError('Recurring invoice not found'); return; }
        const rawLines = Array.isArray(found.lineItems)
          ? (found.lineItems as RawLineItem[])
          : Array.isArray(found.line_items)
            ? (found.line_items as RawLineItem[])
            : [];
        setForm({
          templateName: String(found.templateName ?? found.template_name ?? ''),
          clientId: String(found.clientId ?? found.client_id ?? ''),
          frequency: String(found.frequency ?? 'monthly'),
          nextRunDate: String(found.nextRunDate ?? found.next_run_date ?? '').split('T')[0] ?? '',
          endDate: found.endDate ?? found.end_date ? (String(found.endDate ?? found.end_date ?? '').split('T')[0] ?? '') : '',
          description: String(found.description ?? ''),
          taxRate: Number(found.taxRate ?? found.tax_rate ?? 15),
          paymentTerms: String(found.paymentTerms ?? found.payment_terms ?? '30 days'),
        });
        if (rawLines.length > 0) {
          setLines(rawLines.map((l, i) => ({
            key: String(i),
            description: String(l.description ?? ''),
            quantity: Number(l.quantity ?? 1),
            unitPrice: Number(l.unitPrice ?? l.unit_price ?? 0),
            glAccountId: String(l.glAccountId ?? l.gl_account_id ?? ''),
          })));
        }
      })
      .catch(err => {
        log.error('Failed to load recurring invoice', { id, error: err }, 'recurring-edit');
        setError('Failed to load recurring invoice');
      })
      .finally(() => setLoading(false));
  }, [id]);

  const updateLine = (key: string, field: keyof Omit<LineItem, 'key'>, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };
  const addLine = () => setLines(prev => [...prev, newLine()]);
  const removeLine = (key: string) => {
    if (lines.length > 1) setLines(prev => prev.filter(l => l.key !== key));
  };

  const subtotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);
  const taxAmount = Math.round(subtotal * (form.taxRate / 100) * 100) / 100;
  const total = subtotal + taxAmount;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (lines.some(l => !l.description)) { setError('All line items must have a description'); return; }
    setSubmitting(true);
    try {
      const payload = {
        id,
        templateName: form.templateName,
        frequency: form.frequency,
        nextRunDate: form.nextRunDate,
        description: form.description || undefined,
        lineItems: lines.map(l => ({
          description: l.description,
          quantity: l.quantity,
          unitPrice: l.unitPrice,
          glAccountId: l.glAccountId || undefined,
        })),
      };
      const res = await apiFetch('/api/accounting/recurring-invoices', {
        method: 'PUT',
        body: JSON.stringify(payload),
      });
      const json = await res.json() as { error?: { message?: string } };
      if (!res.ok) throw new Error(json.error?.message ?? 'Update failed');
      await router.push('/accounting/recurring-invoices');
    } catch (err) {
      log.error('Failed to update recurring invoice', { id, error: err }, 'recurring-edit');
      setError(err instanceof Error ? err.message : 'Update failed');
    } finally {
      setSubmitting(false);
    }
  };

  const inputCls = 'w-full px-3 py-2 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-sm text-[var(--ff-text-primary)] focus:outline-none focus:ring-1 focus:ring-violet-500';
  const labelCls = 'block text-xs font-medium text-[var(--ff-text-secondary)] mb-1';

  if (loading) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-violet-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center gap-4">
            <Link
              href="/accounting/recurring-invoices"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)] transition-colors"
            >
              <ArrowLeft className="h-5 w-5" />
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-violet-500/10">
                <Repeat className="h-6 w-6 text-violet-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Edit Recurring Invoice</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">{form.templateName || 'Loading…'}</p>
              </div>
            </div>
          </div>
        </div>

        <form onSubmit={e => void handleSubmit(e)} className="px-6 py-6 max-w-4xl space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}

          {/* Template Details */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">Template Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className={labelCls}>Template Name</label>
                <input
                  className={inputCls}
                  value={form.templateName}
                  onChange={e => setForm(f => ({ ...f, templateName: e.target.value }))}
                  placeholder="e.g. Monthly Retainer"
                />
              </div>
              <div>
                <label className={labelCls}>Customer</label>
                <select
                  className={inputCls}
                  value={form.clientId}
                  onChange={e => setForm(f => ({ ...f, clientId: e.target.value }))}
                  disabled
                >
                  <option value="">Select customer…</option>
                  {customers.map(c => (
                    <option key={c.id} value={c.id}>{c.company_name ?? c.name}</option>
                  ))}
                </select>
                <p className="text-xs text-[var(--ff-text-secondary)] mt-1">Customer cannot be changed after creation</p>
              </div>
              <div>
                <label className={labelCls}>Description</label>
                <input
                  className={inputCls}
                  value={form.description}
                  onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                  placeholder="Optional description"
                />
              </div>
              <div>
                <label className={labelCls}>Payment Terms</label>
                <select
                  className={inputCls}
                  value={form.paymentTerms}
                  onChange={e => setForm(f => ({ ...f, paymentTerms: e.target.value }))}
                  disabled
                >
                  <option value="7 days">7 days</option>
                  <option value="14 days">14 days</option>
                  <option value="30 days">30 days</option>
                  <option value="60 days">60 days</option>
                  <option value="COD">COD</option>
                </select>
              </div>
            </div>
          </div>

          {/* Schedule */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">Schedule</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className={labelCls}>Frequency *</label>
                <select
                  className={inputCls}
                  value={form.frequency}
                  onChange={e => setForm(f => ({ ...f, frequency: e.target.value }))}
                  required
                >
                  {FREQ_OPTIONS.map(o => (
                    <option key={o.value} value={o.value}>{o.label}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className={labelCls}>Next Run Date *</label>
                <input
                  type="date"
                  className={inputCls}
                  value={form.nextRunDate}
                  onChange={e => setForm(f => ({ ...f, nextRunDate: e.target.value }))}
                  required
                />
              </div>
              <div>
                <label className={labelCls}>End Date (optional)</label>
                <input
                  type="date"
                  className={inputCls}
                  value={form.endDate}
                  onChange={e => setForm(f => ({ ...f, endDate: e.target.value }))}
                />
              </div>
            </div>
          </div>

          {/* Line Items */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5 space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] uppercase tracking-wide">Line Items</h2>
              <button
                type="button"
                onClick={addLine}
                className="inline-flex items-center gap-1.5 text-xs text-violet-400 hover:text-violet-300 transition-colors"
              >
                <Plus className="h-3.5 w-3.5" /> Add Line
              </button>
            </div>

            <div className="hidden md:grid grid-cols-12 gap-2 text-xs text-[var(--ff-text-secondary)] px-1">
              <div className="col-span-5">Description</div>
              <div className="col-span-2">Qty</div>
              <div className="col-span-2">Unit Price</div>
              <div className="col-span-2 text-right">Line Total</div>
              <div className="col-span-1" />
            </div>

            {lines.map(line => (
              <div key={line.key} className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-5">
                  <input
                    className={inputCls}
                    value={line.description}
                    onChange={e => updateLine(line.key, 'description', e.target.value)}
                    placeholder="Description *"
                    required
                  />
                </div>
                <div className="col-span-2">
                  <input
                    type="number"
                    className={inputCls}
                    value={line.quantity}
                    min={0.01}
                    step="0.01"
                    onChange={e => updateLine(line.key, 'quantity', Number(e.target.value))}
                  />
                </div>
                <div className="col-span-2">
                  <input
                    type="number"
                    className={inputCls}
                    value={line.unitPrice}
                    min={0}
                    step="0.01"
                    onChange={e => updateLine(line.key, 'unitPrice', Number(e.target.value))}
                  />
                </div>
                <div className="col-span-2 text-right text-sm text-[var(--ff-text-primary)] pr-1">
                  {fmt(line.quantity * line.unitPrice)}
                </div>
                <div className="col-span-1 flex justify-end">
                  <button
                    type="button"
                    onClick={() => removeLine(line.key)}
                    disabled={lines.length === 1}
                    className="p-1 text-red-400 hover:text-red-300 disabled:opacity-30 transition-colors"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            ))}

            {/* Totals */}
            <div className="border-t border-[var(--ff-border-light)] pt-3 space-y-1 text-sm">
              <div className="flex justify-between text-[var(--ff-text-secondary)]">
                <span>Subtotal</span><span>{fmt(subtotal)}</span>
              </div>
              <div className="flex justify-between text-[var(--ff-text-secondary)]">
                <span>VAT ({form.taxRate}%)</span>
                <span>{fmt(taxAmount)}</span>
              </div>
              <div className="flex justify-between font-semibold text-[var(--ff-text-primary)] text-base pt-1">
                <span>Total</span><span>{fmt(total)}</span>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pb-8">
            <Link
              href="/accounting/recurring-invoices"
              className="px-5 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
            >
              Cancel
            </Link>
            <button
              type="submit"
              disabled={submitting}
              className="inline-flex items-center gap-2 px-6 py-2 bg-violet-600 text-white rounded-lg hover:bg-violet-700 transition-colors text-sm font-medium disabled:opacity-50"
            >
              {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
              <Save className="h-4 w-4" />
              Save Changes
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Financial Year Management
 * View all fiscal years, lock/unlock periods, and close the year-end.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { CalendarRange, Plus, Loader2, AlertCircle, RefreshCw } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { useCompany } from '@/contexts/CompanyContext';
import type { FiscalPeriod } from '@/modules/accounting/types/gl.types';
import { groupPeriodsIntoYears } from '@/components/accounting/financialYears/types';
import { YearCard } from '@/components/accounting/financialYears/YearCard';
import { AddYearModal } from '@/components/accounting/financialYears/AddYearModal';
import { CloseYearModal } from '@/components/accounting/financialYears/CloseYearModal';
import { log } from '@/lib/logger';

export default function FinancialYearsPage() {
  const { activeCompany } = useCompany();

  const [periods, setPeriods] = useState<FiscalPeriod[]>([]);
  const [jeCounts, setJeCounts] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [loadingPeriodId, setLoadingPeriodId] = useState<string | null>(null);
  const [closingYear, setClosingYear] = useState<number | null>(null);

  // Modals
  const [showAddYear, setShowAddYear] = useState(false);
  const [closeYearTarget, setCloseYearTarget] = useState<number | null>(null);
  const [closingYearSaving, setClosingYearSaving] = useState(false);

  const groups = groupPeriodsIntoYears(periods);
  const existingYears = groups.map(g => g.year);

  // ── Data fetch ───────────────────────────────────────────────────────────

  const fetchPeriods = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/fiscal-periods');
      const json = await res.json() as { data?: FiscalPeriod[] };
      if (!res.ok) throw new Error('Failed to load fiscal periods');
      setPeriods(json.data ?? []);
    } catch (err) {
      log.error('Failed to fetch fiscal periods', { error: err }, 'financial-years-page');
      setError('Failed to load fiscal periods');
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchJeCounts = useCallback(async (year: number) => {
    try {
      const res = await apiFetch(`/api/accounting/fiscal-periods?jeCounts=true&year=${year}`);
      const json = await res.json() as { data?: Record<string, number> };
      if (res.ok && json.data) {
        setJeCounts(prev => ({ ...prev, ...json.data }));
      }
    } catch (err) {
      log.error('Failed to fetch JE counts', { year, error: err }, 'financial-years-page');
    }
  }, []);

  useEffect(() => {
    if (activeCompany?.id) void fetchPeriods();
  }, [activeCompany?.id, fetchPeriods]);

  useEffect(() => {
    for (const g of groups) void fetchJeCounts(g.year);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [periods, fetchJeCounts]);

  // ── Period actions ────────────────────────────────────────────────────────

  const handlePeriodAction = useCallback(async (id: string, action: 'close' | 'lock' | 'reopen') => {
    setLoadingPeriodId(id);
    try {
      const res = await apiFetch('/api/accounting/fiscal-periods-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, action }),
      });
      const json = await res.json() as { message?: string };
      if (!res.ok) throw new Error(json.message ?? 'Action failed');
      await fetchPeriods();
    } catch (err) {
      log.error('Period action failed', { id, action, error: err }, 'financial-years-page');
      setError(err instanceof Error ? err.message : 'Action failed');
    } finally {
      setLoadingPeriodId(null);
    }
  }, [fetchPeriods]);

  // ── Close year ────────────────────────────────────────────────────────────

  const handleCloseYearClick = useCallback((year: number) => {
    setCloseYearTarget(year);
  }, []);

  const handleCloseYearConfirm = useCallback(async () => {
    if (closeYearTarget === null) return;
    setClosingYearSaving(true);
    setClosingYear(closeYearTarget);
    try {
      const res = await apiFetch('/api/accounting/fiscal-periods-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'close_year', fiscalYear: closeYearTarget }),
      });
      const json = await res.json() as { message?: string };
      if (!res.ok) throw new Error(json.message ?? 'Failed to close year');
      setCloseYearTarget(null);
      await fetchPeriods();
    } catch (err) {
      log.error('Close year failed', { year: closeYearTarget, error: err }, 'financial-years-page');
      setError(err instanceof Error ? err.message : 'Failed to close year');
      setCloseYearTarget(null);
    } finally {
      setClosingYearSaving(false);
      setClosingYear(null);
    }
  }, [closeYearTarget, fetchPeriods]);

  // ── Add year ──────────────────────────────────────────────────────────────

  const handleAddYear = useCallback(async (year: number) => {
    const res = await apiFetch('/api/accounting/fiscal-periods', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ year }),
    });
    const json = await res.json() as { message?: string };
    if (!res.ok) throw new Error(json.message ?? 'Failed to create year');
    await fetchPeriods();
  }, [fetchPeriods]);

  // ── Close year modal data ─────────────────────────────────────────────────

  const closeYearGroup = closeYearTarget !== null
    ? groups.find(g => g.year === closeYearTarget) ?? null
    : null;
  const openCountForCloseYear = closeYearGroup?.periods.filter(p => p.status === 'open').length ?? 0;

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6 max-w-5xl">

        {/* Page header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <CalendarRange className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Financial Years</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Manage fiscal periods, lock months, and close year-end</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => void fetchPeriods()} disabled={loading}
              className="flex items-center gap-1.5 px-3 py-2 text-sm rounded-lg border border-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors disabled:opacity-50">
              <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
            </button>
            <button onClick={() => setShowAddYear(true)}
              className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors">
              <Plus className="h-4 w-4" /> Add New Year
            </button>
          </div>
        </div>

        {/* Error banner */}
        {error && (
          <div className="flex items-center gap-2 px-4 py-3 rounded-lg bg-red-500/10 border border-red-500/30 text-sm text-red-400">
            <AlertCircle className="h-4 w-4 shrink-0" />
            <span>{error}</span>
            <button onClick={() => setError('')} className="ml-auto text-red-400 hover:text-red-300">Dismiss</button>
          </div>
        )}

        {/* Loading state */}
        {loading && (
          <div className="flex justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        )}

        {/* Empty state */}
        {!loading && groups.length === 0 && (
          <div className="text-center py-16 space-y-3">
            <div className="mx-auto p-3 rounded-xl bg-teal-500/10 w-fit">
              <CalendarRange className="h-8 w-8 text-teal-500" />
            </div>
            <p className="text-[var(--ff-text-primary)] font-medium">No fiscal years configured</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">Create your first fiscal year to start tracking periods</p>
            <button onClick={() => setShowAddYear(true)}
              className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors">
              <Plus className="h-4 w-4" /> Add First Year
            </button>
          </div>
        )}

        {/* Year cards */}
        {!loading && groups.length > 0 && (
          <div className="space-y-4">
            {groups.map(group => (
              <YearCard key={group.year} group={group} jeCounts={jeCounts}
                loadingId={loadingPeriodId} onPeriodAction={handlePeriodAction}
                onCloseYear={handleCloseYearClick} closingYear={closingYear} />
            ))}
          </div>
        )}

      </div>

      {/* Modals */}
      {showAddYear && (
        <AddYearModal existingYears={existingYears}
          onConfirm={handleAddYear}
          onClose={() => setShowAddYear(false)} />
      )}

      {closeYearTarget !== null && (
        <CloseYearModal year={closeYearTarget} openCount={openCountForCloseYear}
          onConfirm={() => void handleCloseYearConfirm()}
          onCancel={() => setCloseYearTarget(null)}
          saving={closingYearSaving} />
      )}
    </AppLayout>
  );
}

/**
 * Customer Statements Send Page
 * Bulk-email account statements to selected customers.
 * Sage equivalent: Customers > Special > Statement Run (email variant)
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Mail, Loader2, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { ConfirmSendModal } from '@/components/accounting/statements/ConfirmSendModal';
import {
  CustomerStatementTable,
  type CustomerRow,
} from '@/components/accounting/statements/CustomerStatementTable';

// ─── Types ─────────────────────────────────────────────────────────────────

interface SendResult {
  sent: number;
  failed: number;
  errors: string[];
}

interface AgingBucket {
  entityId?: string;
  days30?: number;
  days60?: number;
  days90?: number;
  days120Plus?: number;
}

// ─── Page ─────────────────────────────────────────────────────────────────

export default function StatementsPage() {
  const today = new Date().toISOString().split('T')[0] ?? '';
  const [customers, setCustomers] = useState<CustomerRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [asAtDate, setAsAtDate] = useState(today);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [showAll, setShowAll] = useState(false);
  const [message, setMessage] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [sendResult, setSendResult] = useState<SendResult | null>(null);
  const [isSending, setIsSending] = useState(false);

  const load = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const [stmtRes, custRes, agingRes] = await Promise.all([
        apiFetch(`/api/accounting/customer-statements?as_at_date=${asAtDate}`),
        apiFetch('/api/accounting/customers?limit=500'),
        apiFetch('/api/accounting/ar-aging'),
      ]);
      const [stmtJson, custJson, agingJson] = await Promise.all([
        stmtRes.json() as Promise<Record<string, unknown>>,
        custRes.json() as Promise<Record<string, unknown>>,
        agingRes.json() as Promise<Record<string, unknown>>,
      ]);

      const balances = ((stmtJson.data ?? stmtJson) as { customers?: CustomerRow[] }).customers ?? [];

      const emailMap = new Map<string, string | null>();
      const custList = ((custJson.data ?? custJson) as { customers?: Array<{ id: string; email?: string | null }> }).customers ?? [];
      for (const c of custList) emailMap.set(c.id, c.email ?? null);

      // AR aging: AgingBucket has entityId + days30..days120Plus buckets
      const agingItems = ((agingJson.data ?? agingJson) as AgingBucket[] | { items?: AgingBucket[] });
      const buckets: AgingBucket[] = Array.isArray(agingItems)
        ? agingItems
        : (agingItems.items ?? []);
      const overdueMap = new Map<string, number>();
      for (const item of buckets) {
        const id = item.entityId ?? '';
        if (!id) continue;
        const overdue = (item.days30 ?? 0) + (item.days60 ?? 0) + (item.days90 ?? 0) + (item.days120Plus ?? 0);
        overdueMap.set(id, (overdueMap.get(id) ?? 0) + overdue);
      }

      const rows: CustomerRow[] = balances.map(b => ({
        client_id: b.client_id,
        client_name: b.client_name,
        email: emailMap.get(b.client_id) ?? null,
        total_invoiced: b.total_invoiced,
        total_paid: b.total_paid,
        balance: b.balance,
        overdue: overdueMap.get(b.client_id) ?? 0,
        invoice_count: b.invoice_count,
      }));

      setCustomers(rows);
      setSelected(new Set(rows.filter(r => r.balance > 0 && r.email).map(r => r.client_id)));
    } catch {
      setError('Failed to load customer data');
    } finally {
      setIsLoading(false);
    }
  }, [asAtDate]);

  useEffect(() => { void load(); }, [load]);

  const visible = useMemo(
    () => showAll ? customers : customers.filter(c => c.balance > 0),
    [customers, showAll]
  );

  function toggleAll() {
    const eligible = visible.filter(c => c.email);
    if (eligible.length > 0 && eligible.every(c => selected.has(c.client_id))) {
      setSelected(new Set());
    } else {
      setSelected(new Set(eligible.map(c => c.client_id)));
    }
  }

  function toggle(id: string) {
    const next = new Set(selected);
    if (next.has(id)) next.delete(id); else next.add(id);
    setSelected(next);
  }

  async function handleSend() {
    setIsSending(true);
    setSendResult(null);
    try {
      const res = await apiFetch('/api/accounting/customer-statements-send', {
        method: 'POST',
        body: JSON.stringify({
          customer_ids: Array.from(selected),
          as_at_date: asAtDate,
          message: message || undefined,
        }),
      });
      const json = await res.json() as { data?: SendResult } & SendResult;
      const result = (json.data ?? json) as SendResult;
      setSendResult(result);
    } catch {
      setSendResult({ sent: 0, failed: selected.size, errors: ['Network error — please try again'] });
    } finally {
      setIsSending(false);
      setShowModal(false);
    }
  }

  const eligibleCount = visible.filter(c => c.email && selected.has(c.client_id)).length;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between flex-wrap gap-3">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-purple-500/10">
                <Mail className="h-6 w-6 text-purple-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Send Statements</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Bulk-email account statements to customers</p>
              </div>
            </div>
            <button
              onClick={() => setShowModal(true)}
              disabled={eligibleCount === 0 || isSending}
              className="inline-flex items-center gap-2 px-5 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-sm font-medium disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <Mail className="h-4 w-4" />
              Send to {eligibleCount} Customer{eligibleCount !== 1 ? 's' : ''}
            </button>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Controls row */}
          <div className="flex items-center gap-4 flex-wrap">
            <label className="flex items-center gap-2 text-sm text-[var(--ff-text-secondary)]">
              As at:
              <input
                type="date"
                value={asAtDate}
                onChange={e => setAsAtDate(e.target.value)}
                className="px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm"
              />
            </label>
            <label className="flex items-center gap-2 text-sm text-[var(--ff-text-secondary)] cursor-pointer select-none">
              <input
                type="checkbox"
                checked={showAll}
                onChange={e => setShowAll(e.target.checked)}
                className="rounded border-[var(--ff-border-light)]"
              />
              Show zero-balance customers
            </label>
            <span className="text-sm text-[var(--ff-text-tertiary)] ml-auto">
              {visible.length} customer{visible.length !== 1 ? 's' : ''} &bull; {selected.size} selected
            </span>
          </div>

          {/* Optional message */}
          <div>
            <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">
              Custom message (optional)
            </label>
            <input
              type="text"
              value={message}
              onChange={e => setMessage(e.target.value)}
              placeholder="e.g. Please find your statement. Contact us if you have any queries."
              className="w-full max-w-xl px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm placeholder:text-[var(--ff-text-tertiary)]"
            />
          </div>

          {/* Send result banner */}
          {sendResult && (
            <div className={`flex items-start gap-3 p-4 rounded-lg text-sm ${sendResult.failed === 0 ? 'bg-emerald-500/10 text-emerald-400' : 'bg-yellow-500/10 text-yellow-400'}`}>
              <AlertCircle className="h-5 w-5 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium">
                  {sendResult.sent} sent successfully{sendResult.failed > 0 ? `, ${sendResult.failed} failed` : ''}.
                </p>
                {sendResult.errors.length > 0 && (
                  <ul className="mt-1 list-disc list-inside text-xs space-y-0.5">
                    {sendResult.errors.map((e, i) => <li key={i}>{e}</li>)}
                  </ul>
                )}
              </div>
            </div>
          )}

          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {/* Customer table */}
          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-8 w-8 animate-spin text-purple-500" />
            </div>
          ) : visible.length === 0 ? (
            <div className="text-center py-16 text-[var(--ff-text-secondary)]">
              No customers with outstanding balances
            </div>
          ) : (
            <CustomerStatementTable
              rows={visible}
              selected={selected}
              onToggle={toggle}
              onToggleAll={toggleAll}
            />
          )}
        </div>
      </div>

      {showModal && (
        <ConfirmSendModal
          count={eligibleCount}
          asAtDate={asAtDate}
          isSending={isSending}
          onConfirm={() => { void handleSend(); }}
          onCancel={() => setShowModal(false)}
        />
      )}
    </AppLayout>
  );
}

/**
 * Supplier Contacts Tab
 * Lists, creates and deletes contacts for a supplier.
 */

import { useState, useEffect, useCallback } from 'react';
import { Users, User, Plus, Trash2, Star, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface SupplierContact {
  id: string;
  full_name: string;
  role: string | null;
  email: string | null;
  phone: string | null;
  is_primary: boolean;
}

const EMPTY_FORM = { fullName: '', role: '', email: '', phone: '', isPrimary: false };

export function ContactsTab({ supplierId }: { supplierId: string }) {
  const [contacts, setContacts] = useState<SupplierContact[]>([]);
  const [loading, setLoading]   = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving]     = useState(false);
  const [form, setForm]         = useState(EMPTY_FORM);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res  = await apiFetch(`/api/accounting/supplier-contacts?supplierId=${supplierId}`);
      const json = await res.json() as { data?: SupplierContact[] } | SupplierContact[];
      const data = (json as { data?: SupplierContact[] }).data ?? (json as SupplierContact[]);
      setContacts(data);
    } finally {
      setLoading(false);
    }
  }, [supplierId]);

  useEffect(() => { void load(); }, [load]);

  const handleAdd = async () => {
    if (!form.fullName.trim()) return;
    setSaving(true);
    try {
      await apiFetch('/api/accounting/supplier-contacts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ supplierId, ...form }),
      });
      setForm(EMPTY_FORM);
      setShowForm(false);
      void load();
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    await apiFetch(`/api/accounting/supplier-contacts?id=${id}`, { method: 'DELETE' });
    void load();
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h3 className="text-sm font-medium text-[var(--ff-text-secondary)] uppercase tracking-wide">
          Contacts
        </h3>
        <button
          onClick={() => setShowForm(true)}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium transition-colors"
        >
          <Plus className="h-4 w-4" /> Add Contact
        </button>
      </div>

      {showForm && (
        <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4 space-y-3">
          <p className="text-sm font-medium text-[var(--ff-text-primary)]">New Contact</p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <input
              placeholder="Full Name *"
              value={form.fullName}
              onChange={e => setForm(f => ({ ...f, fullName: e.target.value }))}
              className="input-field"
            />
            <input
              placeholder="Role / Title"
              value={form.role}
              onChange={e => setForm(f => ({ ...f, role: e.target.value }))}
              className="input-field"
            />
            <input
              placeholder="Email"
              type="email"
              value={form.email}
              onChange={e => setForm(f => ({ ...f, email: e.target.value }))}
              className="input-field"
            />
            <input
              placeholder="Phone"
              value={form.phone}
              onChange={e => setForm(f => ({ ...f, phone: e.target.value }))}
              className="input-field"
            />
          </div>
          <label className="flex items-center gap-2 text-sm text-[var(--ff-text-secondary)] cursor-pointer">
            <input
              type="checkbox"
              checked={form.isPrimary}
              onChange={e => setForm(f => ({ ...f, isPrimary: e.target.checked }))}
              className="rounded"
            />
            Set as primary contact
          </label>
          <div className="flex gap-2">
            <button
              onClick={handleAdd}
              disabled={saving || !form.fullName.trim()}
              className="px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-sm font-medium transition-colors"
            >
              {saving ? 'Saving...' : 'Save Contact'}
            </button>
            <button
              onClick={() => setShowForm(false)}
              className="px-4 py-2 rounded-lg border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] text-sm transition-colors"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {contacts.length === 0 && !showForm && (
        <div className="text-center py-12 bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
          <Users className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
          <p className="text-sm text-[var(--ff-text-secondary)]">No contacts yet</p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
            Add contacts with names, roles and phone numbers
          </p>
        </div>
      )}

      <div className="space-y-3">
        {contacts.map(contact => (
          <div
            key={contact.id}
            className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4 flex items-start justify-between gap-4"
          >
            <div className="flex items-start gap-3">
              <div className="w-8 h-8 rounded-full bg-blue-500/10 flex items-center justify-center shrink-0">
                <User className="h-4 w-4 text-blue-400" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-[var(--ff-text-primary)]">
                    {contact.full_name}
                  </span>
                  {contact.is_primary && (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-teal-500/20 text-teal-400 text-xs font-medium">
                      <Star className="h-3 w-3" /> Primary
                    </span>
                  )}
                </div>
                {contact.role && (
                  <p className="text-xs text-[var(--ff-text-tertiary)]">{contact.role}</p>
                )}
                <div className="flex gap-3 mt-1">
                  {contact.email && (
                    <span className="text-xs text-[var(--ff-text-secondary)]">{contact.email}</span>
                  )}
                  {contact.phone && (
                    <span className="text-xs text-[var(--ff-text-secondary)]">{contact.phone}</span>
                  )}
                </div>
              </div>
            </div>
            <button
              onClick={() => handleDelete(contact.id)}
              title="Delete contact"
              className="p-1.5 rounded hover:bg-red-500/10 text-[var(--ff-text-tertiary)] hover:text-red-400 transition-colors shrink-0"
            >
              <Trash2 className="h-4 w-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Supplier Activity Timeline Tab
 * Displays a chronological feed of supplier activities (notes, calls, emails, etc.)
 * and provides an inline form for creating new activity entries.
 */

import { useState, useEffect, useCallback } from 'react';
import {
  MessageSquare, Phone, Mail, DollarSign, FileText, RefreshCw,
  Clock, Plus, Trash2, Loader2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

type ActivityType =
  | 'note'
  | 'call'
  | 'email_sent'
  | 'email_received'
  | 'payment_made'
  | 'invoice_received'
  | 'status_change';

interface SupplierActivity {
  id: string;
  supplier_id: string;
  activity_type: ActivityType;
  subject: string | null;
  description: string;
  created_at: string | Date;
  created_by: string;
  created_by_email: string | null;
  created_by_first_name: string | null;
  created_by_last_name: string | null;
}

const ACTIVITY_TYPE_OPTIONS: { value: ActivityType; label: string }[] = [
  { value: 'note',             label: 'Note' },
  { value: 'call',             label: 'Call' },
  { value: 'email_sent',       label: 'Email Sent' },
  { value: 'email_received',   label: 'Email Received' },
];

const EMPTY_FORM = { activity_type: 'note' as ActivityType, subject: '', description: '' };

function activityIcon(type: ActivityType) {
  switch (type) {
    case 'note':              return <MessageSquare className="h-4 w-4" />;
    case 'call':              return <Phone         className="h-4 w-4" />;
    case 'email_sent':
    case 'email_received':    return <Mail          className="h-4 w-4" />;
    case 'payment_made':      return <DollarSign    className="h-4 w-4" />;
    case 'invoice_received':  return <FileText      className="h-4 w-4" />;
    case 'status_change':     return <RefreshCw     className="h-4 w-4" />;
  }
}

function activityIconColor(type: ActivityType): string {
  switch (type) {
    case 'note':              return 'bg-blue-500/10 text-blue-400';
    case 'call':              return 'bg-teal-500/10 text-teal-400';
    case 'email_sent':
    case 'email_received':    return 'bg-purple-500/10 text-purple-400';
    case 'payment_made':      return 'bg-green-500/10 text-green-400';
    case 'invoice_received':  return 'bg-orange-500/10 text-orange-400';
    case 'status_change':     return 'bg-yellow-500/10 text-yellow-400';
  }
}

function activityTypeLabel(type: ActivityType): string {
  const map: Record<ActivityType, string> = {
    note:             'Note',
    call:             'Call',
    email_sent:       'Email Sent',
    email_received:   'Email Received',
    payment_made:     'Payment Made',
    invoice_received: 'Invoice Received',
    status_change:    'Status Change',
  };
  return map[type] ?? type;
}

function relativeTime(raw: string | Date): string {
  const date   = raw instanceof Date ? raw : new Date(raw);
  const diffMs  = Date.now() - date.getTime();
  const diffSec = Math.floor(diffMs / 1000);
  if (diffSec < 60)  return 'just now';
  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60)  return `${diffMin} minute${diffMin === 1 ? '' : 's'} ago`;
  const diffHr  = Math.floor(diffMin / 60);
  if (diffHr  < 24)  return `${diffHr} hour${diffHr === 1 ? '' : 's'} ago`;
  const diffDay = Math.floor(diffHr  / 24);
  if (diffDay < 30)  return `${diffDay} day${diffDay === 1 ? '' : 's'} ago`;
  return date.toLocaleDateString('en-ZA');
}

function creatorName(activity: SupplierActivity): string {
  const first = activity.created_by_first_name?.trim() ?? '';
  const last  = activity.created_by_last_name?.trim()  ?? '';
  if (first || last) return `${first} ${last}`.trim();
  return activity.created_by_email ?? 'Unknown';
}

export function ActivityTab({ supplierId }: { supplierId: string }) {
  const [activities, setActivities] = useState<SupplierActivity[]>([]);
  const [loading, setLoading]       = useState(true);
  const [showForm, setShowForm]     = useState(false);
  const [saving, setSaving]         = useState(false);
  const [form, setForm]             = useState(EMPTY_FORM);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res  = await apiFetch(`/api/accounting/supplier-activities?supplierId=${supplierId}`);
      const json = await res.json() as { data?: SupplierActivity[] } | SupplierActivity[];
      const data = (json as { data?: SupplierActivity[] }).data ?? (json as SupplierActivity[]);
      setActivities(data);
    } finally {
      setLoading(false);
    }
  }, [supplierId]);

  useEffect(() => { void load(); }, [load]);

  const handleAdd = async () => {
    if (!form.description.trim()) return;
    setSaving(true);
    try {
      await apiFetch('/api/accounting/supplier-activities', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          supplierId,
          activity_type: form.activity_type,
          subject:       form.subject.trim() || undefined,
          description:   form.description.trim(),
        }),
      });
      setForm(EMPTY_FORM);
      setShowForm(false);
      void load();
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    await apiFetch(`/api/accounting/supplier-activities?id=${id}`, { method: 'DELETE' });
    void load();
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header row */}
      <div className="flex justify-between items-center">
        <h3 className="text-sm font-medium text-[var(--ff-text-secondary)] uppercase tracking-wide">
          Activity Timeline
        </h3>
        <button
          onClick={() => setShowForm(true)}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium transition-colors"
        >
          <Plus className="h-4 w-4" /> Add Activity
        </button>
      </div>

      {/* Add-activity form */}
      {showForm && (
        <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4 space-y-3">
          <p className="text-sm font-medium text-[var(--ff-text-primary)]">New Activity</p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <select
              value={form.activity_type}
              onChange={e => setForm(f => ({ ...f, activity_type: e.target.value as ActivityType }))}
              className="input-field"
            >
              {ACTIVITY_TYPE_OPTIONS.map(opt => (
                <option key={opt.value} value={opt.value}>{opt.label}</option>
              ))}
            </select>
            <input
              placeholder="Subject (optional)"
              value={form.subject}
              onChange={e => setForm(f => ({ ...f, subject: e.target.value }))}
              className="input-field"
            />
          </div>
          <textarea
            placeholder="Description *"
            value={form.description}
            onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
            rows={3}
            className="input-field w-full resize-none"
          />
          <div className="flex gap-2">
            <button
              onClick={handleAdd}
              disabled={saving || !form.description.trim()}
              className="px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-sm font-medium transition-colors"
            >
              {saving ? 'Saving...' : 'Save Activity'}
            </button>
            <button
              onClick={() => { setShowForm(false); setForm(EMPTY_FORM); }}
              className="px-4 py-2 rounded-lg border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] text-sm transition-colors"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Empty state */}
      {activities.length === 0 && !showForm && (
        <div className="text-center py-12 bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
          <Clock className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-2" />
          <p className="text-sm text-[var(--ff-text-secondary)]">No activities yet</p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
            Log calls, notes and emails to keep track of supplier interactions
          </p>
        </div>
      )}

      {/* Timeline feed */}
      <div className="space-y-3">
        {activities.map(activity => (
          <div
            key={activity.id}
            className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4 flex items-start justify-between gap-4"
          >
            <div className="flex items-start gap-3">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${activityIconColor(activity.activity_type)}`}>
                {activityIcon(activity.activity_type)}
              </div>
              <div>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-xs font-semibold uppercase tracking-wide text-[var(--ff-text-tertiary)]">
                    {activityTypeLabel(activity.activity_type)}
                  </span>
                  {activity.subject && (
                    <span className="text-sm font-medium text-[var(--ff-text-primary)]">
                      {activity.subject}
                    </span>
                  )}
                </div>
                <p className="text-sm text-[var(--ff-text-secondary)] mt-0.5 whitespace-pre-wrap">
                  {activity.description}
                </p>
                <p className="text-xs text-[var(--ff-text-tertiary)] mt-1.5">
                  {creatorName(activity)} &middot; {relativeTime(activity.created_at)}
                </p>
              </div>
            </div>
            <button
              onClick={() => handleDelete(activity.id)}
              title="Delete activity"
              className="p-1.5 rounded hover:bg-red-500/10 text-[var(--ff-text-tertiary)] hover:text-red-400 transition-colors shrink-0"
            >
              <Trash2 className="h-4 w-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * ConfirmSendModal
 * Shown before bulk-sending statements. Displays count and as-at date,
 * then calls onConfirm or onCancel.
 */

import { Loader2, Mail, X } from 'lucide-react';

interface Props {
  count: number;
  asAtDate: string;
  isSending: boolean;
  onConfirm: () => void;
  onCancel: () => void;
}

const fmtDate = (d: string): string => {
  const parts = d.split('-');
  return parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : d;
};

