  for (const r of results) {
    const icon = r.result === 'PASS' ? 'PASS' : r.result === 'FAIL' ? 'FAIL' : 'SKIP';
    console.log(
      `${String(r.step).padEnd(5)} ${r.feature.substring(0,31).padEnd(32)} ${r.action.substring(0,44).padEnd(45)} ${r.expected.substring(0,29).padEnd(30)} ${r.actual.substring(0,39).padEnd(40)} ${icon}`
    );
    if (r.notes) console.log(`      NOTE: ${r.notes}`);
  }
  console.log('-'.repeat(170));
  console.log(`\nSummary: ${passed}/${total} steps passed  |  ${failed} failed  |  ${skipped} skipped`);
  console.log('='.repeat(80));
}

(async () => {
  const browser: Browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();

  // Capture unhandled errors
  const consoleErrors: string[] = [];
  page.on('console', msg => {
    if (msg.type() === 'error') consoleErrors.push(`[${page.url().split('/').pop()}] ${msg.text().substring(0, 150)}`);
  });
  page.on('pageerror', err => consoleErrors.push(`[pageerror] ${err.message.substring(0, 150)}`));

  try {
    const loggedIn = await login(page);
    if (!loggedIn) {
      console.log('Login failed. Attempting with demo credentials...');
      // Try demo login
      await page.goto(`${BASE}/login`, { waitUntil: 'networkidle', timeout: 10000 });
