  const routes = ['/customers/statements', '/customers/send-statements', '/customers/customer-statements'];
  let loaded = false;

  for (const route of routes) {
    try {
      await page.goto(`${BASE}${route}`, { waitUntil: 'networkidle', timeout: 10000 });
      await page.waitForTimeout(1500);
      const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 3000));
      const is404 = bodyText.includes('404') || bodyText.includes('Page not found') || bodyText.includes('This page could not be found');
      if (!is404) {
        const url = page.url();
        record(feature, `Navigate to ${route}`, 'Page loads', `URL: ${url}`, 'PASS');
        loaded = true;

        // Check for customer list with balances
        const hasCustomers = bodyText.toLowerCase().includes('customer') || bodyText.toLowerCase().includes('balance');
        record(feature, 'Check customer list with balances', 'Customer list + balances visible', hasCustomers ? 'Customer/balance content found' : 'No customer list', hasCustomers ? 'PASS' : 'FAIL');

        // Check checkboxes
        const hasCheckboxes = await page.$('input[type="checkbox"]') !== null;
        record(feature, 'Check checkboxes for selection', 'Checkboxes visible', hasCheckboxes ? 'Checkboxes present' : 'No checkboxes', hasCheckboxes ? 'PASS' : 'FAIL');
        break;
      }
    } catch (_) {
      // try next route
    }
  }

  if (!loaded) {
    record(feature, 'Navigate to statements page', 'Page loads', 'All routes returned 404', 'FAIL', `Tried: ${routes.join(', ')}`);
  }
}

async function testSupplierDetail(page: Page) {
  const feature = 'Supplier Detail — Contacts & Activity';
  try {
    // First get list of suppliers
    await page.goto(`${BASE}/suppliers`, { waitUntil: 'networkidle', timeout: 15000 });
    await page.waitForTimeout(2000);
    const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 3000));
    const is404 = bodyText.includes('404') || bodyText.includes('Page not found');
    if (is404) {
      record(feature, 'Navigate to /suppliers', 'Supplier list loads', '404', 'FAIL');
      return;
    }

    // Click first supplier link
    const supplierLink = await page.$('table tbody tr td a, [data-testid="supplier-row"] a, a[href*="/suppliers/"]');
    if (!supplierLink) {
      // Try navigating directly to suppliers list
      const links = await page.$$('a[href*="/suppliers/"]');
      if (links.length === 0) {
        record(feature, 'Find a supplier to click', 'Supplier found in list', 'No supplier links found', 'FAIL', 'Supplier list may be empty or use different markup');
        return;
      }
    }

    const link = supplierLink || (await page.$$('a[href*="/suppliers/"]'))[0];
    if (link) {
      const href = await link.getAttribute('href');
      await link.click();
      await page.waitForTimeout(2000);
      const detailUrl = page.url();
      const detailText = await page.evaluate(() => document.body.innerText.substring(0, 3000));
      record(feature, `Click supplier (href: ${href})`, 'Supplier detail page opens', `URL: ${detailUrl}`, 'PASS');

      // Check Contacts tab
      const contactsTab = await page.$('button:has-text("Contacts"), [role="tab"]:has-text("Contacts"), a:has-text("Contacts")');
      record(feature, 'Check "Contacts" tab visible', '"Contacts" tab present', contactsTab ? 'Contacts tab found' : 'Not found', contactsTab ? 'PASS' : 'FAIL');

      // Check Activity tab
      const activityTab = await page.$('button:has-text("Activity"), [role="tab"]:has-text("Activity"), a:has-text("Activity")');
      record(feature, 'Check "Activity" tab visible', '"Activity" tab present', activityTab ? 'Activity tab found' : 'Not found', activityTab ? 'PASS' : 'FAIL');

      // Click Contacts tab
      if (contactsTab) {
        await contactsTab.click();
        await page.waitForTimeout(1500);
        const hasError = (await page.evaluate(() => document.body.innerText)).toLowerCase().includes('application error');
        record(feature, 'Click "Contacts" tab', 'Tab loads without error', hasError ? 'Application error' : 'Tab loaded', hasError ? 'FAIL' : 'PASS');
      } else {
        record(feature, 'Click "Contacts" tab', 'Tab loads', 'Tab not found — skipped', 'SKIP');
      }

      // Click Activity tab
      if (activityTab) {
        await activityTab.click();
        await page.waitForTimeout(1500);
        const hasError = (await page.evaluate(() => document.body.innerText)).toLowerCase().includes('application error');
        record(feature, 'Click "Activity" tab', 'Tab loads without error', hasError ? 'Application error' : 'Tab loaded', hasError ? 'FAIL' : 'PASS');
      } else {
        record(feature, 'Click "Activity" tab', 'Tab loads', 'Tab not found — skipped', 'SKIP');
      }
    } else {
      record(feature, 'Find a supplier to click', 'Supplier found', 'No supplier links', 'FAIL');
    }
  } catch (e: any) {
    record(feature, 'Supplier detail test', 'Page loads', `Exception: ${e.message}`, 'FAIL');
  }
}

async function testItemBundles(page: Page) {
  const feature = 'Item Bundles';
  try {
    // Navigate to items list
    await page.goto(`${BASE}/items`, { waitUntil: 'networkidle', timeout: 15000 });
    await page.waitForTimeout(2000);
    const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 3000));
    const is404 = bodyText.includes('404') || bodyText.includes('Page not found');
    if (is404) {
      record(feature, 'Navigate to /items', 'Items list loads', '404', 'FAIL');
      return;
    }

    // Click first item
    const itemLink = await page.$('a[href*="/items/"], table tbody tr td a');
    if (!itemLink) {
      record(feature, 'Find an item to click', 'Item found in list', 'No item links found', 'FAIL', 'Items list may be empty');
      return;
    }
    const href = await itemLink.getAttribute('href');
    await itemLink.click();
    await page.waitForTimeout(2000);
    const detailUrl = page.url();
    record(feature, `Navigate to item detail (href: ${href})`, 'Item detail page opens', `URL: ${detailUrl}`, 'PASS');

    const detailText = await page.evaluate(() => document.body.innerText.substring(0, 3000));
    // Check Bundle Components section
    const hasBundle = detailText.toLowerCase().includes('bundle') || detailText.toLowerCase().includes('component') ||
      await page.$('[data-testid*="bundle"], .bundle-section, label:has-text("Bundle")') !== null;
    record(feature, 'Check "Bundle Components" section', 'Bundle section visible', hasBundle ? 'Bundle section found' : 'No bundle section', hasBundle ? 'PASS' : 'FAIL');

    // Try toggling bundle switch
    const bundleSwitch = await page.$('input[type="checkbox"][id*="bundle" i], button[role="switch"][aria-label*="bundle" i], [data-testid*="bundle-toggle"]');
    if (bundleSwitch) {
      await bundleSwitch.click();
      await page.waitForTimeout(1000);
      record(feature, 'Toggle bundle switch', 'Switch toggles without error', 'Switch toggled', 'PASS');
    } else {
      record(feature, 'Toggle bundle switch', 'Switch toggles', 'Bundle toggle not found', hasBundle ? 'FAIL' : 'SKIP', 'May be inside bundle section that is not loaded');
    }
  } catch (e: any) {
    record(feature, 'Item bundles test', 'Page loads', `Exception: ${e.message}`, 'FAIL');
  }
}

async function testAdminCompanies(page: Page) {
  const feature = 'Admin — Companies';
  try {
    await page.goto(`${BASE}/admin/companies`, { waitUntil: 'networkidle', timeout: 15000 });
    await page.waitForTimeout(2000);
    const url = page.url();
    const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 3000));

    const is404 = bodyText.includes('404') || bodyText.includes('Page not found') || bodyText.includes('This page could not be found');
    if (is404) {
      record(feature, 'Navigate to /admin/companies', 'Admin companies page loads', '404 — routing issue or separate subdomain', 'FAIL', 'May only be accessible at admin.isaflow.co.za');
      return;
    }
    const hasError = bodyText.toLowerCase().includes('application error') || bodyText.toLowerCase().includes('something went wrong');
    if (hasError) {
      record(feature, 'Navigate to /admin/companies', 'Page loads', 'Application error', 'FAIL');
      return;
    }
    // Redirect to login? (unauthorized)
    if (url.includes('/login')) {
      record(feature, 'Navigate to /admin/companies', 'Admin page loads', 'Redirected to login — unauthorized', 'FAIL', 'Admin route requires admin role');
      return;
    }
    record(feature, 'Navigate to /admin/companies', 'Page loads', `URL: ${url}`, 'PASS');

    // Check "Add Company" button
    const addBtn = await page.$('button:has-text("Add Company"), a:has-text("Add Company"), button:has-text("New Company")');
    record(feature, 'Check "Add Company" button', 'Button visible', addBtn ? 'Button found' : 'Button not found', addBtn ? 'PASS' : 'FAIL');

    // Check Actions column with Suspend/Activate
    const hasActions = bodyText.includes('Suspend') || bodyText.includes('Activate') || bodyText.includes('Actions') ||
      await page.$('[data-testid*="suspend"], [aria-label*="suspend" i], [title*="Suspend"]') !== null;
    record(feature, 'Check Actions column (Suspend/Activate)', 'Suspend/Activate icons visible', hasActions ? 'Actions found' : 'No actions found', hasActions ? 'PASS' : 'FAIL');

  } catch (e: any) {
    record(feature, 'Admin companies test', 'Page loads', `Exception: ${e.message}`, 'FAIL');
  }
}

function printReport() {
  const date = new Date().toISOString().split('T')[0];
  const passed = results.filter(r => r.result === 'PASS').length;
  const failed = results.filter(r => r.result === 'FAIL').length;
  const skipped = results.filter(r => r.result === 'SKIP').length;
  const total = results.length;

  console.log('\n\n' + '='.repeat(80));
  console.log(`QA Report: ISAFlow New Features`);
  console.log(`Date: ${date}`);
  console.log(`Target: ${BASE}`);
  console.log('='.repeat(80));
  console.log(`\n${'Step'.padEnd(5)} ${'Feature'.padEnd(32)} ${'Action'.padEnd(45)} ${'Expected'.padEnd(30)} ${'Actual'.padEnd(40)} Result`);
  console.log('-'.repeat(170));
  for (const r of results) {
    const icon = r.result === 'PASS' ? 'PASS' : r.result === 'FAIL' ? 'FAIL' : 'SKIP';
    console.log(
      `${String(r.step).padEnd(5)} ${r.feature.substring(0,31).padEnd(32)} ${r.action.substring(0,44).padEnd(45)} ${r.expected.substring(0,29).padEnd(30)} ${r.actual.substring(0,39).padEnd(40)} ${icon}`
    );
    if (r.notes) console.log(`      NOTE: ${r.notes}`);
  }
  console.log('-'.repeat(170));
  console.log(`\nSummary: ${passed}/${total} steps passed  |  ${failed} failed  |  ${skipped} skipped`);
  console.log('='.repeat(80));
}

(async () => {
  const browser: Browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();

  // Capture unhandled errors
  const consoleErrors: string[] = [];
  page.on('console', msg => {
    if (msg.type() === 'error') consoleErrors.push(`[${page.url().split('/').pop()}] ${msg.text().substring(0, 150)}`);
  });
  page.on('pageerror', err => consoleErrors.push(`[pageerror] ${err.message.substring(0, 150)}`));

  try {
    const loggedIn = await login(page);
    if (!loggedIn) {
      console.log('Login failed. Attempting with demo credentials...');
      // Try demo login
      await page.goto(`${BASE}/login`, { waitUntil: 'networkidle', timeout: 10000 });
      // Check if there are any users available on page
      const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 500));
      console.log('Login page text:', bodyText.substring(0, 200));
    }

    await testFinancialYears(page);
    await testDeliveryNotes(page);
    await testRecurringInvoices(page);
    await testCustomerStatements(page);
    await testSupplierDetail(page);
    await testItemBundles(page);
    await testAdminCompanies(page);

  } finally {
    if (consoleErrors.length > 0) {
      console.log('\n--- Console Errors Observed During Testing ---');
      consoleErrors.slice(0, 20).forEach(e => console.log('  ' + e));
    }
    printReport();
    await browser.close();
  }
})();

