/**
 * QA script for new ISAFlow features — localhost:3200
 * Tests: Financial Years, Delivery Notes, Recurring Invoices,
 *        Customer Statements, Supplier Detail tabs, Item Bundles, Admin Companies
 */

import { chromium, Browser, Page } from 'playwright';

const BASE = 'http://localhost:3200';
const EMAIL = 'admin@isaflow.co.za';
const PASS = 'admin123';

interface TestResult {
  step: number;
  feature: string;
  action: string;
  expected: string;
  actual: string;
  result: 'PASS' | 'FAIL' | 'SKIP';
  notes?: string;
}

const results: TestResult[] = [];
let stepNum = 0;

function record(
  feature: string,
  action: string,
  expected: string,
  actual: string,
  result: 'PASS' | 'FAIL' | 'SKIP',
  notes?: string
) {
  stepNum++;
  results.push({ step: stepNum, feature, action, expected, actual, result, notes });
  const icon = result === 'PASS' ? '✓' : result === 'FAIL' ? '✗' : '~';
  console.log(`[${icon}] Step ${stepNum} | ${feature} | ${action} → ${result}${notes ? ' | ' + notes : ''}`);
}

async function login(page: Page): Promise<boolean> {
  try {
    await page.goto(`${BASE}/login`, { waitUntil: 'networkidle', timeout: 15000 });
    const url = page.url();
    // If already on dashboard, we're logged in
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      record('Auth', 'Login', 'Logged in', 'Already authenticated', 'PASS');
      return true;
    }
    await page.fill('input[type="email"]', EMAIL);
    await page.fill('input[type="password"]', PASS);
    await page.click('button[type="submit"]');
    await page.waitForTimeout(3000);
    const afterUrl = page.url();
    if (afterUrl.includes('/login')) {
      // Try alternate credentials — demo company
      record('Auth', 'Login with admin@isaflow.co.za', 'Dashboard', `Still on ${afterUrl}`, 'FAIL', 'Trying demo user');
      return false;
    }
    record('Auth', 'Login', 'Dashboard', afterUrl, 'PASS');
    return true;
  } catch (e: any) {
    record('Auth', 'Login', 'Dashboard', `Error: ${e.message}`, 'FAIL');
    return false;
  }
}

async function getConsoleErrors(page: Page): Promise<string[]> {
  const errors: string[] = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text().substring(0, 200));
  });
  return errors;
}

async function testFinancialYears(page: Page) {
