function printReport() {
  const date = new Date().toISOString().split('T')[0];
  const passed = results.filter(r => r.result === 'PASS').length;
  const failed = results.filter(r => r.result === 'FAIL').length;
  const skipped = results.filter(r => r.result === 'SKIP').length;
  const total = results.length;

  console.log('\n\n' + '='.repeat(80));
  console.log(`QA Report: ISAFlow New Features`);
  console.log(`Date: ${date}`);
  console.log(`Target: ${BASE}`);
  console.log('='.repeat(80));
  console.log(`\n${'Step'.padEnd(5)} ${'Feature'.padEnd(32)} ${'Action'.padEnd(45)} ${'Expected'.padEnd(30)} ${'Actual'.padEnd(40)} Result`);
  console.log('-'.repeat(170));
  for (const r of results) {
    const icon = r.result === 'PASS' ? 'PASS' : r.result === 'FAIL' ? 'FAIL' : 'SKIP';
    console.log(
      `${String(r.step).padEnd(5)} ${r.feature.substring(0,31).padEnd(32)} ${r.action.substring(0,44).padEnd(45)} ${r.expected.substring(0,29).padEnd(30)} ${r.actual.substring(0,39).padEnd(40)} ${icon}`
    );
    if (r.notes) console.log(`      NOTE: ${r.notes}`);
  }
  console.log('-'.repeat(170));
  console.log(`\nSummary: ${passed}/${total} steps passed  |  ${failed} failed  |  ${skipped} skipped`);
  console.log('='.repeat(80));
}

