    // Ensure all entities appear in byEntity (even if zero)
    for (const acc of accountMap.values()) {
      for (const id of allIds) {
        if (!acc.byEntity[id]) {
          acc.byEntity[id] = { debit: 0, credit: 0 };
        }
      }
    }

    const accounts = Array.from(accountMap.values()).sort((a, b) =>
      a.accountCode.localeCompare(b.accountCode),
    );

    const totalDebits  = accounts.reduce((s, a) => s + a.totalDebit,  0);
    const totalCredits = accounts.reduce((s, a) => s + a.totalCredit, 0);

    const selfName = groupCompanies[0]?.name ?? companyId;

    return {
      groupName: selfName,
      periodStart,
      periodEnd,
