/**
 * Consolidation Service
 *
 * Manages direct parent-child company relationships and produces consolidated
 * trial balances by aggregating GL data across group entities.
 *
 * NOTE: This is the lightweight "company_relationships" model.
 * The full group-reporting model (company_groups / company_group_members) is
 * in consolidatedTrialBalanceService.ts / consolidatedReportingService.ts.
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = DbRow;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface GroupCompany {
  id: string;
  name: string;
  relationshipType: string;
  ownershipPercent: number;
}

export interface ConsolidatedAccount {
  accountCode: string;
  accountName: string;
  accountType: string;
  byEntity: Record<string, { debit: number; credit: number }>;
  totalDebit: number;
  totalCredit: number;
  isEliminated: boolean;
}

export interface ConsolidatedTrialBalance {
  groupName: string;
  periodStart: string;
  periodEnd: string;
  entities: { companyId: string; companyName: string }[];
  accounts: ConsolidatedAccount[];
  totalDebits: number;
  totalCredits: number;
}

export interface IntercompanyBalance {
  fromCompanyId: string;
  fromCompanyName: string;
  toCompanyId: string;
  toCompanyName: string;
  eliminationType: string;
  amount: number;
  description: string | null;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Returns all child company IDs for a given parent (does NOT include self). */
async function getChildCompanyIds(parentCompanyId: string): Promise<string[]> {
  const rows = (await sql`
    SELECT child_company_id
    FROM company_relationships
    WHERE parent_company_id = ${parentCompanyId}::UUID
    ORDER BY created_at
  `) as Row[];
  return rows.map((r) => String(r.child_company_id));
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Returns the parent company itself plus all direct subsidiaries/branches.
 * The parent row is included first with ownershipPercent = 100.
 */
export async function getGroupCompanies(companyId: string): Promise<GroupCompany[]> {
  try {
    const selfRows = (await sql`
      SELECT id, name FROM companies WHERE id = ${companyId}::UUID
    `) as Row[];

    if (selfRows.length === 0) {
      throw new Error(`Company ${companyId} not found`);
    }

    const parent: GroupCompany = {
      id: String(selfRows[0]!.id),
      name: String(selfRows[0]!.name),
      relationshipType: 'parent',
      ownershipPercent: 100,
    };

    const childRows = (await sql`
      SELECT cr.child_company_id AS id, c.name,
             cr.relationship_type, cr.ownership_percent
      FROM company_relationships cr
      JOIN companies c ON c.id = cr.child_company_id
      WHERE cr.parent_company_id = ${companyId}::UUID
      ORDER BY c.name
    `) as Row[];

    const children: GroupCompany[] = childRows.map((r) => ({
      id: String(r.id),
      name: String(r.name),
      relationshipType: String(r.relationship_type),
      ownershipPercent: Number(r.ownership_percent),
    }));

    return [parent, ...children];
  } catch (err) {
    log.error('getGroupCompanies failed', { companyId, error: err }, 'consolidation');
    throw err;
  }
}

/**
 * Adds a parent-child company relationship.
 * Validates that child is not the same as parent and that the parent is
 * actually the companyId making the request (IDOR guard).
 */
export async function createCompanyRelationship(
  companyId: string,
  childCompanyId: string,
  ownershipPercent: number,
  _userId: string,
  relationshipType: string = 'subsidiary',
): Promise<void> {
  if (companyId === childCompanyId) {
    throw new Error('A company cannot be its own subsidiary');
  }
  if (ownershipPercent < 0 || ownershipPercent > 100) {
    throw new Error('ownershipPercent must be between 0 and 100');
  }

  try {
    await sql`
      INSERT INTO company_relationships
        (parent_company_id, child_company_id, relationship_type, ownership_percent)
      VALUES
        (${companyId}::UUID, ${childCompanyId}::UUID,
         ${relationshipType}, ${ownershipPercent})
      ON CONFLICT (parent_company_id, child_company_id)
      DO UPDATE SET
        relationship_type = EXCLUDED.relationship_type,
        ownership_percent = EXCLUDED.ownership_percent
    `;
    log.info('Company relationship created', { companyId, childCompanyId, ownershipPercent }, 'consolidation');
  } catch (err) {
    log.error('createCompanyRelationship failed', { companyId, childCompanyId, error: err }, 'consolidation');
    throw err;
  }
}

/**
 * Returns the consolidated trial balance for the parent company and all its
 * direct subsidiaries.  Each GL account is broken down by entity.
 * Accounts that have a matching intercompany elimination entry are flagged.
 */
export async function getConsolidatedTrialBalance(
  companyId: string,
  periodStart: string,
  periodEnd: string,
): Promise<ConsolidatedTrialBalance> {
  try {
    const groupCompanies = await getGroupCompanies(companyId);
    const allIds = groupCompanies.map((g) => g.id);

    // Collect entity metadata for the response
    const entities = groupCompanies.map((g) => ({
      companyId: g.id,
      companyName: g.name,
    }));

    // Fetch eliminations once so we can flag accounts
    const elimRows = (await sql`
      SELECT DISTINCT elimination_type
      FROM intercompany_eliminations
      WHERE group_company_id = ${companyId}::UUID
        AND period_start <= ${periodEnd}
        AND period_end   >= ${periodStart}
    `) as Row[];
    const eliminatedTypes = new Set(elimRows.map((r) => String(r.elimination_type)));

    // Account accumulator keyed by "accountCode|accountType"
    const accountMap = new Map<string, ConsolidatedAccount>();

    for (const entity of groupCompanies) {
      const rows = (await sql`
        SELECT
          ga.account_code,
          ga.account_name,
          ga.account_type,
          COALESCE(SUM(jl.debit),  0) AS total_debit,
          COALESCE(SUM(jl.credit), 0) AS total_credit
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga        ON ga.id = jl.gl_account_id
        WHERE je.status      = 'posted'
          AND je.company_id  = ${entity.id}::UUID
          AND ga.company_id  = ${entity.id}::UUID
          AND je.entry_date >= ${periodStart}
          AND je.entry_date <= ${periodEnd}
        GROUP BY ga.account_code, ga.account_name, ga.account_type
        HAVING
          COALESCE(SUM(jl.debit),  0) != 0
          OR COALESCE(SUM(jl.credit), 0) != 0
        ORDER BY ga.account_code
      `) as Row[];

      for (const r of rows) {
        const key = `${String(r.account_code)}|${String(r.account_type)}`;
        const debit  = Number(r.total_debit);
        const credit = Number(r.total_credit);

        let acc = accountMap.get(key);
        if (!acc) {
          // Determine if this account type is covered by any elimination
          const isEliminated = eliminatedTypes.has('receivable_payable')
            ? ['asset', 'liability'].includes(String(r.account_type).toLowerCase())
            : eliminatedTypes.has('revenue_expense')
              ? ['income', 'expense'].includes(String(r.account_type).toLowerCase())
              : false;

          acc = {
            accountCode: String(r.account_code),
            accountName: String(r.account_name),
            accountType: String(r.account_type),
            byEntity: {},
            totalDebit: 0,
            totalCredit: 0,
            isEliminated,
          };
          accountMap.set(key, acc);
        }

        acc.byEntity[entity.id] = {
          debit:  (acc.byEntity[entity.id]?.debit  ?? 0) + debit,
          credit: (acc.byEntity[entity.id]?.credit ?? 0) + credit,
        };
        acc.totalDebit  += debit;
        acc.totalCredit += credit;
      }
    }

    // Ensure all entities appear in byEntity (even if zero)
    for (const acc of accountMap.values()) {
      for (const id of allIds) {
        if (!acc.byEntity[id]) {
          acc.byEntity[id] = { debit: 0, credit: 0 };
        }
      }
    }

    const accounts = Array.from(accountMap.values()).sort((a, b) =>
      a.accountCode.localeCompare(b.accountCode),
    );

    const totalDebits  = accounts.reduce((s, a) => s + a.totalDebit,  0);
    const totalCredits = accounts.reduce((s, a) => s + a.totalCredit, 0);

    const selfName = groupCompanies[0]?.name ?? companyId;

    return {
      groupName: selfName,
      periodStart,
      periodEnd,
      entities,
      accounts,
      totalDebits,
      totalCredits,
    };
  } catch (err) {
    log.error('getConsolidatedTrialBalance failed', { companyId, periodStart, periodEnd, error: err }, 'consolidation');
    throw err;
  }
}

/**
 * Returns intercompany balances (elimination candidates) between entities in
 * the group for the given period.  Scoped strictly to the parent company.
 */
export async function getIntercompanyBalances(
  companyId: string,
  periodStart: string,
  periodEnd: string,
): Promise<IntercompanyBalance[]> {
  try {
    const childIds = await getChildCompanyIds(companyId);
    if (childIds.length === 0) return [];

    const rows = (await sql`
      SELECT
        ie.from_company_id,
        fc.name AS from_company_name,
        ie.to_company_id,
        tc.name AS to_company_name,
        ie.elimination_type,
        ie.amount,
        ie.description
      FROM intercompany_eliminations ie
      JOIN companies fc ON fc.id = ie.from_company_id
      JOIN companies tc ON tc.id = ie.to_company_id
      WHERE ie.group_company_id = ${companyId}::UUID
        AND ie.period_start <= ${periodEnd}
        AND ie.period_end   >= ${periodStart}
      ORDER BY ie.elimination_type, ie.amount DESC
    `) as Row[];

    return rows.map((r) => ({
      fromCompanyId:   String(r.from_company_id),
      fromCompanyName: String(r.from_company_name),
      toCompanyId:     String(r.to_company_id),
      toCompanyName:   String(r.to_company_name),
      eliminationType: String(r.elimination_type),
      amount:          Number(r.amount),
      description:     r.description != null ? String(r.description) : null,
    }));
  } catch (err) {
    log.error('getIntercompanyBalances failed', { companyId, periodStart, periodEnd, error: err }, 'consolidation');
    throw err;
  }
}

