type SyncStatus = 'running' | 'success' | 'failed';

interface BankFeedConnection {
  id: string;
  companyId: string;
  provider: Provider;
  accountId: string | null;
  accountName: string | null;
  externalAccountId: string | null;
  status: ConnectionStatus;
  lastSyncAt: string | null;
  lastSyncStatus: SyncStatus | null;
  lastSyncError: string | null;
  config: Record<string, unknown>;
  createdAt: string;
  updatedAt: string;
}

interface SyncLog {
  id: string;
  connectionId: string;
  startedAt: string;
  completedAt: string | null;
  status: SyncStatus;
  transactionsFound: number;
  transactionsImported: number;
  transactionsDuplicate: number;
  errorMessage: string | null;
}

interface BankAccount {
  id: string;
  accountName: string;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const PROVIDER_LABELS: Record<Provider, string> = {
  manual_csv: 'Manual CSV Upload',
  basiq: 'Basiq (Open Banking AU/ZA)',
  tink: 'Tink (Open Banking EU)',
  plaid: 'Plaid (Open Banking US)',
};

const PROVIDER_DESCRIPTIONS: Record<Provider, string> = {
  manual_csv: 'Import bank statements manually via CSV file upload.',
  basiq: 'Connect directly to SA/AU banks via the Basiq API (requires Basiq API key).',
  tink: 'Connect to European banks via Tink Open Banking (requires Tink credentials).',
  plaid: 'Connect to US and international banks via Plaid (requires Plaid credentials).',
};

const STATUS_STYLES: Record<ConnectionStatus, { cls: string; label: string }> = {
  active: { cls: 'bg-teal-500/20 text-teal-400', label: 'Active' },
  paused: { cls: 'bg-amber-500/20 text-amber-400', label: 'Paused' },
  error: { cls: 'bg-red-500/20 text-red-400', label: 'Error' },
};

const SYNC_STATUS_STYLES: Record<SyncStatus, { cls: string; label: string }> = {
  success: { cls: 'bg-teal-500/20 text-teal-400', label: 'Success' },
  running: { cls: 'bg-blue-500/20 text-blue-400', label: 'Running' },
  failed: { cls: 'bg-red-500/20 text-red-400', label: 'Failed' },
};

// ── Page component ────────────────────────────────────────────────────────────

export default function BankFeedsPage() {
  const [connections, setConnections] = useState<BankFeedConnection[]>([]);
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState<string | null>(null);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [expandedLogs, setExpandedLogs] = useState<string | null>(null);
  const [syncLogs, setSyncLogs] = useState<Record<string, SyncLog[]>>({});
  const [logsLoading, setLogsLoading] = useState<string | null>(null);

  // Add connection form state
  const [form, setForm] = useState<{
    provider: Provider;
    accountId: string;
    externalAccountId: string;
  }>({ provider: 'manual_csv', accountId: '', externalAccountId: '' });
  const [saving, setSaving] = useState(false);

  const fetchConnections = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/bank-feeds');
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to load');
      setConnections(json.data?.items ?? []);
    } catch {
      notify.error('Failed to load bank feed connections');
    }
  }, []);

  const fetchBankAccounts = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/bank-accounts');
      const json = await res.json();
      if (res.ok) {
        setBankAccounts((json.data?.items ?? []).map((a: Record<string, unknown>) => ({
          id: String(a.id),
          accountName: String(a.accountName ?? a.account_name ?? ''),
        })));
      }
    } catch {
      // bank accounts optional — proceed without them
    }
  }, []);

  useEffect(() => {
    setLoading(true);
    Promise.all([fetchConnections(), fetchBankAccounts()]).finally(() => setLoading(false));
  }, [fetchConnections, fetchBankAccounts]);

  const handleAddConnection = async () => {
    if (!form.provider) {
      notify.error('Please select a provider');
      return;
    }
    setSaving(true);
    try {
      const body: Record<string, unknown> = { provider: form.provider };
      if (form.accountId) body.accountId = form.accountId;
      if (form.externalAccountId) body.externalAccountId = form.externalAccountId;

      const res = await apiFetch('/api/accounting/bank-feeds', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to create connection');
      notify.success('Bank feed connection created');
      setShowAddModal(false);
      setForm({ provider: 'manual_csv', accountId: '', externalAccountId: '' });
      await fetchConnections();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Failed to create connection');
    } finally {
      setSaving(false);
    }
  };

  const handleSync = async (connectionId: string) => {
    setSyncing(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}/sync`, {
        method: 'POST',
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Sync failed');
      const r = json.data as { imported?: number; duplicate?: number; instructions?: string };
      if (r.instructions) {
        notify.info(r.instructions);
      } else {
        notify.success(`Sync complete: ${r.imported ?? 0} imported, ${r.duplicate ?? 0} duplicates skipped`);
      }
      await fetchConnections();
      // Refresh logs if expanded
      if (expandedLogs === connectionId) {
        await loadSyncLogs(connectionId);
      }
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Sync failed');
    } finally {
      setSyncing(null);
    }
  };

  const handleDelete = async (connectionId: string) => {
    if (!confirm('Delete this bank feed connection? This cannot be undone.')) return;
    setDeleting(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Delete failed');
      notify.success('Connection deleted');
      await fetchConnections();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Delete failed');
    } finally {
      setDeleting(null);
    }
  };

  const loadSyncLogs = async (connectionId: string) => {
    setLogsLoading(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}/logs`);
      const json = await res.json();
      if (res.ok) {
        setSyncLogs(prev => ({ ...prev, [connectionId]: json.data?.items ?? [] }));
      }
    } catch {
      // fail silently
    } finally {
      setLogsLoading(null);
    }
  };

  const toggleLogs = async (connectionId: string) => {
    if (expandedLogs === connectionId) {
      setExpandedLogs(null);
    } else {
      setExpandedLogs(connectionId);
      if (!syncLogs[connectionId]) {
        await loadSyncLogs(connectionId);
      }
    }
  };

  const fmtDate = (d: string | null) =>
    d ? new Date(d).toLocaleString('en-ZA', { dateStyle: 'short', timeStyle: 'short' }) : '—';

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6 max-w-5xl mx-auto">

        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-teal-500/10 ring-1 ring-teal-500/20">
              <Wifi className="h-6 w-6 text-teal-400" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Feeds</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Automated open banking transaction imports
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors"
          >
            <Plus className="h-4 w-4" />
            Add Connection
          </button>
        </div>

        {/* Connection List */}
        {loading ? (
          <div className="flex justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : connections.length === 0 ? (
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-10 text-center">
            <WifiOff className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">
              No Bank Feed Connections
            </h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mb-6 max-w-sm mx-auto">
              Connect your bank accounts to automatically import transactions via Basiq, Tink, Plaid, or manual CSV upload.
            </p>
            <button
              onClick={() => setShowAddModal(true)}
              className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors"
            >
              Add Your First Connection
            </button>
          </div>
        ) : (
          <div className="space-y-3">
            {connections.map(conn => {
              const statusStyle = STATUS_STYLES[conn.status] ?? STATUS_STYLES['active']!;
              const syncStyle = conn.lastSyncStatus
                ? (SYNC_STATUS_STYLES[conn.lastSyncStatus] ?? SYNC_STATUS_STYLES['success']!)
                : null;
              const logsOpen = expandedLogs === conn.id;
              const connLogs = syncLogs[conn.id] ?? [];

              return (
                <div
                  key={conn.id}
                  className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden"
                >
                  <div className="p-5">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex items-center gap-4 min-w-0">
                        <div className="w-10 h-10 bg-teal-500/10 rounded-lg flex items-center justify-center flex-shrink-0">
                          <Wifi className="h-5 w-5 text-teal-400" />
                        </div>
                        <div className="min-w-0">
                          <p className="font-semibold text-[var(--ff-text-primary)] truncate">
                            {conn.accountName ?? PROVIDER_LABELS[conn.provider]}
                          </p>
                          <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                            {PROVIDER_LABELS[conn.provider]}
                            {conn.externalAccountId && ` • ${conn.externalAccountId}`}
                          </p>
                          {conn.lastSyncAt && (
                            <p className="text-xs text-[var(--ff-text-tertiary)] mt-1 flex items-center gap-1">
                              <Clock className="h-3 w-3" />
                              Last sync: {fmtDate(conn.lastSyncAt)}
                            </p>
                          )}
                          {conn.lastSyncError && (
                            <p className="text-xs text-red-400 mt-1 flex items-center gap-1">
                              <AlertCircle className="h-3 w-3 flex-shrink-0" />
                              {conn.lastSyncError}
                            </p>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 flex-shrink-0">
                        <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${statusStyle.cls}`}>
                          {statusStyle.label}
                        </span>
                        {syncStyle && (
                          <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${syncStyle.cls}`}>
                            {syncStyle.label}
                          </span>
                        )}
                        <button
                          onClick={() => void handleSync(conn.id)}
                          disabled={syncing === conn.id}
                          title="Sync Now"
                          className="flex items-center gap-1.5 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                        >
                          {syncing === conn.id
                            ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                            : <RefreshCw className="h-3.5 w-3.5" />}
                          Sync
                        </button>
                        <button
                          onClick={() => void toggleLogs(conn.id)}
                          title="View sync history"
                          className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                        >
                          {logsOpen
                            ? <ChevronDown className="h-4 w-4" />
                            : <ChevronRight className="h-4 w-4" />}
                        </button>
                        <button
                          onClick={() => void handleDelete(conn.id)}
                          disabled={deleting === conn.id}
                          title="Delete connection"
                          className="p-1.5 text-red-400 hover:text-red-300 transition-colors disabled:opacity-50"
                        >
                          {deleting === conn.id
                            ? <Loader2 className="h-4 w-4 animate-spin" />
                            : <Trash2 className="h-4 w-4" />}
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Sync Logs Panel */}
                  {logsOpen && (
                    <div className="border-t border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                      <div className="px-5 py-3 flex items-center justify-between">
                        <p className="text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wide">
                          Sync History
                        </p>
                        {logsLoading === conn.id && (
                          <Loader2 className="h-3.5 w-3.5 animate-spin text-[var(--ff-text-tertiary)]" />
                        )}
                      </div>
                      {connLogs.length === 0 ? (
                        <p className="px-5 pb-4 text-sm text-[var(--ff-text-tertiary)]">
                          No sync history yet — click Sync to run the first sync.
                        </p>
                      ) : (
                        <div className="overflow-x-auto">
                          <table className="w-full text-xs">
                            <thead>
                              <tr className="border-b border-[var(--ff-border-primary)]">
                                {['Started', 'Status', 'Found', 'Imported', 'Duplicates', 'Duration'].map(h => (
                                  <th
                                    key={h}
                                    className="px-4 py-2 text-left font-medium text-[var(--ff-text-secondary)]"
                                  >
                                    {h}
                                  </th>
                                ))}
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-[var(--ff-border-primary)]">
                              {connLogs.map(entry => {
                                const logStyle = SYNC_STATUS_STYLES[entry.status] ?? SYNC_STATUS_STYLES['success']!;
                                const durationMs = entry.completedAt
                                  ? new Date(entry.completedAt).getTime() - new Date(entry.startedAt).getTime()
                                  : null;
                                const duration = durationMs != null
                                  ? durationMs < 1000 ? `${durationMs}ms` : `${(durationMs / 1000).toFixed(1)}s`
                                  : '—';
                                return (
                                  <tr key={entry.id} className="hover:bg-[var(--ff-bg-hover)]">
                                    <td className="px-4 py-2.5 text-[var(--ff-text-primary)]">
                                      {fmtDate(entry.startedAt)}
                                    </td>
                                    <td className="px-4 py-2.5">
                                      <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${logStyle.cls}`}>
                                        {entry.status === 'success' && <CheckCircle2 className="h-3 w-3" />}
                                        {entry.status === 'failed' && <XCircle className="h-3 w-3" />}
                                        {logStyle.label}
                                      </span>
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-secondary)]">
                                      {entry.transactionsFound}
                                    </td>
                                    <td className="px-4 py-2.5 text-teal-400 font-medium">
                                      {entry.transactionsImported}
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-tertiary)]">
                                      {entry.transactionsDuplicate}
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-tertiary)]">
                                      {duration}
                                    </td>
                                  </tr>
                                );
                              })}
                            </tbody>
                          </table>
                          {connLogs.length > 0 && connLogs[0]?.errorMessage && (
                            <p className="px-5 py-3 text-xs text-red-400 border-t border-[var(--ff-border-primary)]">
                              Last error: {connLogs[0].errorMessage}
                            </p>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Add Connection Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-2xl w-full max-w-lg shadow-2xl">
            <div className="flex items-center justify-between px-6 py-5 border-b border-[var(--ff-border-primary)]">
              <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">Add Bank Feed Connection</h2>
              <button
                onClick={() => setShowAddModal(false)}
                className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <XCircle className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-5">
              {/* Provider selection */}
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
                  Provider <span className="text-red-400">*</span>
                </label>
                <div className="space-y-2">
                  {(['manual_csv', 'basiq', 'tink', 'plaid'] as Provider[]).map(p => (
                    <label
                      key={p}
                      className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                        form.provider === p
                          ? 'border-teal-500 bg-teal-500/10'
                          : 'border-[var(--ff-border-primary)] hover:border-[var(--ff-border-hover)]'
                      }`}
                    >
                      <input
                        type="radio"
                        name="provider"
                        value={p}
                        checked={form.provider === p}
                        onChange={() => setForm(f => ({ ...f, provider: p }))}
                        className="mt-0.5 accent-teal-500"
                      />
                      <div>
                        <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                          {PROVIDER_LABELS[p]}
                        </p>
                        <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                          {PROVIDER_DESCRIPTIONS[p]}
                        </p>
                      </div>
                    </label>
                  ))}
                </div>
              </div>

              {/* Bank account selector */}
              {bankAccounts.length > 0 && (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                    Linked Bank Account
                  </label>
                  <select
                    value={form.accountId}
                    onChange={e => setForm(f => ({ ...f, accountId: e.target.value }))}
                    className="ff-input w-full"
                  >
                    <option value="">— Select a bank account —</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>{a.accountName}</option>
                    ))}
                  </select>
                </div>
              )}

              {/* External account ID (optional for OAuth-based providers) */}
              {form.provider !== 'manual_csv' && (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                    External Account ID
                    <span className="ml-1 text-xs text-[var(--ff-text-tertiary)]">(optional)</span>
                  </label>
                  <input
                    type="text"
                    value={form.externalAccountId}
                    onChange={e => setForm(f => ({ ...f, externalAccountId: e.target.value }))}
                    placeholder={`Your ${PROVIDER_LABELS[form.provider]} account ID`}
                    className="ff-input w-full"
                  />
                </div>
              )}

              {form.provider === 'manual_csv' && (
                <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3">
                  <p className="text-sm text-amber-400">
                    Manual CSV connections do not auto-sync. Use the
                    {' '}<strong>Import Statement</strong>{' '}
                    page to upload your bank statement files.
                  </p>
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-3 px-6 py-5 border-t border-[var(--ff-border-primary)]">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => void handleAddConnection()}
                disabled={saving}
                className="flex items-center gap-2 px-5 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors disabled:opacity-50"
              >
                {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                Add Connection
              </button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

/**
 * Open Banking — Bank Feeds Management
 * List connections, add new connections (manual_csv | basiq | tink | plaid),
 * trigger manual syncs, view per-connection sync log history.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Wifi, WifiOff, RefreshCw, Loader2, AlertCircle,
  Plus, Trash2, ChevronDown, ChevronRight, CheckCircle2,
  Clock, XCircle,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { notify } from '@/utils/toast';

// ── Types ─────────────────────────────────────────────────────────────────────

type Provider = 'manual_csv' | 'basiq' | 'tink' | 'plaid';
type ConnectionStatus = 'active' | 'paused' | 'error';
type SyncStatus = 'running' | 'success' | 'failed';

interface BankFeedConnection {
  id: string;
  companyId: string;
  provider: Provider;
  accountId: string | null;
  accountName: string | null;
  externalAccountId: string | null;
  status: ConnectionStatus;
  lastSyncAt: string | null;
  lastSyncStatus: SyncStatus | null;
  lastSyncError: string | null;
  config: Record<string, unknown>;
  createdAt: string;
  updatedAt: string;
}

interface SyncLog {
  id: string;
  connectionId: string;
  startedAt: string;
  completedAt: string | null;
  status: SyncStatus;
  transactionsFound: number;
  transactionsImported: number;
  transactionsDuplicate: number;
  errorMessage: string | null;
}

interface BankAccount {
  id: string;
  accountName: string;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const PROVIDER_LABELS: Record<Provider, string> = {
  manual_csv: 'Manual CSV Upload',
  basiq: 'Basiq (Open Banking AU/ZA)',
  tink: 'Tink (Open Banking EU)',
  plaid: 'Plaid (Open Banking US)',
};

const PROVIDER_DESCRIPTIONS: Record<Provider, string> = {
  manual_csv: 'Import bank statements manually via CSV file upload.',
  basiq: 'Connect directly to SA/AU banks via the Basiq API (requires Basiq API key).',
  tink: 'Connect to European banks via Tink Open Banking (requires Tink credentials).',
  plaid: 'Connect to US and international banks via Plaid (requires Plaid credentials).',
};

const STATUS_STYLES: Record<ConnectionStatus, { cls: string; label: string }> = {
  active: { cls: 'bg-teal-500/20 text-teal-400', label: 'Active' },
  paused: { cls: 'bg-amber-500/20 text-amber-400', label: 'Paused' },
  error: { cls: 'bg-red-500/20 text-red-400', label: 'Error' },
};

const SYNC_STATUS_STYLES: Record<SyncStatus, { cls: string; label: string }> = {
  success: { cls: 'bg-teal-500/20 text-teal-400', label: 'Success' },
  running: { cls: 'bg-blue-500/20 text-blue-400', label: 'Running' },
  failed: { cls: 'bg-red-500/20 text-red-400', label: 'Failed' },
};

// ── Page component ────────────────────────────────────────────────────────────

export default function BankFeedsPage() {
  const [connections, setConnections] = useState<BankFeedConnection[]>([]);
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState<string | null>(null);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [expandedLogs, setExpandedLogs] = useState<string | null>(null);
  const [syncLogs, setSyncLogs] = useState<Record<string, SyncLog[]>>({});
  const [logsLoading, setLogsLoading] = useState<string | null>(null);

  // Add connection form state
  const [form, setForm] = useState<{
    provider: Provider;
    accountId: string;
    externalAccountId: string;
  }>({ provider: 'manual_csv', accountId: '', externalAccountId: '' });
  const [saving, setSaving] = useState(false);

  const fetchConnections = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/bank-feeds');
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to load');
      setConnections(json.data?.items ?? []);
    } catch {
      notify.error('Failed to load bank feed connections');
    }
  }, []);

  const fetchBankAccounts = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/bank-accounts');
      const json = await res.json();
      if (res.ok) {
        setBankAccounts((json.data?.items ?? []).map((a: Record<string, unknown>) => ({
          id: String(a.id),
          accountName: String(a.accountName ?? a.account_name ?? ''),
        })));
      }
    } catch {
      // bank accounts optional — proceed without them
    }
  }, []);

  useEffect(() => {
    setLoading(true);
    Promise.all([fetchConnections(), fetchBankAccounts()]).finally(() => setLoading(false));
  }, [fetchConnections, fetchBankAccounts]);

  const handleAddConnection = async () => {
    if (!form.provider) {
      notify.error('Please select a provider');
      return;
    }
    setSaving(true);
    try {
      const body: Record<string, unknown> = { provider: form.provider };
      if (form.accountId) body.accountId = form.accountId;
      if (form.externalAccountId) body.externalAccountId = form.externalAccountId;

      const res = await apiFetch('/api/accounting/bank-feeds', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to create connection');
      notify.success('Bank feed connection created');
      setShowAddModal(false);
      setForm({ provider: 'manual_csv', accountId: '', externalAccountId: '' });
      await fetchConnections();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Failed to create connection');
    } finally {
      setSaving(false);
    }
  };

  const handleSync = async (connectionId: string) => {
    setSyncing(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}/sync`, {
        method: 'POST',
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Sync failed');
      const r = json.data as { imported?: number; duplicate?: number; instructions?: string };
      if (r.instructions) {
        notify.info(r.instructions);
      } else {
        notify.success(`Sync complete: ${r.imported ?? 0} imported, ${r.duplicate ?? 0} duplicates skipped`);
      }
      await fetchConnections();
      // Refresh logs if expanded
      if (expandedLogs === connectionId) {
        await loadSyncLogs(connectionId);
      }
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Sync failed');
    } finally {
      setSyncing(null);
    }
  };

  const handleDelete = async (connectionId: string) => {
    if (!confirm('Delete this bank feed connection? This cannot be undone.')) return;
    setDeleting(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Delete failed');
      notify.success('Connection deleted');
      await fetchConnections();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Delete failed');
    } finally {
      setDeleting(null);
    }
  };

  const loadSyncLogs = async (connectionId: string) => {
    setLogsLoading(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}/logs`);
      const json = await res.json();
      if (res.ok) {
        setSyncLogs(prev => ({ ...prev, [connectionId]: json.data?.items ?? [] }));
      }
    } catch {
      // fail silently
    } finally {
      setLogsLoading(null);
    }
  };

  const toggleLogs = async (connectionId: string) => {
    if (expandedLogs === connectionId) {
      setExpandedLogs(null);
    } else {
      setExpandedLogs(connectionId);
      if (!syncLogs[connectionId]) {
        await loadSyncLogs(connectionId);
      }
    }
  };

  const fmtDate = (d: string | null) =>
    d ? new Date(d).toLocaleString('en-ZA', { dateStyle: 'short', timeStyle: 'short' }) : '—';

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6 max-w-5xl mx-auto">

        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-teal-500/10 ring-1 ring-teal-500/20">
              <Wifi className="h-6 w-6 text-teal-400" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Feeds</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Automated open banking transaction imports
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors"
          >
            <Plus className="h-4 w-4" />
            Add Connection
          </button>
        </div>

        {/* Connection List */}
        {loading ? (
          <div className="flex justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : connections.length === 0 ? (
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-10 text-center">
            <WifiOff className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">
              No Bank Feed Connections
            </h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mb-6 max-w-sm mx-auto">
              Connect your bank accounts to automatically import transactions via Basiq, Tink, Plaid, or manual CSV upload.
            </p>
            <button
              onClick={() => setShowAddModal(true)}
              className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors"
            >
              Add Your First Connection
            </button>
          </div>
        ) : (
          <div className="space-y-3">
            {connections.map(conn => {
              const statusStyle = STATUS_STYLES[conn.status] ?? STATUS_STYLES['active']!;
              const syncStyle = conn.lastSyncStatus
                ? (SYNC_STATUS_STYLES[conn.lastSyncStatus] ?? SYNC_STATUS_STYLES['success']!)
                : null;
              const logsOpen = expandedLogs === conn.id;
              const connLogs = syncLogs[conn.id] ?? [];

              return (
                <div
                  key={conn.id}
                  className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden"
                >
                  <div className="p-5">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex items-center gap-4 min-w-0">
                        <div className="w-10 h-10 bg-teal-500/10 rounded-lg flex items-center justify-center flex-shrink-0">
                          <Wifi className="h-5 w-5 text-teal-400" />
                        </div>
                        <div className="min-w-0">
                          <p className="font-semibold text-[var(--ff-text-primary)] truncate">
                            {conn.accountName ?? PROVIDER_LABELS[conn.provider]}
                          </p>
                          <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                            {PROVIDER_LABELS[conn.provider]}
                            {conn.externalAccountId && ` • ${conn.externalAccountId}`}
                          </p>
                          {conn.lastSyncAt && (
                            <p className="text-xs text-[var(--ff-text-tertiary)] mt-1 flex items-center gap-1">
                              <Clock className="h-3 w-3" />
                              Last sync: {fmtDate(conn.lastSyncAt)}
                            </p>
                          )}
                          {conn.lastSyncError && (
                            <p className="text-xs text-red-400 mt-1 flex items-center gap-1">
                              <AlertCircle className="h-3 w-3 flex-shrink-0" />
                              {conn.lastSyncError}
                            </p>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 flex-shrink-0">
                        <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${statusStyle.cls}`}>
                          {statusStyle.label}
                        </span>
                        {syncStyle && (
                          <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${syncStyle.cls}`}>
                            {syncStyle.label}
                          </span>
                        )}
                        <button
                          onClick={() => void handleSync(conn.id)}
                          disabled={syncing === conn.id}
                          title="Sync Now"
                          className="flex items-center gap-1.5 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                        >
                          {syncing === conn.id
                            ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                            : <RefreshCw className="h-3.5 w-3.5" />}
                          Sync
                        </button>
                        <button
                          onClick={() => void toggleLogs(conn.id)}
                          title="View sync history"
                          className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                        >
                          {logsOpen
                            ? <ChevronDown className="h-4 w-4" />
                            : <ChevronRight className="h-4 w-4" />}
                        </button>
                        <button
                          onClick={() => void handleDelete(conn.id)}
                          disabled={deleting === conn.id}
                          title="Delete connection"
                          className="p-1.5 text-red-400 hover:text-red-300 transition-colors disabled:opacity-50"
                        >
                          {deleting === conn.id
                            ? <Loader2 className="h-4 w-4 animate-spin" />
                            : <Trash2 className="h-4 w-4" />}
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Sync Logs Panel */}
                  {logsOpen && (
                    <div className="border-t border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                      <div className="px-5 py-3 flex items-center justify-between">
                        <p className="text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wide">
                          Sync History
                        </p>
                        {logsLoading === conn.id && (
                          <Loader2 className="h-3.5 w-3.5 animate-spin text-[var(--ff-text-tertiary)]" />
                        )}
                      </div>
                      {connLogs.length === 0 ? (
                        <p className="px-5 pb-4 text-sm text-[var(--ff-text-tertiary)]">
                          No sync history yet — click Sync to run the first sync.
                        </p>
                      ) : (
                        <div className="overflow-x-auto">
                          <table className="w-full text-xs">
                            <thead>
                              <tr className="border-b border-[var(--ff-border-primary)]">
                                {['Started', 'Status', 'Found', 'Imported', 'Duplicates', 'Duration'].map(h => (
                                  <th
                                    key={h}
                                    className="px-4 py-2 text-left font-medium text-[var(--ff-text-secondary)]"
                                  >
                                    {h}
                                  </th>
                                ))}
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-[var(--ff-border-primary)]">
                              {connLogs.map(entry => {
                                const logStyle = SYNC_STATUS_STYLES[entry.status] ?? SYNC_STATUS_STYLES['success']!;
                                const durationMs = entry.completedAt
                                  ? new Date(entry.completedAt).getTime() - new Date(entry.startedAt).getTime()
                                  : null;
                                const duration = durationMs != null
                                  ? durationMs < 1000 ? `${durationMs}ms` : `${(durationMs / 1000).toFixed(1)}s`
                                  : '—';
                                return (
                                  <tr key={entry.id} className="hover:bg-[var(--ff-bg-hover)]">
                                    <td className="px-4 py-2.5 text-[var(--ff-text-primary)]">
                                      {fmtDate(entry.startedAt)}
                                    </td>
                                    <td className="px-4 py-2.5">
                                      <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${logStyle.cls}`}>
                                        {entry.status === 'success' && <CheckCircle2 className="h-3 w-3" />}
                                        {entry.status === 'failed' && <XCircle className="h-3 w-3" />}
                                        {logStyle.label}
                                      </span>
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-secondary)]">
                                      {entry.transactionsFound}
                                    </td>
                                    <td className="px-4 py-2.5 text-teal-400 font-medium">
                                      {entry.transactionsImported}
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-tertiary)]">
                                      {entry.transactionsDuplicate}
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-tertiary)]">
                                      {duration}
                                    </td>
                                  </tr>
                                );
                              })}
                            </tbody>
                          </table>
                          {connLogs.length > 0 && connLogs[0]?.errorMessage && (
                            <p className="px-5 py-3 text-xs text-red-400 border-t border-[var(--ff-border-primary)]">
                              Last error: {connLogs[0].errorMessage}
                            </p>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Add Connection Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-2xl w-full max-w-lg shadow-2xl">
            <div className="flex items-center justify-between px-6 py-5 border-b border-[var(--ff-border-primary)]">
              <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">Add Bank Feed Connection</h2>
              <button
                onClick={() => setShowAddModal(false)}
                className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <XCircle className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-5">
              {/* Provider selection */}
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
                  Provider <span className="text-red-400">*</span>
                </label>
                <div className="space-y-2">
                  {(['manual_csv', 'basiq', 'tink', 'plaid'] as Provider[]).map(p => (
                    <label
                      key={p}
                      className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                        form.provider === p
                          ? 'border-teal-500 bg-teal-500/10'
                          : 'border-[var(--ff-border-primary)] hover:border-[var(--ff-border-hover)]'
                      }`}
                    >
                      <input
                        type="radio"
                        name="provider"
                        value={p}
                        checked={form.provider === p}
                        onChange={() => setForm(f => ({ ...f, provider: p }))}
                        className="mt-0.5 accent-teal-500"
                      />
                      <div>
                        <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                          {PROVIDER_LABELS[p]}
                        </p>
                        <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                          {PROVIDER_DESCRIPTIONS[p]}
                        </p>
                      </div>
                    </label>
                  ))}
                </div>
              </div>

              {/* Bank account selector */}
              {bankAccounts.length > 0 && (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                    Linked Bank Account
                  </label>
                  <select
                    value={form.accountId}
                    onChange={e => setForm(f => ({ ...f, accountId: e.target.value }))}
                    className="ff-input w-full"
                  >
                    <option value="">— Select a bank account —</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>{a.accountName}</option>
                    ))}
                  </select>
                </div>
              )}

              {/* External account ID (optional for OAuth-based providers) */}
              {form.provider !== 'manual_csv' && (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                    External Account ID
                    <span className="ml-1 text-xs text-[var(--ff-text-tertiary)]">(optional)</span>
                  </label>
                  <input
                    type="text"
                    value={form.externalAccountId}
                    onChange={e => setForm(f => ({ ...f, externalAccountId: e.target.value }))}
                    placeholder={`Your ${PROVIDER_LABELS[form.provider]} account ID`}
                    className="ff-input w-full"
                  />
                </div>
              )}

              {form.provider === 'manual_csv' && (
                <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3">
                  <p className="text-sm text-amber-400">
                    Manual CSV connections do not auto-sync. Use the
                    {' '}<strong>Import Statement</strong>{' '}
                    page to upload your bank statement files.
                  </p>
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-3 px-6 py-5 border-t border-[var(--ff-border-primary)]">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => void handleAddConnection()}
                disabled={saving}
                className="flex items-center gap-2 px-5 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors disabled:opacity-50"
              >
                {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                Add Connection
              </button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

tool_response.content:
/**
 * Open Banking — Bank Feeds Management
 * List connections, add new connections (manual_csv | basiq | tink | plaid),
 * trigger manual syncs, view per-connection sync log history.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Wifi, WifiOff, RefreshCw, Loader2, AlertCircle,
  Plus, Trash2, ChevronDown, ChevronRight, CheckCircle2,
  Clock, XCircle,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { notify } from '@/utils/toast';

// ── Types ─────────────────────────────────────────────────────────────────────

type Provider = 'manual_csv' | 'basiq' | 'tink' | 'plaid';
type ConnectionStatus = 'active' | 'paused' | 'error';
type SyncStatus = 'running' | 'success' | 'failed';

interface BankFeedConnection {
  id: string;
  companyId: string;
  provider: Provider;
  accountId: string | null;
  accountName: string | null;
  externalAccountId: string | null;
  status: ConnectionStatus;
  lastSyncAt: string | null;
  lastSyncStatus: SyncStatus | null;
  lastSyncError: string | null;
  config: Record<string, unknown>;
  createdAt: string;
  updatedAt: string;
}

interface SyncLog {
  id: string;
  connectionId: string;
  startedAt: string;
  completedAt: string | null;
  status: SyncStatus;
  transactionsFound: number;
  transactionsImported: number;
  transactionsDuplicate: number;
  errorMessage: string | null;
}

interface BankAccount {
  id: string;
  accountName: string;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const PROVIDER_LABELS: Record<Provider, string> = {
  manual_csv: 'Manual CSV Upload',
  basiq: 'Basiq (Open Banking AU/ZA)',
  tink: 'Tink (Open Banking EU)',
  plaid: 'Plaid (Open Banking US)',
};

const PROVIDER_DESCRIPTIONS: Record<Provider, string> = {
  manual_csv: 'Import bank statements manually via CSV file upload.',
  basiq: 'Connect directly to SA/AU banks via the Basiq API (requires Basiq API key).',
  tink: 'Connect to European banks via Tink Open Banking (requires Tink credentials).',
  plaid: 'Connect to US and international banks via Plaid (requires Plaid credentials).',
};

const STATUS_STYLES: Record<ConnectionStatus, { cls: string; label: string }> = {
  active: { cls: 'bg-teal-500/20 text-teal-400', label: 'Active' },
  paused: { cls: 'bg-amber-500/20 text-amber-400', label: 'Paused' },
  error: { cls: 'bg-red-500/20 text-red-400', label: 'Error' },
};

const SYNC_STATUS_STYLES: Record<SyncStatus, { cls: string; label: string }> = {
  success: { cls: 'bg-teal-500/20 text-teal-400', label: 'Success' },
  running: { cls: 'bg-blue-500/20 text-blue-400', label: 'Running' },
  failed: { cls: 'bg-red-500/20 text-red-400', label: 'Failed' },
};

// ── Page component ────────────────────────────────────────────────────────────

export default function BankFeedsPage() {
  const [connections, setConnections] = useState<BankFeedConnection[]>([]);
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState<string | null>(null);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [expandedLogs, setExpandedLogs] = useState<string | null>(null);
  const [syncLogs, setSyncLogs] = useState<Record<string, SyncLog[]>>({});
  const [logsLoading, setLogsLoading] = useState<string | null>(null);

  // Add connection form state
  const [form, setForm] = useState<{
    provider: Provider;
    accountId: string;
    externalAccountId: string;
  }>({ provider: 'manual_csv', accountId: '', externalAccountId: '' });
  const [saving, setSaving] = useState(false);

  const fetchConnections = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/bank-feeds');
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to load');
      setConnections(json.data?.items ?? []);
    } catch {
      notify.error('Failed to load bank feed connections');
    }
  }, []);

  const fetchBankAccounts = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/bank-accounts');
      const json = await res.json();
      if (res.ok) {
        setBankAccounts((json.data?.items ?? []).map((a: Record<string, unknown>) => ({
          id: String(a.id),
          accountName: String(a.accountName ?? a.account_name ?? ''),
        })));
      }
    } catch {
      // bank accounts optional — proceed without them
    }
  }, []);

  useEffect(() => {
    setLoading(true);
    Promise.all([fetchConnections(), fetchBankAccounts()]).finally(() => setLoading(false));
  }, [fetchConnections, fetchBankAccounts]);

  const handleAddConnection = async () => {
    if (!form.provider) {
      notify.error('Please select a provider');
      return;
    }
    setSaving(true);
    try {
      const body: Record<string, unknown> = { provider: form.provider };
      if (form.accountId) body.accountId = form.accountId;
      if (form.externalAccountId) body.externalAccountId = form.externalAccountId;

      const res = await apiFetch('/api/accounting/bank-feeds', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to create connection');
      notify.success('Bank feed connection created');
      setShowAddModal(false);
      setForm({ provider: 'manual_csv', accountId: '', externalAccountId: '' });
      await fetchConnections();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Failed to create connection');
    } finally {
      setSaving(false);
    }
  };

  const handleSync = async (connectionId: string) => {
    setSyncing(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}/sync`, {
        method: 'POST',
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Sync failed');
      const r = json.data as { imported?: number; duplicate?: number; instructions?: string };
      if (r.instructions) {
        notify.info(r.instructions);
      } else {
        notify.success(`Sync complete: ${r.imported ?? 0} imported, ${r.duplicate ?? 0} duplicates skipped`);
      }
      await fetchConnections();
      // Refresh logs if expanded
      if (expandedLogs === connectionId) {
        await loadSyncLogs(connectionId);
      }
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Sync failed');
    } finally {
      setSyncing(null);
    }
  };

  const handleDelete = async (connectionId: string) => {
    if (!confirm('Delete this bank feed connection? This cannot be undone.')) return;
    setDeleting(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Delete failed');
      notify.success('Connection deleted');
      await fetchConnections();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Delete failed');
    } finally {
      setDeleting(null);
    }
  };

  const loadSyncLogs = async (connectionId: string) => {
    setLogsLoading(connectionId);
    try {
      const res = await apiFetch(`/api/accounting/bank-feeds/${connectionId}/logs`);
      const json = await res.json();
      if (res.ok) {
        setSyncLogs(prev => ({ ...prev, [connectionId]: json.data?.items ?? [] }));
      }
    } catch {
      // fail silently
    } finally {
      setLogsLoading(null);
    }
  };

  const toggleLogs = async (connectionId: string) => {
    if (expandedLogs === connectionId) {
      setExpandedLogs(null);
    } else {
      setExpandedLogs(connectionId);
      if (!syncLogs[connectionId]) {
        await loadSyncLogs(connectionId);
      }
    }
  };

  const fmtDate = (d: string | null) =>
    d ? new Date(d).toLocaleString('en-ZA', { dateStyle: 'short', timeStyle: 'short' }) : '—';

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6 max-w-5xl mx-auto">

        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-teal-500/10 ring-1 ring-teal-500/20">
              <Wifi className="h-6 w-6 text-teal-400" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Feeds</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Automated open banking transaction imports
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors"
          >
            <Plus className="h-4 w-4" />
            Add Connection
          </button>
        </div>

        {/* Connection List */}
        {loading ? (
          <div className="flex justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : connections.length === 0 ? (
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-10 text-center">
            <WifiOff className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">
              No Bank Feed Connections
            </h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mb-6 max-w-sm mx-auto">
              Connect your bank accounts to automatically import transactions via Basiq, Tink, Plaid, or manual CSV upload.
            </p>
            <button
              onClick={() => setShowAddModal(true)}
              className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors"
            >
              Add Your First Connection
            </button>
          </div>
        ) : (
          <div className="space-y-3">
            {connections.map(conn => {
              const statusStyle = STATUS_STYLES[conn.status] ?? STATUS_STYLES['active']!;
              const syncStyle = conn.lastSyncStatus
                ? (SYNC_STATUS_STYLES[conn.lastSyncStatus] ?? SYNC_STATUS_STYLES['success']!)
                : null;
              const logsOpen = expandedLogs === conn.id;
              const connLogs = syncLogs[conn.id] ?? [];

              return (
                <div
                  key={conn.id}
                  className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden"
                >
                  <div className="p-5">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex items-center gap-4 min-w-0">
                        <div className="w-10 h-10 bg-teal-500/10 rounded-lg flex items-center justify-center flex-shrink-0">
                          <Wifi className="h-5 w-5 text-teal-400" />
                        </div>
                        <div className="min-w-0">
                          <p className="font-semibold text-[var(--ff-text-primary)] truncate">
                            {conn.accountName ?? PROVIDER_LABELS[conn.provider]}
                          </p>
                          <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                            {PROVIDER_LABELS[conn.provider]}
                            {conn.externalAccountId && ` • ${conn.externalAccountId}`}
                          </p>
                          {conn.lastSyncAt && (
                            <p className="text-xs text-[var(--ff-text-tertiary)] mt-1 flex items-center gap-1">
                              <Clock className="h-3 w-3" />
                              Last sync: {fmtDate(conn.lastSyncAt)}
                            </p>
                          )}
                          {conn.lastSyncError && (
                            <p className="text-xs text-red-400 mt-1 flex items-center gap-1">
                              <AlertCircle className="h-3 w-3 flex-shrink-0" />
                              {conn.lastSyncError}
                            </p>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 flex-shrink-0">
                        <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${statusStyle.cls}`}>
                          {statusStyle.label}
                        </span>
                        {syncStyle && (
                          <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${syncStyle.cls}`}>
                            {syncStyle.label}
                          </span>
                        )}
                        <button
                          onClick={() => void handleSync(conn.id)}
                          disabled={syncing === conn.id}
                          title="Sync Now"
                          className="flex items-center gap-1.5 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                        >
                          {syncing === conn.id
                            ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                            : <RefreshCw className="h-3.5 w-3.5" />}
                          Sync
                        </button>
                        <button
                          onClick={() => void toggleLogs(conn.id)}
                          title="View sync history"
                          className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                        >
                          {logsOpen
                            ? <ChevronDown className="h-4 w-4" />
                            : <ChevronRight className="h-4 w-4" />}
                        </button>
                        <button
                          onClick={() => void handleDelete(conn.id)}
                          disabled={deleting === conn.id}
                          title="Delete connection"
                          className="p-1.5 text-red-400 hover:text-red-300 transition-colors disabled:opacity-50"
                        >
                          {deleting === conn.id
                            ? <Loader2 className="h-4 w-4 animate-spin" />
                            : <Trash2 className="h-4 w-4" />}
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Sync Logs Panel */}
                  {logsOpen && (
                    <div className="border-t border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                      <div className="px-5 py-3 flex items-center justify-between">
                        <p className="text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wide">
                          Sync History
                        </p>
                        {logsLoading === conn.id && (
                          <Loader2 className="h-3.5 w-3.5 animate-spin text-[var(--ff-text-tertiary)]" />
                        )}
                      </div>
                      {connLogs.length === 0 ? (
                        <p className="px-5 pb-4 text-sm text-[var(--ff-text-tertiary)]">
                          No sync history yet — click Sync to run the first sync.
                        </p>
                      ) : (
                        <div className="overflow-x-auto">
                          <table className="w-full text-xs">
                            <thead>
                              <tr className="border-b border-[var(--ff-border-primary)]">
                                {['Started', 'Status', 'Found', 'Imported', 'Duplicates', 'Duration'].map(h => (
                                  <th
                                    key={h}
                                    className="px-4 py-2 text-left font-medium text-[var(--ff-text-secondary)]"
                                  >
                                    {h}
                                  </th>
                                ))}
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-[var(--ff-border-primary)]">
                              {connLogs.map(entry => {
                                const logStyle = SYNC_STATUS_STYLES[entry.status] ?? SYNC_STATUS_STYLES['success']!;
                                const durationMs = entry.completedAt
                                  ? new Date(entry.completedAt).getTime() - new Date(entry.startedAt).getTime()
                                  : null;
                                const duration = durationMs != null
                                  ? durationMs < 1000 ? `${durationMs}ms` : `${(durationMs / 1000).toFixed(1)}s`
                                  : '—';
                                return (
                                  <tr key={entry.id} className="hover:bg-[var(--ff-bg-hover)]">
                                    <td className="px-4 py-2.5 text-[var(--ff-text-primary)]">
                                      {fmtDate(entry.startedAt)}
                                    </td>
                                    <td className="px-4 py-2.5">
                                      <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${logStyle.cls}`}>
                                        {entry.status === 'success' && <CheckCircle2 className="h-3 w-3" />}
                                        {entry.status === 'failed' && <XCircle className="h-3 w-3" />}
                                        {logStyle.label}
                                      </span>
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-secondary)]">
                                      {entry.transactionsFound}
                                    </td>
                                    <td className="px-4 py-2.5 text-teal-400 font-medium">
                                      {entry.transactionsImported}
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-tertiary)]">
                                      {entry.transactionsDuplicate}
                                    </td>
                                    <td className="px-4 py-2.5 text-[var(--ff-text-tertiary)]">
                                      {duration}
                                    </td>
                                  </tr>
                                );
                              })}
                            </tbody>
                          </table>
                          {connLogs.length > 0 && connLogs[0]?.errorMessage && (
                            <p className="px-5 py-3 text-xs text-red-400 border-t border-[var(--ff-border-primary)]">
                              Last error: {connLogs[0].errorMessage}
                            </p>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Add Connection Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-2xl w-full max-w-lg shadow-2xl">
            <div className="flex items-center justify-between px-6 py-5 border-b border-[var(--ff-border-primary)]">
              <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">Add Bank Feed Connection</h2>
              <button
                onClick={() => setShowAddModal(false)}
                className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                <XCircle className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-5">
              {/* Provider selection */}
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
                  Provider <span className="text-red-400">*</span>
                </label>
                <div className="space-y-2">
                  {(['manual_csv', 'basiq', 'tink', 'plaid'] as Provider[]).map(p => (
                    <label
                      key={p}
                      className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                        form.provider === p
                          ? 'border-teal-500 bg-teal-500/10'
                          : 'border-[var(--ff-border-primary)] hover:border-[var(--ff-border-hover)]'
                      }`}
                    >
                      <input
                        type="radio"
                        name="provider"
                        value={p}
                        checked={form.provider === p}
                        onChange={() => setForm(f => ({ ...f, provider: p }))}
                        className="mt-0.5 accent-teal-500"
                      />
                      <div>
                        <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                          {PROVIDER_LABELS[p]}
                        </p>
                        <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">
                          {PROVIDER_DESCRIPTIONS[p]}
                        </p>
                      </div>
                    </label>
                  ))}
                </div>
              </div>

              {/* Bank account selector */}
              {bankAccounts.length > 0 && (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                    Linked Bank Account
                  </label>
                  <select
                    value={form.accountId}
                    onChange={e => setForm(f => ({ ...f, accountId: e.target.value }))}
                    className="ff-input w-full"
                  >
                    <option value="">— Select a bank account —</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>{a.accountName}</option>
                    ))}
                  </select>
                </div>
              )}

              {/* External account ID (optional for OAuth-based providers) */}
              {form.provider !== 'manual_csv' && (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                    External Account ID
                    <span className="ml-1 text-xs text-[var(--ff-text-tertiary)]">(optional)</span>
                  </label>
                  <input
                    type="text"
                    value={form.externalAccountId}
                    onChange={e => setForm(f => ({ ...f, externalAccountId: e.target.value }))}
                    placeholder={`Your ${PROVIDER_LABELS[form.provider]} account ID`}
                    className="ff-input w-full"
                  />
                </div>
              )}

              {form.provider === 'manual_csv' && (
                <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3">
                  <p className="text-sm text-amber-400">
                    Manual CSV connections do not auto-sync. Use the
                    {' '}<strong>Import Statement</strong>{' '}
                    page to upload your bank statement files.
                  </p>
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-3 px-6 py-5 border-t border-[var(--ff-border-primary)]">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => void handleAddConnection()}
                disabled={saving}
                className="flex items-center gap-2 px-5 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors disabled:opacity-50"
              >
                {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                Add Connection
              </button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

