/**
 * Open Banking Service — multi-provider bank feed connection management.
 *
 * Supports providers: manual_csv | basiq | tink | plaid
 * Real integrations (basiq/tink/plaid) are stubbed — they produce sample
 * transactions until real API keys are wired in via environment variables.
 *
 * Deduplication: uses bank_transactions.bank_reference (external tx ID).
 * Fallback dedup when bank_reference is unavailable: amount + date + description.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

// ── Types ─────────────────────────────────────────────────────────────────────

export type Provider = 'manual_csv' | 'basiq' | 'tink' | 'plaid';
export type ConnectionStatus = 'active' | 'paused' | 'error';
export type SyncStatus = 'running' | 'success' | 'failed';

export interface BankFeedConnection {
  id: string;
  companyId: string;
  provider: Provider;
  accountId: string | null;
  accountName: string | null;
  externalAccountId: string | null;
  status: ConnectionStatus;
  lastSyncAt: string | null;
  lastSyncStatus: SyncStatus | null;
  lastSyncError: string | null;
  config: Record<string, unknown>;
  createdAt: string;
  updatedAt: string;
}

export interface BankFeedConnectionInput {
  provider: Provider;
  accountId?: string;          // FK to bank_accounts.id
  externalAccountId?: string;
  config?: Record<string, unknown>;
}

export interface BankFeedSyncResult {
  connectionId: string;
  provider: Provider;
  logId: string;
  found: number;
  imported: number;
  duplicate: number;
  instructions?: string;   // for manual_csv provider
}

export interface BankFeedSyncLog {
  id: string;
  connectionId: string;
  companyId: string;
  startedAt: string;
  completedAt: string | null;
  status: SyncStatus;
  transactionsFound: number;
  transactionsImported: number;
  transactionsDuplicate: number;
  errorMessage: string | null;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function mapConnection(r: Row): BankFeedConnection {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    provider: String(r.provider) as Provider,
    accountId: r.account_id != null ? String(r.account_id) : null,
    accountName: r.account_name != null ? String(r.account_name) : null,
    externalAccountId: r.external_account_id != null ? String(r.external_account_id) : null,
    status: String(r.status ?? 'active') as ConnectionStatus,
    lastSyncAt: r.last_sync_at != null ? String(r.last_sync_at) : null,
    lastSyncStatus: r.last_sync_status != null ? String(r.last_sync_status) as SyncStatus : null,
    lastSyncError: r.last_sync_error != null ? String(r.last_sync_error) : null,
    config: (r.config as Record<string, unknown>) ?? {},
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

function mapSyncLog(r: Row): BankFeedSyncLog {
  return {
    id: String(r.id),
    connectionId: String(r.connection_id),
    companyId: String(r.company_id),
    startedAt: String(r.started_at),
    completedAt: r.completed_at != null ? String(r.completed_at) : null,
    status: String(r.status) as SyncStatus,
    transactionsFound: Number(r.transactions_found ?? 0),
    transactionsImported: Number(r.transactions_imported ?? 0),
    transactionsDuplicate: Number(r.transactions_duplicate ?? 0),
    errorMessage: r.error_message != null ? String(r.error_message) : null,
  };
}

// ── Connection CRUD ───────────────────────────────────────────────────────────

export async function listBankFeedConnections(companyId: string): Promise<BankFeedConnection[]> {
  const rows = (await sql`
    SELECT
      bfc.id,
      bfc.company_id,
      bfc.provider,
      bfc.bank_account_id  AS account_id,
      ba.account_name,
      bfc.external_account_id,
      bfc.status,
      bfc.last_sync_at,
      bfc.last_sync_status,
      bfc.last_sync_error,
      COALESCE(bfc.config, '{}')  AS config,
      bfc.created_at,
      bfc.updated_at
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.company_id = ${companyId}::UUID
      AND bfc.is_active = true
    ORDER BY bfc.created_at DESC
  `) as Row[];
  return rows.map(mapConnection);
}

export async function createBankFeedConnection(
  companyId: string,
  input: BankFeedConnectionInput,
  userId: string,
): Promise<BankFeedConnection> {
  const validProviders: Provider[] = ['manual_csv', 'basiq', 'tink', 'plaid'];
  if (!validProviders.includes(input.provider)) {
    throw new Error(`Invalid provider "${input.provider}". Must be one of: ${validProviders.join(', ')}`);
  }

  // If accountId provided, verify it belongs to this company (IDOR guard)
  if (input.accountId) {
    const check = (await sql`
      SELECT id FROM bank_accounts
      WHERE id = ${input.accountId}::UUID AND company_id = ${companyId}::UUID
      LIMIT 1
    `) as Row[];
    if (check.length === 0) {
      throw new Error('Bank account not found or does not belong to this company');
    }
  }

  const configJson = JSON.stringify(input.config ?? {});

  const rows = (await sql`
    INSERT INTO bank_feed_connections (
      company_id,
      bank_account_id,
      provider,
      external_account_id,
      status,
      config,
      created_by,
      is_active
    ) VALUES (
      ${companyId}::UUID,
      ${input.accountId ?? null}::UUID,
      ${input.provider},
      ${input.externalAccountId ?? null},
      'active',
      ${configJson}::JSONB,
      ${userId}::UUID,
      true
    )
    RETURNING *
  `) as Row[];

  const created = rows[0]!;
  log.info('Open banking connection created', {
    id: String(created.id),
    provider: input.provider,
    companyId,
  }, 'open-banking');

  return mapConnection({ ...created, account_name: null });
}

export async function deleteBankFeedConnection(
  companyId: string,
  connectionId: string,
): Promise<void> {
  await sql`
    UPDATE bank_feed_connections
    SET is_active = false, updated_at = NOW()
    WHERE id = ${connectionId}::UUID
      AND company_id = ${companyId}::UUID
  `;
  log.info('Open banking connection deleted', { connectionId, companyId }, 'open-banking');
}

// ── Sync logic ────────────────────────────────────────────────────────────────

interface StubTransaction {
  externalId: string;
  date: string;
  amount: number;
  description: string;
  reference: string | null;
}

function buildSampleTransactions(provider: Provider): StubTransaction[] {
  const today = new Date();
  const txs: StubTransaction[] = [];
  const count = 5 + Math.floor(Math.random() * 6); // 5–10

  for (let i = 0; i < count; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0]!;
    const amount = (Math.random() > 0.4 ? -1 : 1) * parseFloat((Math.random() * 5000 + 100).toFixed(2));
    txs.push({
      externalId: `${provider}-stub-${dateStr}-${i}`,
      date: dateStr,
      amount,
      description: amount < 0
        ? ['Office supplies', 'Fuel', 'Telkom invoice', 'Eskom payment', 'Staff salary'][i % 5]!
        : ['Client payment', 'Interest income', 'Deposit', 'Invoice receipt'][i % 4]!,
      reference: `REF-${Math.random().toString(36).substring(2, 8).toUpperCase()}`,
    });
  }
  return txs;
}

async function insertTransaction(
  bankAccountId: string,
  tx: StubTransaction,
): Promise<'imported' | 'duplicate'> {
  // Primary dedup: external ID via bank_reference
  const existing = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND bank_reference = ${tx.externalId}
    LIMIT 1
  `) as Row[];

  if (existing.length > 0) return 'duplicate';

  // Fallback dedup: same amount + date + description within 1 day window
  const fallback = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND amount = ${tx.amount}
      AND transaction_date = ${tx.date}::DATE
      AND description = ${tx.description}
    LIMIT 1
  `) as Row[];

  if (fallback.length > 0) return 'duplicate';

  await sql`
    INSERT INTO bank_transactions (
      bank_account_id,
      transaction_date,
      amount,
      description,
      reference,
      bank_reference,
      status
    ) VALUES (
      ${bankAccountId}::UUID,
      ${tx.date}::DATE,
      ${tx.amount},
      ${tx.description},
      ${tx.reference},
      ${tx.externalId},
      'imported'
    )
  `;
  return 'imported';
}

export async function syncBankFeed(
  companyId: string,
  connectionId: string,
  userId: string,
): Promise<BankFeedSyncResult> {
  // Verify connection belongs to company (IDOR guard)
  const connRows = (await sql`
    SELECT bfc.*, ba.account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${connectionId}::UUID
      AND bfc.company_id = ${companyId}::UUID
      AND bfc.is_active = true
    LIMIT 1
  `) as Row[];

  if (connRows.length === 0) {
    throw new Error('Connection not found or does not belong to this company');
  }

  const conn = connRows[0]!;
  const provider = String(conn.provider) as Provider;

  // Create sync log
  const logRows = (await sql`
    INSERT INTO bank_feed_sync_logs (connection_id, company_id, status)
    VALUES (${connectionId}::UUID, ${companyId}::UUID, 'running')
    RETURNING id
  `) as Row[];
  const logId = String(logRows[0]!.id);

  log.info('Bank feed sync started', { connectionId, provider, companyId, userId }, 'open-banking');

  // manual_csv: return instructions, no transaction insertion
  if (provider === 'manual_csv') {
    await sql`
      UPDATE bank_feed_sync_logs
      SET status = 'success', completed_at = NOW(), transactions_found = 0,
          transactions_imported = 0, transactions_duplicate = 0
      WHERE id = ${logId}::UUID
    `;
    await sql`
      UPDATE bank_feed_connections
      SET last_sync_at = NOW(), last_sync_status = 'success',
          last_sync_error = NULL, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
    return {
      connectionId,
      provider,
      logId,
      found: 0,
      imported: 0,
      duplicate: 0,
      instructions: 'Manual CSV import: use the Bank Transactions import page to upload your bank statement file.',
    };
  }

  // Stub fetch for basiq / tink / plaid
  const bankAccountId = conn.bank_account_id != null ? String(conn.bank_account_id) : null;
  if (!bankAccountId) {
    const errMsg = 'Connection has no linked bank account — cannot import transactions';
    await sql`
      UPDATE bank_feed_sync_logs
      SET status = 'failed', completed_at = NOW(), error_message = ${errMsg}
      WHERE id = ${logId}::UUID
    `;
    await sql`
      UPDATE bank_feed_connections
      SET last_sync_at = NOW(), last_sync_status = 'failed',
          last_sync_error = ${errMsg}, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
    throw new Error(errMsg);
  }

  try {
    const transactions = buildSampleTransactions(provider);
    let imported = 0;
    let duplicate = 0;

    for (const tx of transactions) {
      const result = await insertTransaction(bankAccountId, tx);
      if (result === 'imported') imported++;
      else duplicate++;
    }

    const found = transactions.length;

    await sql`
      UPDATE bank_feed_sync_logs
      SET status = 'success', completed_at = NOW(),
          transactions_found = ${found},
          transactions_imported = ${imported},
          transactions_duplicate = ${duplicate}
      WHERE id = ${logId}::UUID
    `;
    await sql`
      UPDATE bank_feed_connections
      SET last_sync_at = NOW(), last_sync_status = 'success',
          last_sync_error = NULL, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;

    log.info('Bank feed sync completed', {
      connectionId, provider, found, imported, duplicate,
    }, 'open-banking');

    return { connectionId, provider, logId, found, imported, duplicate };
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : 'Sync failed';
    await sql`
      UPDATE bank_feed_sync_logs
      SET status = 'failed', completed_at = NOW(), error_message = ${errMsg}
      WHERE id = ${logId}::UUID
    `;
    await sql`
      UPDATE bank_feed_connections
      SET last_sync_at = NOW(), last_sync_status = 'failed',
          last_sync_error = ${errMsg}, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
    log.error('Bank feed sync failed', { connectionId, provider, error: errMsg }, 'open-banking');
    throw err;
  }
}

// ── Sync logs ─────────────────────────────────────────────────────────────────

export async function getBankFeedSyncLogs(
  companyId: string,
  connectionId: string,
  limit = 10,
): Promise<BankFeedSyncLog[]> {
  // Verify connection belongs to company (IDOR guard)
  const connCheck = (await sql`
    SELECT id FROM bank_feed_connections
    WHERE id = ${connectionId}::UUID AND company_id = ${companyId}::UUID
    LIMIT 1
  `) as Row[];
  if (connCheck.length === 0) return [];

  const rows = (await sql`
    SELECT *
    FROM bank_feed_sync_logs
    WHERE connection_id = ${connectionId}::UUID
      AND company_id = ${companyId}::UUID
    ORDER BY started_at DESC
    LIMIT ${limit}
  `) as Row[];

  return rows.map(mapSyncLog);
}

