/**
 * Group Consolidation Page
 * Manage subsidiary relationships and run consolidated trial balances.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Building2, Plus, Loader2, AlertCircle, X, ChevronRight,
  Calendar, BarChart3, Layers, RefreshCw, CheckCircle2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

// ── Types ─────────────────────────────────────────────────────────────────────

interface GroupCompany {
  id: string;
  name: string;
  relationshipType: string;
  ownershipPercent: number;
}

interface ConsolidatedAccount {
  accountCode: string;
  accountName: string;
  accountType: string;
  byEntity: Record<string, { debit: number; credit: number }>;
  totalDebit: number;
  totalCredit: number;
  isEliminated: boolean;
}

interface ConsolidatedTrialBalance {
  groupName: string;
  periodStart: string;
  periodEnd: string;
  entities: { companyId: string; companyName: string }[];
  accounts: ConsolidatedAccount[];
  totalDebits: number;
  totalCredits: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);

function defaultRange() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end   = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return {
    start: start.toISOString().split('T')[0]!,
    end:   end.toISOString().split('T')[0]!,
  };
}

const RELATIONSHIP_LABELS: Record<string, string> = {
  parent: 'Parent',
  subsidiary: 'Subsidiary',
  branch: 'Branch',
  associate: 'Associate',
};

const ACCOUNT_TYPE_COLOUR: Record<string, string> = {
  asset:     'text-blue-400',
  liability: 'text-orange-400',
  equity:    'text-purple-400',
  income:    'text-teal-400',
  expense:   'text-red-400',
};

// ── Add Subsidiary Modal ──────────────────────────────────────────────────────

interface AddSubsidiaryModalProps {
  onClose: () => void;
  onSaved: (items: GroupCompany[]) => void;
}

function AddSubsidiaryModal({ onClose, onSaved }: AddSubsidiaryModalProps) {
  const [childCompanyId, setChildCompanyId] = useState('');
  const [ownershipPercent, setOwnershipPercent] = useState('100');
  const [relationshipType, setRelationshipType] = useState('subsidiary');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!childCompanyId.trim()) { setError('Company ID is required'); return; }
    const pct = Number(ownershipPercent);
    if (isNaN(pct) || pct < 0 || pct > 100) { setError('Ownership must be 0–100'); return; }

    setBusy(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/consolidation/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ childCompanyId: childCompanyId.trim(), ownershipPercent: pct, relationshipType }),
      });
      const json = await res.json();
      if (!json.success) { setError(json.error?.message ?? 'Failed'); return; }
      onSaved(json.data?.items ?? []);
      onClose();
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-full max-w-md rounded-2xl border border-white/10 bg-[#1a1f2e] p-6 shadow-2xl">
        <div className="mb-5 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-white">Add Subsidiary</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-300">
              Child Company ID (UUID)
            </label>
            <input
              type="text"
              value={childCompanyId}
              onChange={(e) => setChildCompanyId(e.target.value)}
              placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
              className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:border-teal-500/50 focus:outline-none focus:ring-1 focus:ring-teal-500/30"
            />
          </div>

          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-300">
              Relationship Type
            </label>
            <select
              value={relationshipType}
              onChange={(e) => setRelationshipType(e.target.value)}
              className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-sm text-white focus:border-teal-500/50 focus:outline-none focus:ring-1 focus:ring-teal-500/30"
            >
              <option value="subsidiary">Subsidiary</option>
              <option value="branch">Branch</option>
              <option value="associate">Associate</option>
            </select>
          </div>

          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-300">
              Ownership %
            </label>
            <input
              type="number"
              min={0}
              max={100}
              step={0.01}
              value={ownershipPercent}
              onChange={(e) => setOwnershipPercent(e.target.value)}
              className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-sm text-white focus:border-teal-500/50 focus:outline-none focus:ring-1 focus:ring-teal-500/30"
            />
          </div>

          {error && (
            <p className="flex items-center gap-2 text-sm text-red-400">
              <AlertCircle className="h-4 w-4 shrink-0" /> {error}
            </p>
          )}

          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg border border-white/10 px-4 py-2 text-sm text-gray-300 hover:bg-white/5 transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={busy}
              className="flex items-center gap-2 rounded-lg bg-teal-500 px-4 py-2 text-sm font-medium text-white hover:bg-teal-400 disabled:opacity-50 transition-colors"
            >
              {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
              Add Subsidiary
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// ── Main Page ─────────────────────────────────────────────────────────────────

export default function ConsolidationPage() {
  const range = defaultRange();
  const [periodStart, setPeriodStart] = useState(range.start);
  const [periodEnd,   setPeriodEnd]   = useState(range.end);

  const [groupCompanies, setGroupCompanies] = useState<GroupCompany[]>([]);
  const [loadingCompanies, setLoadingCompanies] = useState(true);

  const [report, setReport]           = useState<ConsolidatedTrialBalance | null>(null);
  const [loadingReport, setLoadingReport] = useState(false);
  const [reportError, setReportError] = useState('');

  const [showModal, setShowModal] = useState(false);

  const loadGroupCompanies = useCallback(async () => {
    setLoadingCompanies(true);
    try {
      const res  = await apiFetch('/api/accounting/consolidation/companies');
      const json = await res.json();
      setGroupCompanies(json.data?.items ?? []);
    } finally {
      setLoadingCompanies(false);
    }
  }, []);

  useEffect(() => { void loadGroupCompanies(); }, [loadGroupCompanies]);

  async function runReport() {
    if (!periodStart || !periodEnd) return;
    setLoadingReport(true);
    setReportError('');
    setReport(null);
    try {
      const params = new URLSearchParams({ periodStart, periodEnd });
      const res  = await apiFetch(`/api/accounting/consolidation/trial-balance?${params}`);
      const json = await res.json();
      if (!json.success) {
        setReportError(json.error?.message ?? 'Failed to load report');
        return;
      }
      setReport(json.data);
    } catch {
      setReportError('Network error loading report');
    } finally {
      setLoadingReport(false);
    }
  }

  const entities = report?.entities ?? [];

  return (
    <AppLayout title="Group Consolidation">
      <div className="space-y-8 p-6">

        {/* ── Header ────────────────────────────────────────────────────────── */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white">Group Consolidation</h1>
            <p className="mt-1 text-sm text-gray-400">
              Manage subsidiary relationships and view consolidated financials
            </p>
          </div>
        </div>

        {/* ── Group Companies ───────────────────────────────────────────────── */}
        <section className="rounded-2xl border border-white/10 bg-[#1a1f2e]">
          <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
            <div className="flex items-center gap-2 text-white">
              <Building2 className="h-5 w-5 text-teal-400" />
              <span className="font-semibold">Group Companies</span>
              {!loadingCompanies && (
                <span className="ml-1 rounded-full bg-teal-500/10 px-2 py-0.5 text-xs text-teal-400">
                  {groupCompanies.length}
                </span>
              )}
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={loadGroupCompanies}
                className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm text-gray-400 hover:text-white hover:bg-white/5 transition-colors"
              >
                <RefreshCw className="h-3.5 w-3.5" /> Refresh
              </button>
              <button
                onClick={() => setShowModal(true)}
                className="flex items-center gap-1.5 rounded-lg bg-teal-500/10 border border-teal-500/20 px-3 py-1.5 text-sm font-medium text-teal-400 hover:bg-teal-500/20 transition-colors"
              >
                <Plus className="h-4 w-4" /> Add Subsidiary
