/**
 * Tax Directives Page — SARS Lump Sum directive management
 * Route: /payroll/tax-directives
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { FileText, Plus, X, Calculator, Loader2 } from 'lucide-react';
import { calculateLumpSumTax, type TaxDirective, type LumpSumCalculation } from '@/modules/accounting/services/taxDirectiveService';

// ─── Helpers ──────────────────────────────────────────────────────────────────

const fmtCurrency = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const fmtDate = (d: string | Date | null) => {
  if (!d) return '—';
  const date = d instanceof Date ? d : new Date(d);
  return date.toLocaleDateString('en-ZA');
};

const STATUS_COLORS: Record<string, string> = {
  pending:   'bg-amber-500/10 text-amber-400 border border-amber-500/30',
  approved:  'bg-teal-500/10 text-teal-400 border border-teal-500/30',
  expired:   'bg-gray-500/10 text-gray-400 border border-gray-500/30',
  cancelled: 'bg-red-500/10 text-red-400 border border-red-500/30',
};

const DIRECTIVE_TYPES = ['lump_sum', 'retirement', 'severance', 'death'] as const;
const STATUSES = ['pending', 'approved', 'expired', 'cancelled'] as const;

// ─── Create Modal ─────────────────────────────────────────────────────────────

interface CreateModalProps {
  onClose: () => void;
  onCreated: () => void;
}

function CreateModal({ onClose, onCreated }: CreateModalProps) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [form, setForm] = useState({
    employee_name: '',
    employee_tax_number: '',
    directive_number: '',
    directive_type: 'retirement' as typeof DIRECTIVE_TYPES[number],
    amount: '',
    tax_rate: '',
    effective_date: '',
    expiry_date: '',
    sars_reference: '',
    notes: '',
  });

  const set = (k: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) =>
    setForm(f => ({ ...f, [k]: e.target.value }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setError('');
    try {
      const body = {
        ...form,
        amount: parseFloat(form.amount),
        tax_rate: form.tax_rate ? parseFloat(form.tax_rate) / 100 : undefined,
      };
      const res = await apiFetch('/api/accounting/tax-directives', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const j = await res.json();
        throw new Error(j.error?.message || 'Failed to create');
      }
      onCreated();
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setSaving(false);
    }
  };

  const inputCls = 'w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-400 focus:outline-none focus:border-teal-500';
  const labelCls = 'block text-xs font-medium text-gray-400 mb-1';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
      <div className="bg-gray-800 border border-gray-700 rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-700">
          <h2 className="text-lg font-semibold text-white">New Tax Directive</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white"><X className="h-5 w-5" /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {error && <p className="text-sm text-red-400 bg-red-500/10 border border-red-500/30 rounded-lg px-3 py-2">{error}</p>}

          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className={labelCls}>Employee Name *</label>
              <input className={inputCls} value={form.employee_name} onChange={set('employee_name')} required placeholder="Full name" />
            </div>
            <div>
              <label className={labelCls}>Tax Number</label>
              <input className={inputCls} value={form.employee_tax_number} onChange={set('employee_tax_number')} placeholder="SARS tax number" />
            </div>
            <div>
              <label className={labelCls}>Directive Type *</label>
              <select className={inputCls} value={form.directive_type} onChange={set('directive_type')} required>
                {DIRECTIVE_TYPES.map(t => (
                  <option key={t} value={t}>{t.replace('_', ' ').replace(/\b\w/g, c => c.toUpperCase())}</option>
                ))}
              </select>
            </div>
            <div>
              <label className={labelCls}>Gross Amount (ZAR) *</label>
              <input className={inputCls} type="number" min="0" step="0.01" value={form.amount} onChange={set('amount')} required placeholder="0.00" />
            </div>
            <div>
              <label className={labelCls}>Directive Rate (%) — leave blank for SARS table</label>
              <input className={inputCls} type="number" min="0" max="100" step="0.01" value={form.tax_rate} onChange={set('tax_rate')} placeholder="e.g. 18.00" />
            </div>
            <div>
              <label className={labelCls}>Effective Date *</label>
              <input className={inputCls} type="date" value={form.effective_date} onChange={set('effective_date')} required />
            </div>
            <div>
              <label className={labelCls}>Expiry Date</label>
              <input className={inputCls} type="date" value={form.expiry_date} onChange={set('expiry_date')} />
            </div>
            <div>
              <label className={labelCls}>Directive Number</label>
              <input className={inputCls} value={form.directive_number} onChange={set('directive_number')} placeholder="SARS directive number" />
            </div>
            <div>
              <label className={labelCls}>SARS Reference</label>
              <input className={inputCls} value={form.sars_reference} onChange={set('sars_reference')} placeholder="SARS case reference" />
            </div>
            <div className="col-span-2">
              <label className={labelCls}>Notes</label>
              <textarea className={inputCls} rows={2} value={form.notes} onChange={set('notes')} placeholder="Optional notes" />
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-2">
            <button type="button" onClick={onClose} className="px-4 py-2 text-sm text-gray-300 hover:text-white border border-gray-600 rounded-lg">Cancel</button>
            <button type="submit" disabled={saving} className="px-4 py-2 text-sm font-medium bg-teal-600 hover:bg-teal-500 text-white rounded-lg disabled:opacity-50 flex items-center gap-2">
              {saving && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Directive
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// ─── Calculator Panel ─────────────────────────────────────────────────────────

function LumpSumCalculator() {
  const [gross, setGross] = useState('');
  const [useDirectiveRate, setUseDirectiveRate] = useState(false);
  const [directiveRate, setDirectiveRate] = useState('');
  const [result, setResult] = useState<LumpSumCalculation | null>(null);

  const calculate = () => {
    const amount = parseFloat(gross);
    if (isNaN(amount) || amount <= 0) return;
    const rate = useDirectiveRate && directiveRate ? parseFloat(directiveRate) / 100 : null;
    setResult(calculateLumpSumTax(amount, rate));
  };

  return (
    <div className="bg-gray-800 border border-gray-700 rounded-xl p-5">
      <div className="flex items-center gap-2 mb-4">
        <Calculator className="h-5 w-5 text-teal-400" />
        <h3 className="text-sm font-semibold text-white">Lump Sum Calculator</h3>
      </div>

      <div className="space-y-3">
        <div>
          <label className="block text-xs font-medium text-gray-400 mb-1">Gross Amount (ZAR)</label>
          <input
            type="number" min="0" step="0.01"
            className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-teal-500"
            value={gross} onChange={e => setGross(e.target.value)} placeholder="0.00"
          />
        </div>

        <label className="flex items-center gap-2 cursor-pointer">
          <input type="checkbox" checked={useDirectiveRate} onChange={e => setUseDirectiveRate(e.target.checked)} className="accent-teal-500" />
          <span className="text-xs text-gray-300">Use directive rate</span>
        </label>

        {useDirectiveRate && (
          <div>
            <label className="block text-xs font-medium text-gray-400 mb-1">Directive Rate (%)</label>
            <input
              type="number" min="0" max="100" step="0.01"
              className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-teal-500"
              value={directiveRate} onChange={e => setDirectiveRate(e.target.value)} placeholder="e.g. 18.00"
            />
          </div>
        )}

        <button
          onClick={calculate}
          className="w-full py-2 text-sm font-medium bg-teal-600 hover:bg-teal-500 text-white rounded-lg transition-colors"
        >
          Calculate Tax
        </button>

        {result && (
          <div className="mt-3 space-y-2 border-t border-gray-700 pt-3">
            <div className="space-y-1">
              {result.breakdown.map((b, i) => (
                <div key={i} className="flex justify-between text-xs">
                  <span className="text-gray-400">{b.bracket}</span>
                  <span className="text-gray-200">{fmtCurrency(b.tax)}</span>
                </div>
              ))}
            </div>
            <div className="flex justify-between text-sm font-semibold border-t border-gray-600 pt-2">
              <span className="text-white">Total Tax</span>
              <span className="text-red-400">{fmtCurrency(result.taxAmount)}</span>
            </div>
            <div className="flex justify-between text-xs">
              <span className="text-gray-400">Net Payment</span>
              <span className="text-teal-400">{fmtCurrency(result.grossAmount - result.taxAmount)}</span>
            </div>
            <div className="flex justify-between text-xs">
              <span className="text-gray-400">Effective Rate</span>
              <span className="text-gray-200">{(result.effectiveRate * 100).toFixed(2)}%</span>
            </div>
            {result.directiveRateUsed && (
              <p className="text-xs text-amber-400">Using SARS directive rate</p>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────

export default function TaxDirectivesPage() {
  const [directives, setDirectives] = useState<TaxDirective[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('');
  const [showCreate, setShowCreate] = useState(false);
  const [updating, setUpdating] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      const res = await apiFetch(`/api/accounting/tax-directives?${params}`, { credentials: 'include' });
      const json = await res.json();
      setDirectives(json.data || []);
    } catch {
      setDirectives([]);
    } finally {
      setLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => { load(); }, [load]);

  const handleStatusChange = async (id: string, status: string) => {
    setUpdating(id);
    try {
      await apiFetch(`/api/accounting/tax-directives?id=${id}`, {
        method: 'PATCH',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      });
      await load();
    } finally {
      setUpdating(null);
    }
  };

  return (
    <AppLayout>
      {showCreate && <CreateModal onClose={() => setShowCreate(false)} onCreated={load} />}

      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <FileText className="h-5 w-5 text-teal-400" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-white">Tax Directives</h1>
                <p className="text-sm text-gray-400">SARS lump sum, retirement, severance & death directives</p>
              </div>
            </div>
            <button
              onClick={() => setShowCreate(true)}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-teal-600 hover:bg-teal-500 text-white rounded-lg transition-colors"
            >
              <Plus className="h-4 w-4" />
              New Directive
            </button>
          </div>
        </div>

        <div className="p-6">
          <div className="grid grid-cols-1 xl:grid-cols-4 gap-6">
            {/* Table — 3/4 width */}
            <div className="xl:col-span-3 space-y-4">
              {/* Filters */}
              <div className="flex gap-2 flex-wrap">
                <button
                  onClick={() => setStatusFilter('')}
                  className={`px-3 py-1.5 text-xs rounded-full border transition-colors ${!statusFilter ? 'bg-teal-500/20 text-teal-300 border-teal-500/40' : 'text-gray-400 border-gray-600 hover:text-white'}`}
                >
                  All
                </button>
                {STATUSES.map(s => (
                  <button
                    key={s}
                    onClick={() => setStatusFilter(s)}
                    className={`px-3 py-1.5 text-xs rounded-full border transition-colors capitalize ${statusFilter === s ? 'bg-teal-500/20 text-teal-300 border-teal-500/40' : 'text-gray-400 border-gray-600 hover:text-white'}`}
                  >
                    {s}
                  </button>
                ))}
              </div>

              {/* Table */}
              <div className="bg-gray-800 border border-gray-700 rounded-xl overflow-hidden">
                {loading ? (
                  <div className="flex items-center justify-center py-20">
                    <Loader2 className="h-8 w-8 animate-spin text-teal-400" />
                  </div>
                ) : directives.length === 0 ? (
                  <div className="text-center py-16 text-gray-500">
                    <FileText className="h-10 w-10 mx-auto mb-3 opacity-30" />
                    <p>No tax directives found</p>
                  </div>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-gray-700 bg-gray-750">
                          <th className="text-left px-4 py-3 text-xs font-medium text-gray-400">Employee</th>
                          <th className="text-left px-4 py-3 text-xs font-medium text-gray-400">Type</th>
                          <th className="text-right px-4 py-3 text-xs font-medium text-gray-400">Amount</th>
                          <th className="text-right px-4 py-3 text-xs font-medium text-gray-400">Rate</th>
                          <th className="text-right px-4 py-3 text-xs font-medium text-gray-400">Tax Amount</th>
                          <th className="text-left px-4 py-3 text-xs font-medium text-gray-400">Effective Date</th>
                          <th className="text-left px-4 py-3 text-xs font-medium text-gray-400">Status</th>
                          <th className="text-left px-4 py-3 text-xs font-medium text-gray-400">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-700">
                        {directives.map(d => (
                          <tr key={d.id} className="hover:bg-gray-700/30 transition-colors">
                            <td className="px-4 py-3">
                              <div className="text-white font-medium">{d.employee_name}</div>
                              {d.employee_tax_number && <div className="text-xs text-gray-400">{d.employee_tax_number}</div>}
                            </td>
                            <td className="px-4 py-3 capitalize text-gray-300">{d.directive_type.replace('_', ' ')}</td>
                            <td className="px-4 py-3 text-right text-gray-200">{fmtCurrency(Number(d.amount))}</td>
                            <td className="px-4 py-3 text-right text-gray-400">
                              {d.tax_rate !== null ? `${(Number(d.tax_rate) * 100).toFixed(2)}%` : 'SARS table'}
                            </td>
                            <td className="px-4 py-3 text-right text-red-400">
                              {d.tax_amount !== null ? fmtCurrency(Number(d.tax_amount)) : '—'}
                            </td>
                            <td className="px-4 py-3 text-gray-300">{fmtDate(d.effective_date)}</td>
                            <td className="px-4 py-3">
                              <span className={`inline-block px-2 py-0.5 text-xs rounded-full capitalize ${STATUS_COLORS[d.status] || ''}`}>
                                {d.status}
                              </span>
                            </td>
                            <td className="px-4 py-3">
                              {d.status === 'pending' && (
                                <div className="flex gap-2">
                                  <button
                                    disabled={updating === d.id}
                                    onClick={() => handleStatusChange(d.id, 'approved')}
                                    className="text-xs px-2 py-1 bg-teal-600/20 hover:bg-teal-600/40 text-teal-400 rounded transition-colors disabled:opacity-50"
                                  >
                                    Approve
                                  </button>
                                  <button
                                    disabled={updating === d.id}
                                    onClick={() => handleStatusChange(d.id, 'cancelled')}
                                    className="text-xs px-2 py-1 bg-red-600/20 hover:bg-red-600/40 text-red-400 rounded transition-colors disabled:opacity-50"
                                  >
                                    Cancel
                                  </button>
                                </div>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </div>

            {/* Calculator — 1/4 width */}
            <div className="xl:col-span-1">
              <LumpSumCalculator />
            </div>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

