import { useState } from 'react';
import { XCircle, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { notify } from '@/utils/toast';
import {
  PROVIDER_LABELS, PROVIDER_DESCRIPTIONS,
  type Provider, type BankAccount,
} from './bankFeedTypes';

const PROVIDERS: Provider[] = ['manual_csv', 'basiq', 'tink', 'plaid'];

interface Props {
  bankAccounts: BankAccount[];
  onClose: () => void;
  onCreated: () => void;
}

export function AddConnectionModal({ bankAccounts, onClose, onCreated }: Props) {
  const [provider, setProvider] = useState<Provider>('manual_csv');
  const [accountId, setAccountId] = useState('');
  const [externalAccountId, setExternalAccountId] = useState('');
  const [saving, setSaving] = useState(false);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-2xl w-full max-w-lg shadow-2xl">
        <div className="flex items-center justify-between px-6 py-5 border-b border-[var(--ff-border-primary)]">
          <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">Add Bank Feed Connection</h2>
          <button onClick={onClose} className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <XCircle className="h-5 w-5" />
          </button>
        </div>

        <div className="p-6 space-y-5">
          {/* Provider selection */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              Provider <span className="text-red-400">*</span>
            </label>
            <div className="space-y-2">
              {PROVIDERS.map(p => (
                <label
                  key={p}
                  className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                    provider === p
                      ? 'border-teal-500 bg-teal-500/10'
                      : 'border-[var(--ff-border-primary)] hover:border-[var(--ff-border-hover)]'
                  }`}
                >
                  <input
                    type="radio"
                    name="provider"
                    value={p}
                    checked={provider === p}
                    onChange={() => setProvider(p)}
                    className="mt-0.5 accent-teal-500"
                  />
                  <div>
                    <p className="text-sm font-medium text-[var(--ff-text-primary)]">{PROVIDER_LABELS[p]}</p>
                    <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">{PROVIDER_DESCRIPTIONS[p]}</p>
                  </div>
                </label>
              ))}
            </div>
          </div>

          {/* Bank account selector */}
          {bankAccounts.length > 0 && (
            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                Linked Bank Account
              </label>
              <select
                value={accountId}
                onChange={e => setAccountId(e.target.value)}
                className="ff-input w-full"
              >
                <option value="">— Select a bank account —</option>
                {bankAccounts.map(a => (
                  <option key={a.id} value={a.id}>{a.accountName}</option>
                ))}
              </select>
            </div>
          )}

          {/* External account ID — OAuth providers only */}
          {provider !== 'manual_csv' && (
            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1.5">
                External Account ID
                <span className="ml-1 text-xs text-[var(--ff-text-tertiary)]">(optional)</span>
              </label>
              <input
                type="text"
                value={externalAccountId}
                onChange={e => setExternalAccountId(e.target.value)}
                placeholder={`Your ${PROVIDER_LABELS[provider]} account ID`}
                className="ff-input w-full"
              />
            </div>
          )}

          {provider === 'manual_csv' && (
            <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3">
              <p className="text-sm text-amber-400">
                Manual CSV connections do not auto-sync. Use the{' '}
                <strong>Import Statement</strong>{' '}
                page to upload your bank statement files.
              </p>
            </div>
          )}
        </div>

        <div className="flex items-center justify-end gap-3 px-6 py-5 border-t border-[var(--ff-border-primary)]">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={() => void handleSubmit()}
            disabled={saving}
            className="flex items-center gap-2 px-5 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold transition-colors disabled:opacity-50"
          >
            {saving && <Loader2 className="h-4 w-4 animate-spin" />}
            Add Connection
          </button>
        </div>
      </div>
    </div>
  );

  async function handleSubmit() {
    setSaving(true);
    try {
      const body: Record<string, unknown> = { provider };
      if (accountId) body.accountId = accountId;
      if (externalAccountId) body.externalAccountId = externalAccountId;

      const res = await apiFetch('/api/accounting/bank-feeds', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || 'Failed to create connection');
      notify.success('Bank feed connection created');
      onCreated();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Failed to create connection');
    } finally {
      setSaving(false);
    }
  }
}

/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 * Uses useAdminPrefix hook for subdomain-aware navigation.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
  ToggleRight,
} from 'lucide-react';

interface NavDef {
  label: string;
  /** Relative path without /admin prefix, e.g. '' for dashboard, '/companies' etc. */
  path: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Navigation definitions with relative paths — full hrefs built dynamically via useAdminHref */
const NAV_DEFS: NavDef[] = [
  { label: 'Dashboard',   path: '',                          icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies',                icon: Building2 },
  { label: 'Users',       path: '/users',                    icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
    ],
  },
  { label: 'Features',    path: '/features',   icon: ToggleRight },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',   path: '/analytics',  icon: BarChart2 },
  { label: 'Components',  path: '/components', icon: Palette },
  { label: 'Settings',    path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const buildHref = useAdminHref();

  const isActive = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    if (adminPath === '') return router.asPath === href;
    return router.asPath.startsWith(href);
  };

  const isSectionOpen = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    return router.asPath.startsWith(href);
  };

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {NAV_DEFS.map(item => {
          const Icon = item.icon;
          const href = buildHref(`/admin${item.path}`);

          if (item.disabled) {
            return (
              <div
                key={item.path}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.path);
            return (
              <div key={item.path}>
                <Link
                  href={href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.path) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.path) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childHref = buildHref(`/admin${child.path}`);
                      const childActive = router.asPath === childHref;
                      return (
                        <Link
                          key={child.path}
                          href={childHref}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.path);
          return (
            <Link
              key={item.path}
              href={href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

