// ── Types ─────────────────────────────────────────────────────────────────────

interface CashFlowPeriod {
  weekStart: string;
  inflows: number;
  outflows: number;
  netFlow: number;
  runningBalance: number;
}

interface ForecastWeek {
  weekStart: string;
  projectedInflows: number;
  projectedOutflows: number;
  projectedNet: number;
  confidence: 'high' | 'medium' | 'low';
  notes: string;
}

interface CashFlowForecast {
  companyId: string;
  generatedAt: string;
  horizonDays: number;
  historicalPeriods: CashFlowPeriod[];
  forecastPeriods: ForecastWeek[];
  summary: string;
  risks: string[];
  opportunities: string[];
  currentCashBalance: number;
  projectedEndBalance: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function fmtCurrency(n: number): string {
  const abs = Math.abs(n).toLocaleString('en-ZA', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
  return (n < 0 ? '-' : '') + 'R ' + abs;
}

function fmtShortDate(dateStr: string): string {
  const d = new Date(dateStr + 'T00:00:00');
  return d.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' });
}

type ChartPoint = {
  label: string;
  actualBalance: number | null;
  forecastBalance: number | null;
  isHistorical: boolean;
};

function buildChartData(forecast: CashFlowForecast): ChartPoint[] {
  const points: ChartPoint[] = [];

  // Historical weekly actuals
  for (const h of forecast.historicalPeriods) {
    points.push({
      label: fmtShortDate(h.weekStart),
      actualBalance: h.runningBalance,
      forecastBalance: null,
      isHistorical: true,
    });
  }

  // Bridge point: current balance connects both series
  const lastHistorical = forecast.historicalPeriods[forecast.historicalPeriods.length - 1];
  const bridgeBalance = lastHistorical?.runningBalance ?? forecast.currentCashBalance;

  if (forecast.forecastPeriods.length > 0) {
    points.push({
      label: 'Now',
      actualBalance: bridgeBalance,
      forecastBalance: bridgeBalance,
      isHistorical: false,
    });
  }

  // Forecast weeks
  let runningForecast = bridgeBalance;
  for (const w of forecast.forecastPeriods) {
    runningForecast += w.projectedNet;
    points.push({
      label: fmtShortDate(w.weekStart),
      actualBalance: null,
      forecastBalance: runningForecast,
      isHistorical: false,
    });
  }

  return points;
}

