/**
 * Group Consolidation Page
 * Manage subsidiary relationships and run consolidated trial balances.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Building2, Plus, Loader2, AlertCircle, ChevronRight,
  Calendar, BarChart3, Layers, RefreshCw, CheckCircle2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { AddSubsidiaryModal } from '@/components/accounting/consolidation/AddSubsidiaryModal';
import type { GroupCompany, ConsolidatedTrialBalance } from '@/modules/accounting/services/consolidationTypes';

// ── Constants ─────────────────────────────────────────────────────────────────

const RELATIONSHIP_LABELS: Record<string, string> = {
  parent: 'Parent', subsidiary: 'Subsidiary', branch: 'Branch', associate: 'Associate',
};

const ACCOUNT_TYPE_COLOUR: Record<string, string> = {
  asset: 'text-blue-400', liability: 'text-orange-400', equity: 'text-purple-400',
  income: 'text-teal-400', expense: 'text-red-400',
};

// ── Helpers ───────────────────────────────────────────────────────────────────

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);

function defaultRange() {
  const now   = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end   = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return { start: start.toISOString().split('T')[0]!, end: end.toISOString().split('T')[0]! };
}

// ── Group Companies Table ─────────────────────────────────────────────────────

interface GroupCompaniesProps {
  items: GroupCompany[];
  loading: boolean;
  onRefresh: () => void;
  onAdd: () => void;
}

function GroupCompaniesSection({ items, loading, onRefresh, onAdd }: GroupCompaniesProps) {
  return (
    <section className="rounded-2xl border border-white/10 bg-[#1a1f2e]">
      <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
        <div className="flex items-center gap-2 text-white">
          <Building2 className="h-5 w-5 text-teal-400" />
          <span className="font-semibold">Group Companies</span>
          {!loading && (
            <span className="ml-1 rounded-full bg-teal-500/10 px-2 py-0.5 text-xs text-teal-400">
              {items.length}
            </span>
          )}
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={onRefresh}
            className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm text-gray-400 hover:text-white hover:bg-white/5 transition-colors"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Refresh
          </button>
          <button
            onClick={onAdd}
            className="flex items-center gap-1.5 rounded-lg bg-teal-500/10 border border-teal-500/20 px-3 py-1.5 text-sm font-medium text-teal-400 hover:bg-teal-500/20 transition-colors"
          >
            <Plus className="h-4 w-4" /> Add Subsidiary
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex items-center justify-center gap-2 py-10 text-gray-400">
          <Loader2 className="h-5 w-5 animate-spin" /> Loading…
        </div>
      ) : items.length === 0 ? (
        <div className="flex flex-col items-center gap-3 py-12 text-center">
          <Layers className="h-10 w-10 text-gray-600" />
          <p className="text-gray-400">No subsidiaries linked yet.</p>
          <button
            onClick={onAdd}
            className="mt-1 flex items-center gap-1.5 rounded-lg bg-teal-500 px-4 py-2 text-sm font-medium text-white hover:bg-teal-400 transition-colors"
          >
            <Plus className="h-4 w-4" /> Add First Subsidiary
          </button>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-white/5 text-left text-xs font-medium uppercase tracking-wider text-gray-500">
                <th className="px-6 py-3">Company</th>
                <th className="px-4 py-3">Relationship</th>
                <th className="px-4 py-3 text-right">Ownership %</th>
                <th className="px-4 py-3">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {items.map((c) => (
                <tr key={c.id} className="hover:bg-white/[0.02] transition-colors">
                  <td className="px-6 py-3">
                    <div className="flex items-center gap-2">
                      <Building2 className="h-4 w-4 shrink-0 text-gray-500" />
                      <div>
                        <p className="font-medium text-white">{c.name}</p>
                        <p className="text-xs text-gray-500">{c.id}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <span className="rounded-full bg-white/5 px-2 py-0.5 text-xs text-gray-300">
                      {RELATIONSHIP_LABELS[c.relationshipType] ?? c.relationshipType}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right font-mono text-gray-200">
                    {c.ownershipPercent.toFixed(2)}%
                  </td>
                  <td className="px-4 py-3">
                    <span className="flex items-center gap-1 text-xs text-teal-400">
                      <CheckCircle2 className="h-3.5 w-3.5" /> Active
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

// ── Trial Balance Table ───────────────────────────────────────────────────────

interface TBTableProps { report: ConsolidatedTrialBalance }

function TrialBalanceTable({ report }: TBTableProps) {
  const entities = report.entities;
  return (
    <>
      <div className="px-6 pb-2 text-xs text-gray-500">
        {report.groupName} — {report.periodStart} to {report.periodEnd}
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-y border-white/5 text-left text-xs font-medium uppercase tracking-wider text-gray-500">
              <th className="sticky left-0 bg-[#1a1f2e] px-6 py-3 w-28">Code</th>
              <th className="px-3 py-3 min-w-[180px]">Account</th>
              <th className="px-3 py-3">Type</th>
              {entities.map((e) => (
                <th key={e.companyId} className="px-3 py-3 text-right" colSpan={2}>
                  <span className="block truncate max-w-[140px]" title={e.companyName}>{e.companyName}</span>
                  <span className="flex justify-end gap-4 text-[10px] font-normal text-gray-600 mt-0.5">
                    <span>DR</span><span>CR</span>
                  </span>
                </th>
              ))}
              <th className="px-3 py-3 text-right">Total DR</th>
              <th className="px-3 py-3 text-right">Total CR</th>
              <th className="px-3 py-3 text-center">Elim.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {report.accounts.map((acc) => (
              <tr key={`${acc.accountCode}|${acc.accountType}`} className="hover:bg-white/[0.02] transition-colors">
                <td className="sticky left-0 bg-[#1a1f2e] px-6 py-2.5 font-mono text-xs text-gray-400">
                  {acc.accountCode}
                </td>
                <td className="px-3 py-2.5 font-medium text-gray-200">{acc.accountName}</td>
                <td className="px-3 py-2.5">
                  <span className={`capitalize text-xs ${ACCOUNT_TYPE_COLOUR[acc.accountType.toLowerCase()] ?? 'text-gray-400'}`}>
                    {acc.accountType}
                  </span>
                </td>
                {entities.map((e) => {
                  const bal = acc.byEntity[e.companyId] ?? { debit: 0, credit: 0 };
                  return (
                    <td key={e.companyId} className="px-3 py-2.5 text-right" colSpan={2}>
                      <span className="flex justify-end gap-4 font-mono text-xs text-gray-300">
                        <span>{bal.debit  ? fmt(bal.debit)  : '—'}</span>
                        <span>{bal.credit ? fmt(bal.credit) : '—'}</span>
                      </span>
                    </td>
                  );
                })}
                <td className="px-3 py-2.5 text-right font-mono text-xs font-semibold text-gray-200">{fmt(acc.totalDebit)}</td>
                <td className="px-3 py-2.5 text-right font-mono text-xs font-semibold text-gray-200">{fmt(acc.totalCredit)}</td>
                <td className="px-3 py-2.5 text-center">
                  {acc.isEliminated && (
                    <span className="rounded-full bg-amber-500/15 px-2 py-0.5 text-[10px] font-medium text-amber-400">
                      Elim
                    </span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr className="border-t-2 border-white/20 bg-white/[0.03] font-semibold">
              <td className="sticky left-0 bg-[#1a1f2e] px-6 py-3 text-xs text-gray-400 uppercase tracking-wider" colSpan={3}>Totals</td>
              {entities.map((e) => <td key={e.companyId} colSpan={2} />)}
              <td className="px-3 py-3 text-right font-mono text-sm text-white">{fmt(report.totalDebits)}</td>
              <td className="px-3 py-3 text-right font-mono text-sm text-white">{fmt(report.totalCredits)}</td>
              <td />
            </tr>
          </tfoot>
        </table>
      </div>
    </>
  );
}

// ── Page ──────────────────────────────────────────────────────────────────────

export default function ConsolidationPage() {
  const range = defaultRange();
  const [periodStart, setPeriodStart] = useState(range.start);
  const [periodEnd,   setPeriodEnd]   = useState(range.end);

  const [groupCompanies, setGroupCompanies]       = useState<GroupCompany[]>([]);
  const [loadingCompanies, setLoadingCompanies]   = useState(true);
  const [report, setReport]                       = useState<ConsolidatedTrialBalance | null>(null);
  const [loadingReport, setLoadingReport]         = useState(false);
  const [reportError, setReportError]             = useState('');
  const [showModal, setShowModal]                 = useState(false);

  const loadGroupCompanies = useCallback(async () => {
    setLoadingCompanies(true);
    try {
      const res  = await apiFetch('/api/accounting/consolidation/companies');
      const json = await res.json();
      setGroupCompanies((json.data?.items ?? []) as GroupCompany[]);
    } finally {
      setLoadingCompanies(false);
    }
  }, []);

  useEffect(() => { void loadGroupCompanies(); }, [loadGroupCompanies]);

  async function runReport() {
    if (!periodStart || !periodEnd) return;
    setLoadingReport(true);
    setReportError('');
    setReport(null);
    try {
      const params = new URLSearchParams({ periodStart, periodEnd });
      const res  = await apiFetch(`/api/accounting/consolidation/trial-balance?${params}`);
      const json = await res.json();
      if (!json.success) { setReportError(json.error?.message ?? 'Failed to load report'); return; }
      setReport(json.data as ConsolidatedTrialBalance);
    } catch {
      setReportError('Network error loading report');
    } finally {
      setLoadingReport(false);
    }
  }

  return (
    <AppLayout>
      <div className="space-y-8 p-6">
        <div>
          <h1 className="text-2xl font-bold text-white">Group Consolidation</h1>
          <p className="mt-1 text-sm text-gray-400">
            Manage subsidiary relationships and view consolidated financials
          </p>
        </div>

        <GroupCompaniesSection
          items={groupCompanies}
          loading={loadingCompanies}
          onRefresh={loadGroupCompanies}
          onAdd={() => setShowModal(true)}
        />

        {/* ── Consolidated Trial Balance ─────────────────────────────────────── */}
        <section className="rounded-2xl border border-white/10 bg-[#1a1f2e]">
          <div className="border-b border-white/10 px-6 py-4">
            <div className="flex items-center gap-2 text-white">
              <BarChart3 className="h-5 w-5 text-indigo-400" />
              <span className="font-semibold">Consolidated Trial Balance</span>
            </div>
          </div>

          <div className="flex flex-wrap items-end gap-4 px-6 py-4">
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-gray-400">Period Start</label>
              <div className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/5 px-3 py-2">
                <Calendar className="h-4 w-4 text-gray-500" />
                <input
                  type="date" value={periodStart}
                  onChange={(e) => setPeriodStart(e.target.value)}
                  className="bg-transparent text-sm text-white focus:outline-none"
                />
              </div>
            </div>
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-gray-400">Period End</label>
              <div className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/5 px-3 py-2">
                <Calendar className="h-4 w-4 text-gray-500" />
                <input
                  type="date" value={periodEnd}
                  onChange={(e) => setPeriodEnd(e.target.value)}
                  className="bg-transparent text-sm text-white focus:outline-none"
                />
              </div>
            </div>
            <button
              onClick={runReport}
              disabled={loadingReport || groupCompanies.length === 0}
              className="flex items-center gap-2 rounded-lg bg-indigo-500/90 px-5 py-2.5 text-sm font-medium text-white hover:bg-indigo-500 disabled:opacity-40 transition-colors"
            >
              {loadingReport
                ? <><Loader2 className="h-4 w-4 animate-spin" /> Running…</>
                : <><ChevronRight className="h-4 w-4" /> Run</>}
            </button>
          </div>

          {reportError && (
            <div className="mx-6 mb-4 flex items-center gap-2 rounded-lg border border-red-500/20 bg-red-500/10 px-4 py-3 text-sm text-red-400">
              <AlertCircle className="h-4 w-4 shrink-0" /> {reportError}
            </div>
          )}

          {report && <TrialBalanceTable report={report} />}

          {!report && !loadingReport && !reportError && (
            <div className="flex flex-col items-center gap-2 py-12 text-center text-gray-500">
              <BarChart3 className="h-10 w-10 text-gray-700" />
              <p className="text-sm">Select a date range and click Run to generate the report.</p>
            </div>
          )}
        </section>
      </div>

      {showModal && (
        <AddSubsidiaryModal
          onClose={() => setShowModal(false)}
          onSaved={(items) => setGroupCompanies(items)}
        />
      )}
    </AppLayout>
  );
}

