/**
 * Customer Sales Orders API
 * GET  — list orders (search, status, limit, offset)
 * GET  — get single order (?id=UUID) with items
 * POST — create order
 * PUT  — update order (draft only, requires id in body)
 * DELETE — delete order (draft only, requires id in body)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withWriteAccess} from '@/lib/auth';
import {
  getSalesOrders,
  getSalesOrder,
  createSalesOrder,
  updateSalesOrder,
  deleteSalesOrder,
} from '@/modules/accounting/services/salesOrderService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { id, status, search, limit, offset } = req.query;
    if (id) {
      const order = await getSalesOrder(companyId, id as string);
      if (!order) return apiResponse.notFound(res, 'Sales Order', id as string);
      return apiResponse.success(res, order);
    }
    const result = await getSalesOrders(companyId, {
      status: status as string,
      search: search as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = req.user.id;
    const order = await createSalesOrder(companyId, req.body, userId);
    return apiResponse.created(res, order);
  }

  if (req.method === 'PUT') {
    const { id, ...input } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    const order = await updateSalesOrder(companyId, id, input);
    if (!order) return apiResponse.badRequest(res, 'Sales order not found or not in draft status');
    return apiResponse.success(res, order);
  }

  if (req.method === 'DELETE') {
    const { id } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    const deleted = await deleteSalesOrder(companyId, id);
    if (!deleted) return apiResponse.badRequest(res, 'Sales order not found or not in draft status');
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Customer Sales Orders List Page
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { ClipboardList, Plus, Search, Loader2, Trash2, Edit } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface SalesOrder {
  id: string;
  orderNumber: string;
  customerName: string;
  orderDate: string;
  deliveryDate: string | null;
  status: string;
  totalAmount: number;
}

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const STATUS_BADGE: Record<string, string> = {
  draft: 'bg-gray-500/10 text-gray-400',
  confirmed: 'bg-blue-500/10 text-blue-400',
  partially_invoiced: 'bg-amber-500/10 text-amber-400',
  invoiced: 'bg-teal-500/10 text-teal-400',
  cancelled: 'bg-red-500/10 text-red-400',
};

const STATUS_LABEL: Record<string, string> = {
  draft: 'Draft',
  confirmed: 'Confirmed',
  partially_invoiced: 'Partially Invoiced',
  invoiced: 'Invoiced',
  cancelled: 'Cancelled',
};

const TABS = ['all', 'draft', 'confirmed', 'invoiced'] as const;

export default function CustomerSalesOrdersPage() {
  const router = useRouter();
  const [orders, setOrders] = useState<SalesOrder[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [tab, setTab] = useState<string>('all');
  const [search, setSearch] = useState('');
  const [showNew, setShowNew] = useState(false);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [form, setForm] = useState({
    customer_id: '',
    order_date: new Date().toISOString().split('T')[0],
    delivery_date: '',
    reference: '',
    notes: '',
    internal_notes: '',
  });
  const [lines, setLines] = useState([
    { description: '', quantity: 1, unit_price: 0, tax_rate: 15 },
  ]);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (tab !== 'all') params.set('status', tab);
      if (search) params.set('search', search);
      const res = await apiFetch(`/api/accounting/customer-sales-orders?${params}`);
      const json = await res.json();
      const d = json.data || json;
      setOrders(d.orders || []);
      setTotal(d.total || 0);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, [tab, search]);

  useEffect(() => {
    load();
  }, [load]);

  const handleDelete = async (id: string) => {
    const confirmed = window.confirm('Delete this draft sales order?');
    if (!confirmed) return;
    setDeleting(id);
    await apiFetch('/api/accounting/customer-sales-orders', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id }),
    });
    setDeleting(null);
    load();
  };

  const handleCreate = async () => {
    if (lines.every((l) => !l.description)) return;
    setSaving(true);
    await apiFetch('/api/accounting/customer-sales-orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...form,
        items: lines.filter((l) => l.description),
      }),
    });
    setSaving(false);
    setShowNew(false);
    setForm({
      customer_id: '',
      order_date: new Date().toISOString().split('T')[0],
      delivery_date: '',
      reference: '',
      notes: '',
      internal_notes: '',
    });
    setLines([{ description: '', quantity: 1, unit_price: 0, tax_rate: 15 }]);
    load();
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10">
                <ClipboardList className="h-6 w-6 text-blue-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Customer Sales Orders
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {total} sales order{total !== 1 ? 's' : ''}
                </p>
              </div>
            </div>
            <button
              onClick={() => setShowNew(!showNew)}
              className="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-sm"
            >
              <Plus className="h-4 w-4" /> New Sales Order
            </button>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">{error}</div>}
          {/* Tabs + Search */}
          <div className="flex items-center justify-between gap-4">
            <div className="flex gap-1">
              {TABS.map((t) => (
                <button
                  key={t}
                  onClick={() => setTab(t)}
                  className={`px-3 py-1.5 text-xs font-medium rounded-lg capitalize ${
                    tab === t
                      ? 'bg-blue-600 text-white'
                      : 'text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-secondary)]'
                  }`}
                >
                  {t === 'all' ? 'All' : STATUS_LABEL[t] || t}
                </button>
              ))}
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[var(--ff-text-tertiary)]" />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search sales orders..."
                className="ff-input pl-9 text-sm w-64"
              />
            </div>
          </div>

          {/* New Sales Order Form */}
          {showNew && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 space-y-3">
              <div className="grid grid-cols-3 gap-3">
                <input
                  value={form.customer_id}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, customer_id: e.target.value }))
                  }
                  placeholder="Customer ID"
                  className="ff-input text-sm"
                />
                <input
                  type="date"
                  value={form.order_date}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, order_date: e.target.value }))
                  }
                  className="ff-input text-sm"
                />
                <input
                  type="date"
                  value={form.delivery_date}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, delivery_date: e.target.value }))
                  }
                  placeholder="Delivery date"
                  className="ff-input text-sm"
                />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <input
                  value={form.reference}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, reference: e.target.value }))
                  }
                  placeholder="Reference"
                  className="ff-input text-sm"
                />
                <input
                  value={form.notes}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, notes: e.target.value }))
                  }
