/**
 * Customer Duplicates API
 * GET /api/accounting/customer-duplicates
 *
 * Returns pairs of customers that are likely duplicates based on:
 * - Matching email address
 * - Matching VAT number
 * - Similar name (ILIKE on first word of name, length > 3)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';
import type { DuplicatePair } from '@/types/customer-duplicates';

export type { DuplicatePair };

type Row = Record<string, unknown>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const rows = (await sql`
      SELECT
        a.id                AS id_a,
        a.name              AS name_a,
        a.email             AS email_a,
        a.vat_number        AS vat_a,
        COALESCE(inv_a.cnt, 0)::int AS invoice_count_a,
        b.id                AS id_b,
        b.name              AS name_b,
        b.email             AS email_b,
        b.vat_number        AS vat_b,
        COALESCE(inv_b.cnt, 0)::int AS invoice_count_b,
        CASE
          WHEN a.email IS NOT NULL AND a.email = b.email
            THEN 'email'
          WHEN a.vat_number IS NOT NULL AND a.vat_number = b.vat_number
            THEN 'vat'
          ELSE 'name'
        END AS match_reason
      FROM customers a
      JOIN customers b
        ON b.id > a.id
        AND b.company_id = a.company_id
        AND b.is_active = true
        AND b.deleted_at IS NULL
      LEFT JOIN (
        SELECT COALESCE(client_id, customer_id) AS cust_id, COUNT(*)::int AS cnt
        FROM customer_invoices
        WHERE company_id = ${companyId}
        GROUP BY 1
      ) inv_a ON inv_a.cust_id = a.id
      LEFT JOIN (
        SELECT COALESCE(client_id, customer_id) AS cust_id, COUNT(*)::int AS cnt
        FROM customer_invoices
        WHERE company_id = ${companyId}
        GROUP BY 1
      ) inv_b ON inv_b.cust_id = b.id
      WHERE a.company_id = ${companyId}
        AND a.is_active = true
        AND a.deleted_at IS NULL
        AND (
          (a.email IS NOT NULL AND a.email = b.email)
          OR (a.vat_number IS NOT NULL AND a.vat_number = b.vat_number)
          OR (
            a.name ILIKE '%' || split_part(b.name, ' ', 1) || '%'
            AND length(split_part(b.name, ' ', 1)) > 3
          )
        )
      ORDER BY match_reason, a.name
      LIMIT 20
    `) as Row[];

    const pairs: DuplicatePair[] = rows.map((r) => ({
      id_a: String(r.id_a),
      name_a: String(r.name_a),
      email_a: r.email_a != null ? String(r.email_a) : null,
      vat_a: r.vat_a != null ? String(r.vat_a) : null,
      invoice_count_a: Number(r.invoice_count_a),
      id_b: String(r.id_b),
      name_b: String(r.name_b),
      email_b: r.email_b != null ? String(r.email_b) : null,
      vat_b: r.vat_b != null ? String(r.vat_b) : null,
      invoice_count_b: Number(r.invoice_count_b),
      match_reason: r.match_reason as DuplicatePair['match_reason'],
    }));

    return apiResponse.success(res, pairs);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) {
      return apiResponse.success(res, []);
    }
    log.error('customer-duplicates GET failed', { error: message, module: 'accounting' });
    return apiResponse.internalError(res, err, 'Failed to find duplicate customers');
  }
}

export default withCompany(withErrorHandler(handler as never));

/**
 * Customer Merge API
 * POST /api/accounting/customer-merge
 *
 * Re-parents all FK references from source_id → target_id within a single
 * transaction, then soft-deletes the source customer.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withTransaction } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

interface MergeBody {
  source_id: string;
  target_id: string;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const body = req.body as MergeBody;
  const { source_id, target_id } = body;

  if (!source_id?.trim() || !target_id?.trim()) {
    return apiResponse.badRequest(res, 'source_id and target_id are required');
  }
  if (source_id === target_id) {
    return apiResponse.badRequest(res, 'source_id and target_id must be different customers');
  }

  try {
    await withTransaction(async (tx) => {
      // 1. Validate both customers belong to this company and are active
      const customers = await tx`
        SELECT id, name
        FROM customers
        WHERE id IN (${source_id}, ${target_id})
          AND company_id = ${companyId}
          AND deleted_at IS NULL
      `;

      if ((customers as { id: string; name: string }[]).length !== 2) {
        throw new Error('One or both customers not found or do not belong to this company');
      }

      // 2. Re-parent customer_invoices
      await tx`
        UPDATE customer_invoices
        SET customer_id = ${target_id}
        WHERE customer_id = ${source_id}
          AND company_id = ${companyId}
      `;

      // 3. Re-parent customer_payments
      await tx`
        UPDATE customer_payments
        SET customer_id = ${target_id}
        WHERE customer_id = ${source_id}
          AND company_id = ${companyId}
      `;

      // 4. Re-parent customer_contacts
      await tx`
        UPDATE customer_contacts
        SET customer_id = ${target_id}
        WHERE customer_id = ${source_id}
          AND company_id = ${companyId}
      `;

      // 5. Re-parent customer_delivery_addresses
      await tx`
        UPDATE customer_delivery_addresses
        SET customer_id = ${target_id}
        WHERE customer_id = ${source_id}
          AND company_id = ${companyId}
      `;

      // 6. Re-parent customer_activities (table may not exist — swallow gracefully)
      try {
        await tx`
          UPDATE customer_activities
          SET customer_id = ${target_id}
          WHERE customer_id = ${source_id}
            AND company_id = ${companyId}
        `;
      } catch (actErr: unknown) {
        const msg = actErr instanceof Error ? actErr.message : String(actErr);
        if (!msg.includes('does not exist')) throw actErr;
        log.info('customer_activities table not found — skipping re-parent', {
          module: 'accounting',
        });
      }

      // 7. Soft-delete the source customer
      await tx`
        UPDATE customers
        SET is_active = false,
            name = name || ' [MERGED]'
        WHERE id = ${source_id}
          AND company_id = ${companyId}
      `;
    });

    log.info('Customer merge completed', {
      source_id,
      target_id,
      companyId,
      module: 'accounting',
    });

    return apiResponse.success(res, { merged: true, target_id });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('customer-merge POST failed', { error: message, module: 'accounting' });

    if (message.includes('not found or do not belong')) {
      return apiResponse.badRequest(res, message);
    }
    return apiResponse.internalError(res, err, 'Failed to merge customers');
  }
}

export default withCompany(withErrorHandler(withWriteAccess(handler as never)));

/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 * Uses useAdminPrefix hook for subdomain-aware navigation.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
  ToggleRight,
  Zap,
} from 'lucide-react';

interface NavDef {
  label: string;
  /** Relative path without /admin prefix, e.g. '' for dashboard, '/companies' etc. */
  path: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Navigation definitions with relative paths — full hrefs built dynamically via useAdminHref */
const NAV_DEFS: NavDef[] = [
  { label: 'Dashboard',   path: '',                          icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies',                icon: Building2 },
  { label: 'Users',       path: '/users',                    icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
    ],
  },
  { label: 'Features',    path: '/features',   icon: ToggleRight },
  { label: 'Job Queue',   path: '/job-queue',  icon: Zap },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',   path: '/analytics',  icon: BarChart2 },
  { label: 'Components',  path: '/components', icon: Palette },
  { label: 'Settings',    path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const buildHref = useAdminHref();

  const isActive = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    if (adminPath === '') return router.asPath === href;
    return router.asPath.startsWith(href);
  };

  const isSectionOpen = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    return router.asPath.startsWith(href);
  };

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {NAV_DEFS.map(item => {
          const Icon = item.icon;
          const href = buildHref(`/admin${item.path}`);

          if (item.disabled) {
            return (
              <div
                key={item.path}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.path);
            return (
              <div key={item.path}>
                <Link
                  href={href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.path) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.path) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childHref = buildHref(`/admin${child.path}`);
                      const childActive = router.asPath === childHref;
                      return (
                        <Link
                          key={child.path}
                          href={childHref}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.path);
          return (
            <Link
              key={item.path}
              href={href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

/**
 * Supplier Credit Notes Page
 * Standalone view filtered to supplier credit notes only
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  FileText, Plus, Loader2, AlertCircle, ChevronRight, Filter, Download,
} from 'lucide-react';
import type { CreditNote } from '@/modules/accounting/types/ar.types';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

const STATUS_OPTIONS: { value: string; label: string }[] = [
  { value: '', label: 'All Statuses' },
  { value: 'draft', label: 'Draft' },
  { value: 'approved', label: 'Approved' },
  { value: 'applied', label: 'Applied' },
  { value: 'cancelled', label: 'Cancelled' },
];

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-gray-500/20 text-gray-400',
    approved: 'bg-teal-500/20 text-teal-400',
    applied: 'bg-blue-500/20 text-blue-400',
    cancelled: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

export default function SupplierCreditNotesPage() {
  const [creditNotes, setCreditNotes] = useState<CreditNote[]>([]);
  const [total, setTotal] = useState(0);
  const [statusFilter, setStatusFilter] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const loadCreditNotes = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ type: 'supplier' });
      if (statusFilter) params.set('status', statusFilter);
      const res = await apiFetch(`/api/accounting/credit-notes?${params}`);
      const json = await res.json();
      const payload = json.data || json;
      setCreditNotes(payload.creditNotes || []);
      setTotal(payload.total || 0);
    } catch {
      setError('Failed to load supplier credit notes');
    } finally {
      setIsLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => { loadCreditNotes(); }, [loadCreditNotes]);

  const exportCSV = () => {
    const headers = ['CN #', 'Supplier', 'Invoice', 'Date', 'Amount', 'Status'];
    const rows = creditNotes.map(cn => [
      cn.creditNoteNumber, cn.supplierName || '',
      cn.invoiceNumber || '', new Date(cn.creditDate).toLocaleDateString('en-ZA'),
      cn.totalAmount, cn.status,
    ]);
    const csv = [headers, ...rows].map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
    a.download = `supplier-credit-notes-${new Date().toISOString().split('T')[0]}.csv`; a.click();
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-orange-500/10">
                <FileText className="h-6 w-6 text-orange-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Supplier Credit Notes</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {total} credit note{total !== 1 ? 's' : ''} recorded
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {creditNotes.length > 0 && (
                <button onClick={exportCSV} className="inline-flex items-center gap-2 px-3 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-primary)] text-sm">
                  <Download className="h-4 w-4" /> CSV
                </button>
              )}
              <Link
                href="/accounting/credit-notes/new?type=supplier"
                className="inline-flex items-center gap-2 px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition-colors text-sm font-medium"
              >
                <Plus className="h-4 w-4" /> New Credit Note
              </Link>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Filters */}
          <div className="flex items-center gap-3">
            <Filter className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
            <select
              value={statusFilter}
              onChange={e => setStatusFilter(e.target.value)}
              className="ff-select text-sm"
            >
              {STATUS_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
          </div>

          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-orange-500" />
            </div>
          ) : creditNotes.length === 0 ? (
            <div className="text-center py-12 text-[var(--ff-text-secondary)]">
              No supplier credit notes found
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)]">
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">CN #</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Supplier</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Invoice</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Date</th>
                    <th className="text-right px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Amount</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Status</th>
                    <th className="px-4 py-3"></th>
                  </tr>
                </thead>
                <tbody>
                  {creditNotes.map(cn => (
                    <tr key={cn.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)] transition-colors cursor-pointer" onClick={() => window.location.href = `/accounting/credit-notes/${cn.id}`}>
                      <td className="px-4 py-3 font-mono text-[var(--ff-text-primary)]">{cn.creditNoteNumber}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-primary)]">{cn.supplierName || '—'}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">
                        {cn.invoiceNumber || '—'}
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                        {new Date(cn.creditDate).toLocaleDateString('en-ZA')}
                      </td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                        {formatCurrency(cn.totalAmount)}
                      </td>
                      <td className="px-4 py-3"><StatusBadge status={cn.status} /></td>
                      <td className="px-4 py-3 text-right">
                        <ChevronRight className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * AccountingNav configuration — tab definitions and route resolution.
 * Standalone version: all routes are internal /accounting/* paths.
 * /clients routes replaced with /accounting/customers.
 * /suppliers routes replaced with /accounting/suppliers.
 * External links to /procurement/purchase-orders, /stock-items, /inventory removed.
 *
 * Split into navSections/ for maintainability. This file re-exports everything
 * for backward compatibility.
 */

// Import types (also re-exported below for backward compatibility)
import type { DropdownItem, FlyoutSection, NavItem, Tab } from './navSections/types';
import { isFlyout } from './navSections/types';

export type { DropdownItem, FlyoutSection, NavItem, Tab };
