/**
 * Customer Detail Page
 * Tabs: Overview | Delivery Addresses | Contacts
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, User, MapPin, Users, Loader2, AlertCircle, CheckCircle2, XCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { DeliveryAddressesTab } from '@/components/accounting/customers/DeliveryAddressesTab';
import { ContactsTab } from '@/components/accounting/customers/ContactsTab';

interface Customer {
  id: string;
  name: string;
  email: string | null;
  phone: string | null;
  contact_person: string | null;
  vat_number: string | null;
  registration_number: string | null;
  payment_terms: number | null;
  credit_limit: number | null;
  is_active: boolean;
  created_at: string;
}

type Tab = 'overview' | 'addresses' | 'contacts';

const TABS: { id: Tab; label: string; icon: typeof User }[] = [
  { id: 'overview', label: 'Overview', icon: User },
  { id: 'addresses', label: 'Delivery Addresses', icon: MapPin },
  { id: 'contacts', label: 'Contacts', icon: Users },
];

export default function CustomerDetailPage() {
  const router = useRouter();
  const { customerId } = router.query;
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState<Tab>('overview');

  useEffect(() => {
    if (!customerId) return;
    void loadCustomer();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  const loadCustomer = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/customers?id=${customerId as string}`);
      const json = await res.json() as { data?: Customer | Customer[] } | Customer | Customer[];
      const data = (json as { data?: Customer | Customer[] }).data ?? json;
      if (Array.isArray(data)) {
        const match = data.find((c: Customer) => c.id === customerId);
        setCustomer(match ?? null);
        if (!match) setError('Customer not found');
      } else {
        setCustomer(data as Customer);
      }
    } catch {
      setError('Failed to load customer');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
        </div>
      </AppLayout>
    );
  }

  if (!customer) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh] flex-col">
          <AlertCircle className="h-8 w-8 text-red-400 mb-2" />
          <p className="text-[var(--ff-text-secondary)]">{error || 'Customer not found'}</p>
          <Link href="/accounting/customers" className="mt-4 text-sm text-blue-400 hover:text-blue-300">
            Back to Customers
          </Link>
        </div>
      </AppLayout>
    );
  }

  const fields: { label: string; value: string | number | null | undefined; highlight?: boolean }[] = [
    { label: 'Name', value: customer.name, highlight: true },
    { label: 'Email', value: customer.email },
    { label: 'Phone', value: customer.phone },
    { label: 'Contact Person', value: customer.contact_person },
    { label: 'VAT Number', value: customer.vat_number },
    { label: 'Registration Number', value: customer.registration_number },
    { label: 'Payment Terms', value: customer.payment_terms ? `${customer.payment_terms} days` : null },
    {
      label: 'Credit Limit',
      value: customer.credit_limit != null
        ? new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(Number(customer.credit_limit))
        : null,
    },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/customers" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Customers
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <User className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{customer.name}</h1>
              {customer.email && <p className="text-sm text-[var(--ff-text-secondary)]">{customer.email}</p>}
            </div>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${customer.is_active ? 'bg-teal-500/20 text-teal-400' : 'bg-gray-500/20 text-gray-400'}`}>
              {customer.is_active ? 'Active' : 'Inactive'}
            </span>
          </div>

          {/* Tab bar */}
          <div className="flex gap-1 mt-4 border-b border-[var(--ff-border-light)] -mx-6 px-6">
            {TABS.map(tab => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${activeTab === tab.id ? 'border-blue-500 text-blue-400' : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}
                >
                  <Icon className="h-4 w-4" />
                  {tab.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* Tab content */}
        <div className="p-6">
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {fields.map((f, i) => (
                  <div key={i} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                    <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{f.label}</p>
                    <p className={`text-lg font-semibold mt-1 ${f.highlight ? 'text-blue-400' : 'text-[var(--ff-text-primary)]'}`}>
                      {f.value || '—'}
                    </p>
                  </div>
                ))}
              </div>

              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] uppercase mb-2">Status</p>
                <div className="flex items-center gap-2">
                  {customer.is_active
                    ? <><CheckCircle2 className="h-5 w-5 text-teal-400" /><span className="text-sm text-teal-400 font-medium">Active Customer</span></>
                    : <><XCircle className="h-5 w-5 text-gray-400" /><span className="text-sm text-gray-400 font-medium">Inactive Customer</span></>}
                </div>
                {customer.created_at && (
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-2">
                    Created: {customer.created_at.split('T')[0]}
                  </p>
                )}
              </div>
            </div>
          )}

          {activeTab === 'addresses' && typeof customerId === 'string' && (
            <DeliveryAddressesTab customerId={customerId} />
          )}

          {activeTab === 'contacts' && typeof customerId === 'string' && (
            <ContactsTab customerId={customerId} />
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Customers API
 * GET  /api/accounting/customers         - List customers (optional ?q= search)
 * POST /api/accounting/customers         - Create a new customer
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  // ─── GET: List customers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        // Search queries are not cached — results change with every keystroke
        rows = (await sql`
          SELECT
            id, name, email, phone, contact_person,
            payment_terms, credit_limit, is_active,
            vat_number, registration_number,
            created_at
          FROM customers
          WHERE company_id = ${companyId}
            AND deleted_at IS NULL
            AND (name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR vat_number ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm})
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = await cacheThrough(
          CACHE_KEYS.customers(companyId),
          async () => (await sql`
            SELECT
              id, name, email, phone, contact_person,
              payment_terms, credit_limit, is_active,
              vat_number, registration_number,
              created_at
            FROM customers
            WHERE company_id = ${companyId}
              AND deleted_at IS NULL
            ORDER BY name ASC
            LIMIT 200
          `) as Row[],
          CACHE_TTL.REFERENCE_DATA,
        );
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Return empty list if table does not yet exist
      if (message.includes('does not exist')) {
        return apiResponse.success(res, []);
      }
      log.error('customers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch customers');
    }
  }

  // ─── POST: Create customer ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const b = req.body as Record<string, unknown>;
      const name = b.name as string | undefined;

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Customer name is required');
      }

      const s = (k: string) => { const v = b[k]; return typeof v === 'string' && v.trim() ? v.trim() : null; };
      const n = (k: string) => { const v = b[k]; return v !== undefined && v !== null && v !== '' ? Number(v) : null; };
      const bool = (k: string, def = false) => { const v = b[k]; return typeof v === 'boolean' ? v : def; };

      const rows = (await sql`
        INSERT INTO customers (
          company_id, name, email, phone, mobile, fax, web_address,
          vat_number, registration_number,
          billing_address, shipping_address, contact_person,
          payment_terms, payment_terms_type, credit_limit, is_active, notes,
          category_id, cash_sale, opening_balance, opening_balance_date,
          accepts_electronic_invoices, auto_allocate_receipts,
          statement_distribution, default_discount, default_vat_type,
          subject_to_drc_vat, invoices_viewable_online,
          sales_rep_id, default_price_list
        ) VALUES (
          ${companyId},
          ${name.trim()},
          ${s('email')},
          ${s('phone')},
          ${s('mobile')},
          ${s('fax')},
          ${s('web_address')},
          ${s('vat_number')},
          ${s('registration_number')},
          ${s('billing_address')},
          ${s('shipping_address')},
          ${s('contact_person')},
          ${n('payment_terms') ?? 30},
          ${s('payment_terms_type') ?? 'days'},
          ${n('credit_limit')},
          ${bool('is_active', true)},
          ${s('notes')},
          ${s('category_id') ? s('category_id') : null}::uuid,
          ${bool('cash_sale')},
          ${n('opening_balance') ?? 0},
          ${s('opening_balance_date')}::date,
          ${bool('accepts_electronic_invoices')},
          ${bool('auto_allocate_receipts')},
          ${s('statement_distribution') ?? 'email'},
          ${n('default_discount') ?? 0},
          ${s('default_vat_type')},
          ${bool('subject_to_drc_vat')},
          ${bool('invoices_viewable_online', true)},
          ${s('sales_rep_id') ? s('sales_rep_id') : null}::uuid,
          ${s('default_price_list')}
        )
        RETURNING *
      `) as Row[];

      cache.invalidate(CACHE_KEYS.customers(companyId));
      log.info('Customer created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('customers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create customer');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(withErrorHandler(withWriteAccess(handler)));

/**
 * Credit Notes API
 * GET  /api/accounting/credit-notes - List credit notes (with filters)
 * POST /api/accounting/credit-notes - Create draft credit note
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest, withWriteAccess} from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCreditNotes,
  getCreditNoteById,
  createCreditNote,
} from '@/modules/accounting/services/creditNoteService';
import type { CreditNoteStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { id, type, status, limit, offset } = req.query;
      if (id) {
        const note = await getCreditNoteById(companyId, id as string);
        if (!note) return apiResponse.notFound(res, 'Credit Note', id as string);
        return apiResponse.success(res, note);
      }
      const result = await getCreditNotes(companyId, {
        type: type as 'customer' | 'supplier' | undefined,
        status: status as CreditNoteStatus | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get credit notes', { error: err }, 'accounting-api');
      return apiResponse.internalError(res, err, 'Failed to get credit notes');
    }
  }

  if (req.method === 'POST') {
    try {
      const { type, clientId, customerInvoiceId, supplierId, supplierInvoiceId,
        creditDate, reason, subtotal, taxRate, projectId } = req.body;

      if (!type || !creditDate || subtotal === undefined) {
        return apiResponse.badRequest(res, 'type, creditDate, and subtotal are required');
      }

      // User identity comes from JWT (req.user), never from client request body
      const userId = req.user.id;

      const creditNote = await createCreditNote(companyId, {
        type,
        clientId: clientId || undefined,
        customerInvoiceId: customerInvoiceId || undefined,
        supplierId: supplierId || undefined,
        supplierInvoiceId: supplierInvoiceId || undefined,
        creditDate,
        reason: reason || undefined,
        subtotal: Number(subtotal),
        taxRate: taxRate !== undefined ? Number(taxRate) : undefined,
        projectId: projectId || undefined,
      }, userId);

      return apiResponse.created(res, creditNote);
    } catch (err) {
      log.error('Failed to create credit note', { error: err }, 'accounting-api');
      return apiResponse.internalError(res, err, 'Failed to create credit note');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(withWriteAccess(handler)));

