                          step="0.001"
                          value={li.quantity}
                          onChange={e => updateLine(idx, { quantity: Number(e.target.value) })}
                          className="ff-input w-full text-sm text-right"
                        />
                      </td>
                      <td className="py-2 pr-2">
                        <input
                          type="number"
