/**
 * Admin Usage Analytics — DAU/WAU/MAU, feature adoption, revenue by plan, churn signals.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { StatsCard } from '@/components/admin/StatsCard';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2 } from 'lucide-react';

interface UsageAnalytics {
  dau: number;
  wau: number;
  mau: number;
  stickiness_percent: number;
  top_pages: Array<{ path: string; views: number }>;
  feature_adoption: Array<{ feature: string; adoption_percent: number; user_count: number }>;
  revenue_by_plan: Array<{ plan_name: string; mrr_cents: number; company_count: number }>;
  churn_signals: Array<{ company_id: string; company_name: string; days_inactive: number; last_login: string | null }>;
}

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtDate(dateStr: string | null) {
  if (!dateStr) return 'Never';
  return new Date(dateStr).toLocaleDateString('en-ZA');
}

export default function AdminAnalytics() {
  const [data, setData]       = useState<UsageAnalytics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res  = await apiFetch('/api/admin/analytics/usage');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load analytics');
      setData(json.data as UsageAnalytics);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load analytics');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  return (
    <AdminLayout title="Usage Analytics">
      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-6">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          {error}
        </div>
      )}

      {loading && !data && (
        <div className="flex items-center justify-center py-24">
          <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
        </div>
      )}

      {data && (
        <>
          {/* Engagement Row */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
            <StatsCard title="DAU"          value={data.dau} subtitle="daily active users" />
            <StatsCard title="WAU"          value={data.wau} subtitle="weekly active users" />
            <StatsCard title="MAU"          value={data.mau} subtitle="monthly active users" />
            <StatsCard title="Stickiness"   value={`${data.stickiness_percent}%`} subtitle="DAU / MAU" />
          </div>

          {/* Revenue by Plan */}
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm mb-6">
            <div className="px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Revenue by Plan</h2>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700">
                    <th className="px-5 py-3 font-medium">Plan</th>
                    <th className="px-5 py-3 font-medium text-right">MRR</th>
                    <th className="px-5 py-3 font-medium text-right">Companies</th>
                  </tr>
                </thead>
                <tbody>
                  {data.revenue_by_plan.length === 0 && (
                    <tr><td colSpan={3} className="px-5 py-8 text-center text-gray-400">No plan data</td></tr>
                  )}
                  {data.revenue_by_plan.map((row, i) => (
                    <tr key={i} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40">
                      <td className="px-5 py-3 font-medium text-gray-800 dark:text-gray-200">{row.plan_name}</td>
                      <td className="px-5 py-3 text-right text-gray-700 dark:text-gray-300">{fmtZAR(row.mrr_cents)}</td>
                      <td className="px-5 py-3 text-right text-gray-600 dark:text-gray-400">{row.company_count}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Feature Adoption */}
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm mb-6">
            <div className="px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Feature Adoption</h2>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700">
                    <th className="px-5 py-3 font-medium">Feature</th>
                    <th className="px-5 py-3 font-medium text-right">Adoption</th>
                    <th className="px-5 py-3 font-medium text-right">Companies</th>
                  </tr>
                </thead>
                <tbody>
                  {data.feature_adoption.length === 0 && (
                    <tr><td colSpan={3} className="px-5 py-8 text-center text-gray-400">No feature data</td></tr>
                  )}
                  {data.feature_adoption.map((row, i) => (
                    <tr key={i} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40">
                      <td className="px-5 py-3 text-gray-800 dark:text-gray-200">{row.feature}</td>
                      <td className="px-5 py-3 text-right">
                        <span className="inline-flex items-center gap-1">
                          <span className="text-gray-700 dark:text-gray-300 font-medium">{row.adoption_percent}%</span>
                        </span>
                      </td>
                      <td className="px-5 py-3 text-right text-gray-600 dark:text-gray-400">{row.user_count}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Churn Signals */}
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm">
            <div className="px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Churn Signals</h2>
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">Companies with no user login in 14+ days</p>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700">
                    <th className="px-5 py-3 font-medium">Company</th>
                    <th className="px-5 py-3 font-medium text-right">Days Inactive</th>
                    <th className="px-5 py-3 font-medium text-right">Last Login</th>
                  </tr>
                </thead>
                <tbody>
                  {data.churn_signals.length === 0 && (
                    <tr><td colSpan={3} className="px-5 py-8 text-center text-gray-400">No churn signals — great!</td></tr>
                  )}
                  {data.churn_signals.map((row, i) => (
                    <tr
                      key={i}
                      className={[
                        'border-b border-gray-100 dark:border-gray-800 last:border-0',
                        row.days_inactive > 30
                          ? 'bg-red-50 dark:bg-red-900/10'
                          : 'hover:bg-gray-50 dark:hover:bg-gray-800/40',
                      ].join(' ')}
                    >
                      <td className={[
                        'px-5 py-3 font-medium',
                        row.days_inactive > 30 ? 'text-red-700 dark:text-red-400' : 'text-gray-800 dark:text-gray-200',
                      ].join(' ')}>
                        {row.company_name}
                      </td>
                      <td className={[
                        'px-5 py-3 text-right font-semibold',
                        row.days_inactive > 30 ? 'text-red-600 dark:text-red-400' : 'text-gray-600 dark:text-gray-400',
                      ].join(' ')}>
                        {row.days_inactive}d
                      </td>
                      <td className="px-5 py-3 text-right text-gray-500 dark:text-gray-400">
                        {fmtDate(row.last_login)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </AdminLayout>
  );
}

/**
 * Admin Usage Analytics API
 * GET /api/admin/analytics/usage — DAU/WAU/MAU, feature adoption, churn signals
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getUsageAnalytics } from '@/modules/admin/services/analyticsService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const analytics = await getUsageAnalytics();
      return apiResponse.success(res, analytics);
    } catch (err) {
      log.error('Failed to get usage analytics', { error: err }, 'admin-analytics-api');
      return apiResponse.badRequest(res, 'Failed to get usage analytics');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

export default withAdmin(handler);

/**
 * Audit Service
 * Admin action logging for ISAFlow Admin Platform
 * Includes unified audit log across admin, accounting, and auth sources.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { AuditLogEntry, PaginatedResult } from '../types/admin.types';

export interface UnifiedAuditEntry {
  id: string;
  source: 'admin' | 'accounting' | 'auth';
  user_id: string | null;
  user_name: string | null;
  user_email: string | null;
  company_id: string | null;
  company_name: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  entity_ref: string | null;
  details: Record<string, unknown> | string | null;
  ip_address: string | null;
  created_at: string;
}

export interface UnifiedAuditFilters {
  source?: 'admin' | 'accounting' | 'auth';
  company_id?: string;
  user_id?: string;
  action?: string;
  entity_type?: string;
  search?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

export interface AuditLogFilters {
  admin_user_id?: string;
  target_type?: string;
  target_id?: string;
  action?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = DbRow;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortColKey = filters.sort_by ?? '';
  if (sortColKey && !ALLOWED_SORT_COLUMNS[sortColKey]) throw new Error(`Invalid sort column: ${sortColKey}`);
  const sortCol = ALLOWED_SORT_COLUMNS[sortColKey] ?? 'c.created_at';
  const rawDir = (filters.sort_dir ?? 'desc').toUpperCase();
  if (rawDir !== 'ASC' && rawDir !== 'DESC') throw new Error('Invalid sort direction');
  const sortDir = rawDir === 'ASC' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

/**
 * Admin Analytics Service
 * Platform health, usage analytics, and settings for ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { PlatformHealth, UsageAnalytics, PlatformSettings } from '../types/admin.types';
type Row = DbRow;


function toISOString(value: unknown): string | null {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

export async function getPlatformHealth(): Promise<PlatformHealth> {
  const [activeUsers, apiCalls, dbSize, topCompanies] = await Promise.all([
    getActiveUserCounts(),
    getApiCallCount(),
    getDbSizeMb(),
    getTopCompaniesBySize(),
  ]);

  const health: PlatformHealth = {
    active_users_24h: activeUsers.h24,
    active_users_7d: activeUsers.d7,
    active_users_30d: activeUsers.d30,
    total_api_calls_24h: apiCalls.total,
    error_count_24h: apiCalls.errors,
    error_rate_percent: apiCalls.total > 0
      ? Math.round((apiCalls.errors / apiCalls.total) * 10000) / 100
      : 0,
    db_size_mb: dbSize,
    top_companies_by_size: topCompanies,
  };

  log.info('Platform health fetched', {
    active_users_24h: health.active_users_24h,
    db_size_mb: health.db_size_mb,
  }, 'analyticsService');

  return health;
}

async function getActiveUserCounts(): Promise<{ h24: number; d7: number; d30: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '24 hours') AS h24,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')   AS d7,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days')  AS d30
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    h24: parseInt(row.h24 as string, 10) || 0,
    d7: parseInt(row.d7 as string, 10) || 0,
    d30: parseInt(row.d30 as string, 10) || 0,
  };
}

async function getApiCallCount(): Promise<{ total: number; errors: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE action ILIKE 'error%') AS errors
    FROM admin_audit_log
    WHERE created_at >= NOW() - INTERVAL '24 hours'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10) || 0,
    errors: parseInt(row.errors as string, 10) || 0,
  };
}

async function getDbSizeMb(): Promise<number> {
  const rows = await sql`
    SELECT ROUND(pg_database_size(current_database()) / 1048576.0, 2) AS size_mb
  `;
  const val = (rows[0] as Row).size_mb;
  return parseFloat(val as string) || 0;
}

async function getTopCompaniesBySize(): Promise<PlatformHealth['top_companies_by_size']> {
  // Proxy company "size" by counting rows in major tables grouped by company_id
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name AS company_name,
      (
        COALESCE((SELECT COUNT(*) FROM gl_journal_entries je WHERE je.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM customer_invoices ci WHERE COALESCE(ci.client_id, ci.customer_id) IS NOT NULL AND ci.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM bank_transactions bt WHERE bt.company_id = c.id), 0)
      )::float / 1000.0 AS size_mb
    FROM companies c
    WHERE c.status IS DISTINCT FROM 'deleted'
    ORDER BY size_mb DESC
    LIMIT 10
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    size_mb: parseFloat(row.size_mb as string) || 0,
  }));
}

export async function getUsageAnalytics(): Promise<UsageAnalytics> {
  const [engagement, featureAdoption, revenueByPlan, churnSignals] = await Promise.all([
    getEngagementCounts(),
    getFeatureAdoption(),
    getRevenueByPlan(),
    getChurnSignals(),
  ]);

  const stickiness = engagement.mau > 0
    ? Math.round((engagement.dau / engagement.mau) * 10000) / 100
    : 0;

  const analytics: UsageAnalytics = {
    dau: engagement.dau,
    wau: engagement.wau,
    mau: engagement.mau,
    stickiness_percent: stickiness,
    // top_pages requires a page_views tracking table — not yet implemented
    top_pages: [],
    feature_adoption: featureAdoption,
    revenue_by_plan: revenueByPlan,
    churn_signals: churnSignals,
  };

  log.info('Usage analytics fetched', {
    dau: analytics.dau,
    mau: analytics.mau,
    churn_signals: analytics.churn_signals.length,
  }, 'analyticsService');

  return analytics;
}

async function getEngagementCounts(): Promise<{ dau: number; wau: number; mau: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '1 day')   AS dau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')  AS wau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS mau
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    dau: parseInt(row.dau as string, 10) || 0,
    wau: parseInt(row.wau as string, 10) || 0,
    mau: parseInt(row.mau as string, 10) || 0,
  };
}

async function getFeatureAdoption(): Promise<UsageAnalytics['feature_adoption']> {
  const totalRow = await sql`SELECT COUNT(*) AS total FROM companies WHERE status IS DISTINCT FROM 'deleted'`;
  const total = parseInt((totalRow[0] as Row).total as string, 10) || 1;

  const rows = await sql`
    SELECT
      ff.name AS feature,
      COUNT(DISTINCT cfo.company_id) AS user_count
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo ON cfo.feature_id = ff.id AND cfo.enabled = true
    GROUP BY ff.id, ff.name
    ORDER BY user_count DESC
  `;

  return (rows as Row[]).map((row) => ({
    feature: row.feature as string,
    user_count: parseInt(row.user_count as string, 10) || 0,
    adoption_percent: Math.round(((parseInt(row.user_count as string, 10) || 0) / total) * 10000) / 100,
  }));
}

async function getRevenueByPlan(): Promise<UsageAnalytics['revenue_by_plan']> {
  const rows = await sql`
    SELECT
      p.name AS plan_name,
      COUNT(s.id) AS company_count,
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM plans p
    LEFT JOIN subscriptions s ON s.plan_id = p.id AND s.status IN ('active', 'trial')
    GROUP BY p.id, p.name
    ORDER BY mrr_cents DESC
  `;
  return (rows as Row[]).map((row) => ({
    plan_name: row.plan_name as string,
    mrr_cents: parseInt(row.mrr_cents as string, 10) || 0,
    company_count: parseInt(row.company_count as string, 10) || 0,
  }));
}

async function getChurnSignals(): Promise<UsageAnalytics['churn_signals']> {
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name     AS company_name,
      EXTRACT(DAY FROM NOW() - MAX(u.last_login))::int AS days_inactive,
      MAX(u.last_login) AS last_login
    FROM companies c
    INNER JOIN company_users cu ON cu.company_id = c.id
    INNER JOIN users u ON u.id = cu.user_id AND u.is_active = true
    WHERE c.status IS DISTINCT FROM 'deleted'
    GROUP BY c.id, c.name
    HAVING MAX(u.last_login) < NOW() - INTERVAL '14 days'
        OR MAX(u.last_login) IS NULL
    ORDER BY days_inactive DESC NULLS LAST
    LIMIT 20
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    days_inactive: parseInt(row.days_inactive as string, 10) || 0,
    last_login: toISOString(row.last_login),
  }));
}

export async function getPlatformSettings(): Promise<PlatformSettings> {
  // MVP: sensible defaults — persistence table not yet implemented
  return {
    maintenance_mode: false,
    registration_enabled: true,
    default_trial_days: 14,
