/**
 * Customer Detail Page
 * Tabs: Overview | Delivery Addresses | Contacts
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, User, MapPin, Users, Loader2, AlertCircle, CheckCircle2, XCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { DeliveryAddressesTab } from '@/components/accounting/customers/DeliveryAddressesTab';
import { ContactsTab } from '@/components/accounting/customers/ContactsTab';

interface Customer {
  id: string;
  name: string;
  email: string | null;
  phone: string | null;
  contact_person: string | null;
  vat_number: string | null;
  registration_number: string | null;
  payment_terms: number | null;
  credit_limit: number | null;
  is_active: boolean;
  created_at: string;
}

type Tab = 'overview' | 'addresses' | 'contacts';

const TABS: { id: Tab; label: string; icon: typeof User }[] = [
  { id: 'overview', label: 'Overview', icon: User },
  { id: 'addresses', label: 'Delivery Addresses', icon: MapPin },
  { id: 'contacts', label: 'Contacts', icon: Users },
];

export default function CustomerDetailPage() {
  const router = useRouter();
  const { customerId } = router.query;
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState<Tab>('overview');

  useEffect(() => {
    if (!customerId) return;
    void loadCustomer();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  const loadCustomer = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/customers?id=${customerId as string}`);
      const json = await res.json() as { data?: Customer | Customer[] } | Customer | Customer[];
      const data = (json as { data?: Customer | Customer[] }).data ?? json;
      if (Array.isArray(data)) {
        const match = data.find((c: Customer) => c.id === customerId);
        setCustomer(match ?? null);
        if (!match) setError('Customer not found');
      } else {
        setCustomer(data as Customer);
      }
    } catch {
      setError('Failed to load customer');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
        </div>
      </AppLayout>
    );
  }

  if (!customer) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh] flex-col">
          <AlertCircle className="h-8 w-8 text-red-400 mb-2" />
          <p className="text-[var(--ff-text-secondary)]">{error || 'Customer not found'}</p>
          <Link href="/accounting/customers" className="mt-4 text-sm text-blue-400 hover:text-blue-300">
            Back to Customers
          </Link>
        </div>
      </AppLayout>
    );
  }

  const fields: { label: string; value: string | number | null | undefined; highlight?: boolean }[] = [
    { label: 'Name', value: customer.name, highlight: true },
    { label: 'Email', value: customer.email },
    { label: 'Phone', value: customer.phone },
    { label: 'Contact Person', value: customer.contact_person },
    { label: 'VAT Number', value: customer.vat_number },
    { label: 'Registration Number', value: customer.registration_number },
    { label: 'Payment Terms', value: customer.payment_terms ? `${customer.payment_terms} days` : null },
    {
      label: 'Credit Limit',
      value: customer.credit_limit != null
        ? new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(Number(customer.credit_limit))
        : null,
    },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/customers" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Customers
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <User className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{customer.name}</h1>
              {customer.email && <p className="text-sm text-[var(--ff-text-secondary)]">{customer.email}</p>}
            </div>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${customer.is_active ? 'bg-teal-500/20 text-teal-400' : 'bg-gray-500/20 text-gray-400'}`}>
              {customer.is_active ? 'Active' : 'Inactive'}
            </span>
          </div>

          {/* Tab bar */}
          <div className="flex gap-1 mt-4 border-b border-[var(--ff-border-light)] -mx-6 px-6">
            {TABS.map(tab => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${activeTab === tab.id ? 'border-blue-500 text-blue-400' : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}
                >
                  <Icon className="h-4 w-4" />
                  {tab.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* Tab content */}
        <div className="p-6">
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {fields.map((f, i) => (
                  <div key={i} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                    <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{f.label}</p>
                    <p className={`text-lg font-semibold mt-1 ${f.highlight ? 'text-blue-400' : 'text-[var(--ff-text-primary)]'}`}>
                      {f.value || '—'}
                    </p>
                  </div>
                ))}
              </div>

              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] uppercase mb-2">Status</p>
                <div className="flex items-center gap-2">
                  {customer.is_active
                    ? <><CheckCircle2 className="h-5 w-5 text-teal-400" /><span className="text-sm text-teal-400 font-medium">Active Customer</span></>
                    : <><XCircle className="h-5 w-5 text-gray-400" /><span className="text-sm text-gray-400 font-medium">Inactive Customer</span></>}
                </div>
                {customer.created_at && (
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-2">
                    Created: {customer.created_at.split('T')[0]}
                  </p>
                )}
              </div>
            </div>
          )}

          {activeTab === 'addresses' && typeof customerId === 'string' && (
            <DeliveryAddressesTab customerId={customerId} />
          )}

          {activeTab === 'contacts' && typeof customerId === 'string' && (
            <ContactsTab customerId={customerId} />
          )}
        </div>
      </div>
    </AppLayout>
  );
}

tool_input.content:
/**
 * Customer Deduplication Page
 * Route: /accounting/customers/dedup
 *
 * Scans for duplicate customers (same email, VAT number, or similar name)
 * and lets the user merge the duplicate into the primary record.
 * All transactions are re-parented to the surviving customer.
 */

import { useState, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Users2,
  Loader2,
  AlertCircle,
  GitMerge,
  ScanSearch,
  Info,
  CheckCircle2,
  X,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import type { DuplicatePair } from '@/types/customer-duplicates';

// ── Badge helpers ──────────────────────────────────────────────────────────────

const REASON_LABEL: Record<DuplicatePair['match_reason'], string> = {
  email: 'Same email',
  vat: 'Same VAT number',
  name: 'Similar name',
};

const REASON_COLOUR: Record<DuplicatePair['match_reason'], string> = {
  email: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  vat: 'bg-rose-500/10 text-rose-400 border-rose-500/30',
  name: 'bg-blue-500/10 text-blue-400 border-blue-500/30',
};

function MatchBadge({ reason }: { reason: DuplicatePair['match_reason'] }) {
  return (
    <span
      className={`px-2 py-0.5 rounded-full text-xs font-medium border ${REASON_COLOUR[reason]}`}
    >
      {REASON_LABEL[reason]}
    </span>
  );
}

// ── Confirm Modal ──────────────────────────────────────────────────────────────

interface ConfirmModalProps {
  keepName: string;
  mergeName: string;
  onConfirm: () => void;
  onCancel: () => void;
  isBusy: boolean;
}

function ConfirmModal({ keepName, mergeName, onConfirm, onCancel, isBusy }: ConfirmModalProps) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded-xl shadow-2xl p-6 max-w-md w-full mx-4">
        <div className="flex items-start gap-3 mb-4">
          <div className="p-2 rounded-lg bg-amber-500/10 shrink-0 mt-0.5">
            <AlertCircle className="h-5 w-5 text-amber-400" />
          </div>
          <div>
            <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">Confirm Merge</h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
              This will move <span className="font-medium text-[var(--ff-text-primary)]">all transactions</span> from
            </p>
            <p className="text-sm font-medium text-rose-400 mt-0.5">{mergeName}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">into</p>
            <p className="text-sm font-medium text-teal-400">{keepName}</p>
            <p className="text-sm text-[var(--ff-text-secondary)] mt-2">
              The duplicate record will be marked inactive. This action <span className="font-medium text-[var(--ff-text-primary)]">cannot be undone</span>.
            </p>
          </div>
        </div>
        <div className="flex justify-end gap-2">
          <button
            onClick={onCancel}
            disabled={isBusy}
            className="px-4 py-2 rounded-lg text-sm font-medium bg-[var(--ff-bg-tertiary)] hover:bg-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] transition-colors disabled:opacity-40"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            disabled={isBusy}
            className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium bg-rose-600 hover:bg-rose-700 text-white transition-colors disabled:opacity-40"
          >
            {isBusy ? <Loader2 className="h-4 w-4 animate-spin" /> : <GitMerge className="h-4 w-4" />}
            Merge Now
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Toast ──────────────────────────────────────────────────────────────────────

interface ToastProps {
  message: string;
  type: 'success' | 'error';
  onClose: () => void;
}

function Toast({ message, type, onClose }: ToastProps) {
  return (
    <div
      className={`fixed bottom-6 right-6 z-50 flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg border text-sm font-medium
        ${type === 'success'
          ? 'bg-teal-900/80 border-teal-500/30 text-teal-200'
          : 'bg-rose-900/80 border-rose-500/30 text-rose-200'
        }`}
    >
      {type === 'success'
