/**
 * Email Service
 * Generic email sending via SMTP (nodemailer) + invoice-specific helpers
 * Gracefully handles missing SMTP configuration
 */

import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { generateInvoicePdf } from './invoicePdfService';
import { inviteEmailHtml, invoiceEmailHtml } from '@/lib/email-templates';
import type { InviteEmailData, InvoiceEmailData } from '@/lib/email-templates';
import { fireWebhook } from './webhookService';
type Row = Record<string, unknown>;


// ─── Types ──────────────────────────────────────────────────────────────────

export interface EmailAttachment {
  filename: string;
  content: Buffer;
  contentType: string;
}

export interface EmailOptions {
  to: string | string[];
  subject: string;
  html: string;
  attachments?: EmailAttachment[];
}

export interface EmailResult {
  success: boolean;
  messageId?: string;
  error?: string;
}

// ─── SMTP Configuration ────────────────────────────────────────────────────

interface SmtpConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  from: string;
}

function getSmtpConfig(): SmtpConfig | null {
  const host = process.env.SMTP_HOST;
  const port = process.env.SMTP_PORT;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  const from = process.env.SMTP_FROM || 'accounts@isaflow.co.za';

  if (!host || !user || !pass) {
    return null;
  }

  return {
    host,
    port: port ? parseInt(port, 10) : 587,
    user,
    pass,
    from,
  };
}

// ─── Generic Email Sender ───────────────────────────────────────────────────

export async function sendEmail(options: EmailOptions): Promise<EmailResult> {
  const config = getSmtpConfig();

  if (!config) {
    log.warn('SMTP not configured. Set SMTP_HOST, SMTP_USER, SMTP_PASS environment variables.', {}, 'emailService');
    return { success: false, error: 'SMTP not configured' };
  }

  try {
    // Dynamic import to avoid loading nodemailer when not needed
    const nodemailer = await import('nodemailer');

    const transporter = nodemailer.createTransport({
      host: config.host,
      port: config.port,
      secure: config.port === 465,
      auth: {
        user: config.user,
        pass: config.pass,
      },
      tls: {
        // Allow self-signed certs in dev; enforce TLS validation in production
        rejectUnauthorized: process.env.NODE_ENV === 'production',
      },
    });

    const recipients = Array.isArray(options.to) ? options.to.join(', ') : options.to;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const mailOptions: any = {
      from: config.from,
      to: recipients,
      subject: options.subject,
      html: options.html,
      attachments: options.attachments?.map((att) => ({
        filename: att.filename,
        content: att.content,
        contentType: att.contentType,
      })),
    };

    const info = await transporter.sendMail(mailOptions);

    log.info('Email sent', {
      messageId: info.messageId,
      to: recipients,
      subject: options.subject,
    }, 'emailService');

    return {
      success: true,
      messageId: info.messageId,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown email error';
    log.error('Failed to send email', { error: message, to: options.to }, 'emailService');
    return { success: false, error: message };
  }
}

// ─── Invoice Email ──────────────────────────────────────────────────────────

const fmtZAR = (amount: number): string =>
  'R ' + Number(amount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const fmtDate = (d: string | null | undefined): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

export async function sendInvoiceEmail(companyId: string, 
  invoiceId: string,
  recipientEmail: string
): Promise<EmailResult> {
  // Fetch invoice summary for email body
  const invoiceRows = (await sql`
    SELECT ci.invoice_number, ci.invoice_date, ci.due_date,
           ci.total_amount, ci.amount_paid,
           c.name AS client_name
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID
  `) as Row[];

  if (invoiceRows.length === 0) {
    throw new Error(`Invoice not found: ${invoiceId}`);
  }

  const invoiceRow = invoiceRows[0]!;
  const invoice = {
    invoice_number: String(invoiceRow.invoice_number ?? ''),
    invoice_date: invoiceRow.invoice_date != null ? String(invoiceRow.invoice_date) : null,
    due_date: invoiceRow.due_date != null ? String(invoiceRow.due_date) : null,
    total_amount: Number(invoiceRow.total_amount),
    amount_paid: Number(invoiceRow.amount_paid ?? 0),
    client_name: invoiceRow.client_name != null ? String(invoiceRow.client_name) : null,
  };
  const balance = invoice.total_amount - invoice.amount_paid;
  const companyName = 'IsaFlow';

  // Generate PDF
  const pdfBuffer = await generateInvoicePdf(companyId, invoiceId);

  // Build email HTML (table-based for email client compatibility)
  const invoiceData: InvoiceEmailData = {
    invoiceNumber: invoice.invoice_number,
    clientName: invoice.client_name || 'Valued Customer',
    invoiceDate: fmtDate(invoice.invoice_date),
    dueDate: fmtDate(invoice.due_date),
    totalAmount: fmtZAR(invoice.total_amount),
    balanceDue: fmtZAR(balance),
    companyName,
  };
  const html = invoiceEmailHtml(invoiceData);

  // Send email with PDF attachment
  const result = await sendEmail({
    to: recipientEmail,
    subject: `Invoice ${invoice.invoice_number} from ${companyName}`,
    html,
    attachments: [
      {
        filename: `${invoice.invoice_number || 'Invoice'}.pdf`,
        content: pdfBuffer,
        contentType: 'application/pdf',
      },
    ],
  });

  // Update tracking fields on the invoice
  if (result.success) {
    await sql`
      UPDATE customer_invoices
      SET email_sent_at = NOW(),
          email_sent_to = ${recipientEmail},
          email_message_id = ${result.messageId || null},
          updated_at = NOW()
      WHERE id = ${invoiceId}::UUID
    `;

    log.info('Invoice email sent and tracked', {
      invoiceId,
      recipientEmail,
      messageId: result.messageId,
    }, 'emailService');

    // Fire invoice.sent webhook — non-blocking
    void fireWebhook(companyId, 'invoice.sent', {
      invoiceId,
      invoiceNumber: invoice.invoice_number,
      totalAmount: invoice.total_amount,
      recipientEmail,
    });
  }

  return result;
}

// ─── Invite Email ───────────────────────────────────────────────────────────

export interface InviteEmailOptions {
  recipientEmail: string;
  inviteToken: string;
  companyName: string;
  inviterName: string;
  role: string;
  baseUrl: string;
}

export async function sendInviteEmail(options: InviteEmailOptions): Promise<EmailResult> {
  const inviteUrl = `${options.baseUrl}/invite/${options.inviteToken}`;

  const inviteData: InviteEmailData = {
    inviterName: options.inviterName,
    companyName: options.companyName,
    role: options.role,
    inviteUrl,
    recipientEmail: options.recipientEmail,
  };

  return sendEmail({
    to: options.recipientEmail,
    subject: `You've been invited to join ${options.companyName} on ISAFlow`,
    html: inviteEmailHtml(inviteData),
  });
}

/**
 * Admin User Service
 * Cross-company user management for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import type { DbRow } from '@/lib/neon';
import { log } from '@/lib/logger';
import { generateRandomPassword, hashPassword } from '@/lib/auth';
import type {
  AdminUserListItem,
  AdminUserDetail,
  AdminUserCompany,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = DbRow;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  email: 'u.email',
  first_name: 'u.first_name',
  last_name: 'u.last_name',
  created_at: 'u.created_at',
  last_login: 'u.last_login',
  role: 'u.role',
};

export async function listUsers(
  filters: AdminListFilters & { role?: string; company_id?: string } = {}
): Promise<PaginatedResult<AdminUserListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortColKey = filters.sort_by ?? '';
  if (sortColKey && !ALLOWED_SORT_COLUMNS[sortColKey]) throw new Error(`Invalid sort column: ${sortColKey}`);
  const sortCol = ALLOWED_SORT_COLUMNS[sortColKey] ?? 'u.created_at';
  const rawDir = (filters.sort_dir ?? 'desc').toUpperCase();
  if (rawDir !== 'ASC' && rawDir !== 'DESC') throw new Error('Invalid sort direction');
  const sortDir = rawDir === 'ASC' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;
  const companyFilter = filters.company ? `%${filters.company}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT u.id) AS total
    FROM users u
    LEFT JOIN company_users cu ON cu.user_id = u.id
    WHERE (${searchPattern}::text IS NULL
           OR u.email ILIKE ${searchPattern}
           OR u.first_name ILIKE ${searchPattern}
           OR u.last_name ILIKE ${searchPattern})
      AND (${filters.role ?? null}::text IS NULL OR u.role = ${filters.role ?? null})
      AND (${filters.company_id ?? null}::uuid IS NULL OR cu.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR (${filters.status ?? null} = 'active'    AND u.is_active = true)
           OR (${filters.status ?? null} = 'suspended' AND u.is_active = false))
      AND (${companyFilter}::text IS NULL OR EXISTS (
        SELECT 1 FROM company_users cu4
        JOIN companies c4 ON c4.id = cu4.company_id
        WHERE cu4.user_id = u.id AND c4.name ILIKE ${companyFilter}
      ))
  `;

  const rows = await sql`
    SELECT
      u.id,
      u.email,
      u.first_name,
      u.last_name,
      u.role,
      CASE WHEN u.is_active THEN 'active' ELSE 'suspended' END        AS status,
      (SELECT COUNT(*)
         FROM company_users cu2
        WHERE cu2.user_id = u.id)::int                                AS company_count,
      ARRAY(
        SELECT c.name
          FROM company_users cu3
          JOIN companies c ON c.id = cu3.company_id
         WHERE cu3.user_id = u.id
         ORDER BY c.name
         LIMIT 10
      )                                                               AS company_names,
      (SELECT c.name
         FROM company_users cup
         JOIN companies c ON c.id = cup.company_id
        WHERE cup.user_id = u.id
        ORDER BY cup.created_at ASC
        LIMIT 1)                                                      AS primary_company,
      u.last_login,
      COALESCE(
        (SELECT COUNT(*) FROM user_sessions s WHERE s.user_id = u.id)::int,
        0
      )                                                               AS login_count,
      u.created_at
    FROM users u
    LEFT JOIN company_users cu ON cu.user_id = u.id
    WHERE (${searchPattern}::text IS NULL
           OR u.email ILIKE ${searchPattern}
           OR u.first_name ILIKE ${searchPattern}
           OR u.last_name ILIKE ${searchPattern})
      AND (${filters.role ?? null}::text IS NULL OR u.role = ${filters.role ?? null})
      AND (${filters.company_id ?? null}::uuid IS NULL OR cu.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR (${filters.status ?? null} = 'active'    AND u.is_active = true)
           OR (${filters.status ?? null} = 'suspended' AND u.is_active = false))
      AND (${companyFilter}::text IS NULL OR EXISTS (
        SELECT 1 FROM company_users cu4
        JOIN companies c4 ON c4.id = cu4.company_id
        WHERE cu4.user_id = u.id AND c4.name ILIKE ${companyFilter}
      ))
    GROUP BY u.id, u.email, u.first_name, u.last_name, u.role, u.is_active,
             u.last_login, u.created_at
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listUsers: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminUserService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      email: r.email as string,
      first_name: r.first_name as string | null,
      last_name: r.last_name as string | null,
      role: r.role as string,
      status: r.status as string,
      company_count: r.company_count as number,
      company_names: (r.company_names as string[]) ?? [],
      last_login: toIso(r.last_login),
      login_count: r.login_count as number,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getUserDetail(
  userId: string
): Promise<AdminUserDetail | null> {
  const rows = await sql`
    SELECT
      u.id,
      u.email,
      u.first_name,
      u.last_name,
      u.role,
      CASE WHEN u.is_active THEN 'active' ELSE 'suspended' END AS status,
      u.phone,
      u.department,
      u.last_login,
      u.last_login_ip,
      u.suspended_at,
      u.suspended_reason,
      COALESCE(
        (SELECT COUNT(*) FROM user_sessions s WHERE s.user_id = u.id)::int,
        0
      ) AS login_count,
      u.created_at
    FROM users u
    WHERE u.id = ${userId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  const companyRows = await sql`
    SELECT
      cu.company_id,
      c.name AS company_name,
      cu.role,
      COALESCE(cu.is_default, false) AS is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId}
    ORDER BY c.name
  `;

  const companies: AdminUserCompany[] = (companyRows as Row[]).map((c) => ({
    company_id: c.company_id as string,
    company_name: c.company_name as string,
    role: c.role as string,
    is_default: c.is_default as boolean,
  }));

  return {
    id: r.id as string,
    email: r.email as string,
    first_name: r.first_name as string | null,
    last_name: r.last_name as string | null,
    role: r.role as string,
    status: r.status as string,
    company_count: companies.length,
    company_names: companies.map((c) => c.company_name),
    last_login: toIso(r.last_login),
    login_count: r.login_count as number,
    created_at: toIso(r.created_at) ?? '',
    phone: r.phone as string | null,
    department: r.department as string | null,
    last_login_ip: r.last_login_ip as string | null,
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    companies,
  };
}

// 'super_admin' is intentionally excluded — promotion via API is not permitted (H13)
const ALLOWED_ROLES = ['admin', 'manager', 'storeman', 'technician', 'viewer'];

export async function updateUser(
  userId: string,
  data: { first_name?: string; last_name?: string; role?: string; phone?: string }
): Promise<void> {
  if (data.role === 'super_admin') {
    throw new Error('Cannot promote to super_admin via API');
  }
  if (data.role && !ALLOWED_ROLES.includes(data.role)) {
    throw new Error(`Invalid role: ${data.role}`);
  }
  await sql`
    UPDATE users SET
      first_name = COALESCE(${data.first_name ?? null}, first_name),
      last_name  = COALESCE(${data.last_name ?? null}, last_name),
      role       = COALESCE(${data.role ?? null}, role),
      phone      = COALESCE(${data.phone ?? null}, phone),
      updated_at = NOW()
    WHERE id = ${userId}
  `;
  log.info('updateUser', { userId }, 'AdminUserService');
}

export async function suspendUser(
  userId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE users
    SET is_active        = false,
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${userId}
  `;
  // Invalidate all active sessions immediately
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('suspendUser', { userId, reason }, 'AdminUserService');
}

export async function activateUser(userId: string): Promise<void> {
  await sql`
    UPDATE users
    SET is_active        = true,
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${userId}
  `;
  log.info('activateUser', { userId }, 'AdminUserService');
}

/**
 * Generate a temporary password, hash and store it, return plain text.
 * Caller is responsible for emailing the reset token/password.
 */
export async function resetPassword(userId: string): Promise<string> {
  const temporaryPassword = generateRandomPassword();
  const hashed = await hashPassword(temporaryPassword);

  await sql`
    UPDATE users
    SET password_hash        = ${hashed},
        must_change_password = true,
        updated_at           = NOW()
    WHERE id = ${userId}
  `;

  log.info('resetPassword — temporary password issued', { userId }, 'AdminUserService');
  return temporaryPassword;
}

/**
 * Force logout by deleting all active sessions for a user.
 * A no-op placeholder message is logged if no sessions exist.
 */
export async function forceLogout(userId: string): Promise<void> {
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('forceLogout — sessions cleared', { userId }, 'AdminUserService');
}

const ALLOWED_COMPANY_ROLES = ['admin', 'accountant', 'bookkeeper', 'viewer'];

export async function addUserToCompany(
  userId: string,
  companyId: string,
  role: string
): Promise<void> {
  if (role && !ALLOWED_COMPANY_ROLES.includes(role)) {
    throw new Error(`Invalid role: ${role}`);
  }
  await sql`
    INSERT INTO company_users (user_id, company_id, role, created_at)
    VALUES (${userId}, ${companyId}, ${role}, NOW())
    ON CONFLICT (user_id, company_id) DO UPDATE
      SET role = EXCLUDED.role
  `;
  log.info('addUserToCompany', { userId, companyId, role }, 'AdminUserService');
}

export async function removeUserFromCompany(
  userId: string,
  companyId: string
): Promise<void> {
  await sql`
    DELETE FROM company_users
    WHERE user_id = ${userId} AND company_id = ${companyId}
  `;
  log.info('removeUserFromCompany', { userId, companyId }, 'AdminUserService');
}

/**
 * Reset a user's onboarding state so they go through the company wizard again
 * on next login. Removes all company links and clears sessions.
 */
export async function resetOnboarding(userId: string): Promise<void> {
  await sql`
    UPDATE users
    SET onboarding_completed = false,
        updated_at           = NOW()
    WHERE id = ${userId}
  `;
  await sql`DELETE FROM company_users WHERE user_id = ${userId}`;
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('resetOnboarding — user must re-onboard', { userId }, 'AdminUserService');
}

