      });
      if (!res.ok) throw new Error('Bulk extend failed');
      setSelected(new Set());
      await load();
    } catch {
      setError('Bulk extend failed');
    } finally {
      setBulkWorking(false);
    }
  }, [selected, load]);

  /* --------------------------------------------------- select helpers */
  const toggleAll = () => {
    if (selected.size === filtered.length) {
      setSelected(new Set());
    } else {
