                { label: 'Converted This Month',  value: stats.converted_this_month,   icon: CheckCircle, colour: 'text-green-400' },
                { label: 'Conversion Rate',       value: `${stats.conversion_rate_percent}%`, icon: TrendingUp, colour: 'text-teal-400' },
              ].map((card) => {
