 * Used exclusively by pages/accounting/customers/dedup.tsx
 */

import { useState } from 'react';
import {
  AlertCircle,
  GitMerge,
  CheckCircle2,
  X,
  Loader2,
} from 'lucide-react';
import type { DuplicatePair } from '@/types/customer-duplicates';

// ── Match badge ────────────────────────────────────────────────────────────────

const REASON_LABEL: Record<DuplicatePair['match_reason'], string> = {
  email: 'Same email',
  vat: 'Same VAT number',
  name: 'Similar name',
};

const REASON_COLOUR: Record<DuplicatePair['match_reason'], string> = {
  email: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  vat: 'bg-rose-500/10 text-rose-400 border-rose-500/30',
  name: 'bg-blue-500/10 text-blue-400 border-blue-500/30',
};

export function MatchBadge({ reason }: { reason: DuplicatePair['match_reason'] }) {
  return (
    <span
      className={`px-2 py-0.5 rounded-full text-xs font-medium border ${REASON_COLOUR[reason]}`}
    >
      {REASON_LABEL[reason]}
    </span>
  );
}

// ── Confirm modal ──────────────────────────────────────────────────────────────

export interface ConfirmModalProps {
  keepName: string;
  mergeName: string;
  onConfirm: () => void;
  onCancel: () => void;
  isBusy: boolean;
}

