/**
 * Customer Deduplication Page
 * Route: /accounting/customers/dedup
 *
 * Scans for duplicate customers (same email, VAT number, or similar name)
 * and lets the user merge the duplicate into the primary record.
 * All transactions are re-parented to the surviving customer.
 */

import { useState, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Users2,
  Loader2,
  AlertCircle,
  GitMerge,
  Search,
  Info,
  CheckCircle2,
  X,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import type { DuplicatePair } from '@/types/customer-duplicates';

// ── Badge helpers ──────────────────────────────────────────────────────────────

const REASON_LABEL: Record<DuplicatePair['match_reason'], string> = {
  email: 'Same email',
  vat: 'Same VAT number',
  name: 'Similar name',
};

const REASON_COLOUR: Record<DuplicatePair['match_reason'], string> = {
  email: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  vat: 'bg-rose-500/10 text-rose-400 border-rose-500/30',
  name: 'bg-blue-500/10 text-blue-400 border-blue-500/30',
};

function MatchBadge({ reason }: { reason: DuplicatePair['match_reason'] }) {
  return (
    <span
      className={`px-2 py-0.5 rounded-full text-xs font-medium border ${REASON_COLOUR[reason]}`}
    >
      {REASON_LABEL[reason]}
    </span>
  );
}

// ── Confirm Modal ──────────────────────────────────────────────────────────────

interface ConfirmModalProps {
  keepName: string;
  mergeName: string;
  onConfirm: () => void;
  onCancel: () => void;
  isBusy: boolean;
}

function ConfirmModal({ keepName, mergeName, onConfirm, onCancel, isBusy }: ConfirmModalProps) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded-xl shadow-2xl p-6 max-w-md w-full mx-4">
        <div className="flex items-start gap-3 mb-4">
          <div className="p-2 rounded-lg bg-amber-500/10 shrink-0 mt-0.5">
            <AlertCircle className="h-5 w-5 text-amber-400" />
          </div>
          <div>
            <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">Confirm Merge</h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
              This will move <span className="font-medium text-[var(--ff-text-primary)]">all transactions</span> from
            </p>
            <p className="text-sm font-medium text-rose-400 mt-0.5">{mergeName}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">into</p>
            <p className="text-sm font-medium text-teal-400">{keepName}</p>
            <p className="text-sm text-[var(--ff-text-secondary)] mt-2">
              The duplicate record will be marked inactive. This action <span className="font-medium text-[var(--ff-text-primary)]">cannot be undone</span>.
            </p>
          </div>
        </div>
        <div className="flex justify-end gap-2">
          <button
            onClick={onCancel}
            disabled={isBusy}
            className="px-4 py-2 rounded-lg text-sm font-medium bg-[var(--ff-bg-tertiary)] hover:bg-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] transition-colors disabled:opacity-40"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            disabled={isBusy}
            className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium bg-rose-600 hover:bg-rose-700 text-white transition-colors disabled:opacity-40"
          >
            {isBusy ? <Loader2 className="h-4 w-4 animate-spin" /> : <GitMerge className="h-4 w-4" />}
            Merge Now
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Toast ──────────────────────────────────────────────────────────────────────

interface ToastProps {
  message: string;
  type: 'success' | 'error';
  onClose: () => void;
}

function Toast({ message, type, onClose }: ToastProps) {
  return (
    <div
      className={`fixed bottom-6 right-6 z-50 flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg border text-sm font-medium
        ${type === 'success'
          ? 'bg-teal-900/80 border-teal-500/30 text-teal-200'
          : 'bg-rose-900/80 border-rose-500/30 text-rose-200'
        }`}
    >
      {type === 'success'
        ? <CheckCircle2 className="h-4 w-4 text-teal-400 shrink-0" />
        : <AlertCircle className="h-4 w-4 text-rose-400 shrink-0" />
      }
      {message}
      <button onClick={onClose} className="ml-1 opacity-60 hover:opacity-100">
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

// ── Customer Card ──────────────────────────────────────────────────────────────

interface CustomerCardProps {
  id: string;
  name: string;
  email: string | null;
  vat: string | null;
  invoiceCount: number;
  isKeep: boolean;
  onKeep: () => void;
}

function CustomerCard({ id: _id, name, email, vat, invoiceCount, isKeep, onKeep }: CustomerCardProps) {
  return (
    <div
      className={`flex-1 rounded-xl border p-4 transition-all ${
        isKeep
          ? 'border-teal-500/50 bg-teal-500/5 ring-1 ring-teal-500/30'
          : 'border-[var(--ff-border-primary)] bg-[var(--ff-bg-tertiary)]'
      }`}
    >
      {isKeep && (
        <div className="flex items-center gap-1.5 mb-2">
          <CheckCircle2 className="h-3.5 w-3.5 text-teal-400" />
          <span className="text-xs font-medium text-teal-400">Will be kept</span>
        </div>
      )}
      <p className="font-semibold text-[var(--ff-text-primary)] text-sm mb-1">{name}</p>
      {email && <p className="text-xs text-[var(--ff-text-secondary)] truncate">{email}</p>}
      {vat && <p className="text-xs text-[var(--ff-text-tertiary)]">VAT: {vat}</p>}
      <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
        {invoiceCount} invoice{invoiceCount !== 1 ? 's' : ''}
      </p>
      {!isKeep && (
        <button
          onClick={onKeep}
          className="mt-3 w-full px-3 py-1.5 rounded-lg text-xs font-medium bg-teal-600 hover:bg-teal-700 text-white transition-colors"
        >
          Keep this one
        </button>
      )}
    </div>
  );
}

// ── Pair Row ───────────────────────────────────────────────────────────────────

interface PairRowProps {
  pair: DuplicatePair;
  onMergeRequest: (keepId: string, mergeId: string, keepName: string, mergeName: string) => void;
}

function PairRow({ pair, onMergeRequest }: PairRowProps) {
  const [keepId, setKeepId] = useState<string>(pair.id_a);

  const mergeId = keepId === pair.id_a ? pair.id_b : pair.id_a;
  const keepName = keepId === pair.id_a ? pair.name_a : pair.name_b;
  const mergeName = keepId === pair.id_a ? pair.name_b : pair.name_a;

  return (
    <div className="rounded-xl border border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)] p-4">
      <div className="flex items-center justify-between mb-3">
        <MatchBadge reason={pair.match_reason} />
        <button
          onClick={() => onMergeRequest(keepId, mergeId, keepName, mergeName)}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium bg-[var(--ff-bg-tertiary)] hover:bg-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] border border-[var(--ff-border-primary)] transition-colors"
        >
          <GitMerge className="h-3.5 w-3.5" />
          Merge
        </button>
      </div>

      <div className="flex gap-3">
        <CustomerCard
          id={pair.id_a}
          name={pair.name_a}
          email={pair.email_a}
          vat={pair.vat_a}
          invoiceCount={pair.invoice_count_a}
          isKeep={keepId === pair.id_a}
          onKeep={() => setKeepId(pair.id_a)}
        />

        <div className="flex flex-col items-center justify-center shrink-0 gap-1 py-2">
          <div className="w-px h-6 bg-[var(--ff-border-primary)]" />
          <span className="text-[var(--ff-text-tertiary)] text-xs font-medium">vs</span>
          <div className="w-px h-6 bg-[var(--ff-border-primary)]" />
        </div>

        <CustomerCard
          id={pair.id_b}
          name={pair.name_b}
          email={pair.email_b}
          vat={pair.vat_b}
          invoiceCount={pair.invoice_count_b}
          isKeep={keepId === pair.id_b}
          onKeep={() => setKeepId(pair.id_b)}
        />
      </div>
    </div>
  );
}

// ── Main Page ──────────────────────────────────────────────────────────────────

interface PendingMerge {
  keepId: string;
  mergeId: string;
  keepName: string;
  mergeName: string;
}

export default function CustomerDedupPage() {
  const [pairs, setPairs] = useState<DuplicatePair[]>([]);
  const [scanned, setScanned] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [isMerging, setIsMerging] = useState(false);
  const [pending, setPending] = useState<PendingMerge | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 5000);
  }, []);

  const scan = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/customer-duplicates');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json() as { data: DuplicatePair[] };
      setPairs(json.data ?? []);
      setScanned(true);
    } catch {
      setError('Failed to scan for duplicates. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleMergeConfirm = useCallback(async () => {
    if (!pending) return;
    setIsMerging(true);
    try {
      const res = await apiFetch('/api/accounting/customer-merge', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ target_id: pending.keepId, source_id: pending.mergeId }),
      });
      if (!res.ok) {
        const body = await res.json() as { message?: string };
        throw new Error(body.message ?? `HTTP ${res.status}`);
      }
      setPairs((prev) => prev.filter(
        (p) =>
          !(
            (p.id_a === pending.mergeId || p.id_b === pending.mergeId) ||
            (p.id_a === pending.keepId && p.id_b === pending.mergeId) ||
            (p.id_b === pending.keepId && p.id_a === pending.mergeId)
          )
      ));
      showToast(`"${pending.mergeName}" merged into "${pending.keepName}"`, 'success');
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      showToast(`Merge failed: ${msg}`, 'error');
    } finally {
      setIsMerging(false);
      setPending(null);
    }
  }, [pending, showToast]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Users2 className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">
                  Customer Deduplication
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Detect and merge duplicate customer records
                </p>
              </div>
            </div>
            <button
              onClick={scan}
              disabled={isLoading}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
            >
              {isLoading
                ? <Loader2 className="h-4 w-4 animate-spin" />
                : <Search className="h-4 w-4" />
              }
              {isLoading ? 'Scanning…' : 'Scan for Duplicates'}
            </button>
          </div>
        </div>

        <div className="p-6 max-w-4xl">
          {/* Info banner */}
          <div className="flex items-start gap-3 p-4 rounded-xl border border-blue-500/20 bg-blue-500/5 mb-6">
            <Info className="h-4 w-4 text-blue-400 mt-0.5 shrink-0" />
            <div className="text-sm text-[var(--ff-text-secondary)]">
              <p className="font-medium text-[var(--ff-text-primary)] mb-0.5">How deduplication works</p>
              <p>
                ISAFlow matches customers by identical email address, VAT number, or similar name.
                When you merge, all invoices, payments, quotes, sales orders, and credit notes are
                moved to the customer you keep. The duplicate is then marked inactive.
              </p>
            </div>
          </div>

          {/* Error state */}
          {error && (
            <div className="flex items-center gap-2 p-4 rounded-xl border border-rose-500/20 bg-rose-500/5 text-rose-400 text-sm mb-6">
              <AlertCircle className="h-4 w-4 shrink-0" />
              {error}
            </div>
          )}

          {/* Not yet scanned */}
          {!scanned && !isLoading && !error && (
            <div className="text-center py-16">
              <Search className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)] font-medium">Ready to scan</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1 mb-4">
                Click "Scan for Duplicates" to find potential matches
              </p>
              <button
                onClick={scan}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
              >
                <Search className="h-4 w-4" />
                Scan for Duplicates
              </button>
            </div>
          )}

          {/* Loading */}
          {isLoading && (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          )}

          {/* No duplicates found */}
          {scanned && !isLoading && pairs.length === 0 && (
            <div className="text-center py-16">
              <CheckCircle2 className="h-12 w-12 text-teal-400 mx-auto mb-3" />
              <p className="text-[var(--ff-text-primary)] font-medium">No duplicates found</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Your customer list looks clean
              </p>
            </div>
          )}

          {/* Duplicate pairs */}
          {!isLoading && pairs.length > 0 && (
            <>
              <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
                Found <span className="font-medium text-[var(--ff-text-primary)]">{pairs.length}</span> potential
                duplicate pair{pairs.length !== 1 ? 's' : ''}.
                Select which record to keep, then click Merge.
              </p>
              <div className="space-y-4">
                {pairs.map((pair) => (
                  <PairRow
                    key={`${pair.id_a}:${pair.id_b}`}
                    pair={pair}
                    onMergeRequest={(keepId, mergeId, keepName, mergeName) =>
                      setPending({ keepId, mergeId, keepName, mergeName })
                    }
                  />
                ))}
              </div>
            </>
          )}
        </div>
      </div>

      {/* Confirm modal */}
      {pending && (
        <ConfirmModal
          keepName={pending.keepName}
          mergeName={pending.mergeName}
          onConfirm={handleMergeConfirm}
          onCancel={() => setPending(null)}
          isBusy={isMerging}
        />
      )}

      {/* Toast */}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </AppLayout>
  );
}

/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 * Uses useAdminPrefix hook for subdomain-aware navigation.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
  ToggleRight,
  Zap,
  Database,
  ArrowUpDown,
  Clock,
} from 'lucide-react';

interface NavDef {
  label: string;
  /** Relative path without /admin prefix, e.g. '' for dashboard, '/companies' etc. */
  path: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Navigation definitions with relative paths — full hrefs built dynamically via useAdminHref */
const NAV_DEFS: NavDef[] = [
  { label: 'Dashboard',   path: '',                          icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies',                icon: Building2 },
  { label: 'Users',       path: '/users',                    icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
      { label: 'Sage Import',    path: '/tools/sage-import',   icon: Database },
      { label: 'Migrations',     path: '/tools/migrations',    icon: ArrowUpDown },
    ],
  },
  { label: 'Features',    path: '/features',   icon: ToggleRight },
  { label: 'Job Queue',   path: '/job-queue',  icon: Zap },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',   path: '/analytics',  icon: BarChart2 },
  { label: 'Components',  path: '/components', icon: Palette },
  { label: 'Settings',    path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const buildHref = useAdminHref();

  const isActive = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    if (adminPath === '') return router.asPath === href;
    return router.asPath.startsWith(href);
  };

  const isSectionOpen = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    return router.asPath.startsWith(href);
  };

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {NAV_DEFS.map(item => {
          const Icon = item.icon;
          const href = buildHref(`/admin${item.path}`);

          if (item.disabled) {
            return (
              <div
                key={item.path}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.path);
            return (
              <div key={item.path}>
                <Link
                  href={href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.path) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.path) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childHref = buildHref(`/admin${child.path}`);
                      const childActive = router.asPath === childHref;
                      return (
                        <Link
                          key={child.path}
                          href={childHref}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.path);
          return (
            <Link
              key={item.path}
              href={href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

