/**
 * Engagement Trend Chart — 30-day DAU/WAU/MAU line chart
 */

import dynamic from 'next/dynamic';
import type { EngagementTrendPoint } from '@/modules/admin/types/admin.types';

const ResponsiveContainer = dynamic(() => import('recharts').then((m) => m.ResponsiveContainer), { ssr: false });
const LineChart           = dynamic(() => import('recharts').then((m) => m.LineChart),           { ssr: false });
const Line                = dynamic(() => import('recharts').then((m) => m.Line),                { ssr: false });
const XAxis               = dynamic(() => import('recharts').then((m) => m.XAxis),              { ssr: false });
const YAxis               = dynamic(() => import('recharts').then((m) => m.YAxis),              { ssr: false });
const CartesianGrid       = dynamic(() => import('recharts').then((m) => m.CartesianGrid),      { ssr: false });
const Tooltip             = dynamic(() => import('recharts').then((m) => m.Tooltip),            { ssr: false });
const Legend              = dynamic(() => import('recharts').then((m) => m.Legend),             { ssr: false });

interface Props {
  data: EngagementTrendPoint[];
}

function fmtShortDate(dateStr: string) {
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' });
}

export function EngagementTrendChart({ data }: Props) {
  if (data.length === 0) {
    return (
      <div className="flex items-center justify-center h-48 text-gray-400 text-sm">
        No engagement data available
      </div>
    );
  }

  return (
    <ResponsiveContainer width="100%" height={220}>
      <LineChart data={data} margin={{ top: 4, right: 16, left: 8, bottom: 0 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#374151" vertical={false} />
        <XAxis
          dataKey="date"
          tickFormatter={(v: unknown) => fmtShortDate(v)}
          tick={{ fill: '#9ca3af', fontSize: 11 }}
          axisLine={false}
          tickLine={false}
          interval={4}
        />
        <YAxis
          tick={{ fill: '#9ca3af', fontSize: 11 }}
          axisLine={false}
          tickLine={false}
          width={36}
        />
        <Tooltip
          contentStyle={{ background: '#1f2937', border: '1px solid #374151', borderRadius: 8 }}
          labelStyle={{ color: '#e5e7eb', marginBottom: 4 }}
          labelFormatter={(label: unknown) => fmtShortDate(String(label))}
        />
        <Legend
          wrapperStyle={{ fontSize: 12, color: '#9ca3af', paddingTop: 8 }}
        />
        <Line type="monotone" dataKey="dau" name="DAU" stroke="#3b82f6" strokeWidth={2} dot={false} activeDot={{ r: 4 }} />
        <Line type="monotone" dataKey="wau" name="WAU" stroke="#10b981" strokeWidth={2} dot={false} activeDot={{ r: 4 }} />
        <Line type="monotone" dataKey="mau" name="MAU" stroke="#a855f7" strokeWidth={2} dot={false} activeDot={{ r: 4 }} />
      </LineChart>
    </ResponsiveContainer>
  );
}

